def _short_reason(verdict: "Verdict | None") -> tuple[str, str, str]:
    """(D number, English reason, German reason) of the short line for verdict (D53)."""
    if verdict is None:
        return _SHORT_UNKNOWN
    if verdict.reason_id == "git_form_not_free" and verdict.detail == _CODEX_READ_FORM_EXPLANATION:
        return _SHORT_CODEX_READ
    if verdict.reason_id == "git_form_not_free" and verdict.evidence.startswith("none, the gate reads no repository"):
        return _SHORT_GIT_FORM
    if verdict.reason_id == "remote_read_not_modeled" and (verdict.failed or "").startswith("git ls-remote "):
        named = _SHORT_LAST_D.findall(verdict.detail)
        return (f"D{named[-1]}" if named else "D41",) + _SHORT_LS_REMOTE   # D59: the ask names ls-remote, not a fetch
    entry = _SHORT_REASONS.get(verdict.reason_id, _SHORT_UNKNOWN)
    if entry[0] is None:
        named = _SHORT_LAST_D.findall(verdict.detail)
        entry = (f"D{named[-1]}" if named else "D3", entry[1], entry[2])
    return entry


#: D116: the forms of the short line whose reason is what can go wrong: an ask, a block, a warning, the block of D85, a
#: rewrite, a card, and since follow-up note 47 (O46-5, D118) the end the Stop hook holds.
_SHORT_DANGER_FORMS = frozenset({"ask", "deny", "warn", "sperre", "umweg", "karte", "stop"})
#: D116: reasons that say only that the gate cannot read or resolve a call; for the line of a card the danger of a more
#: specific reason of the same answer comes first.
_SHORT_DANGER_GENERIC = frozenset({"net_unmodeled_git", "possible_unmodeled_push", "push_not_measured",
                                   "directory_unresolved", "step_after_state_change", "git_form_not_free",
                                   "gh_form_not_free"})


def _short_card_cause(outcome: "Outcome", step: str | None = None) -> "Verdict | None":
    """D116: the verdict whose danger the line of a card of D93 names: the ask of the step the line names (D72,
    _d72_cause) where it is more than the gate's own blind spot (_SHORT_DANGER_GENERIC), else the first ask that is,
    else the ask of the step, else the first ask; so the danger belongs to the step wherever the answer allows."""
    asks = [v for v in outcome.verdicts if v.decision == "ask"]
    own = _d72_cause(asks, "ask", step) if step else None
    if own is not None and own.reason_id not in _SHORT_DANGER_GENERIC:
        return own
    return next((v for v in asks if v.reason_id not in _SHORT_DANGER_GENERIC), own or (asks[0] if asks else None))


def _short_git_form_name(verdict: "Verdict") -> str | None:
    """The git form a not-free answer of D3 names: from its evidence (the state check, the read profile) or from what
    failed ("<form> may start a program …")."""
    m = _PINNED_EVIDENCE.fullmatch(verdict.evidence or "")
    if m is not None:
        return f"git {m.group(1)}"
    failed = verdict.failed or ""
    return failed.split(" may start", 1)[0] if " may start" in failed else None


def _short_danger(verdict: "Verdict | None") -> tuple[str, str] | None:
    """D116: (English, German) of what can go wrong for the verdict that decides, or None where
    its reason of D53 names that already (_SHORT_DANGER_IN_REASON), and that reason stands."""
    if verdict is None:
        return _SHORT_DANGER_SPECIAL[_SHORT_UNKNOWN[1]]
    if verdict.reason_id == "git_form_not_free" and verdict.detail == _CODEX_READ_FORM_EXPLANATION:
        return _SHORT_DANGER_SPECIAL[_SHORT_CODEX_READ[1]]
    if verdict.reason_id == "git_form_not_free":
        name = _short_git_form_name(verdict)
        if name in _SHORT_DANGER_GIT_FORM:
            return _SHORT_DANGER_GIT_FORM[name]
        if name is not None and _SHORT_READ_FORMS.match(name):
            return _SHORT_DANGER_GIT_FORM["read"]
        return _SHORT_DANGER["git_form_not_free"]
    if verdict.reason_id == "remote_read_not_modeled" and (verdict.failed or "").startswith("git ls-remote "):
        return _SHORT_DANGER_SPECIAL[_SHORT_LS_REMOTE[0]]
    if verdict.reason_id not in _SHORT_REASONS:
        return _SHORT_DANGER_SPECIAL[_SHORT_UNKNOWN[1]]
    return _SHORT_DANGER.get(verdict.reason_id)   # None for _SHORT_DANGER_IN_REASON: its reason stands


def _short_step_name(command: str | None, cwd: str) -> str | None:
    """The name of the heaviest git or gh step of a command (D72, _sh_heaviest), the first where several weigh the same,
    `git <subcommand>` or the gh call (D53), or None. A command the step parser does not model is named by the
    heaviest git or gh call of the scan (gated_calls); one the scan reads no such call in is "this command"."""
    if not command:
        return None
    steps: list = []
    try:
        _sh_walk(_sh_parse(command), cwd, steps)
    except Exception:  # noqa: BLE001 - a command the parser does not model is named by the scan
        try:
            calls = [c for c in gated_calls(command) if c[0].startswith(("git", "gh"))]
        except Exception:  # noqa: BLE001 - a command the scan does not read either is named as "this command"
            return None
        return max(calls, key=lambda c: _d72_call_weight(c[0], c[2]))[0] if calls else None
    return _sh_short_name(_sh_heaviest(steps))


def short_line(decision: str, outcome: "Outcome | None", step: str | None, language: str, form: str | None = None,
               suffix: str = "", hint: str = "") -> str:
    """The one line the user sees for an answer that is no pass (D53): the step that has the decision, the reason in
    everyday words and the D number, at most SHORT_LINE_MAX characters, in the language a person set. For an ask, a
    block, a warning and a held end the reason is what can go wrong, before the D number (D116, _short_danger). The long
    reason goes on to the model and the log keeps what it kept."""
    language = language if language in _LANGUAGES else "en"
    lead = None
    if outcome is not None:
        lead = outcome.cause or next((v for v in outcome.verdicts if v.decision == decision), None) or \
            (outcome.verdicts[0] if outcome.verdicts else None)   # D72: the verdict of the step or rule that decides
    if lead is not None and lead.reason_id == "autonomy_card" and outcome is not None and form is None:
        form, lead = "karte", (_short_card_cause(outcome, step) or lead)   # D116: the danger of the call, then the card
    d, english, german = _short_reason(lead)
    danger = _short_danger(lead) if (form or decision) in _SHORT_DANGER_FORMS else None
    if danger is not None:
        english, german = danger
    name = step or (_SHORT_NO_STEP_OBJECT if (form or decision) in _SHORT_OBJECT_FORMS else _SHORT_NO_STEP)[language]
    if len(name) > _SHORT_STEP_MAX:
        name = name[:_SHORT_STEP_MAX - 1] + "…"
    template = _SHORT_TEMPLATES[language][form or decision]
    when = max(_STAMP_TIME.findall(lead.detail if lead is not None else ""), default=_SHORT_UNKNOWN_TIME[language])
    reason = german if language == "de" else english

    def build(name: str, suffix: str) -> str:
        line = template.format(step=name, reason=reason, d=d, when=when, hint=hint)
        return f"{line} {suffix}" if suffix else line

    # D116: a line that is too long takes the short form of its suffix, then a shorter step, and is cut only where
    # neither fits, so the danger, its D number and the end of the template stay whole where they fit at all
    suffix = suffix if len(build(name, suffix)) <= SHORT_LINE_MAX else _SHORT_SUFFIX_SHORT.get(suffix, suffix)
    line = build(name, suffix)
    room = len(name) - (len(line) - SHORT_LINE_MAX)
    if len(line) > SHORT_LINE_MAX and room >= _SHORT_STEP_MIN:
        line = build(name[:room - 1] + "…", suffix)
    if len(line) > SHORT_LINE_MAX:
        line = line[:SHORT_LINE_MAX - 2] + "…."
    return line


def _inactive_first(host: str, session: object, outcome: "Outcome") -> bool:
    """Whether an inactive answer is the first of its session for one of its repositories (D53), so the user sees once
    that the gate is not active there. One empty file per host, session and repository in INACTIVE_SEEN_DIR of the
    plugin data directory, created with O_EXCL: the call that creates it shows the line. Without a session id or a
    writable data directory every inactive answer counts as the first, as before D53."""
    directory = log_directory(host)
    if directory is None or not isinstance(session, str) or not session:
        return True
    folder = os.path.join(directory, INACTIVE_SEEN_DIR)
    repos = sorted({str(v.repo) for v in outcome.verdicts if v.decision == "inactive"}) or ["none"]
    first = False
    try:
        os.makedirs(folder, exist_ok=True)
        for repo in repos:
            key = hashlib.sha256("\0".join((host, session, repo)).encode("utf-8", "surrogateescape")).hexdigest()[:32]
            try:
                fd = os.open(os.path.join(folder, key), os.O_WRONLY | os.O_CREAT | os.O_EXCL
                             | getattr(os, "O_NOFOLLOW", 0) | getattr(os, "O_CLOEXEC", 0), 0o600)
            except FileExistsError:
                continue
            os.close(fd)
            first = True
        if first:
            _inactive_seen_trim(folder)
    except OSError:
        return True
    return first


def _inactive_seen_trim(folder: str) -> None:
    """Remove the oldest half of the records once there are more than _INACTIVE_SEEN_KEEP; never raises."""
    try:
        names = os.listdir(folder)
        if len(names) <= _INACTIVE_SEEN_KEEP:
            return
        dated = sorted((os.lstat(os.path.join(folder, n)).st_mtime, n) for n in names)
        for _when, name in dated[:len(dated) // 2]:
            os.unlink(os.path.join(folder, name))
    except OSError:
        pass


def answer(decision: str, reason: str, host: str = "claude", short: str | None = None,
           hint: dict | None = None) -> dict | None:
    """The PreToolUse answer (D53). A pass answers nothing: the hook prints nothing, carries no permission decision
    (D4) and its reason stays in the log as its reason ids. An inactive gate, a warn and a hand-over carry no permission
    decision either (D4, D5, D35).

    Every other answer shows the user one short line, `short` (systemMessage), and gives the model the long reason
    (additionalContext). Under Claude Code the dialog of an "ask" shows permissionDecisionReason to the user, so it
    carries the short line, and a "deny" gives permissionDecisionReason to the model, so it carries the long reason.
    Codex has no dialog (D12): its deny carries the short line there. Without `short` the long reason, with the Codex
    and warning sentences, stands in its place, as before D53. Every field used here is one both hosts accept; Codex rejects an answer with any other field, and a
    permissionDecisionReason without a permissionDecision. A "warn" (a git push under Codex, Karte 5 A) goes out with
    the warning sentence in the long reason.
    """
    if decision == "pass":
        return None
    if decision == "ask" and host == "codex":
        decision, reason = "deny", reason + " Codex cannot ask, so the gate denies the call."
    if decision == "warn":
        reason = f"{reason} {CODEX_PUSH_WARNING}"
    short = reason if short is None else short
    specific = {"hookEventName": "PreToolUse", "additionalContext": reason}
    if decision not in ("inactive", "warn", "handover"):   # D4: the gate never answers allow (D35 too)
        specific.update(permissionDecision=decision,
                        permissionDecisionReason=short if decision == "ask" or host == "codex" else reason)
    printed = {"systemMessage": short, "hookSpecificOutput": specific}
    if hint is not None and host == "claude":
        # D85: the rewrite as a field of its own (Claude Code accepts it, measured; it does not reach the model, so the
        # deny's reason, which does, leads with the same rewrite). Never under Codex, which rejects any other field.
        printed["rewriteHint"] = hint
    return printed


def pre_tool_answer(outcome: "Outcome", host: str, event: object, step: str | None,
                    environ: dict | None = None) -> dict | None:
    """What the PreToolUse hook prints for an outcome (D53): nothing for a pass, nothing for an inactive gate after the
    first inactive answer of the session for its repositories, else answer() with the short line in the language a
    person set. Under Codex an ask is a deny, and its short line says that Codex cannot ask (D12)."""
    environ = os.environ if environ is None else environ
    decision = outcome.decision
    klasse = (getattr(outcome, "autonomy", None) or {}).get("klasse")
    if decision == "pass" and klasse in ("go", "maschine", "freigabe"):
        # D87, D92, D111: a call a machine check or a release frees stays visible, as a call a rule frees does: one
        # line, no decision
        short = short_line("pass", outcome, outcome.step or step, _read_language(environ), form=klasse,
                           hint=(getattr(outcome, "autonomy", None) or {}).get("quittung", {}).get("karte", ""))
        return {"systemMessage": short, "hookSpecificOutput": {"hookEventName": "PreToolUse",
                                                               "additionalContext": outcome.text}}
    if decision == "pass" and any(v.reason_id in HINT_REASONS for v in outcome.verdicts):
        # D105: a hint is a line for the person and the long reason as context for the model (measured: it reaches the
        # model after the tool's result), no permission decision; the call runs
        short = short_line("pass", outcome, outcome.step or step, _read_language(environ), form="hinweis")
        return {"systemMessage": short, "hookSpecificOutput": {"hookEventName": "PreToolUse",
                                                               "additionalContext": outcome.text}}
    if decision == "pass":
        if not any(v.reason_id == "approved_by_rule" for v in outcome.verdicts):
            return None
        # A call a human rule frees stays visible (review round 15, F15-2: a shell command can switch the mode and
        # the rules unseen, and making each freed call visible is the owner's remedy): one short line with the time
        # the mode and the rules last changed, the long reason to the model, no permission decision (D4, D25, D53).
        lead = next(v for v in outcome.verdicts if v.reason_id == "approved_by_rule")
        short = short_line("pass", Outcome("pass", lead.detail, [lead]), outcome.step or step,
                           _read_language(environ), form="rule")
        return {"systemMessage": short, "hookSpecificOutput": {"hookEventName": "PreToolUse",
                                                               "additionalContext": outcome.text}}
    session = event.get("session_id") if isinstance(event, dict) else None
    if decision == "inactive" and not _inactive_first(host, session, outcome):
        return None
    language = _read_language(environ)
    name = outcome.step or step
    autonomy = getattr(outcome, "autonomy", None) or {}
    if decision == "ask" and host == "codex":
        short = short_line("ask", outcome, name, language, form="deny", suffix=_SHORT_CODEX_DENY[language])
    elif autonomy.get("klasse") in ("umweg", "sperre"):
        # D85: the line names the rewrite (or that there is none) before the reason, so a cut keeps it
        first = (autonomy.get("hinweise") or [None])[0]
        label = _AUTONOMY_HINT_LABELS[first][1 if language == "de" else 0] if first else ""
        short = short_line(decision, outcome, name, language, form=autonomy["klasse"], hint=label)
    else:
        short = short_line(decision, outcome, name, language)
    hint = None
    if autonomy.get("klasse") in ("umweg", "sperre"):
        hint = {"ids": autonomy.get("hinweise", []) or ["kein_freier_weg"], "calls": autonomy.get("aufrufe", []),
                "text": "; ".join(_AUTONOMY_HINTS[h][0] for h in autonomy.get("hinweise", [])) or _AUTONOMY_NO_WAY[0]}
    return answer(decision, outcome.text, host=host, short=short, hint=hint)


# --- D85: the autonomous answer under Claude Code ------------------------------------------------------

#: D85: the command-line flag with which the plugin's hook of Claude Code (hooks.json) starts the gate for the autonomous
#: answer. Started without it, the gate answers as decide() judges, as before follow-up note 35; under Codex the flag changes
#: nothing.
AUTONOMOUS_FLAG = "--autonomous"
#: D85: the closed list of external effects for which the gate still asks under Claude Code where
#: no standing GO covers them; the list is owner question O35-1. Each with its words for the long reason (English) and
#: the short line (German). Every other ask of decide() becomes a deny that names the rewrite the gate checked free.
AUTONOMY_EFFECTS = {
    "push": ("a push to a branch that is no own work branch under the standing GO",
             "ein Push auf einen Zweig, der kein eigener Arbeitszweig unter dem stehenden GO ist"),
    "push_delete": ("a push that deletes a branch of the remote", "ein Push, der einen entfernten Zweig löscht"),
    "tag": ("a tag that is made, deleted or sent", "ein Tag, das angelegt, gelöscht oder gesendet wird"),
    "release": ("a release", "eine Release"),
    "merge": ("a merge of a pull request without --auto", "ein Merge eines PR ohne --auto"),
    "pr": ("a pull request, an issue, a comment or a review", "ein PR, ein Issue, ein Kommentar oder ein Review"),
    "settings": ("a setting of a repository", "eine Einstellung eines Repositorys"),
    "gh_write": ("a call that writes on GitHub", "ein Aufruf, der auf GitHub schreibt"),
    "done_order": ("a change of a local done order (D38)", "eine Änderung eines lokalen Abschlussauftrags (D38)"),
    "programm": ("a local form that starts a program of the own clone the gate does not see (a hook, a filter, "
                 "fsmonitor; D91, owner question O37-1)",
                 "eine lokale Form, die ein Programm des eigenen Klons startet, das das Tor nicht sieht (D91)"),
    "upload": ("a file or data sent to a host outside (D103)", "eine Datei oder Daten, die an einen fremden Host gehen (D103)"),
}
#: The gh pairs with an external effect, by the entry of AUTONOMY_EFFECTS (gh 2.89.0, `gh <command> --help`); every
#: other pair is none. `gh api` is judged by its method (_autonomy_gh_api_writes).
_AUTONOMY_GH = {
    **{("pr", s): "pr" for s in ("create", "new", "comment", "review", "close", "reopen", "ready", "edit", "lock",
                                  "unlock", "update-branch")},
    ("pr", "merge"): "merge",
    **{("issue", s): "pr" for s in ("create", "new", "comment", "close", "reopen", "edit", "delete", "transfer",
                                     "lock", "unlock", "pin", "unpin", "develop")},
    **{("release", s): "release" for s in ("create", "new", "edit", "delete", "upload", "delete-asset")},
    **{("repo", s): "settings" for s in ("edit", "delete", "rename", "archive", "unarchive", "create", "fork",
                                          "sync", "deploy-key", "set-default")},
    **{(c, s): "settings" for c in ("secret", "variable") for s in ("set", "delete", "remove")},
    **{("label", s): "settings" for s in ("create", "edit", "delete", "clone")},
    ("workflow", "run"): "gh_write", ("workflow", "enable"): "settings", ("workflow", "disable"): "settings",
    **{("run", s): "gh_write" for s in ("rerun", "cancel", "delete")},
    ("cache", "delete"): "gh_write",
    **{("gist", s): "gh_write" for s in ("create", "new", "edit", "delete", "rename")},
}
#: The MCP tools the gate gates (MCP_GATED_TOOLS), by their external effect.
_AUTONOMY_MCP = {"create_pull_request": "pr", "create_merge_request": "pr", "create_release": "release",
                 "push_files": "push", "create_or_update_file": "push", "merge_pull_request": "merge"}
#: The rewrite hints of D85: (English for the long reason, German for the short line). Each names exactly what makes the
#: form free; the gate names one only after it judged every call of the rewrite free or an external effect it asks for.
_AUTONOMY_HINTS = {
    "kette_teilen": ("split the chain, one git call per Bash call", "teile die Kette, ein git-Aufruf je Bash-Aufruf"),
    "git_C_statt_cd": ("git -C <absolute path> instead of cd", "git -C <absoluter Pfad> statt cd"),
    "git_nicht_in_subst": ("git not in $( ): run the call on its own and write its output into the next call",
                           "git nicht in $( ), eigener Aufruf, Ausgabe in den nächsten"),
    "pipe_teilen": ("run the git or gh call alone, without a pipe, and read its output yourself",
                    "git- oder gh-Aufruf allein, ohne Pipe"),
    "heredoc_als_datei": ("write the file with the Write tool, no here-document with git",
                          "Datei mit Write, kein Heredoc mit git"),
    "nachricht_als_datei": ("write the text to a file outside the repository with the Write tool and name that file in "
                            "place of the here-document (git commit -F <file>, gh … --body-file <file>)",
                            "Text als Datei statt Heredoc"),
    "woertlich": ("write the words literally, as the call below names them", "wörtliche Schreibweise"),
    "push_HEAD": ("push HEAD in place of the branch name from $( )", "HEAD statt Zweigname aus $( )"),
}
#: The rewrite hints as the short line names them (D53: one line, at most SHORT_LINE_MAX characters).
_AUTONOMY_HINT_LABELS = {
    "kette_teilen": ("split the chain", "Kette teilen"), "git_C_statt_cd": ("git -C instead of cd", "git -C statt cd"),
    "git_nicht_in_subst": ("git not in $( )", "git nicht in $( )"), "pipe_teilen": ("no pipe", "ohne Pipe"),
    "heredoc_als_datei": ("Write, no here-document", "Write statt Heredoc"),
    "nachricht_als_datei": ("message as a file, commit -F", "Nachricht als Datei, commit -F"),
    "woertlich": ("literal words", "wörtlich schreiben"), "push_HEAD": ("push HEAD", "Push von HEAD"),
}
_AUTONOMY_NO_WAY = ("no form of this call is free, and it is no external effect the gate asks the owner about. Do not "
                    "try another spelling of the same call; tell the person what you wanted to run and why",
                    "kein freier Weg")
#: The why of a rewrite of several calls that are all external effects: the ask of the whole command stays.
_AUTONOMY_ONLY_EXTERNAL = "every call of the rewrite is an external effect"
#: The words of a git call whose output is the name of the current branch: in a push, HEAD names the same branch to git
#: push, which pushes it under its own name (git-push(1), "HEAD" in <refspec>), so the rewrite writes HEAD (push_HEAD).
_AUTONOMY_CURRENT_BRANCH = ("git rev-parse --abbrev-ref HEAD", "git branch --show-current",
                            "git symbolic-ref --short HEAD", "git symbolic-ref --short -q HEAD")
#: The mark of a `$(pwd)` or `$PWD` the rewrite wrote as the directory the command runs in (a key no variable has).
_AUTONOMY_PWD = "\x00pwd"
#: A value the rewrite leaves to the session (the output of an earlier call), as the gate judges it and as it names it.
_AUTONOMY_HOLE = "PB_AUTONOMY_VALUE_{k}"
_AUTONOMY_HOLE_SHOWN = "<output of call {k}>"
#: The file a rewrite of D85 writes with the Write tool where the command named none (a commit message), as the gate
#: judges it and as it names it.
_AUTONOMY_FILE = "/tmp/pb-autonomy-commit-message.txt"
_AUTONOMY_FILE_SHOWN = "<a file outside the repository>"
#: The commit of a message written by a here-document in a command substitution, the form Claude Code writes itself.
_AUTONOMY_COMMIT_MESSAGE = re.compile(
    r"\A(?P<head>git(?: -C /[A-Za-z0-9_./+-]+)? commit(?: -[aqsn]+| --(?:all|amend|signoff|allow-empty|no-edit|quiet))*)"
    r" (?:-m|--message) \"\$\(cat <<'?(?P<mark>[A-Za-z_][A-Za-z0-9_]*)'?\n(?:.*\n)?(?P=mark)\n *\)\" *\Z", re.DOTALL)
_AUTONOMY_PARAM = re.compile(r'\A"?\$(?:([A-Za-z_][A-Za-z0-9_]*)|\{([A-Za-z_][A-Za-z0-9_]*)\})"?\Z')
#: The answers of decide() that let a call run.
_AUTONOMY_FREE = ("pass", "inactive", "handover")


def _autonomy_gh_api_writes(args: list[str]) -> bool:
    """Whether `gh api <args>` writes: a method other than GET and HEAD, or a field or an input without a method (gh
    then sends POST, `gh api --help`)."""
    method, fields, i = None, False, 0
    while i < len(args):
        word = args[i]
        if word in ("-X", "--method") and i + 1 < len(args):
            method, i = args[i + 1].upper(), i + 2
            continue
        if word.startswith("--method="):
            method = word.split("=", 1)[1].upper()
        elif word.startswith("-X") and len(word) > 2:
            method = word[2:].upper()
        elif word in ("-f", "-F", "--field", "--raw-field", "--input"):
            fields, i = True, i + 1
        elif word.startswith(("--field=", "--raw-field=", "--input=")) or (word[:2] in ("-f", "-F") and len(word) > 2):
            fields = True
        i += 1
    return (method or ("POST" if fields else "GET")) not in ("GET", "HEAD")


def _autonomy_effect(words: list[str]) -> str | None:
    """The entry of AUTONOMY_EFFECTS a git or gh call with these words has, or None."""
    if not words:
        return None
    head = os.path.basename(words[0])
    if head == "git":
        i = 1
        while i < len(words) and words[i].startswith("-"):
            option, eq, _value = words[i].partition("=")
            i += 2 if (option in _GIT_GLOBAL_VALUE and not eq) else 1
        sub, rest = (words[i], words[i + 1:]) if i < len(words) else (None, [])
        if sub in ("push", "send-pack"):
            return "push"
        if sub == "tag":
            return None if _work_tag_list(rest) else "tag"
        return None
    if head == "gh" and len(words) >= 2:
        if words[1] == "api":
            return "gh_write" if _autonomy_gh_api_writes(words[2:]) else None
        return _AUTONOMY_GH.get((words[1], words[2])) if len(words) >= 3 else None
    k = _guard_program(words) if head not in _UPLOAD_PROGRAMS else 0
    if os.path.basename(words[k]) in _UPLOAD_PROGRAMS and _upload_form(words[k:]) is not None:
        return "upload"   # D103
    return None


def _autonomy_single(command: str) -> list[str] | None:
    """The words of the command where it is one simple command with no substitution of any kind, here-document, pipe or
    list, else None."""
    try:
        tree = _sh_parse(command)
    except Exception:  # noqa: BLE001 - a command the parser does not model is no single call
        return None
    if len(tree.items) != 1 or len(tree.items[0][0]) != 1 or len(tree.items[0][0][0]) != 1:
        return None
    cmd = tree.items[0][0][0][0]
    if not isinstance(cmd, _ShSimple) or not cmd.words:
        return None
    if any(w.subs for w in cmd.assigns + cmd.words) or \
            any(isinstance(r.target, _ShHeredoc) or r.target.subs for r in cmd.redirs):
        return None
    return [w.value for w in cmd.words]


def _autonomy_record(outcome: "Outcome", kind: str, **fields) -> "Outcome":
    outcome.autonomy = {"klasse": kind, "vorher": "ask", **fields}
    return outcome


def _autonomy_external(outcome: "Outcome", command: str, cwd: str, deadline: float,
                       environ: dict) -> "Outcome | None":
    """The answer to a single call with an external effect of AUTONOMY_EFFECTS, or with a change of a done order (D38):
    the ask kept, and for a `git push` the answer of D86 (_autonomy_push); None for any other command."""
    words = _autonomy_single(command)
    if words is None:
        return None
    if words[0] == "git" and _autonomy_effect(words) == "push" and \
            not any(v.reason_id == "done_order_change" for v in outcome.verdicts):
        return _autonomy_push(outcome, words, cwd, deadline, environ)   # D86
    if words[:3] == ["gh", "pr", "edit"] and not any(v.reason_id == "done_order_change" for v in outcome.verdicts):
        checked = _autonomy_pr_edit(outcome, words, cwd, deadline, environ)   # D92
        if checked is not None:
            return checked
    effects = ["done_order"] if any(v.reason_id == "done_order_change" for v in outcome.verdicts) else []
    effect = _autonomy_effect(words)
    if effect is not None:
        effects.append(effect)
    return _autonomy_record(outcome, "aussen", wirkung=sorted(set(effects))) if effects else None


def _autonomy_call_words(cmd: "_ShSimple", directory: str | None, holes: dict, calls: list,
                         here: str = "") -> list | None:
    """The words of one simple command as a call of the rewrite: literal words as they are, a word that is exactly one
    command substitution of a single literal git or gh call lifted into a call of its own before it (its output a hole),
    a word that is exactly a variable a lifted call set, the hole; after a `cd`, `-C <directory>` after git. None where
    the command is not of these words (an assignment, a redirection, any other expansion, gh or another program after a
    `cd`)."""
    if cmd.assigns or cmd.redirs or not cmd.words:
        return None
    if cmd.words[0].value not in ("git", "gh") and not _autonomy_reads(cmd, words_too=False):
        return None   # its other words are read below: literal, a hole, a lifted call or the directory
    words: list = []
    pushing = bool(cmd.words) and cmd.words[0].value == "git" and any(x.value == "push" for x in cmd.words[1:3])
    for w in cmd.words:
        if w.literal:
            words.append(w.value)
            continue
        if pushing and len(w.subs) == 1 and w.subs[0].kind == "cmd" and \
                " ".join(w.subs[0].text.split()) in _AUTONOMY_CURRENT_BRANCH and \
                w.raw in (f"$({w.subs[0].text})", f'"$({w.subs[0].text})"'):
            words.append("HEAD")   # push_HEAD: the current branch under its own name
            continue
        if here and w.raw in ("$(pwd)", '"$(pwd)"', "$PWD", '"$PWD"', "${PWD}", '"${PWD}"'):
            words.append(here)   # the directory the command runs in, which the hook names as cwd
            holes[_AUTONOMY_PWD] = 0
            continue
        param = _AUTONOMY_PARAM.fullmatch(w.raw)
        if param is not None and len(w.subs) == 1 and (param.group(1) or param.group(2)) in holes:
            words.append(holes[param.group(1) or param.group(2)])
            continue
        lifted = _autonomy_lift(w, directory, calls)
        if lifted is None:
            return None
        words.append(lifted)
    if directory is not None:
        if words[0] != "git" or (len(words) > 1 and words[1] == "-C"):
            return None
        words = ["git", "-C", directory] + words[1:]
    return words


def _autonomy_lift(w: "_ShWord", directory: str | None, calls: list) -> int | None:
    """Lift the command substitution that is the whole word w into a call of its own; the number of that call, or None
    where w is not exactly one `$( )` or backtick around one literal git or gh call."""
    if len(w.subs) != 1 or w.subs[0].kind != "cmd" or w.subs[0].tree is None:
        return None
    text = w.subs[0].text
    if w.raw not in (f"$({text})", f'"$({text})"', f"`{text}`", f'"`{text}`"'):
        return None
    tree = w.subs[0].tree
    if len(tree.items) != 1 or len(tree.items[0][0]) != 1 or len(tree.items[0][0][0]) != 1:
        return None
    inner = tree.items[0][0][0][0]
    if not isinstance(inner, _ShSimple) or inner.assigns or inner.redirs or not inner.words or \
            not all(x.literal for x in inner.words) or inner.words[0].value not in ("git", "gh"):
        return None
    words = [x.value for x in inner.words]
    if directory is not None:
        if words[0] != "git" or (len(words) > 1 and words[1] == "-C"):
            return None
        words = ["git", "-C", directory] + words[1:]
    calls.append({"kind": "bash", "words": words, "directory": directory})
    return len(calls)


def _autonomy_rewrite(command: str, cwd: str) -> tuple[list, list] | None:
    """(hint ids, calls) of the rewrite of D85 for a command, before the gate judged any call, or None where the command
    has none. A call is {"kind": "bash", "words": [...], "directory": dir or None} with an int for the output of an
    earlier call, or {"kind": "write", "path": ...}. The rewrite only splits, lifts and drops: every git or gh call in it
    stands in the command as written, with `-C` for a `cd` before it."""
    matched = _AUTONOMY_COMMIT_MESSAGE.fullmatch(command)
    if matched is not None:
        return (["nachricht_als_datei"], [{"kind": "write", "path": None},
                                         {"kind": "bash", "words": shlex.split(matched.group("head")) +
                                          ["-F", _AUTONOMY_FILE], "directory": None}])
    try:
        tree = _sh_parse(command)
    except Exception:  # noqa: BLE001 - a command the parser does not model has no rewrite
        return None
    hints, calls, holes, directory = [], [], {}, None
    if len(tree.items) > 1 or any(len(pipes) > 1 for pipes, _ops in tree.items):
        hints.append("kette_teilen")
    for pipes, _ops in tree.items:
        for pipeline in pipes:
            if any(not isinstance(c, _ShSimple) for c in pipeline):
                return None
            if len(pipeline) > 1:
                gated = [c for c in pipeline if c.words and c.words[0].value in ("git", "gh")]
                if not gated:
                    # a pipe of no git or gh call stays one call: every stage a data step that writes nothing, every
                    # word literal
                    if directory is not None or not all(_autonomy_reads(c) for c in pipeline):
                        return None
                    calls.append({"kind": "bash", "pipe": [[w.value for w in c.words] for c in pipeline],
                                  "directory": None})
                    continue
                if len(gated) != 1 or pipeline[0] is not gated[0] or \
                        not all(_autonomy_reads(c) for c in pipeline[1:]):
                    return None
                hints.append("pipe_teilen")
                pipeline = gated
            cmd = pipeline[0]
            if not cmd.words and cmd.assigns:
                if len(cmd.assigns) != 1 or cmd.redirs:
                    return None
                name, _eq, _value = cmd.assigns[0].raw.partition("=")
                fake = _ShWord(cmd.assigns[0].raw[len(name) + 1:], "", cmd.assigns[0].subs, False, True)
                k = _autonomy_lift(fake, directory, calls)
                if k is None:
                    return None
                holes[name] = k
                hints.append("git_nicht_in_subst")
                continue
            if cmd.words and cmd.words[0].value in ("cd", "pushd") and cmd.words[0].literal:
                if len(cmd.words) != 2 or not cmd.words[1].literal or cmd.assigns or cmd.redirs or \
                        cmd.words[1].value.startswith("-"):
                    return None
                directory = os.path.normpath(os.path.join(directory or cwd, cmd.words[1].value))
                hints.append("git_C_statt_cd")
                continue
            heredoc = [r for r in cmd.redirs if isinstance(r.target, _ShHeredoc)]
            stdin_text = _autonomy_stdin_text(cmd)
            if stdin_text is not None:
                # a text given on stdin by a here-document as `-F -` or `--body-file -`: a Write and the file
                words = _autonomy_call_words(_ShSimple(cmd.assigns, cmd.words, []), directory, holes, calls,
                                             directory or cwd)
                if words is None:
                    return None
                calls.append({"kind": "write", "path": None})
                calls.append({"kind": "bash", "words": [_AUTONOMY_FILE if k == stdin_text else w
                                                        for k, w in enumerate(words)], "directory": directory})
                hints.append("nachricht_als_datei")
                continue
            if heredoc:
                path = _autonomy_heredoc_target(cmd, directory or cwd)
                if path is None:
                    return None
                calls.append({"kind": "write", "path": path})
                hints.append("heredoc_als_datei")
                continue
            lifted_before = len(calls)
            words = _autonomy_call_words(cmd, directory, holes, calls, directory or cwd)
            if words is None:
                return None
            if len(calls) > lifted_before:
                hints.append("git_nicht_in_subst")
            if holes.pop(_AUTONOMY_PWD, None) is not None:
                hints.append("woertlich")
            if "HEAD" in words and not all(w.literal for w in cmd.words):
                hints.append("push_HEAD")
            calls.append({"kind": "bash", "words": words, "directory": directory})
    return (sorted(set(hints), key=_AUTONOMY_HINT_ORDER.index), calls) if calls else None


#: The order in which a rewrite names its hints, the most particular first: the short line names the first.
_AUTONOMY_HINT_ORDER = ("push_HEAD", "git_C_statt_cd", "git_nicht_in_subst", "nachricht_als_datei",
                        "heredoc_als_datei", "pipe_teilen", "woertlich", "kette_teilen")


def _autonomy_reads(cmd: "_ShSimple", words_too: bool = True) -> bool:
    """Whether a simple command may stand in a rewrite beside its git and gh calls: a data step of D72 (_sh_kind) whose
    program word is literal, with no assignment, no redirection and no tee, and with words_too every word literal. A
    carrier, an interpreter, a program the gate does not know and a step that writes may run or change what a git call
    reads (a script a Write wrote, a configuration), so a command with one has no rewrite."""
    return bool(cmd.words) and not cmd.assigns and not cmd.redirs and cmd.words[0].literal and \
        (not words_too or all(w.literal for w in cmd.words)) and cmd.words[0].value != "tee" and \
        _ShStep(cmd, None, False, 1, []).kind == "data"


def _autonomy_stdin_text(cmd: "_ShSimple") -> int | None:
    """The position of the `-` that takes stdin as a text of a git commit (-F, --file) or of a gh call (-F, --body-file)
    whose stdin is one here-document bash expands nothing in, with no other redirection; else None."""
    docs = [r for r in cmd.redirs if isinstance(r.target, _ShHeredoc)]
    if len(docs) != 1 or len(cmd.redirs) != 1 or docs[0].op not in ("<<", "<<-") or docs[0].fd not in ("", "0") or \
            not _autonomy_quiet(docs[0].target) or not cmd.words or cmd.words[0].value not in ("git", "gh"):
        return None
    values = [w.value for w in cmd.words]
    options = ("-F", "--file") if values[0] == "git" else ("-F", "--body-file")
    found = [k + 1 for k, v in enumerate(values[:-1]) if v in options and values[k + 1] == "-"]
    return found[0] if len(found) == 1 and "-" not in values[found[0] + 1:] else None


def _autonomy_quiet(doc: "_ShHeredoc") -> bool:
    """Whether bash expands nothing in a here-document: a quoted marker, or a body with no expansion."""
    return doc.quoted or not doc.subs


def _autonomy_heredoc_target(cmd: "_ShSimple", directory: str) -> str | None:
    """The file `cat > <file> <<MARK` or `tee <file> <<MARK` writes whole from a here-document: the absolute path, or
    None for any other form (an append, more than one target, a word the shell rewrites, another program)."""
    if cmd.assigns or not cmd.words or not all(w.literal for w in cmd.words):
        return None
    head, args = cmd.words[0].value, [w.value for w in cmd.words[1:]]
    others = [r for r in cmd.redirs if not isinstance(r.target, _ShHeredoc)]
    docs = [r.target for r in cmd.redirs if isinstance(r.target, _ShHeredoc)]
    if len(docs) != 1 or not _autonomy_quiet(docs[0]):
        return None
    if head == "cat" and not args and len(others) == 1 and others[0].op == ">" and others[0].fd in ("", "1") and \
            others[0].target.literal:
        target = others[0].target.value
    elif head == "tee" and len(args) == 1 and not args[0].startswith("-") and \
            all(r.op == ">" and r.target.literal and r.target.value == "/dev/null" for r in others):
        target = args[0]
    else:
        return None
    return os.path.normpath(os.path.join(directory, target))


def _autonomy_text(call: dict, shown: bool) -> str:
    """The call as a command: holes as the gate judges them (shown False) or as it names them to the session."""
    if call["kind"] == "write":
        return f"Write {call['path'] or (_AUTONOMY_FILE_SHOWN if shown else _AUTONOMY_FILE)}"
    if "pipe" in call:
        return " | ".join(" ".join(shlex.quote(w) for w in words) for words in call["pipe"])
    hole = _AUTONOMY_HOLE_SHOWN if shown else _AUTONOMY_HOLE
    words = [hole.format(k=w) if isinstance(w, int) else w for w in call["words"]]
    if shown:
        return " ".join(w if w.startswith("<output of call") else _AUTONOMY_FILE_SHOWN if w == _AUTONOMY_FILE
                        else shlex.quote(w) for w in words)
    return " ".join(shlex.quote(w) for w in words)


def _autonomy_write_place(path: str, cwd: str, deadline: float) -> bool:
    """Whether a rewrite may name a Write of path: inside the work tree of cwd (not its .git) or inside the temp folder,
    and no part of the path below that place starts with a dot (a configuration such as ~/.bashrc or .git/config, which
    a later program reads, is no text the session hands over)."""
    real = os.path.realpath(path)
    top, _why = _work_tree(cwd, deadline)
    for place in [p for p in (top, tempfile.gettempdir()) if p]:
        base = os.path.realpath(place)
        if real.startswith(base + os.sep):
            return not any(part.startswith(".") for part in os.path.relpath(real, base).split(os.sep))
    return False


def _autonomy_judge(call: dict, cwd: str, deadline: float, environ: dict) -> tuple[str, str]:
    """("free" | "external" | "blocked", why) for one call of a rewrite: the gate's own answer to it in the same
    context, with D85 for a single call. A write is free where decide_write leaves it alone."""
    if call["kind"] == "write":
        if call["path"] is not None and not _autonomy_write_place(call["path"], cwd, deadline):
            return "blocked", "a Write the rewrite names goes only into the work tree or the temp folder, to no hidden file"
        out = decide_write("Write", {"file_path": call["path"] or _AUTONOMY_FILE, "content": ""}, cwd, deadline,
                           host="claude", environ=environ)
        return ("free", "") if out is None else ("blocked", f"the Write of it is {out.decision}")
    text = _autonomy_text(call, shown=False)
    directory = call["directory"] or cwd
    out = decide(text, directory, deadline, "claude", environ)
    if out is not None and out.decision == "ask":
        out = _autonomy_external(out, text, directory, deadline, environ) or \
            _autonomy_recorded(out, text, directory, deadline, environ) or \
            _autonomy_pinned(out, text, directory, deadline, environ) or \
            _autonomy_local(out, text, directory, deadline, environ) or out   # D106, D114 and D115, D91
        if out.decision == "ask" and (out.autonomy or {}).get("klasse") == "aussen":
            return "external", ""
    if out is None or out.decision in _AUTONOMY_FREE:
        return "free", ""
    reasons = ", ".join(dict.fromkeys(v.reason_id for v in out.verdicts if v.decision == out.decision))
    return "blocked", f"`{_autonomy_text(call, shown=True)}` alone is {out.decision} ({reasons})"


def _autonomy_checked(command: str, cwd: str, deadline: float, environ: dict) -> tuple | None:
    """(hint ids, calls, judgements) of a rewrite whose every call the gate judged free or an external effect it asks
    for, at least one of them free or the rewrite one call; else (None, None, why) with why the first call that is
    neither, or _AUTONOMY_ONLY_EXTERNAL where every call of a rewrite of several is an external effect (splitting them
    would only add clicks, so the ask stays)."""
    rewrite = _autonomy_rewrite(command, cwd)
    candidates = [rewrite] if rewrite is not None else []
    spelled = _narrower_spelling(command)
    if spelled is not None:
        candidates.append((["woertlich"], [{"kind": "bash", "words": shlex.split(spelled), "directory": None}]))
    why = None
    for hints, calls in candidates:
        judged = [_autonomy_judge(call, cwd, deadline, environ) for call in calls]
        blocked = [w for kind, w in judged if kind == "blocked"]
        if not blocked and (len(calls) == 1 or any(kind == "free" for kind, _w in judged)):
            return hints, calls, judged
        why = why or (blocked[0] if blocked else _AUTONOMY_ONLY_EXTERNAL)
    return None, None, why


def autonomous_outcome(outcome: "Outcome | None", command: str | None, cwd: str, deadline: float,
                       host: str = "claude", environ: dict | None = None, tool: str = "Bash",
                       take: bool = True) -> "Outcome | None":
    """The answer of the hook to the outcome of decide() under Claude Code with --autonomous: D85 to D92
    (_autonomy_answer), D93 for an ask of the closed list in the work profile of b7n0de (_autonomy_card), and D111 for
    a Bash call decide() asked about that the owner released on a card (_autonomy_release). take writes the use of such
    a release before the pass; tool_outcome leaves the use to the hook, which writes it only where the call runs
    (release_settle, D119)."""
    answer = _autonomy_answer(outcome, command, cwd, deadline, host, environ, tool)
    if host != "claude" or answer is None:
        return answer
    environ = os.environ if environ is None else environ
    if answer.decision == "ask":
        answer = _autonomy_card(answer, command, cwd, deadline, environ, tool)
    if tool == "Bash" and outcome is not None and outcome.decision == "ask" and answer.decision in ("ask", "deny"):
        released = _autonomy_release(answer, command, environ, take=take)   # D111, D119
        if released is not None:
            return released
    return answer


def _autonomy_answer(outcome: "Outcome | None", command: str | None, cwd: str, deadline: float,
                     host: str = "claude", environ: dict | None = None, tool: str = "Bash") -> "Outcome | None":
    """D85: the answer of the hook to the outcome of decide() under Claude Code. An ask for a single call
    with an external effect of AUTONOMY_EFFECTS, a change of a done order and a gated MCP tool stays an ask (an owner
    click). Every other ask becomes a deny: with a rewrite hint where the gate judged every call of the rewrite free
    or an external effect it asks for, and at least one free (_autonomy_checked), else with none ("kein freier Weg").
    Nothing gets freer: every other answer, and every answer under Codex, stays as decide() gave it. The record of the
    answer is outcome.autonomy (klasse aussen, umweg or sperre); the log keeps what decide() gave as the verdict."""
    if host != "claude" or outcome is None or outcome.decision != "ask":
        return outcome
    environ = os.environ if environ is None else environ
    if tool.startswith("mcp__"):
        return _autonomy_record(outcome, "aussen", wirkung=[_AUTONOMY_MCP.get(tool.rsplit("__", 1)[-1], "gh_write")])
    if tool == "Bash" and command is not None:
        kept = _autonomy_external(outcome, command, cwd, deadline, environ)
        if kept is not None:
            return kept
        recorded = _autonomy_recorded(outcome, command, cwd, deadline, environ)   # D106, the rule of D114
        if recorded is not None:
            return recorded
        pinned = _autonomy_pinned(outcome, command, cwd, deadline, environ)   # D114, D115
        if pinned is not None:
            return pinned
        local = _autonomy_local(outcome, command, cwd, deadline, environ)   # D91
        if local is not None:
            return local
        try:
            hints, calls, judged = _autonomy_checked(command, cwd, deadline, environ)
        except GateError as exc:
            hints, calls, judged = None, None, f"the check of a rewrite reached no result ({exc})"
    else:
        hints, calls, judged = None, None, f"a {tool} call has no rewrite"
    if judged == _AUTONOMY_ONLY_EXTERNAL:
        return _autonomy_record(outcome, "aussen", wirkung=["mehrere"])
    if hints is not None:
        lines = []
        for k, (call, (kind, _why)) in enumerate(zip(calls, judged), start=1):
            asked = " (the gate asks the owner for this one: an external effect)" if kind == "external" else ""
            lines.append(f"{k}. `{_autonomy_text(call, shown=True)}`{asked}")
        hint = "; ".join(_AUTONOMY_HINTS[h][0] for h in hints)
        lead = (f"proofbundle gate, autonomous operation (D85): this command is not run as written. It is no external "
                f"effect the gate asks the owner about, and the gate checked a rewrite of it now. Rewrite: {hint}. Run "
                f"instead, one call per tool call: " + " ".join(lines) + ". The reason the command was not free:")
        detail = f"{lead.split(' The reason')[0]}"
        verdict = Verdict("deny", detail, "autonomy_rewrite", evidence="the words of the command and the gate's answer "
                          "to each call of the rewrite", failed="the command as written is not free",
                          next_step=hint)
        shown = [_autonomy_text(call, shown=True) for call in calls]
        new = Outcome("deny", f"{lead} {outcome.text}", list(outcome.verdicts) + [verdict], None, step=outcome.step,
                      cause=outcome.cause or next((v for v in outcome.verdicts if v.decision == "ask"), None))
        return _autonomy_record(new, "umweg", hinweise=hints, aufrufe=shown, folgen=_autonomy_follows(calls))
    lead = (f"proofbundle gate, autonomous operation (D85): this command is blocked. {_AUTONOMY_NO_WAY[0]}. The gate "
            f"found no rewrite it lets run ({judged or 'none'}). The reason the command was not free:")
    verdict = Verdict("deny", lead.split(" The reason")[0], "autonomy_blocked", evidence="the words of the command",
                      failed="no form of the call is free and it is no external effect", next_step=_AUTONOMY_NO_WAY[0])
    new = Outcome("deny", f"{lead} {outcome.text}", list(outcome.verdicts) + [verdict], None, step=outcome.step,
                  cause=outcome.cause or next((v for v in outcome.verdicts if v.decision == "ask"), None))
    return _autonomy_record(new, "sperre", hinweise=[])


# --- D86: the targets of a push, measured from its words, its refspecs and the local refs -----

_PushMeasure = collections.namedtuple("_PushMeasure", "force mirror delete tags remote dests repo why")
"""What D86 reads of a `git push` without the network: whether it forces (-f, --force, --force-with-lease,
--force-if-includes, a `+` refspec), mirrors, deletes (-d, --delete, --prune, `:dst`) or sends tags (--tags,
--follow-tags, a tag ref); the configured remote it names; the full refs it updates (None where it cannot name them);
the repository; and why it could not measure (None where it could)."""
#: The long options of git push 2.43 that D86 reads, by what they make the push do (None: nothing D86 counts).
_PUSH_LONG = {"--force": "force", "--force-if-includes": "force", "--mirror": "mirror", "--all": "all",
              "--branches": "all", "--tags": "tags", "--follow-tags": "tags", "--delete": "delete", "--prune": "delete",
              "--set-upstream": None, "--quiet": None, "--verbose": None, "--progress": None, "--no-progress": None,
              "--porcelain": None, "--dry-run": None, "--atomic": None, "--no-atomic": None, "--thin": None,
              "--no-thin": None, "--ipv4": None, "--ipv6": None, "--no-signed": None, "--verify": None,
              "--no-verify": None, "--no-force-with-lease": None, "--no-force-if-includes": None,
              "--no-recurse-submodules": None}
_PUSH_SHORT = {"f": "force", "d": "delete", "u": None, "q": None, "v": None, "n": None, "4": None, "6": None}
#: The branches D86 counts as protected, beside every release/… and the branch the remote's HEAD names here (AGENTS.md:
#: main and the release branch grow only through the maintainer).
_PUSH_PROTECTED = frozenset({"refs/heads/main", "refs/heads/master", "refs/heads/release"})


def _push_measure(words: list[str], cwd: str, deadline: float) -> _PushMeasure:
    """D86: the measure of a `git [-C <dir>] push …` (words with `git` first), from its words, the push configuration
    git reads for a push without refspec (_default_push) and the local refs; never the network."""
    flags, why, i, directory = set(), None, 1, cwd
    while i < len(words) and words[i].startswith("-"):
        if words[i] == "-C" and i + 1 < len(words):
            directory, i = os.path.join(directory, words[i + 1]), i + 2
            continue
        if words[i] != "--no-pager":
            why = why or f"the global option {words[i].partition('=')[0]} of git"
        i += 2 if words[i] in _GIT_GLOBAL_VALUE else 1
    if i >= len(words) or words[i] != "push":
        return _PushMeasure(False, False, False, False, None, None, None, "no push")
    positional, done, i = [], False, i + 1
    while i < len(words):
        word = words[i]
        i += 1
        if not done and word == "--":
            done = True
        elif not done and word.startswith("--"):
            name, eq, _value = word.partition("=")
            if name == "--force-with-lease":
                flags.add("force")
            elif name in ("--signed", "--push-option"):
                i += 1 if (name == "--push-option" and not eq) else 0
            elif name in _PUSH_LONG and not eq:
                flags.add(_PUSH_LONG[name])
            else:
                why = why or f"the option {name}"
        elif not done and word.startswith("-") and word != "-":
            if word == "-o":
                i += 1
                continue
            for letter in word[1:]:
                if letter not in _PUSH_SHORT:
                    why = why or f"the option -{letter}"
                    break
                flags.add(_PUSH_SHORT[letter])
        else:
            positional.append(word)
    force, mirror = "force" in flags, "mirror" in flags
    delete, tags = "delete" in flags, "tags" in flags
    repo, unreadable = _work_tree(directory, deadline)
    if repo is None:
        return _PushMeasure(force, mirror, delete, tags, None, None, None, unreadable or "no work tree")
    remotes = _remote_names(repo, deadline) or set()
    remote, specs = (positional[0], positional[1:]) if positional else (None, [])
    dests: list | None = []
    if remote is None:
        try:
            default = _default_push(repo, deadline, remotes, None)
        except GateError:
            default = None
        if default is None:
            return _PushMeasure(force, mirror, delete, tags, None, None, repo,
                                why or "the push names no remote and git pushes no single branch by default")
        remote, dests = default[0], [default[1]]
    if remote not in remotes:
        return _PushMeasure(force, mirror, delete, tags, None, None, repo,
                            why or "the remote is a URL or a path, not a configured name")
    if mirror:
        dests = None
    elif "all" in flags:
        listed = _git(repo, "for-each-ref", "--format=%(refname)", "refs/heads/", deadline=deadline)
        dests = (_git_lines(listed.stdout) or []) if listed.returncode == 0 else None
    elif not specs and positional:
        try:
            default = _default_push(repo, deadline, remotes, remote)
        except GateError:
            default = None
        dests = [default[1]] if default is not None and not tags else ([] if tags else None)
    if delete:
        # --delete names branches of the remote, not local sources (git push --delete <remote> <ref>…)
        specs, dests = [], [s if s.startswith("refs/") else f"refs/heads/{s}" for s in specs] if dests is not None else None
    for spec in specs:
        if spec.startswith("+"):
            force, spec = True, spec[1:]
        if "*" in spec or spec.startswith("^") or dests is None:
            dests = None
            continue
        src, sep, dst = spec.partition(":")
        if sep and not src:
            delete = True
            dests.append(dst if dst.startswith("refs/") else f"refs/heads/{dst}")
            continue
        full = _source_full_name(repo, src, deadline)
        if not sep:
            if full is None:
                dests = None
                continue
            dests.append(full)
        elif dst.startswith("refs/"):
            dests.append(dst)
        elif full is not None and full.startswith(("refs/heads/", "refs/tags/")):
            dests.append(full[:full.index("/", 5) + 1] + dst)
        else:
            dests = None
    tags = tags or any(d.startswith("refs/tags/") for d in dests or [])
    return _PushMeasure(force, mirror, delete, tags, remote, dests, repo,
                        why if dests is not None or mirror else (why or "a refspec names no single ref here"))


def _push_protected(repo: str, remote: str | None, dest: str, deadline: float) -> bool:
    """Whether dest is a protected branch of D86: main, master, release, every release/…, and the branch the remote's
    HEAD names in this repository (refs/remotes/<remote>/HEAD)."""
    if dest in _PUSH_PROTECTED or dest.startswith("refs/heads/release/"):
        return True
    if remote is None:
        return False
    head = _git(repo, "symbolic-ref", "--quiet", f"refs/remotes/{remote}/HEAD", deadline=deadline)
    named = _git_value(head.stdout) if head.returncode == 0 else None
    return named is not None and named == f"refs/remotes/{remote}/{dest.removeprefix('refs/heads/')}"


#: The reasons of D86, each with the text of its verdict and its next step.
_PUSH_REASONS = {
    "push_force": ("a forced push (-f, --force, --force-with-lease, --force-if-includes or a `+` refspec) overwrites "
                   "commits of others on the remote", "push without force; history that must be replaced is replaced "
                                                      "by a person"),
    "push_mirror": ("a mirror push replaces every ref of the remote and deletes every ref this repository lacks",
                    "push the branch by its name; a mirror is made by a person"),
    "push_protected": ("main, master, release, every release/… and the branch the remote's HEAD names grow only "
                       "through a pull request with its required checks", "push your own work branch and open a pull "
                                                                          "request, which the maintainer merges"),
    "push_unmeasured": ("the gate cannot measure from the words of the push and the local refs where it goes",
                        "push to a configured remote by its name with an explicit refspec, `git push <remote> "
                        "<branch>:refs/heads/<branch>`, as one call of its own"),
    "push_delete": ("the push deletes a branch of the remote", "the gate asks the owner"),
}


def _autonomy_push(outcome: "Outcome", words: list[str], cwd: str, deadline: float, environ: dict) -> "Outcome":
    """D86 for an ask of decide() for one `git push` call under Claude Code: a deny of its own reason for force, a
    mirror, a protected branch and a push whose targets the gate cannot measure; an ask of its own reason for a push
    that deletes a remote branch; an ask of the closed list for a tag and for every other branch; and D87 for the own
    work branch under the standing GO."""
    m = _push_measure(words, cwd, deadline)
    reason, dest = None, None
    if m.force:
        reason = "push_force"
    elif m.mirror:
        reason = "push_mirror"
    else:
        dest = next((d for d in m.dests or [] if _push_protected(m.repo, m.remote, d, deadline)), None)
        if dest is not None:
            reason = "push_protected"
        elif m.dests is None or m.why is not None:
            reason = "push_unmeasured"
    if reason is not None:
        said, step = _PUSH_REASONS[reason]
        where = f" ({dest})" if dest else (f" ({m.why})" if reason == "push_unmeasured" and m.why else "")
        verdict = Verdict("deny", f"proofbundle gate: {said}{where}, so the gate blocks the push in autonomous "
                                  "operation (DECISIONS.md D86).", reason,
                          evidence="the words of the push, its refspecs and the local refs, never the network",
                          failed=f"{said}{where}", next_step=step, repo=m.repo)
        new = Outcome("deny", f"{verdict.text()} {outcome.text}", list(outcome.verdicts) + [verdict], None,
                      step=outcome.step, cause=verdict)
        return _autonomy_record(new, "push", grund=reason)
    if m.delete:
        said, step = _PUSH_REASONS["push_delete"]
        verdict = Verdict("ask", f"proofbundle gate: {said} (DECISIONS.md D86).", "push_delete",
                          evidence="the words of the push", failed=said, next_step=step, repo=m.repo)
        new = Outcome("ask", f"{verdict.text()} {outcome.text}", list(outcome.verdicts) + [verdict], None,
                      step=outcome.step, cause=verdict)
        return _autonomy_record(new, "aussen", wirkung=["push_delete"])
    if m.tags:
        return _autonomy_record(outcome, "aussen", wirkung=["tag"])
    return _autonomy_go(outcome, m, words, deadline, environ) or _autonomy_record(outcome, "aussen", wirkung=["push"])


# --- D87: a push to the own work branch under the standing GO, once measured -----------------

#: D87 and D92: the destinations of the standing GO are branches; which branch is the own one D92 measures
#: (_go_source): the local branch of the same name, neither the default branch nor a protected one (O37-3).
GO_BRANCHES = "refs/heads/"


def _go_source(m: "_PushMeasure", words: list[str], deadline: float) -> tuple[str, str] | None:
    """D92: (the full name, the commit) of the one local branch the push sends, where it is the branch of the same name
    as the destination D86 measured (a refspec `<branch>`, `<branch>:<branch>`, `HEAD` on that branch, or no refspec
    where the push configuration names that branch), and the remote's HEAD is recorded here, so the default branch is
    measured (_push_protected); else None."""
    _remote, specs, _options, unmodeled = _push_words(words[words.index("push") + 1:])
    if unmodeled is not None or len(specs) > 1 or not m.dests or len(m.dests) != 1:
        return None
    src = specs[0].partition(":")[0] if specs else "HEAD"
    full, commit = _source_full_name(m.repo, src, deadline), _push_source(m.repo, src, deadline)
    recorded = _git(m.repo, "symbolic-ref", "--quiet", f"refs/remotes/{m.remote}/HEAD", deadline=deadline)
    if full != m.dests[0] or commit is None or recorded.returncode != 0:
        return None
    return full, commit


def _go_rules_equal(m: "_PushMeasure", words: list[str], deadline: float) -> bool:
    """D87, the evidence rules of D20: the rules at the commit the push sends (_rules_at) equal those at every local
    record of its destination (_destination_records), or, where there is none (a new branch), those at the local record
    of the branch the remote's HEAD names (refs/remotes/<remote>/HEAD), the branch the work goes back to. No record,
    an unreadable side or a difference keeps the ask."""
    _remote, specs, _options, unmodeled = _push_words(words[words.index("push") + 1:])
    if unmodeled is not None or len(specs) > 1:
        return False
    src, sep, dst = (specs[0].partition(":") if specs else ("HEAD", "", ""))
    source = _push_source(m.repo, src, deadline)
    value = (dst if sep else _source_full_name(m.repo, src, deadline)) if specs else m.dests[0]
    if source is None or value is None:
        return False
    records, _why = _destination_records(m.repo, m.remote, [value], deadline)
    if records is None:
        return False
    commits = [commit for _local, _name, commit in records]
    if not commits:
        head = _git(m.repo, "rev-parse", "--verify", "--quiet", f"refs/remotes/{m.remote}/HEAD^{{commit}}",
                    deadline=deadline)
        if head.returncode != 0 or not head.stdout.strip():
            return False
        commits = [head.stdout.decode().strip()]
    rules = _rules_at(m.repo, source, deadline)
    return rules[0] != "unreadable" and all(_rules_at(m.repo, commit, deadline) == rules for commit in commits)


def _autonomy_go(outcome: "Outcome", m: "_PushMeasure", words: list[str], deadline: float,
                 environ: dict) -> "Outcome | None":
    """D87: a pass for one `git push` under Claude Code whose every condition the gate measured: decide() asked only
    because the destination's state on the remote is not measured (push_not_measured), after the evidence at every
    commit the push sends showed no failure (Verdict.sources_clean); D86 measured exactly one destination, an own work
    branch (GO_WORK_BRANCH_PREFIX and the branch grammar of the fetch form), with no force, mirror, deletion or tag, to
    a configured remote; the repository is one of D71 (it declares, and every URL of every remote is a repository of
    WORK_OWNER on github.com); the push configuration adds nothing the command does not name and the push URL is the
    fetch URL; GIT_NAMESPACE is unset; the evidence rules at the commit it sends equal those of a local record
    (_go_rules_equal, D20). Else None, and the ask stays."""
    dests = m.dests or []
    if len(dests) != 1 or not dests[0].startswith(GO_BRANCHES) or m.force or m.mirror or m.delete or \
            m.tags or m.why is not None or m.remote is None or m.repo is None:
        return None
    if not _fetch_branch(dests[0][len("refs/heads/"):]) or _git_namespace() is not None:
        return None
    if not outcome.verdicts or any(v.reason_id != "push_not_measured" or not v.sources_clean
                                   for v in outcome.verdicts):
        return None
    try:
        source = _go_source(m, words, deadline)   # D92
        if source is None or _work_repo_problem(m.repo, deadline, environ) is not None or \
                _push_config_problem(m.repo, deadline, []) is not None or \
                _push_adds_unnamed_refs(m.repo, m.remote, deadline) or \
                not _endpoint_consistent(m.repo, m.remote, deadline) or \
                not _go_rules_equal(m, words, deadline):
            return None
    except GateError:
        return None
    verdict = Verdict("pass", f"proofbundle gate: the push to {dests[0]} is free under the standing GO for work "
                              f"branches. The gate measured its one destination, the own work branch (the local "
                              f"branch of the same name, neither the default branch nor a protected one), from its "
                              f"words and the local refs, with no force, mirror, deletion or tag; the repository at "
                              f"{m.repo} declares, every remote of it is a repository of {WORK_OWNER} on github.com, "
                              "the evidence at every commit the push sends showed no failure, and the push "
                              "configuration adds nothing the command does not name. The receipt stands in the gate "
                              "log (DECISIONS.md D87, D92).", "free_work_branch_go", repo=m.repo)
    new = Outcome("pass", verdict.text(), list(outcome.verdicts) + [verdict], None, step=outcome.step)
    return _autonomy_record(new, "go", wirkung=["push"],
                            quittung={"art": "push", "ziel": dests[0], "remote": m.remote, "commit": source[1],
                                      "pruefung": ["ziel_gemessen", "eigener_zweig", "kein_standardzweig",
                                                   "belege_ohne_fehler", "regeln_gleich"]})


# --- D88: owner clicks, detours, catches and blocks, in the log and the bilanz ---------

#: The reasons of an ask or a deny in which the gate caught a danger it names (D88, owner question O35-5): a turned-off
#: check, a write to the gate or the hooks, a house rule, evidence that failed, a push it blocks or asks for by its
#: target, code that starts git, a change of a done order. Every other reason is NOT MEASURED, which is no catch.
FANG_REASONS = frozenset({
    "hooks_disabled", "write_to_gate_dir", "write_to_repo_state", "house_admin_merge", "house_protection_api",
    "house_kill_own", "house_kill_pattern", "house_tag_out", "verification_failed", "not_done", "no_receipt",
    "stale_receipt", "other_selection", "not_bound", "stale_subject", "rules_changed", "possible_unmodeled_push",
    "code_names_git", "program_word_unknown", "done_order_change", "handover_refused", "push_force", "push_mirror",
    "push_protected", "push_delete", "push_unmeasured", "write_to_declaration", "write_to_shell_start",
    "write_to_host_settings", "secret_path", "upload_to_host", "delete_outside_work", "append_outside_work",
    "text_literal_newline", "text_form_red", "house_pr_limit_reached", "house_own_door_root", "house_own_door_pypi",
    "house_own_door_signature"})
AUTONOMY_STATE = "autonomy-state.json"
AUTONOMY_STATE_SCHEMA = "proofbundle-plugin/autonomy-state/v0.1"
MAX_AUTONOMY_STATE_BYTES = 256 * 1024
_AUTONOMY_KEEP_SESSIONS = 64
_AUTONOMY_KEEP_PENDING = 8
BILANZ_SCHEMA = "b7n0de.plugin_bilanz"


def _autonomy_key(words: list) -> str:
    """The key of a call's words for the follow of a detour: sha256 of the words, a hole as one byte 0 (D88). The state
    keeps keys, never the words, as a command may name a value the gate must not keep."""
    joined = "\x1f".join("\x00" if isinstance(w, int) else w for w in words)
    return hashlib.sha256(joined.encode("utf-8", "surrogateescape")).hexdigest()


def _autonomy_follows(calls: list) -> list:
    """The follows of a detour's calls: per bash call of one simple command its word count, its hole positions and
    its key; per Write of a named file the key of the path."""
    follows = []
    for call in calls:
        if call["kind"] == "write" and call["path"]:
            follows.append({"write": _autonomy_key([os.path.realpath(call["path"])])})
        elif call["kind"] == "bash" and "words" in call:
            words = [w if isinstance(w, int) or w != _AUTONOMY_FILE else 0 for w in call["words"]]
            follows.append({"n": len(words), "holes": [k for k, w in enumerate(words) if isinstance(w, int)],
                            "key": _autonomy_key(words)})
    return follows


def _autonomy_matches(follow: dict, tool: str, event: dict) -> bool:
    """Whether a later call of the session is the call a follow names: the same words with any word in a hole, or a
    Write or Edit of the same file."""
    if "write" in follow:
        path = (event.get("tool_input") or {}).get("file_path") if isinstance(event.get("tool_input"), dict) else None
        return tool in FILE_WRITE_TOOLS and isinstance(path, str) and \
            _autonomy_key([os.path.realpath(path)]) == follow["write"]
    if tool != "Bash":
        return False
    try:
        command, _cwd = _command_from_event(event)
    except GateError:
        return False
    words = _autonomy_single(command)
    if words is None or len(words) != follow["n"]:
        return False
    return _autonomy_key([0 if k in follow["holes"] else w for k, w in enumerate(words)]) == follow["key"]


def _autonomy_track(host: str, event: object, outcome: "Outcome | None", environ: dict | None = None) -> dict | None:
    """D88: the detour a call completes, {"hinweise", "seit"}, or None; and the state of pending detours kept up to
    date. A call that runs (no answer, pass, inactive, hand-over) completes the oldest pending detour of its session one
    of whose follows it matches; a deny with a rewrite (D85) adds one. The state lies in the plugin data directory, per
    session by the sha256 of its id, at most _AUTONOMY_KEEP_PENDING per session and _AUTONOMY_KEEP_SESSIONS sessions.
    Never raises, never changes an answer."""
    if host != "claude" or not isinstance(event, dict) or not isinstance(event.get("session_id"), str):
        return None
    directory = log_directory(host, environ)
    if directory is None:
        return None
    path = os.path.join(directory, AUTONOMY_STATE)
    try:
        try:
            raw = _read_regular(path, MAX_AUTONOMY_STATE_BYTES + 1)
            state = json.loads(raw) if len(raw) <= MAX_AUTONOMY_STATE_BYTES else {}
        except FileNotFoundError:
            state = {}
        if not isinstance(state, dict) or state.get("schema") != AUTONOMY_STATE_SCHEMA or \
                not isinstance(state.get("sessions"), dict):
            state = {"schema": AUTONOMY_STATE_SCHEMA, "sessions": {}}
        session = hashlib.sha256(event["session_id"].encode("utf-8", "surrogateescape")).hexdigest()[:32]
        pending = state["sessions"].get(session, [])
        tool = event.get("tool_name") if isinstance(event.get("tool_name"), str) else "Bash"
        done, changed = None, False
        if outcome is None or outcome.decision in ("pass", "inactive", "handover"):
            for item in pending:
                if any(_autonomy_matches(f, tool, event) for f in item.get("folgen", [])):
                    done = {"hinweise": item.get("hinweise", []), "seit": item.get("ts")}
                    pending.remove(item)
                    changed = True
                    break
        autonomy = getattr(outcome, "autonomy", None) if outcome is not None else None
        if autonomy and autonomy.get("klasse") == "umweg" and autonomy.get("folgen"):
            pending.append({"ts": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
                            "hinweise": autonomy.get("hinweise", []), "folgen": autonomy["folgen"]})
            changed = True
        if changed:
            state["sessions"].pop(session, None)
            state["sessions"][session] = pending[-_AUTONOMY_KEEP_PENDING:]
            while len(state["sessions"]) > _AUTONOMY_KEEP_SESSIONS:
                state["sessions"].pop(next(iter(state["sessions"])))
            fd, tmp = tempfile.mkstemp(prefix=".autonomy-", dir=directory)
            with os.fdopen(fd, "w", encoding="utf-8") as handle:
                json.dump(state, handle, sort_keys=True)
            os.replace(tmp, path)
        return done
    except (OSError, ValueError, KeyError, TypeError):
        return None


def _bilanz_lines(paths: list[str]) -> list[dict]:
    lines = []
    for path in paths:
        try:
            raw = _read_regular(path, MAX_LOG_BYTES * 4)
        except OSError:
            continue
        for line in raw.decode("utf-8", "replace").splitlines():
            try:
                entry = json.loads(line)
            except ValueError:
                continue
            if isinstance(entry, dict) and isinstance(entry.get("ts"), str):
                lines.append(entry)
    return sorted(lines, key=lambda e: e["ts"])


def bilanz(entries: list[dict], bahn: str = "proofbundle", period: str = "tag") -> dict:
    """D88: the bilanz of the gate's log per period (a UTC day, or the whole log): calls,
    owner_klicks (asks sent under Claude Code), umwege (calls that completed a detour of D85), faenge (asks and denies
    whose reasons name a caught danger, FANG_REASONS) and sperren (denies sent), with the asks and the denies per
    reason. The fields of schema b7n0de.plugin_bilanz are the order's; the rest of that schema is the review session's (owner
    question O35-6)."""
    periods: dict = {}
    answers = _ask_answers(entries)   # D94
    for entry in entries:
        if entry.get("decision") == "answered":
            continue   # D94: the answer to an ask, no call of its own
        key = entry["ts"][:10] if period == "tag" else "gesamt"
        row = periods.setdefault(key, {"von": entry["ts"], "bis": entry["ts"], "aufrufe": 0, "owner_klicks": 0,
                                       "umwege": 0, "faenge": 0, "sperren": 0, "karten": 0, "freigaben": 0,
                                       "fragen_je_grund": {},
                                       "sperren_je_grund": {}, "antworten_je_grund": {}})
        row["bis"] = entry["ts"]
        row["aufrufe"] += 1
        decision, reasons = entry.get("decision"), entry.get("reason_ids") or []
        if decision == "ask" and entry.get("host") == "claude":
            row["owner_klicks"] += 1
            state = answers.get(entry.get("frage"), "ohne_schluessel")   # D94
            for reason in dict.fromkeys(reasons):
                cell = row["antworten_je_grund"].setdefault(reason, {"fragen": 0, "ja": 0, "nein": 0, "offen": 0,
                                                                     "ohne_schluessel": 0,
                                                                     "fang": reason in FANG_REASONS})
                cell["fragen"] += 1
                cell[state] += 1
        if decision == "deny":
            row["sperren"] += 1
            row["karten"] += "autonomy_card" in reasons   # D93
        if decision in ("ask", "deny"):
            table = row["fragen_je_grund" if decision == "ask" else "sperren_je_grund"]
            for reason in dict.fromkeys(reasons):
                table[reason] = table.get(reason, 0) + 1
            if FANG_REASONS & set(reasons):
                row["faenge"] += 1
        if isinstance(entry.get("umweg"), dict):
            row["umwege"] += 1
        if (entry.get("autonomy") or {}).get("klasse") == "freigabe":
            row["freigaben"] += 1   # D111
    return {"schema": BILANZ_SCHEMA, "bahn": bahn, "zeitraum": period,
            "zeitraeume": [periods[k] for k in sorted(periods)],
            "kandidaten_zum_freigeben": _release_candidates(entries, answers)}


def bilanz_command(argv: list[str]) -> int:
    """`bilanz [--log FILE] [--bahn NAME] [--zeitraum tag|gesamt]`: the bilanz of the gate's log (D88), as JSON on
    stdout. Without --log the log of the plugin data directory of Claude Code, with its rotated part."""
    log, bahn, period, i = None, "proofbundle", "tag", 0
    while i < len(argv):
        if argv[i] in ("--log", "--bahn", "--zeitraum") and i + 1 < len(argv):
            log, bahn, period = ((argv[i + 1], bahn, period) if argv[i] == "--log" else
                                 (log, argv[i + 1], period) if argv[i] == "--bahn" else (log, bahn, argv[i + 1]))
            i += 2
            continue
        print(f"bilanz: unknown argument {argv[i]}", file=sys.stderr)
        return 2
    if period not in ("tag", "gesamt"):
        print("bilanz: --zeitraum is tag or gesamt", file=sys.stderr)
        return 2
    if log is None:
        directory = log_directory("claude")
        if directory is None:
            print("bilanz: no plugin data directory", file=sys.stderr)
            return 2
        log = os.path.join(directory, LOG_NAME)
    result = bilanz(_bilanz_lines([log + ".1", log]), bahn, period)
    result["quelle"] = {"log": os.path.basename(log)}
    sys.stdout.write(json.dumps(result, ensure_ascii=False, sort_keys=True) + "\n")
    return 0


# --- D91: the local class that can be taken back, free in autonomous operation -----------

#: D91: the flags of `git merge-tree` the class takes beside --write-tree, each of which only chooses what it prints.
#: Measured with git 2.43.0 (truth_local_n37.py of the delivery, every hook of githooks(5) a marker, strace -f): the
#: form started no hook and no program and changed no path outside the object store, on a pipe and on a terminal of
#: script(1), with and without a conflict.
_LOCAL_MERGE_TREE_FLAGS = frozenset({"--write-tree", "--name-only", "--no-messages", "--messages", "-z"})
#: A stash entry as `git stash pop` and `git stash apply` take it in D91: stash@{<n>}, no other reflog.
_LOCAL_STASH_ENTRY = re.compile(r"stash@\{(?:0|[1-9][0-9]{0,4})\}")
#: The local forms of D91 that write the work tree: those of D71, and stash pop and apply.
_LOCAL_TREE_WRITERS = _WORK_TREE_WRITERS | {"git stash pop", "git stash apply"}
#: The forms that bring the tree of another commit into the work tree, with the roles of their refs that name it; for
#: merge and rebase the role "commit" is the other side of a merge, every other role a tree the work tree takes whole.
_LOCAL_BRINGS = {"git merge": ("commit",), "git checkout": ("branch", "commit", "start"),
                 "git switch": ("branch", "commit", "start"), "git rebase": ("commit", "branch"),
                 "git stash pop": ("stash",), "git stash apply": ("stash",)}


def _local_merge(args: list[str]) -> tuple | None:
    """The refs of `git merge` with a message of its own, else None: exactly one revision, the flags of
    _WORK_MERGE_FLAGS, and -m/--message <text>, --message=<text>, -F <file> or --file=<file> (a literal file, not
    standard input). Measured (truth_local_n37.py): with a message git starts no editor, on a pipe and on a terminal,
    and runs the hooks of a merge commit as `git merge --no-edit` does."""
    positional, message, i = [], False, 0
    while i < len(args):
        word = args[i]
        if word in ("-m", "--message", "-F") and i + 1 < len(args):
            if word == "-F" and args[i + 1] in ("", "-"):
                return None
            message, i = True, i + 2
            continue
        if word.startswith("--message="):
            message = True
        elif word.startswith("--file="):
            if word[len("--file="):] in ("", "-"):
                return None
            message = True
        elif word not in _WORK_MERGE_FLAGS:
            if word.startswith("-") or not _work_rev(word):
                return None
            positional.append(word)
        i += 1
    return (("commit", positional[0]),) if len(positional) == 1 and message else None


def _local_merge_tree(args: list[str]) -> tuple | None:
    """The refs of `git merge-tree --write-tree [<flag>…] [--merge-base=<rev>] <rev> <rev>`, else None."""
    if "--write-tree" not in args:
        return None
    positional, bases = [], []
    for word in args:
        if word in _LOCAL_MERGE_TREE_FLAGS:
            continue
        if word.startswith("--merge-base="):
            if not _work_rev(word[len("--merge-base="):]):
                return None
            bases.append(("commit", word[len("--merge-base="):]))
        elif word.startswith("-") or not _work_rev(word):
            return None
        else:
            positional.append(("commit", word))
    return tuple(positional + bases) if len(positional) == 2 and len(bases) <= 1 else None


def _local_stash_restore(args: list[str]) -> tuple | None:
    """The stash entry of `git stash pop|apply [-q|--quiet] [--index] [stash@{<n>}]`, else None."""
    entries = []
    for word in args:
        if word in ("-q", "--quiet", "--index"):
            continue
        if entries or not _LOCAL_STASH_ENTRY.fullmatch(word):
            return None
        entries.append(word)
    return (("stash", entries[0] if entries else "stash@{0}"),)


def _local_form(command: str) -> _WorkForm | None:
    """D91: the form of the local class the whole command is, or None: a read, local or target form of D71
    (_work_form, never fetch, ls-remote or gh), or, in the same literal grammar, `git merge` with a message of its own,
    `git merge-tree --write-tree` (kind tree: it writes objects only) and `git stash pop` or `apply`."""
    form = _work_form(command)
    if form is not None:
        return form if form.kind in ("read", "local", "target") else None
    toks = _lex(_drop_comments(command))
    if toks is None or not toks or any(t[0] != "word" or t[2] for t in toks) or _expansion_present(command):
        return None
    words, raws = [t[1] for t in toks], [t[3] for t in toks]
    if raws[0] != "git" or any(_shell_rewrites(raw) for raw in raws):
        return None
    k, directory = 1, None
    if words[1:2] == ["-C"]:
        if len(words) < 4 or not os.path.isabs(words[2]):
            return None
        k, directory = 3, words[2]
    if k >= len(words):
        return None
    sub, args = words[k], words[k + 1:]
    if sub == "merge":
        refs = _local_merge(args)
        return _WorkForm("local", "git merge", directory, refs) if refs is not None else None
    if sub == "merge-tree":
        refs = _local_merge_tree(args)
        return _WorkForm("tree", "git merge-tree", directory, refs) if refs is not None else None
    if sub == "stash" and args[:1] in (["pop"], ["apply"]):
        refs = _local_stash_restore(args[1:])
        return _WorkForm("local", f"git stash {args[0]}", directory, refs) if refs is not None else None
    return None


def _local_refs_problem(form: _WorkForm, directory: str, deadline: float) -> str | None:
    """None when git would take every ref of the form (_work_refs_problem, and a stash entry that names a commit), else
    what it would refuse; such a form changes nothing, and D91 leaves its answer to D85."""
    problem = _work_refs_problem(form, directory, deadline)
    if problem is not None:
        return problem
    for role, word in form.refs:
        if role == "stash" and _git(directory, "rev-parse", "--verify", "--quiet", f"{word}^{{commit}}",
                                    deadline=deadline).returncode != 0:
            return f"{word} names no stash entry"
    return None


def _local_write_problem(form: _WorkForm, directory: str, deadline: float,
                         environ: dict) -> tuple[str, str] | None:
    """("kept", why) where git would refuse the form for its target (a path that exists), ("guarded", why) where the
    form would write a configuration file, a hook or the gate directory (the work-tree guard of D71, decide_write for
    the target of `worktree add` and `bundle create`), else None."""
    if form.name in _LOCAL_TREE_WRITERS:
        guard = _work_tree_guard_problem(directory, deadline)
        if guard is not None:
            return "guarded", guard
    if form.kind == "target":
        role, word = form.refs[0]
        target = os.path.join(directory, word) if role == "file" else word
        if os.path.lexists(target):
            return "kept", f"the target {target} exists"
        written = decide_write("Write", {"file_path": target}, directory, deadline, "claude", environ)
        if written is not None:
            return "guarded", ("a write the gate guards: " +
                               (written.verdicts[0].failed if written.verdicts else written.text))
    return None


def _local_program_problem(form: _WorkForm, directory: str, deadline: float, environ: dict,
                           recorded_hooks: bool = False) -> str | None:
    """None when the check of the form's class finds nothing that starts a program the gate does not see, else what it
    found: the read profile of D34 for a read; the checkout check of D40 for `worktree add`; the state check of D40
    with no hook counted for merge-tree (measured: it starts none) and with the hooks of D71 for every other form,
    with recorded_hooks those the owner recorded left out (D106)."""
    if form.kind == "read":
        bound = [] if _no_terminal_host("claude", environ) else None
        return _read_profile_problem(form.name.split(" ")[1], directory, deadline, environ, inert_pagers=bound)
    if form.name == "git worktree add":
        return _checkout_state_problem(directory, dict(form.refs)["target"], deadline, environ)
    if form.kind == "tree":
        return _add_commit_state_problem(directory, deadline, environ, hook_counts=lambda _name: False,
                                         own_known=_OWN_FSMONITOR)
    return _add_commit_state_problem(directory, deadline, environ, hooks_not_run=_HOOKS_NOT_RUN_BY_WORK,
                                     own_known=_OWN_KNOWN if form.name in _WORK_LFS_FORMS else _OWN_FSMONITOR,
                                     recorded_hooks=recorded_hooks)


def _local_declaration_changes(form: _WorkForm, directory: str, deadline: float) -> bool:
    """Whether the form writes the declaration (DECLARATION) into the work tree: a form of _LOCAL_BRINGS whose other
    tree holds another blob there than HEAD; for the other side of a merge or a rebase only where that side changed
    it since the merge base, and for a stash entry where the entry changed it against its own base. A side git cannot
    read counts as a change."""
    roles = _LOCAL_BRINGS.get(form.name, ())

    def blob(rev: str) -> str | None:
        got = _git(directory, "rev-parse", "--verify", "--quiet", f"{rev}:{DECLARATION}", deadline=deadline)
        return _git_value(got.stdout) if got.returncode == 0 else None

    head = blob("HEAD")
    for role, word in form.refs:
        if role not in roles:
            continue
        other = blob(f"{word}^{{commit}}")
        if role == "stash":
            if other != blob(f"{word}^1"):
                return True
        elif role == "commit" and form.name in ("git merge", "git rebase"):
            base = _git(directory, "merge-base", "HEAD", f"{word}^{{commit}}", deadline=deadline)
            if other != head and (base.returncode != 0 or other != blob(_git_value(base.stdout) or "HEAD")):
                return True
        elif other != head:
            return True
    return False


def _autonomy_local(outcome: "Outcome", command: str, cwd: str, deadline: float, environ: dict) -> "Outcome | None":
    """D91: the answer to an ask of decide() whose every reason is one of _WORK_REPLACEABLE,
    for a command that is one form of the local class (_local_form), in any repository that does not overlap the gate
    directory: a pass where the check of its class finds nothing; a deny where the form would write a configuration
    file, a hook or the gate directory (write_to_repo_state) or the declaration (write_to_declaration); the ask kept
    where it starts a program of the clone the gate does not see (local_program, owner question O37-1). None where the
    command is no such form or git would refuse it, and D85 answers."""
    if not outcome.verdicts or any(v.reason_id not in _WORK_REPLACEABLE for v in outcome.verdicts):
        return None
    form = _local_form(command)
    if form is None:
        return None
    directory = os.path.realpath(form.directory if form.directory is not None else cwd)
    try:
        _paths, problem = _repo_overlap_problem(directory, deadline, environ)
        if problem is not None or _local_refs_problem(form, directory, deadline) is not None:
            return None
        written = _local_write_problem(form, directory, deadline, environ)
        if written is not None and written[0] == "kept":
            return None
        declaration = written is None and _local_declaration_changes(form, directory, deadline)
        program = None if written or declaration else _local_program_problem(form, directory, deadline, environ)
        recorded = program is not None and form.name in _RECORDED_HOOK_FORMS and \
            _local_program_problem(form, directory, deadline, environ, recorded_hooks=True) is None
    except GateError:
        return None
    if recorded:
        return _recorded_pass(outcome, [form.name], directory)   # D106
    cause = next((v for v in outcome.verdicts if v.decision == "ask"), None)
    if written is not None or declaration:
        reason = "write_to_repo_state" if written is not None else "write_to_declaration"
        said = written[1] if written is not None else f"it writes the evidence declaration {DECLARATION}"
        verdict = Verdict("deny", f"proofbundle gate: {form.name} is local, but {said}; the local class is free only "
                                  "where it writes no configuration, no hook, nothing of the gate and not the "
                                  "declaration (DECISIONS.md D91).", reason,
                          evidence="the configuration files, the hook directory and the declaration the form writes",
                          failed=said, next_step="a person makes this change", repo=directory)
        new = Outcome("deny", f"{verdict.text()} {outcome.text}", list(outcome.verdicts) + [verdict], None,
                      step=outcome.step, cause=verdict)
        return _autonomy_record(new, "sperre", grund=reason)
    if program is not None:
        verdict = Verdict("ask", f"proofbundle gate: {form.name} is local and can be taken back, but it starts a "
                                 f"program of the clone the gate does not see: {program}. The gate asks the owner "
                                 "(owner question O37-1; DECISIONS.md D91).", "local_program",
                          evidence="the configuration, the hooks and the environment the form reads", failed=program,
                          next_step="the owner answers", repo=directory)
        new = Outcome("ask", f"{verdict.text()} {outcome.text}", list(outcome.verdicts) + [verdict], None,
                      step=outcome.step, cause=cause)
        return _autonomy_record(new, "aussen", wirkung=["programm"])
    verdict = Verdict("pass", f"proofbundle gate: {form.name} is free in autonomous operation: local, without the "
                              f"network, and it can be taken back. The check of its class at {directory} found nothing "
                              "that starts a program, and the form writes no configuration, no hook, nothing of the "
                              "gate and not the declaration (DECISIONS.md D91).", "free_local_reversible",
                      repo=directory)
    new = Outcome("pass", verdict.text(), list(outcome.verdicts) + [verdict], None, step=outcome.step)
    return _autonomy_record(new, "lokal", wirkung=[form.name])


# --- D106: a hook of the own clone is free where the owner recorded the hook state (O39-1) -------------

#: D106: the file in the gate directory, which only a person writes (D25), that records the hooks of a clone:
#: {"schema": HOOK_STATE_SCHEMA, "klone": [{"pfad": <absolute path of the clone>, "haken": {<hook name>: <sha256>}}]}.
#: `proofbundle_gate.py hook-state <path>` prints the entry of a clone as it is now and writes nothing.
HOOK_STATE_FILE = "hook-state.json"
HOOK_STATE_SCHEMA = "proofbundle-plugin/hook-state/v0.1"
MAX_HOOK_STATE_BYTES = 64 * 1024
#: The most bytes of a hook the gate hashes; a larger one is never the recorded hook.
MAX_RECORDED_HOOK_BYTES = 1024 * 1024
#: The forms whose hooks a record frees in autonomous operation: account A's forms of follow-up note 41 (an owner card), as
#: the state check of D3 frees add and commit and the local class of D91 frees commit and merge.
_RECORDED_HOOK_FORMS = frozenset({"git add", "git commit", "git merge"})
#: The evidence of the not-free answer of D3 for each of its two forms (_state_free_verdict).
_STATE_FREE_EVIDENCE = {f"the repository state {name} runs with": name for name in ("git add", "git commit")}
_HOOK_NAME = re.compile(r"[A-Za-z0-9][A-Za-z0-9._-]{0,127}")
_SHA256_HEX = re.compile(r"[0-9a-f]{64}")


def _hook_state_entries(environ) -> list[tuple[str, dict]]:
    """D106: the clones hook-state.json in the gate directory records, each (its path resolved, {hook name: sha256}).
    A file that does not read whole records nothing: no regular file, more than MAX_HOOK_STATE_BYTES, not strict JSON
    (a repeated key), another schema, or an entry, a path, a hook name or a value of another shape."""
    gate_dir = _gate_dir(environ)
    if gate_dir is None or not _owner_state_read(environ):   # D124
        return []
    try:
        raw = _read_regular(os.path.join(gate_dir, HOOK_STATE_FILE), MAX_HOOK_STATE_BYTES + 1)
        data = strict_json(raw) if len(raw) <= MAX_HOOK_STATE_BYTES else None
    except (OSError, ValueError, UnicodeDecodeError):
        return []
    if not isinstance(data, dict) or set(data) != {"schema", "klone"} or data["schema"] != HOOK_STATE_SCHEMA or \
            not isinstance(data["klone"], list):
        return []
    entries = []
    for entry in data["klone"]:
        if not isinstance(entry, dict) or set(entry) != {"pfad", "haken"} or not isinstance(entry["pfad"], str) or \
                not os.path.isabs(entry["pfad"]) or not isinstance(entry["haken"], dict):
            return []
        if not all(_HOOK_NAME.fullmatch(name) and isinstance(sha, str) and _SHA256_HEX.fullmatch(sha)
                   for name, sha in entry["haken"].items()):
            return []
        entries.append((_realpath(entry["pfad"]), dict(entry["haken"])))
    return entries


def _own_hook_directory(paths: dict) -> str | None:
    """D106: the clone's own hook directory, <common directory resolved>/hooks, where git takes the hooks from it; None
    where core.hooksPath names another folder, and where the hook directory is a link (it resolves to another path)."""
    if not paths.get("common") or not paths.get("hooks"):
        return None
    own = os.path.join(_realpath(paths["common"]), "hooks")
    return None if _realpath(paths["hooks"]) != own else own


def _recorded_hooks(paths: dict, environ) -> dict:
    """D106: {hook name: sha256} the owner recorded for the clone at paths, by its work tree or by its common directory
    (a linked work tree shares the hooks of its clone); {} where git does not take the hooks from the clone's own hook
    directory, where no entry names the clone, or where more than one does."""
    if _own_hook_directory(paths) is None:
        return {}
    top, common = paths.get("toplevel"), _realpath(paths["common"])
    found = [hooks for root, hooks in _hook_state_entries(environ)
             if (top and root == _realpath(top)) or _realpath(os.path.join(root, ".git")) == common]
    return found[0] if len(found) == 1 else {}


def _hook_recorded(hooks: str, name: str, recorded: dict) -> bool:
    """D106: whether the hook of that name is the one the owner recorded: a regular file, opened without following a
    link, whose at most MAX_RECORDED_HOOK_BYTES bytes hash to the recorded sha256."""
    want = recorded.get(name)
    if want is None:
        return False
    try:
        raw = _read_regular(os.path.join(hooks, name), MAX_RECORDED_HOOK_BYTES + 1)
    except (OSError, ValueError):
        return False
    return len(raw) <= MAX_RECORDED_HOOK_BYTES and hashlib.sha256(raw).hexdigest() == want


def _recorded_pass(outcome: "Outcome", names: list[str], directory: str) -> "Outcome":
    """D106: the pass of autonomous operation for forms whose only program the state check found is a recorded hook."""
    verdict = Verdict("pass", f"proofbundle gate: {' and '.join(names)} is free in autonomous operation: every hook it "
                              f"starts in the clone at {directory} is one the owner recorded in the hook state of the "
                              "gate directory, with the bytes it holds now, and the state check found nothing else "
                              "that starts a program (O39-1; DECISIONS.md D106).", "free_recorded_hooks",
                      repo=directory)
    new = Outcome("pass", verdict.text(), list(outcome.verdicts) + [verdict], None, step=outcome.step)
    return _autonomy_record(new, "lokal", wirkung=names)


def _autonomy_recorded(outcome: "Outcome", command: str, cwd: str, deadline: float,
                       environ: dict) -> "Outcome | None":
    """D106 (O39-1): the answer to an ask of decide() whose every verdict that is no pass is the not-free
    answer of D3 for `git add` or `git commit` (a form of its own or their chain), for a command of plain git calls only
    (_pinned_command, the rule of D114; follow-up note 51, O46-3): a pass where the state check of each repository finds
    nothing with the hooks the owner recorded left out (_recorded_hooks, _hook_recorded), in a repository that does not
    overlap the gate directory. None otherwise, and D91 and D85 answer. cwd is unused: each verdict names its
    repository."""
    if outcome is None or outcome.decision != "ask" or not _pinned_command(command):
        return None
    asks = [v for v in outcome.verdicts if v.decision != "pass"]
    if not asks or any(v.reason_id != "git_form_not_free" or v.evidence not in _STATE_FREE_EVIDENCE
                       or not isinstance(v.repo, str) or not os.path.isabs(v.repo) for v in asks):
        return None
    directories = list(dict.fromkeys(v.repo for v in asks))
    try:
        for directory in directories:
            _paths, problem = _repo_overlap_problem(directory, deadline, environ)
            if problem is not None or _add_commit_state_problem(directory, deadline, environ, own_known=_OWN_KNOWN,
                                                                recorded_hooks=True) is not None:
                return None
    except GateError:
        return None
    return _recorded_pass(outcome, list(dict.fromkeys(_STATE_FREE_EVIDENCE[v.evidence] for v in asks)),
                          ", ".join(directories))


def hook_state_command(argv: list[str]) -> int:
    """D106: `hook-state <path>` prints the entry of hook-state.json for the clone at path as it is now: its work tree
    and the sha256 of every hook of its own hook directory that is a regular file; a .sample is left out, and so is a
    link or any other entry, named on stderr. It writes nothing: a person reads the entry and copies it into the file.
    Exit 1 where the path is no work tree or git takes the hooks from elsewhere (core.hooksPath, a link), 2 for a
    wrong call."""
    if len(argv) != 1:
        print("usage: proofbundle_gate.py hook-state <path of the clone>", file=sys.stderr)
        return 2
    deadline = time.monotonic() + DEADLINE_SECONDS
    try:
        paths, why = _repo_paths(os.path.abspath(argv[0]), deadline)
    except GateError as exc:
        paths, why = None, str(exc)
    if paths is None or paths["toplevel"] is None:
        print(f"hook-state: no git work tree there ({why or 'not inside one'})", file=sys.stderr)
        return 1
    own = _own_hook_directory(paths)
    if own is None:
        print("hook-state: git takes the hooks of this clone from core.hooksPath or through a link, not from its own "
              "hook directory; D106 records only those", file=sys.stderr)
        return 1
    hooks = {}
    try:
        names = sorted(os.listdir(own)) if os.path.isdir(own) else []
    except OSError as exc:
        print(f"hook-state: the hook directory cannot be read ({_os_error(exc)})", file=sys.stderr)
        return 1
    for name in names:
        if name.endswith(".sample"):
            continue
        try:
            raw = _read_regular(os.path.join(own, name), MAX_RECORDED_HOOK_BYTES + 1)
        except (OSError, ValueError):
            raw = None
        if raw is None or len(raw) > MAX_RECORDED_HOOK_BYTES or not _HOOK_NAME.fullmatch(name):
            print(f"hook-state: left out {name!r}: a link, no regular file, a name of another shape or more than "
                  f"{MAX_RECORDED_HOOK_BYTES} bytes; it stays a hook the gate counts", file=sys.stderr)
            continue
        hooks[name] = hashlib.sha256(raw).hexdigest()
    print(json.dumps({"schema": HOOK_STATE_SCHEMA, "klone": [{"pfad": _realpath(paths["toplevel"]), "haken": hooks}]},
                     indent=2))
    return 0


# --- D114 and D115: the pinned state of the own clone -------------------------------------------

#: D114: the file in the gate directory, which only a person writes (D25), that pins the state of a clone:
#: {"schema": PIN_STATE_SCHEMA, "klone": [{"pfad": <work tree>, "hakenordner": <the hook directory git uses>,
#: "haken": {<hook name>: <sha256>}, "konfig": <sha256 of the clone's .git/config>}]}. `proofbundle_gate.py pin-state
#: <path>` prints the entry of a clone as it is now and writes nothing.
PIN_STATE_FILE = "pin-state.json"
PIN_STATE_SCHEMA = "proofbundle-plugin/pin-state/v0.1"
MAX_PIN_STATE_BYTES = 64 * 1024
#: The most bytes of a pinned .git/config the gate hashes; a larger one is never the pinned one.
MAX_PINNED_CONFIG_BYTES = 1024 * 1024
#: D115: the read forms of the order that the pin frees, each only where the read grammar of D34 took its options.
_PINNED_READS = frozenset({"rev-parse", "status", "log", "show", "diff", "ls-files", "merge-base", "cat-file"})
#: D114: the forms of the state check of D3 the pin frees.
_PINNED_LOCAL = frozenset({"add", "commit"})
#: The evidence of the not-free answer of D3 for a form of the state check or of the read profile.
_PINNED_EVIDENCE = re.compile(r"the repository state git ([a-z-]+) runs with")
#: The own branch of a session: a branch under claude/ with a name after the slash.
_PINNED_BRANCH = re.compile(r"refs/heads/claude/[^\s]+")
#: D115 (follow-up note 46, point 2: no pager, no external diff, no textconv, no fsmonitor): a key whose last part names a
#: program, a driver, a tool, a hook or a signature, which a pin never leaves out of the read profile, though
#: _program_source, written for add and commit, names none: diff.external, the textconv and command of a diff driver,
#: log.showSignature, core.alternateRefsCommand and their kind.
_READ_PROGRAM_KEY = re.compile(r"(command|cmd|program|textconv|tool|driver|process|external|helper|hook|pager|editor|"
                               r"askpass|signature|filter|fsmonitor)[^.]*$")


def _pin_state_entries(environ) -> list[dict]:
    """D114: the clones pin-state.json in the gate directory pins, each {"pfad", "hakenordner", "haken", "konfig"} with
    both paths resolved. A file that does not read whole pins nothing: no regular file, more than MAX_PIN_STATE_BYTES,
    not strict JSON (a repeated key), another schema, or an entry, a path, a hook name or a value of another shape."""
    gate_dir = _gate_dir(environ)
    if gate_dir is None or not _owner_state_read(environ):   # D124
        return []
    try:
        raw = _read_regular(os.path.join(gate_dir, PIN_STATE_FILE), MAX_PIN_STATE_BYTES + 1)
        data = strict_json(raw) if len(raw) <= MAX_PIN_STATE_BYTES else None
    except (OSError, ValueError, UnicodeDecodeError):
        return []
    if not isinstance(data, dict) or set(data) != {"schema", "klone"} or data["schema"] != PIN_STATE_SCHEMA or \
            not isinstance(data["klone"], list):
        return []
    entries = []
    for entry in data["klone"]:
        if not isinstance(entry, dict) or set(entry) != {"pfad", "hakenordner", "haken", "konfig"}:
            return []
        if not all(isinstance(entry[k], str) and os.path.isabs(entry[k]) for k in ("pfad", "hakenordner")) or \
                not isinstance(entry["haken"], dict) or not isinstance(entry["konfig"], str) or \
                not _SHA256_HEX.fullmatch(entry["konfig"]):
            return []
        if not all(_HOOK_NAME.fullmatch(name) and isinstance(sha, str) and _SHA256_HEX.fullmatch(sha)
                   for name, sha in entry["haken"].items()):
            return []
        entries.append({"pfad": _realpath(entry["pfad"]), "hakenordner": _realpath(entry["hakenordner"]),
                        "haken": dict(entry["haken"]), "konfig": entry["konfig"]})
    return entries


def _hooks_now(hooks: str) -> dict | None:
    """{name: sha256} of every entry of the hook directory but a .sample, as pin-state reads it; None where an entry is
    no regular file (a link, a folder, a FIFO), is larger than MAX_RECORDED_HOOK_BYTES or has a name of another shape,
    or the directory cannot be read. {} where the directory does not exist."""
    if not os.path.lexists(hooks):
        return {}
    if not os.path.isdir(hooks) or os.path.islink(hooks):
        return None
    found = {}
    try:
        names = sorted(os.listdir(hooks))
    except OSError:
        return None
    for name in names:
        if name.endswith(".sample"):
            continue
        try:
            raw = _read_regular(os.path.join(hooks, name), MAX_RECORDED_HOOK_BYTES + 1)
        except (OSError, ValueError):
            return None
        if len(raw) > MAX_RECORDED_HOOK_BYTES or not _HOOK_NAME.fullmatch(name):
            return None
        found[name] = hashlib.sha256(raw).hexdigest()
    return found


def _pinned_config_digest(common: str) -> str | None:
    """The sha256 of the clone's .git/config (<common directory>/config), read without following a link; None where it
    is no regular file or larger than MAX_PINNED_CONFIG_BYTES."""
    try:
        raw = _read_regular(os.path.join(common, "config"), MAX_PINNED_CONFIG_BYTES + 1)
    except (OSError, ValueError):
        return None
    return None if len(raw) > MAX_PINNED_CONFIG_BYTES else hashlib.sha256(raw).hexdigest()


def _pinned_hook_place(paths: dict, top: str) -> bool:
    """D114: whether the hook directory git uses lies inside the clone, in its git directory or its work tree; a
    core.hooksPath that points elsewhere is no state of the clone the owner can pin (follow-up note 46: where it points
    elsewhere, the ask stays)."""
    hooks = _realpath(paths["hooks"])
    return _within(hooks, top) or _within(hooks, _realpath(paths["common"]))


def _pinned_clone(directory: str, deadline: float, environ) -> dict | None:
    """D114: the pin of the repository at directory, {"config": <the pinned .git/config, resolved>, "hooks": {name:
    sha256}}, where the condition of follow-up note 46 holds now: exactly one entry of pin-state.json names its work tree; HEAD
    is a branch under claude/; the hook directory git uses for it lies inside the clone (_pinned_hook_place), is the
    pinned one and holds exactly the pinned hooks, each a regular file with the pinned bytes; its .git/config is a
    regular file with the pinned bytes; and there is no config.worktree. None otherwise: then nothing is pinned and
    every check counts as before."""
    paths, _why = _repo_paths(directory, deadline)
    if paths is None or paths["toplevel"] is None or not paths["common"] or not paths["hooks"]:
        return None
    top = _realpath(paths["toplevel"])
    found = [e for e in _pin_state_entries(environ) if e["pfad"] == top]
    if len(found) != 1:
        return None
    entry = found[0]
    head = _git(directory, "symbolic-ref", "-q", "HEAD", deadline=deadline)
    lines = _git_lines(head.stdout) if head.returncode == 0 else None
    if not lines or len(lines) != 1 or not _PINNED_BRANCH.fullmatch(lines[0]):
        return None
    if not _pinned_hook_place(paths, top):
        return None
    if _realpath(paths["hooks"]) != entry["hakenordner"] or _hooks_now(paths["hooks"]) != entry["haken"]:
        return None
    if _pinned_config_digest(paths["common"]) != entry["konfig"]:
        return None
    for base in {paths["gitdir"], paths["common"]}:
        if base and os.path.lexists(os.path.join(base, "config.worktree")):
            return None
    return {"config": _realpath(os.path.join(paths["common"], "config")), "hooks": entry["haken"],
            "toplevel": top}


def _pinned_origin(pin: dict | None, scope: str, origin: str) -> bool:
    """D114: whether a configuration entry comes from the pinned .git/config: scope local and its origin that file (git
    names the repository's own file relative to the work tree, and a linked work tree's absolutely)."""
    if pin is None or scope != "local" or not origin.startswith("file:"):
        return False
    path = origin[len("file:"):]
    if not os.path.isabs(path):
        path = os.path.join(pin["toplevel"], path)
    return _realpath(path) == pin["config"]


#: D114: the program sources of _program_source a pinned key may name without keeping the answer: the default signing
#: program of commit.gpgSign, which git takes from PATH like itself (the D27 class), and git's own automatic
#: maintenance. A filter, a configuration hook, fsmonitor and a signature program a key names by path keep it: such a
#: key points elsewhere.
_PINNED_SOURCES = frozenset({"automatic maintenance"})


def _pinned_source_ok(pin: dict | None, scope: str, origin: str, key: str, source: str) -> bool:
    return _pinned_origin(pin, scope, origin) and (source in _PINNED_SOURCES or (source == "signature program"
                                                                                 and key == "commit.gpgsign"))


def _pinned_pass(outcome: "Outcome", names: list[str], directories: list[str], reads: bool) -> "Outcome":
    """D114 and D115: the pass of autonomous operation for forms whose only finding the pin answers."""
    d = "D115" if reads else "D114"
    verdict = Verdict("pass", f"proofbundle gate: {' and '.join(names)} is free in autonomous operation: the clone at "
                              f"{', '.join(directories)} is the session's own tree on its own claude/ branch, its "
                              "hooks, its hook directory and its .git/config hold the bytes the owner pinned in the "
                              "pin state of the gate directory, and the check found nothing else that starts a program "
                              f"(DECISIONS.md {d}).", "free_pinned_state", repo=", ".join(directories))
    new = Outcome("pass", verdict.text(), list(outcome.verdicts) + [verdict], None, step=outcome.step)
    return _autonomy_record(new, "lokal", wirkung=names)


#: D114, D115: the operators that may join the steps of a command the pin frees.
_PINNED_JOINS = frozenset({"&&", ";"})


def _pinned_command(command: str) -> bool:
    """D114 and D115: whether the whole command is plain git calls of _PINNED_LOCAL and _PINNED_READS joined by `&&` or
    `;`, each `git [-C <absolute path>] <form> …` in the literal grammar: no other program, no redirection, no pipe, no
    expansion and no word the shell may rewrite. Another step of the same line can change a hook or the configuration
    after the gate read them and before git runs them (a write in another language is not gated, D8), so the pin
    answers no such command."""
    toks = _lex(_drop_comments(command))
    if not toks or _expansion_present(command):
        return False
    steps, step = [], []
    for tok in toks:
        if tok[0] == "op" and tok[1] in _PINNED_JOINS and step:
            steps.append(step)
            step = []
        elif tok[0] != "word" or tok[2] or _shell_rewrites(tok[3]) or (not step and tok[3] != "git"):
            return False
        else:
            step.append(tok[1])
    steps += [step] if step else []
    for words in steps:
        k = 3 if words[1:2] == ["-C"] and len(words) > 3 and os.path.isabs(words[2]) else 1
        if k >= len(words) or words[k] not in _PINNED_LOCAL | _PINNED_READS:
            return False
    return bool(steps)


def _autonomy_pinned(outcome: "Outcome", command: str, cwd: str, deadline: float,
                     environ: dict) -> "Outcome | None":
    """D114 and D115: the answer to an ask of decide() whose every verdict that is no pass is the
    not-free answer of D3 for `git add` or `git commit` (the state check) or for a read form of _PINNED_READS (the read
    profile of D34, whose grammar took its options), for a command of plain git calls only (_pinned_command): a pass
    where each repository is pinned now (_pinned_clone), does not overlap the gate directory, and its check finds
    nothing with the pin. None otherwise, and D91 and D85 answer. cwd is unused: each verdict names its repository."""
    if outcome is None or outcome.decision != "ask" or not _pinned_command(command):
        return None
    asks = [v for v in outcome.verdicts if v.decision != "pass"]
    if not asks:
        return None
    forms = []
    for v in asks:
        m = _PINNED_EVIDENCE.fullmatch(v.evidence or "")
        if v.reason_id != "git_form_not_free" or m is None or m.group(1) not in _PINNED_LOCAL | _PINNED_READS or \
                not isinstance(v.repo, str) or not os.path.isabs(v.repo):
            return None
        forms.append((m.group(1), v.repo))
    inert = [] if _no_terminal_host("claude", environ) else None
    try:
        for sub, directory in dict.fromkeys(forms):
            pin = _pinned_clone(directory, deadline, environ)
            _paths, overlap = _repo_overlap_problem(directory, deadline, environ)
            if pin is None or overlap is not None:
                return None
            if sub in _PINNED_LOCAL:
                problem = _add_commit_state_problem(directory, deadline, environ, own_known=_OWN_KNOWN, pin=pin)
            else:
                problem = _read_profile_problem(sub, directory, deadline, environ, inert_pagers=inert, pin=pin)
            if problem is not None:
                return None
    except GateError:
        return None
    names = list(dict.fromkeys(f"git {sub}" for sub, _d in forms))
    return _pinned_pass(outcome, names, list(dict.fromkeys(d for _s, d in forms)),
                        reads=all(sub in _PINNED_READS for sub, _d in forms))


def pin_state_command(argv: list[str]) -> int:
    """D114: `pin-state <path>` prints the entry of pin-state.json for the clone at path as it is now: its work tree,
    the hook directory git uses for it, the sha256 of every hook in it but a .sample, and the sha256 of its .git/config.
    It writes nothing: a person reads the entry and copies it into the file. Exit 1 where the path is no work tree or a
    part cannot be pinned (a hook directory outside the clone, a hook that is a link or no regular file, a
    config.worktree, a .git/config that is no regular file), 2 for a wrong call."""
    if len(argv) != 1:
        print("usage: proofbundle_gate.py pin-state <path of the clone>", file=sys.stderr)
        return 2
    deadline = time.monotonic() + DEADLINE_SECONDS
    try:
        paths, why = _repo_paths(os.path.abspath(argv[0]), deadline)
    except GateError as exc:
        paths, why = None, str(exc)
    if paths is None or paths["toplevel"] is None or not paths["common"] or not paths["hooks"]:
        print(f"pin-state: no git work tree there ({why or 'not inside one'})", file=sys.stderr)
        return 1
    if not _pinned_hook_place(paths, _realpath(paths["toplevel"])):
        print("pin-state: git takes the hooks of this clone from a folder outside it (core.hooksPath); D114 pins only a "
              "hook directory inside the clone", file=sys.stderr)
        return 1
    hooks = _hooks_now(paths["hooks"])
    config = _pinned_config_digest(paths["common"])
    worktree = any(base and os.path.lexists(os.path.join(base, "config.worktree"))
                   for base in (paths["gitdir"], paths["common"]))
    if hooks is None or config is None or worktree:
        print("pin-state: the clone cannot be pinned: a hook is a link, no regular file or of another name, the hook "
              "directory is a link, .git/config is no regular file, or a config.worktree stands beside it",
              file=sys.stderr)
        return 1
    print(json.dumps({"pfad": _realpath(paths["toplevel"]), "hakenordner": _realpath(paths["hooks"]), "haken": hooks,
                      "konfig": config}, indent=2))
    return 0


# --- D92: gh pr edit --body-file with the house's form checker, a receipt in place of a click ---------

#: D92: the house's form checker for the text of a pull request, as the default branch of the remote records it
#: (b7n0de/proofbundle since PR 308: rule (a) a milestone, (b) the house footer at the end, (c) no tool attribution, no
#: session link, no retired sentence). The gate reads it at refs/remotes/<remote>/HEAD, never in the work tree, which
#: the session writes.
HOUSE_FORM_CHECKER = "scripts/b7_pr_form_gate.py"
#: The most bytes of a checker and of a body file the gate reads.
MAX_HOUSE_FORM_CHECKER_BYTES = 512 * 1024
MAX_PR_BODY_BYTES = 256 * 1024
#: The seconds the checker may run at most.
HOUSE_FORM_SECONDS = 20
#: The options of `gh pr edit` D92 takes (gh 2.89.0): the title, the body from a file, the repository.
_PR_EDIT_OPTIONS = {"--title": True, "-t": True, "--body-file": True, "-F": True, "-R": True, "--repo": True}
_PR_EDIT_CANONICAL = {"-t": "--title", "-F": "--body-file", "-R": "--repo"}
#: The program that runs the checker: it loads the checker from the file the gate wrote, judges the text as the body of a
#: pull request through the checker's own judge(), and prints the reasons of rules (b) and (c) as JSON. Rule (a), the
#: milestone, reads no text, and the edit does not change it.
_HOUSE_FORM_DRIVER = """import importlib.util, json, sys
spec = importlib.util.spec_from_file_location("house_form_checker", sys.argv[1])
module = importlib.util.module_from_spec(spec)
spec.loader.exec_module(module)
with open(sys.argv[2], encoding="utf-8") as handle:
    body = handle.read()
reasons, _title = module.judge({"pull_request": {"body": body}})
if not isinstance(reasons, list) or not all(isinstance(r, str) for r in reasons):
    sys.exit(3)
print(json.dumps([r for r in reasons if not r.startswith("(a)")]))
"""


def _pr_edit_form(words: list[str]) -> tuple[str, str | None, str] | None:
    """(number, repository or None, body file) of `gh pr edit <number> [-R <owner>/<repo>] --body-file <file>
    [--title <title>]` with the owner of D71 in -R, no option twice, else None. A title alone is D71's."""
    if words[:3] != ["gh", "pr", "edit"]:
        return None
    parsed = _gh_words(words[3:], _PR_EDIT_OPTIONS)
    if parsed is None:
        return None
    positional, pairs = parsed
    values = {_PR_EDIT_CANONICAL.get(n, n): v for n, v in pairs}
    if len(positional) != 1 or not _WORK_PR_NUMBER.fullmatch(positional[0]) or len(values) != len(pairs) or \
            not values.get("--body-file"):
        return None
    repo = values.get("--repo")
    if repo is not None and (not _WORK_GH_REPO.fullmatch(repo) or _WORK_GH_REPO.fullmatch(repo).group(1) in (".", "..")):
        return None
    return positional[0], repo, values["--body-file"]


def _house_form_checker(directory: str, deadline: float) -> tuple[bytes, str] | None:
    """(the bytes, the blob id) of HOUSE_FORM_CHECKER at the default branch the remote records here: the remote origin,
    or the one remote; None where it is not recorded or holds no such file."""
    remotes = sorted(_remote_names(directory, deadline))
    remote = "origin" if "origin" in remotes else (remotes[0] if len(remotes) == 1 else None)
    if remote is None:
        return None
    got = _git(directory, "rev-parse", "--verify", "--quiet", f"refs/remotes/{remote}/HEAD:{HOUSE_FORM_CHECKER}",
               deadline=deadline)
    blob = _git_value(got.stdout) if got.returncode == 0 else None
    if not blob:
        return None
    content = _git(directory, "cat-file", "blob", blob, deadline=deadline)
    if content.returncode != 0 or len(content.stdout) > MAX_HOUSE_FORM_CHECKER_BYTES:
        return None
    return content.stdout, blob


def _house_form_judge(checker: bytes, body: bytes, deadline: float, rules: tuple | None = None) -> list[str] | None:
    """The reasons of rules (b) and (c) of the house's form checker for the text, from the checker run by this
    interpreter in a folder of its own, with no network the gate opens and only PATH and the locale in its
    environment: the measured reds where there is one; empty where it is green; None where it cannot measure (only a
    NOT MEASURABLE of its own, such as the CommonMark parser rule (c) needs, an error, the time). rules, where given,
    keeps the reasons of those rules only (D109: rule (c) for a text that is no description)."""
    folder = tempfile.mkdtemp(prefix="pb-house-form-")
    try:
        files = {}
        for name, data in (("checker.py", checker), ("body.md", body), ("driver.py", _HOUSE_FORM_DRIVER.encode())):
            files[name] = os.path.join(folder, name)
            with open(files[name], "wb") as handle:
                handle.write(data)
        seconds = min(HOUSE_FORM_SECONDS, deadline - time.monotonic())
        if seconds <= 1:
            return None
        proc = subprocess.run([sys.executable, "-I", files["driver.py"], files["checker.py"], files["body.md"]],
                              cwd=folder, env={"PATH": "/usr/bin:/bin", "LC_ALL": "C.UTF-8"}, capture_output=True,
                              timeout=seconds, stdin=subprocess.DEVNULL)
        if proc.returncode != 0:
            return None
        reasons = json.loads(proc.stdout.decode("utf-8"))
        if not isinstance(reasons, list) or not all(isinstance(r, str) for r in reasons):
            return None
        if rules is not None:
            reasons = [r for r in reasons if r.startswith(rules)]
        red = [r for r in reasons if "NOT MEASURABLE" not in r]
        return red if red or len(red) == len(reasons) else None
    except (OSError, ValueError, subprocess.TimeoutExpired):
        return None
    finally:
        shutil.rmtree(folder, ignore_errors=True)


def _autonomy_pr_edit(outcome: "Outcome", words: list[str], cwd: str, deadline: float,
                      environ: dict) -> "Outcome | None":
    """D92: `gh pr edit <number> --body-file <file>` (with --title and -R of the owner of
    D71) in a repository of D71: a pass with a receipt in the gate log where the house's form checker
    (HOUSE_FORM_CHECKER at the remote's default branch) passes the text; a deny (pr_form_red) with its reasons where it
    finds the text red. None, and the answer of the last class, where the checker is missing or cannot measure, the
    file lies outside the work tree and the temp folder or below a name with a dot, or is no regular UTF-8 file of at
    most MAX_PR_BODY_BYTES. Whose pull request it is, the gate does not measure (no network, owner question O37-4)."""
    form = _pr_edit_form(words)
    if form is None:
        return None
    number, named, body_file = form
    if named is None and environ.get("GH_REPO") is not None and not _WORK_GH_REPO.fullmatch(environ["GH_REPO"]):
        return None
    directory = os.path.realpath(cwd)
    path = os.path.realpath(body_file if os.path.isabs(body_file) else os.path.join(directory, body_file))
    try:
        if _work_repo_problem(directory, deadline, environ) is not None or \
                not _autonomy_write_place(path, directory, deadline):
            return None
        body = _read_regular(path, MAX_PR_BODY_BYTES + 1)
        if len(body) > MAX_PR_BODY_BYTES:
            return None
        body.decode("utf-8")
        found = _house_form_checker(directory, deadline)
        reasons = None if found is None else _house_form_judge(found[0], body, deadline)
    except (GateError, OSError, UnicodeDecodeError):
        return None
    if reasons is None:
        return None
    receipt = {"art": "pr_edit", "pr": number, "repo": named, "pruefer": HOUSE_FORM_CHECKER, "pruefer_blob": found[1],
               "text_sha256": hashlib.sha256(body).hexdigest(), "regeln": ["b", "c"]}
    if reasons:
        said = "; ".join(reasons)
        verdict = Verdict("deny", f"proofbundle gate: the house's form checker ({HOUSE_FORM_CHECKER} at the remote's "
                                  f"default branch) finds the text of the pull request red: {said}. Correct the file "
                                  "and edit again (DECISIONS.md D92).", "pr_form_red",
                          evidence="the text of the body file and the house's form checker", failed=said,
                          next_step="correct the text as the checker names it", repo=directory)
        new = Outcome("deny", f"{verdict.text()} {outcome.text}", list(outcome.verdicts) + [verdict], None,
                      step=outcome.step, cause=verdict)
        return _autonomy_record(new, "sperre", grund="pr_form_red", quittung=receipt)
    verdict = Verdict("pass", f"proofbundle gate: gh pr edit {number} is free in autonomous operation: the house's form "
                              f"checker ({HOUSE_FORM_CHECKER} at the remote's default branch) passes the text of the "
                              f"body file, the repository at {directory} is one of D71, and the receipt stands in the "
                              "gate log (DECISIONS.md D92).", "free_pr_edit_form", repo=directory)
    new = Outcome("pass", verdict.text(), list(outcome.verdicts) + [verdict], None, step=outcome.step)
    return _autonomy_record(new, "maschine", wirkung=["pr"], quittung=receipt)


# --- D93: a card on the owner's decision board in place of an ask in the terminal, in the work profile of b7n0de ----


def _autonomy_profile_directory(command: str, cwd: str) -> str:
    """The directory whose repository the work profile is read in for a Bash call: the literal absolute path of `-C`
    of a single git call, else the hook's directory."""
    words = _autonomy_single(command)
    if words and words[0] == "git" and words[1:2] == ["-C"] and len(words) > 2 and os.path.isabs(words[2]):
        return words[2]
    return cwd


def _autonomy_card(answer: "Outcome", command: str | None, cwd: str, deadline: float, environ: dict,
                   tool: str) -> "Outcome":
    """D93: an ask of the closed list of D85 (klasse aussen, an effect other than the
    programm of D91) in the work profile of b7n0de, the repository of the call one of D71 (_work_repo_problem: Claude
    Code, a declaration at HEAD, every remote a repository of b7n0de on github.com), becomes a deny (autonomy_card) that
    tells the session to put a card on the owner's decision board, where the owner answers (owner word of 2026-10-18, 16:52 Berlin:
    no options in the terminal). Outside that profile, where there is no decision board, and where the profile cannot be
    read, the ask stays."""
    record = getattr(answer, "autonomy", None) or {}
    effects = list(record.get("wirkung") or [])
    if record.get("klasse") != "aussen" or not effects or set(effects) <= {"programm"}:
        return answer
    directory = os.path.realpath(_autonomy_profile_directory(command, cwd) if tool == "Bash" and command else cwd)
    try:
        if _work_repo_problem(directory, deadline, environ) is not None:
            return answer
    except GateError:
        return answer
    said = "; ".join(AUTONOMY_EFFECTS[e][0] for e in effects if e in AUTONOMY_EFFECTS) or "an external effect"
    binding = ""
    if tool == "Bash" and command:   # D119: what the card carries, and what a release frees
        door = _release_door(command, answer)
        binding = (f" The card carries the line verbatim, sha256 {command_sha256(command)}, and what it does outside: "
                   f"{said}. The owner's answer A frees exactly this line once, in this session, within "
                   f"{RELEASE_SECONDS // 60} minutes of the answer; a changed line needs a new card (DECISIONS.md "
                   "D111, D119).") if door is None else \
            (f" The line touches {_RELEASE_DOORS[door][0]}, an own door of the owner: no card frees it. Say so on the "
             "card; the owner runs the line themselves (DECISIONS.md D119).")
    verdict = Verdict("deny", f"proofbundle gate, autonomous operation (D93): {said} is asked of the owner on a card in "
                              "the Leitstand, not in the terminal. Put a card in the Leitstand that names the command, "
                              "what it does outside and why, and wait for the owner's answer there; do not try another "
                              "spelling of the call (owner word of 2026-10-18, 16:52 Berlin; "
                              f"DECISIONS.md D93).{binding}", "autonomy_card",
                      evidence="the effect of the call and the work profile of the repository (D71)",
                      failed=f"{said} needs the owner", next_step="put a card in the Leitstand", repo=directory)
    new = Outcome("deny", f"{verdict.text()} {answer.text}", list(answer.verdicts) + [verdict], None,
                  step=answer.step, cause=verdict)
    return _autonomy_record(new, "karte", wirkung=effects)


# --- D111: an owner's release on a card frees exactly one command once ---------------------------------

#: D111: the folder in the gate's directory where the fetcher on the operator's machine leaves the owner's answers to cards, one file
#: per release: {"schema": RELEASE_SCHEMA, "karte": "OA-<10 hex>", "sitzung": <session id>, "sha256": <the sha256 of the
#: command's words as written, UTF-8>, "antwort": "<UTC time of the answer, YYYY-MM-DDTHH:MM:SSZ>"}. The gate reads it
#: and never writes it; a write of the session into the gate's directory is denied (write_to_gate_dir, D25, a weight
#: of _D72_WRITES).
RELEASES_DIR = "freigaben"
RELEASE_SCHEMA = "proofbundle-plugin/freigabe/v0.1"
MAX_RELEASE_BYTES = 4 * 1024
MAX_RELEASE_FILES = 256
#: A release frees its command from the owner's answer on for this many seconds (the order: 15 minutes), and not
#: before the answer beyond RELEASE_SKEW_SECONDS of clock skew between the operator's machine and the owner's decision board.
RELEASE_SECONDS = 15 * 60
RELEASE_SKEW_SECONDS = 60
#: The releases used, in the plugin data directory: the hook writes the use under a lock before the call runs, and only
#: where it runs (release_settle, D119). An identity whose use it dropped stays in it as a digest (verbraucht,
#: _release_take), which it never drops (follow-up note 28).
RELEASES_USED = "freigaben-genutzt.json"
RELEASES_USED_SCHEMA = "proofbundle-plugin/freigaben-genutzt/v0.1"
MAX_RELEASES_USED = 1024
MAX_RELEASES_USED_BYTES = 512 * 1024
_CARD_ID = re.compile(r"OA-[0-9a-f]{10}")
_SESSION_ID = re.compile(r"[A-Za-z0-9][A-Za-z0-9._-]{0,127}")
_UTC_STAMP = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z")
#: The digest of an identity in the record of the releases used (verbraucht, _release_identity).
_CONSUMED = re.compile(r"[0-9a-f]{32}")
#: D119: the owner's own doors, which no release on a card opens: --admin, a forced push, a tag, a
#: release, PyPI, a signature and root; and a merge whose line does not pin the head it merges (--match-head-commit),
#: as the card shows a line, not the head the merge finds when it runs. (English, German.)
_RELEASE_DOORS = {
    "admin": ("--admin", "--admin"),
    "force": ("a forced push", "ein Force-Push"),
    "tag": ("a tag", "ein Tag"),
    "release": ("a release", "eine Release"),
    "pypi": ("an upload to PyPI", "ein Upload nach PyPI"),
    "signatur": ("a signature", "eine Signatur"),
    "root": ("root", "Root"),
    "merge_kopf": ("a merge without --match-head-commit", "ein Merge ohne --match-head-commit"),
}
#: The reasons of decide() that name a door: --admin and the protection API (D73 H1), a forced push (D86), a tag (D73 H2).
_RELEASE_DOOR_REASONS = {"house_admin_merge": "admin", "house_protection_api": "admin", "push_force": "force",
                         "house_tag_out": "tag"}
_RELEASE_ROOT = frozenset({"sudo", "su", "doas", "pkexec", "run0"})
_RELEASE_SIGNERS = frozenset({"gpg", "gpg2", "cosign", "minisign", "signify", "sigstore", "rekor-cli", "notation"})
_RELEASE_PUBLISHERS = frozenset({"uv", "poetry", "flit", "hatch", "pdm", "maturin", "rye"})
_RELEASE_SPLIT = re.compile(r"[\s;&|()<>`'\"]+")


def _release_door(command: str, answer: "Outcome") -> str | None:
    """D119: the own door of _RELEASE_DOORS a line touches, or None: by the words of the line, split at blanks, quotes
    and the shell's operators without its grammar, so a door word in a chain, a substitution, `sh -c` or a
    here-document counts as well, and by the reasons decide() gave. A door word in a message or a title holds the
    release back too: a release frees less, never more."""
    door = _release_door_words(command)
    if door is not None:
        return door
    for verdict in answer.verdicts:
        if verdict.reason_id in _RELEASE_DOOR_REASONS:
            return _RELEASE_DOOR_REASONS[verdict.reason_id]
    return None


#: The shell joins the quoted and unquoted parts of a word and drops a backslash before a letter: `s''udo`, `\sudo`
#: and `su"d"o` all run sudo, while the split at quotes sees `s` and `udo`.
_RELEASE_JOIN = re.compile(r"[\\'\"]")
#: bash's ANSI-C quoting, `$'…'`, whose escapes it decodes (`$'\x73udo'` runs sudo), and its locale quoting, `$"…"`,
#: which a message catalog may translate (re-reading of the fixes at 21fead88, line 3, P1). The gate does not rebuild
#: the escapes of a shell: a part with a backslash, and a locale part with text, count as not resolved (fourth reading
#: at de05121d, line 3: it claimed `$'\0163'` is `s` in bash; measured, bash 5.1.16 and zsh 5.8.1 read `\016` and `3`,
#: as Python does, but another shell may read it otherwise). A part without them is its text.
_RELEASE_ANSI_C = re.compile(r"\$'((?:[^'\\]|\\.)*)'", re.S)
_RELEASE_LOCALE = re.compile(r'\$"((?:[^"\\]|\\.)*)"', re.S)
#: The expansions the gate does not resolve in a word: a parameter, a command substitution, an arithmetic expansion, a
#: backquoted command and a process substitution.
_RELEASE_EXPANSION = re.compile(r"\$\{[^}]*\}|\$\(\([^)]*\)\)|\$\([^)]*\)|\$[A-Za-z_][A-Za-z0-9_]*|\$[0-9@*#?$!-]|"
                                r"`[^`]*`|[<>]\([^)]*\)")
_RELEASE_UNKNOWN = "\x01"
#: A dollar sign the shell keeps as text (_release_quote_parts), so that no expansion is read into it. A letter, not a
#: control character: next to a control character `sudo` still stood at a word boundary and read as the program.
_RELEASE_LITERAL_DOLLAR = "\u01c2"


def _release_ansi_c(match: "re.Match") -> str:
    return _RELEASE_UNKNOWN if "\\" in match.group(1) else match.group(1)


def _release_locale(match: "re.Match") -> str:
    return _RELEASE_UNKNOWN if match.group(1) else ""


def _release_quote_parts(text: str) -> str:
    """The text with each ANSI-C part `$'…'` and each locale part `$"…"` read as bash reads it, and only where bash reads
    it: outside single and double quotes. Inside single quotes `$"hello"` is those characters, inside double quotes
    `$'\\x73udo'` is too (fifth reading of G-2, P2; measured with bash 5.1.16, printf prints [$"hello"]), and reading them
    there held a release back that the shell never runs. A backslash outside single quotes keeps the next character."""
    out: list[str] = []
    i, quote = 0, ""
    while i < len(text):
        c = text[i]
        if quote != "'" and c == "\\" and i + 1 < len(text):
            out.append(text[i:i + 2])
            i += 2
            continue
        if not quote and c == "$" and text[i + 1:i + 2] in ("'", '"'):
            m = (_RELEASE_ANSI_C if text[i + 1] == "'" else _RELEASE_LOCALE).match(text, i)
            if m:
                out.append(_release_ansi_c(m) if text[i + 1] == "'" else _release_locale(m))
                i = m.end()
                continue
        if c in "'\"" and quote in ("", c):
            quote = "" if quote else c
        elif c == "$" and (quote == "'" or (quote == '"' and text[i + 1:i + 2] in ("'", '"'))):
            # A `$` the shell keeps as a character: every one inside single quotes, and one before a quote inside double
            # quotes. Once the quotes are joined away, `$"hello"` would read as the parameter `$hello`.
            c = _RELEASE_LITERAL_DOLLAR
        out.append(c)
        i += 1
    return "".join(out)


def _release_door_words(command: str) -> str | None:
    """The door of the words of a line: of the line as written, and of the line as the shell assembles its words (an
    ANSI-C or locale part read where it has no escape and no text to translate, else not resolved; every quote and
    backslash removed), so that a word the shell joins from
    quoted parts is read as the shell reads it (reading of G-2, part 8, P1, and the re-reading of its fix). A program
    word with an expansion the gate does not resolve counts as the door root where what is written of it may still
    be a program of _RELEASE_ROOT (_release_unresolved_root). Words that only the assembled line forms can hold a
    release back too: a release frees less, never more."""
    door = _release_door_words_split(command)
    if door is not None:
        return door
    # bash's word formation for a program word, in its order (third reading at 097cedad, line 3, P1): a line
    # continuation goes first, then the quoting is read, then the brace expansion makes words of a word.
    continued = command.replace("\\\n", "")
    readings = _release_assembled(continued)
    for assembled in readings:
        for text in dict.fromkeys([assembled, _release_braced(assembled)]):
            if text != command:
                door = _release_door_words_split(text)
                if door is not None:
                    return door
    for assembled in readings:
        door = _release_unresolved_door(assembled)
        if door is not None:
            return door
    return None


#: What opens a context in which bash reads the quotes anew: a command substitution (an arithmetic one too), a
#: backquoted command and a braced parameter.
_RELEASE_NEW_CONTEXT = ("$(", "`", "${")


def _release_assembled(continued: str) -> list[str]:
    """The line as the shell assembles its words, every quote and backslash removed: read where its quotes stand
    (_release_quote_parts), and where the line holds a command substitution, a backquoted command or a braced parameter,
    also with every ANSI-C and locale part decoded wherever it stands, as the gate read it at 647ed0a2. Inside those
    bash reads the quotes in a context of its own, also within double quotes, so `x="$(s$'u'do -n true)"` runs sudo
    (reading of the follow-up to 441, line 3, P1; measured with bash 5.1.16, printf prints [sudo]), and a context closes
    where only a parser of the whole shell grammar can tell (a case pattern closes with a parenthesis). There the line is
    read both ways, and a release frees less, never more.

    The same holds where a word of the line, as written or as the shell joins it (`e\\val`, `ev''al`), is one of
    _RELEASE_TEXT_RUNNERS. eval and a shell with -c read their text a second time, so a dollar sign the first reading
    keeps as a character expands there, and `X=udo; eval 's$X' -n true` runs sudo (Codex on pull request 447, P1;
    measured with bash 5.1.16 and a function named sudo, also for `bash -c`). The gate does not tell the forms of a
    runner apart, so a line where a runner reads a file, `source` or a shell given a script, is read the strict way
    as well: it holds back more, never less."""
    readings = [_RELEASE_JOIN.sub("", _release_quote_parts(continued))]
    runs_text = any(os.path.basename(word) in _RELEASE_TEXT_RUNNERS
                    for word in _RELEASE_SPLIT.split(continued) + _RELEASE_SPLIT.split(readings[0]))
    if runs_text or any(opening in continued for opening in _RELEASE_NEW_CONTEXT):
        readings.append(_RELEASE_JOIN.sub("", _RELEASE_LOCALE.sub(_release_locale,
                                                                  _RELEASE_ANSI_C.sub(_release_ansi_c, continued))))
    return list(dict.fromkeys(readings))


def _release_braced(text: str) -> str:
    """The text with each blank-separated word replaced by the words of its brace expansion (D100, _sh_brace_expand),
    where the gate can expand it: `{s,x}udo` runs sudo."""
    return "".join(" ".join(_sh_brace_expand(w) or [w]) if "{" in w else w for w in re.split(r"(\s+)", text))


#: The programs that run text as a command: a word of theirs the gate does not resolve may be a root program.
_RELEASE_TEXT_RUNNERS = frozenset({"eval", "source", ".", "sh", "bash", "zsh", "dash", "ksh", "watch", "runuser"})
#: The shells, which also run the text they read from a pipe.
_RELEASE_SHELLS = frozenset({"sh", "bash", "zsh", "dash", "ksh"})


def _release_unresolved_door(assembled: str) -> str | None:
    """The door root or signatur where a program word of a line (behind its prefix assignments and wrappers,
    _guard_program) may still be one of their programs though the gate does not resolve it: a word with an expansion
    (read as `*`) or a pattern (`/usr/bin/su[d]o`), compared without case with _RELEASE_ROOT and _RELEASE_SIGNERS by
    the comparison of D102 (proofbundle_secrets.may_match). The door root also where a program that runs text
    (_RELEASE_TEXT_RUNNERS: eval, `bash -c`) gets an expansion the gate does not resolve, and where a shell reads its
    commands from a pipe (`printf 'su%s' do | sh`). A program word that is a path counts by its last part. Not known to
    the gate: aliases and functions defined outside the line, and the text of a file a line sources or a shell runs."""
    marked = _RELEASE_EXPANSION.sub(_RELEASE_UNKNOWN, assembled)
    sec = _secrets()
    parts = re.split(r"([;&|()\n]+)", marked)
    for i in range(0, len(parts), 2):
        words = parts[i].split()
        if not words:
            continue
        k = _guard_program(words)
        runners = [os.path.basename(w).lower() for w in words[:k + 1]]
        if any(r in _RELEASE_TEXT_RUNNERS for r in runners) and any(_RELEASE_UNKNOWN in w for w in words[k + 1:]):
            return "root"
        before = parts[i - 1] if i else ""
        if runners[-1] in _RELEASE_SHELLS and before.strip() == "|":
            return "root"
        name = words[k].rsplit("/", 1)[-1].lower()
        if _RELEASE_UNKNOWN in name or _SH_GLOB_CHARS.search(name):
            pattern = name.replace(_RELEASE_UNKNOWN, "*")
            if any(sec.may_match(pattern, root) for root in _RELEASE_ROOT):
                return "root"
            if any(sec.may_match(pattern, signer) for signer in _RELEASE_SIGNERS):
                return "signatur"
    return None


def _release_door_words_split(command: str) -> str | None:
    words = [w for w in _RELEASE_SPLIT.split(command) if w]
    # A program name is compared without case: a file system without case (macOS) finds /usr/bin/sudo for `SUDO`.
    names = [os.path.basename(w).lower() for w in words]
    subs = {}   # the index of the subcommand of each git and gh word: the first word after its options
    for i, name in enumerate(names):
        if name in ("git", "gh"):
            j = i + 1
            while j < len(words) and words[j].startswith("-"):
                j += 2 if (name == "git" and words[j] in _GIT_GLOBAL_VALUE) or words[j] in ("-R", "--repo") else 1
            if j < len(words):
                subs[j] = name
    pushed = [k for k, name in subs.items() if name == "git" and words[k] == "push"]
    after_push = words[min(pushed) + 1:] if pushed else []
    if any(w == "--admin" or w.startswith("--admin=") for w in words):
        return "admin"
    if any(w in ("-f", "--mirror") or w.startswith("--force") or (w.startswith("+") and len(w) > 1) or
           (w.startswith("-") and not w.startswith("--") and "f" in w[1:]) for w in after_push):
        return "force"
    if any(name == "git" and words[k] == "tag" for k, name in subs.items()) or \
            any(w in ("--tags", "--follow-tags") or "refs/tags/" in w for w in after_push):
        return "tag"
    if any(name == "gh" and words[k] == "release" for k, name in subs.items()) or \
            any(name == "gh" and words[k] == "api" and any("/releases" in w for w in words[k + 1:])
                for k, name in subs.items()):
        return "release"
    if "twine" in names or any("pypi.org" in w for w in words) or \
            any(n in _RELEASE_PUBLISHERS and ("publish" in words[i + 1:] or (n == "maturin" and "upload" in words[i + 1:]))
                for i, n in enumerate(names)):
        return "pypi"
    # D120 (O49-1, a neighbour measured 2026-10-24): git signs with the owner's key also through its configuration, by
    # `-c commit.gpgsign=true`, by GIT_CONFIG_KEY_<n>=tag.gpgSign and by -S with its key joined (-S<key>); until then a
    # release let `git -c commit.gpgsign=true commit -m x` run. A word that names gpgsign holds the release back, also
    # one that sets it false: a release frees less, never more.
    if any(n in _RELEASE_SIGNERS for n in names) or ("ssh-keygen" in names and "-Y" in words and "sign" in words) or \
            ("openssl" in names and any(w in ("-sign", "sign") for w in words)) or \
            ("git" in names and any(w.startswith(("-S", "--gpg-sign")) or "gpgsign" in w.lower() for w in words)):
        return "signatur"
    if any(n in _RELEASE_ROOT for n in names):
        return "root"
    if any(name == "gh" and words[k] == "pr" and words[k + 1:k + 2] == ["merge"] for k, name in subs.items()) and \
            not any(w == "--match-head-commit" or w.startswith("--match-head-commit=") for w in words):
        return "merge_kopf"
    return None


def command_sha256(command: str) -> str:
    """D111: the sha256 of a command's words as written, as UTF-8 (a byte that is no UTF-8 as it came)."""
    return hashlib.sha256(command.encode("utf-8", "surrogateescape")).hexdigest()


def _releases(environ) -> list[dict]:
    """D111: the releases in the folder RELEASES_DIR of the gate's directory that read whole, each with its time in
    seconds (zeit). A file that does not is left out: no file ending in .json, a link, no regular file, more than
    MAX_RELEASE_BYTES, not strict JSON, another schema or another key, or a card, a session, a sha256 or a time of
    another shape. The folder itself must be a folder and no link."""
    gate_dir = _gate_dir(environ)
    if gate_dir is None or not _owner_state_read(environ):   # D124
        return []
    folder = os.path.join(gate_dir, RELEASES_DIR)
    try:
        if os.path.islink(folder) or not os.path.isdir(folder):
            return []
        names = sorted(n for n in os.listdir(folder) if n.endswith(".json"))[:MAX_RELEASE_FILES]
    except OSError:
        return []
    found = []
    for name in names:
        try:
            raw = _read_regular(os.path.join(folder, name), MAX_RELEASE_BYTES + 1)
            data = strict_json(raw) if len(raw) <= MAX_RELEASE_BYTES else None
        except (OSError, ValueError, UnicodeDecodeError):
            continue
        if not isinstance(data, dict) or set(data) != {"schema", "karte", "sitzung", "sha256", "antwort"} or \
                data["schema"] != RELEASE_SCHEMA:
            continue
        card, session, sha, answered = data["karte"], data["sitzung"], data["sha256"], data["antwort"]
        if not all(isinstance(v, str) for v in (card, session, sha, answered)) or not _CARD_ID.fullmatch(card) or \
                not _SESSION_ID.fullmatch(session) or not _SHA256_HEX.fullmatch(sha) or \
                not _UTC_STAMP.fullmatch(answered):
            continue
        when = _ts_seconds(answered)
        if when is None:
            continue
        found.append({"karte": card, "sitzung": session, "sha256": sha, "antwort": answered, "zeit": when})
    return found


def _release_key(release: dict) -> str:
    """D119: a card frees its line once in its session, whatever answer times the fetcher writes for it."""
    return f"{release['karte']}:{release['sha256']}:{release['sitzung']}"


def _release_used(release: dict, used: dict) -> bool:
    """Whether the record of the releases used names this release: by its key, or by the key of D111, which named the
    time of the answer as well."""
    return _release_key(release) in used or f"{_release_key(release)}:{release['antwort']}" in used


def _release_identity(key: str) -> str:
    """The digest of the identity a key of the record names: the first 32 hex signs of the sha256 of card, sha256 and
    session. The key of D111 names the time of the answer as well; the identity leaves it out, as no part of it holds
    a colon."""
    return hashlib.sha256(":".join(key.split(":")[:3]).encode("utf-8")).hexdigest()[:32]


def _release_free(release: dict, used: dict, consumed: set, now: float) -> bool:
    """Whether this release may be used now: now lies within its window (RELEASE_SKEW_SECONDS before its answer to
    RELEASE_SECONDS after it), the record names no use of it (_release_used), and the record dropped no use of its
    identity into its digests (consumed, _releases_record), whatever answer time this copy of the release carries
    (follow-up note 28). The gate chooses by it and _release_take checks it again under the lock with the clock that
    stamps the use."""
    return release["zeit"] - RELEASE_SKEW_SECONDS <= now <= release["zeit"] + RELEASE_SECONDS and \
        not _release_used(release, used) and _release_identity(_release_key(release)) not in consumed


def _releases_record(directory: str) -> tuple[dict, set]:
    """D111, D119: the releases used {key: time of use}, and the digests of the identities whose use the record dropped
    (verbraucht, _release_identity), which it never drops; a ValueError where the record does not read whole, so no
    release is used twice through a record the gate cannot read."""
    try:
        raw = _read_regular(os.path.join(directory, RELEASES_USED), MAX_RELEASES_USED_BYTES + 1)
    except FileNotFoundError:
        return {}, set()
    data = strict_json(raw) if len(raw) <= MAX_RELEASES_USED_BYTES else None
    if not isinstance(data, dict) or data.get("schema") != RELEASES_USED_SCHEMA or \
            not isinstance(data.get("genutzt"), dict):
        raise ValueError("the record of the releases used does not read whole")
    consumed = data.get("verbraucht", [])
    if not isinstance(consumed, list) or not all(isinstance(d, str) and _CONSUMED.fullmatch(d) for d in consumed):
        raise ValueError("the record of the releases used does not read whole")
    return dict(data["genutzt"]), set(consumed)


def _write_releases_used(directory: str, used: dict, consumed: set | frozenset = frozenset()) -> None:
    """The record as _releases_record reads it; a ValueError before anything is written where it would pass
    MAX_RELEASES_USED_BYTES, so the hook never writes a record it cannot read."""
    record = {"schema": RELEASES_USED_SCHEMA, "genutzt": used}
    if consumed:
        record["verbraucht"] = sorted(consumed)
    text = json.dumps(record, sort_keys=False)
    if len(text.encode("utf-8")) > MAX_RELEASES_USED_BYTES:
        raise ValueError("the record of the releases used would pass MAX_RELEASES_USED_BYTES")
    fd, tmp = tempfile.mkstemp(prefix=".freigaben-", dir=directory)
    with os.fdopen(fd, "w", encoding="utf-8") as handle:
        handle.write(text)
    os.replace(tmp, os.path.join(directory, RELEASES_USED))


def _release_use_past(stamp: object, now: float) -> bool:
    """Whether a use the record keeps lies more than RELEASE_SECONDS + RELEASE_SKEW_SECONDS before now: a release is used
    no earlier than RELEASE_SKEW_SECONDS before its answer and binds at most RELEASE_SECONDS after it, so no release binds
    any more with the answer it had. A time that does not read is no such use."""
    seconds = _ts_seconds(stamp) if isinstance(stamp, str) else None
    return seconds is not None and seconds < now - RELEASE_SECONDS - RELEASE_SKEW_SECONDS


def _release_take(release: dict, environ, now: float | None = None) -> bool:
    """D111, D119: write the use of a release to RELEASES_USED in the plugin data directory, under the lock of the
    answer hook (D94); False where _release_free does not let it be used now (outside its window, used, or an identity
    whose use was dropped), where the record is full, where it would pass MAX_RELEASES_USED_BYTES, or where the gate
    cannot read or write the record: then the release lets nothing run and the record stays as it is. At
    MAX_RELEASES_USED uses the record first drops the uses with which no release binds any more (_release_use_past,
    follow-up note 26) and keeps their identities as digests, so no copy of such a release with a later answer is
    used again (follow-up note 28); where it is still full, it stays as it is."""
    data = environ.get("CLAUDE_PLUGIN_DATA")
    if not data or not os.path.isabs(data) or not os.path.isdir(data):
        return False
    now = time.time() if now is None else now
    try:
        hook = _answer_hook()
        with hook.asks_lock(data, RELEASES_USED):
            used, consumed = _releases_record(data)
            if not _release_free(release, used, consumed, now):
                return False
            if len(used) >= MAX_RELEASES_USED:
                kept = {key: stamp for key, stamp in used.items() if not _release_use_past(stamp, now)}
                if len(kept) >= MAX_RELEASES_USED:
                    return False
                consumed = consumed | {_release_identity(key) for key in used if key not in kept}
                used = kept
            used[_release_key(release)] = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(now))
            _write_releases_used(data, used, consumed)
    except (OSError, ValueError, UnicodeDecodeError, ImportError, AttributeError, SyntaxError):
        return False
    return True


def _release_kept(answer: "Outcome", release: dict, why: str) -> "Outcome":
    """D119: the answer without the owner's release, with one sentence that names why the release does not let the call
    run; the release stays as it was (freigabe_offen in the record of the answer)."""
    new = Outcome(answer.decision, f"proofbundle gate: the owner's release on the card {release['karte']} does not let "
                                   f"this call run: {why}. {answer.text}", list(answer.verdicts), answer.applied_rule,
                  step=answer.step, cause=answer.cause)
    new.autonomy = {**(getattr(answer, "autonomy", None) or {}), "freigabe_offen": {"karte": release["karte"],
                                                                                    "warum": why}}
    return new


def _autonomy_release(answer: "Outcome", command: str | None, environ, now: float | None = None,
                      take: bool = True) -> "Outcome | None":
    """D111: the pass for a Bash call decide() asked about and the autonomous answer does not let run,
    where the owner released exactly this command on a card: a release (_releases) whose sha256 is that of the
    command's words as written, whose session is the hook's (CLAUDE_CODE_SESSION_ID) and whose answer lies at most
    RELEASE_SECONDS back, not used before (_release_used). D119: a line that touches an own door of the
    owner (_release_door) keeps its answer, with a sentence that names the door. With take the use is written before
    the pass (_release_take); without it the pass holds the release in outcome.release and the hook writes the use only
    where the call runs (release_settle). Where the gate cannot read or write the record, nothing is released."""
    session = environ.get("CLAUDE_CODE_SESSION_ID")
    data = environ.get("CLAUDE_PLUGIN_DATA")
    if not command or not isinstance(session, str) or not _SESSION_ID.fullmatch(session) or not data or \
            not os.path.isabs(data) or not os.path.isdir(data):
        return None
    sha = command_sha256(command)
    now = time.time() if now is None else now
    fitting = [r for r in _releases(environ) if r["sha256"] == sha and r["sitzung"] == session
               and r["zeit"] - RELEASE_SKEW_SECONDS <= now <= r["zeit"] + RELEASE_SECONDS]
    if not fitting:
        return None
    door = _release_door(command, answer)
    if door is not None:
        return _release_kept(answer, fitting[0], f"the line touches {_RELEASE_DOORS[door][0]}, an own door of the "
                                                 "owner that no card opens (DECISIONS.md D119)")
    try:
        used, consumed = _releases_record(data)
    except (OSError, ValueError, UnicodeDecodeError):
        return None
    release = next((r for r in fitting if _release_free(r, used, consumed, now)), None)
    if release is None or (take and not _release_take(release, environ, now)):
        return None
    verdict = Verdict("pass", f"proofbundle gate: the owner released this command on the card {release['karte']}, "
                              f"answered at {release['antwort']}. The release frees exactly the command whose words "
                              f"as written have the sha256 {sha}, once, in this session, within "
                              f"{RELEASE_SECONDS // 60} minutes of the answer; its use stands in the plugin data "
                              "before the call runs (DECISIONS.md D111, D119).", "released_by_owner")
    new = Outcome("pass", verdict.text(), list(answer.verdicts) + [verdict], None, step=answer.step)
    new.release = {"freigabe": release, "ohne": answer, "genutzt": take}
    record = getattr(answer, "autonomy", None) or {}
    return _autonomy_record(new, "freigabe", wirkung=list(record.get("wirkung") or []),
                            quittung={"art": "freigabe", "karte": release["karte"], "sha256": sha,
                                      "antwort": release["antwort"]})


def release_settle(event: object, outcome: "Outcome", environ, host: str = "claude",
                   event_text: str | None = None) -> tuple["Outcome", bool]:
    """D119 (O43-1): the hook's step for an answer that holds an owner's release whose use is not written
    (outcome.release): the release is used once, and only where the call runs. Where the pilot is on and reads the
    call as a GitHub write (Level 1, D55), the signer service first decides the call again and signs the receipt ALLOW
    (D58); only then the hook writes the use (_release_take) and the call runs. Where the service signs nothing, or the
    use cannot be written, the answer without the release stands, with a sentence that names why, and the release
    stays as it was. Returns the answer and whether a receipt was asked for this call."""
    held = outcome.release
    release, without = held["freigabe"], held["ohne"]
    config = _pilot_config(environ) if isinstance(event, dict) else None
    action, key = _pilot_tool_action(event) if config is not None else (None, "")
    if action is not None:
        text = event_text if isinstance(event_text, str) else json.dumps(event)
        try:
            _pilot_issue(config, environ, action, key, "ALLOW", _pilot_reasons([v.reason_id for v in outcome.verdicts]),
                         {"level": 1, "host": host, "event": text})
        except Exception as exc:  # noqa: BLE001 - no signature, no use: the release stays as it was
            why = str(exc) if isinstance(exc, GateError) and _PILOT_REASON.fullmatch(str(exc)) else \
                f"internal_{type(exc).__name__}"
            try:
                _pilot_journal(config["receipts"], {"issued": False, "why": why})
            except Exception:  # noqa: BLE001 - nor does a journal it cannot write change the answer
                pass
            return _release_kept(without, release, f"the signer service did not sign the effect ({why})"), True
    if not _release_take(release, environ):
        return _release_kept(without, release, "its use could not be written, or it was used before"), action is not None
    held["genutzt"] = True
    return outcome, action is not None


# --- D94: the answers to the asks per reason, and the candidates to free -----------------

#: D94: the keys of the asks the hook sent under Claude Code, until the answer hook (ANSWER_HOOK, on PostToolUse and
#: PostToolUseFailure) finds the call ran. The names and the store are the answer hook's own (proofbundle_answered.py).
ASKS_PENDING = "asks-pending.json"
ASKS_SCHEMA = "proofbundle-plugin/asks-pending/v0.1"
MAX_ASKS_PENDING = 256
ANSWER_HOOK = "proofbundle_answered.py"
#: An ask whose call did not run counts as a no once its session made a later call, or this long after it.
ANSWER_WINDOW_SECONDS = 3600
#: The candidates to free (owner question O37-5): over the last CANDIDATE_DAYS days of the log, a reason of no catch
#: (not in FANG_REASONS) with at least CANDIDATE_MIN_ANSWERS answers, of which at least CANDIDATE_YES_SHARE were yes.
CANDIDATE_DAYS = 14
CANDIDATE_MIN_ANSWERS = 20
CANDIDATE_YES_SHARE = 0.95


def _answer_hook():
    """The answer hook's module, loaded from its file beside this one (the gate runs with -I, so not by import)."""
    location = os.path.join(os.path.dirname(os.path.realpath(__file__)), ANSWER_HOOK)
    spec = importlib.util.spec_from_file_location("proofbundle_answered", location)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def _asks_keep(event: object, outcome: "Outcome | None", environ: dict | None = None) -> str | None:
    """D94: the key of an ask the hook sends (the sha256 of its tool_use_id, never the id), kept with its time and its
    reasons in the plugin data directory, at most MAX_ASKS_PENDING, the oldest dropped first; None where the hook sends
    no ask, the event names no tool_use_id or the store cannot be written. Never raises, never changes an answer."""
    if outcome is None or outcome.decision != "ask" or not isinstance(event, dict) or \
            not isinstance(event.get("tool_use_id"), str):
        return None
    directory = log_directory("claude", environ)
    if directory is None:
        return None
    try:
        hook = _answer_hook()
        key = hook.ask_key(event["tool_use_id"])
        with hook.asks_lock(directory):
            asks = hook.read_asks(directory)
            asks.pop(key, None)
            asks[key] = {"ts": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
                         "gruende": list(dict.fromkeys(v.reason_id for v in outcome.verdicts))}
            while len(asks) > MAX_ASKS_PENDING:
                asks.pop(next(iter(asks)))
            hook.write_asks(directory, asks)
        return key
    except Exception:  # noqa: BLE001 - the count never changes an answer
        return None


def _ts_seconds(ts: str) -> int | None:
    """The seconds of a stamp of the form %Y-%m-%dT%H:%M:%SZ, or None. time.strptime refuses a day the month does not
    have but takes the seconds 60 and 61, which calendar.timegm reads as the next minute; such a stamp is none (D122)."""
    try:
        parsed = time.strptime(ts, "%Y-%m-%dT%H:%M:%SZ")
    except (TypeError, ValueError):
        return None
    return calendar.timegm(parsed) if parsed.tm_sec < 60 else None


def _ask_answers(entries: list[dict]) -> dict:
    """D94: {key: "ja" | "nein" | "offen"} for every ask of the log that carries a key: yes where an answer line names
    it (the call ran); no where it does not and its session made a later call, or the newest line of the log is
    ANSWER_WINDOW_SECONDS after it; open else."""
    answered = {e.get("frage") for e in entries if e.get("decision") == "answered" and e.get("antwort") == "ja"}
    last: dict = {}
    for e in entries:
        if e.get("decision") != "answered" and isinstance(e.get("ts"), str):
            last[e.get("session_id")] = max(last.get(e.get("session_id"), ""), e["ts"])
    newest = max((_ts_seconds(e.get("ts")) or 0 for e in entries), default=0)
    result = {}
    for e in entries:
        key = e.get("frage")
        if e.get("decision") != "ask" or not isinstance(key, str):
            continue
        if key in answered:
            result[key] = "ja"
            continue
        later = e.get("session_id") is not None and last.get(e.get("session_id"), "") > e["ts"]
        old = newest - (_ts_seconds(e["ts"]) or newest) >= ANSWER_WINDOW_SECONDS
        result[key] = "nein" if later or old else "offen"
    return result


def _release_candidates(entries: list[dict], answers: dict) -> list[dict]:
    """D94: the reasons the gate names as candidates to free, each an owner question (O37-5); the gate frees nothing
    itself. Over the last CANDIDATE_DAYS days of the log: a reason not in FANG_REASONS whose answered asks under Claude
    Code number at least CANDIDATE_MIN_ANSWERS, at least CANDIDATE_YES_SHARE of them yes."""
    stamps = [s for s in (_ts_seconds(e.get("ts")) for e in entries) if s is not None]
    if not stamps:
        return []
    since = max(stamps) - CANDIDATE_DAYS * 86400
    count: dict = {}
    for e in entries:
        state = answers.get(e.get("frage"))
        if e.get("decision") != "ask" or e.get("host") != "claude" or state not in ("ja", "nein") or \
                (_ts_seconds(e.get("ts")) or 0) < since:
            continue
        for reason in dict.fromkeys(e.get("reason_ids") or []):
            count.setdefault(reason, [0, 0])[state == "nein"] += 1
    found = []
    for reason, (yes, no) in sorted(count.items()):
        if reason in FANG_REASONS or yes + no < CANDIDATE_MIN_ANSWERS or yes < CANDIDATE_YES_SHARE * (yes + no):
            continue
        found.append({"grund": reason, "ja": yes, "nein": no, "ja_quote": round(yes / (yes + no), 3),
                      "zeitraum_tage": CANDIDATE_DAYS, "owner_frage": "O37-5"})
    return found


def tree_digest_command(argv: list[str]) -> int:
    """`tree-digest [--repo DIR] [--rev REV] [--statement]`: the producer's side of the binding."""
    options, statement, i = {"--repo": ".", "--rev": "HEAD"}, False, 0
    while i < len(argv):
        if argv[i] == "--statement":
            statement, i = True, i + 1
        elif argv[i] in options and i + 1 < len(argv):
            options[argv[i]], i = argv[i + 1], i + 2
        else:
            print(f"usage: tree-digest [--repo DIR] [--rev REV] [--statement]; unknown {argv[i]!r}", file=sys.stderr)
            return 2
    try:
        digest = tree_digest(options["--repo"], options["--rev"])
    except GateError as exc:
        print(f"tree-digest: {exc}", file=sys.stderr)
        return 1
    sys.stdout.write((subject_statement(digest).decode() if statement else digest) + "\n")
    return 0


def state_digest_command(argv: list[str]) -> int:
    """`state-digest [--repo DIR]`: print the bound-state digest a human puts in a rule, with the repository's
    canonical path and a ready rule skeleton. The gate recomputes this digest on every call and frees the form
    only while it matches, so a human runs this in the same environment the agent runs in."""
    options, i = {"--repo": "."}, 0
    while i < len(argv):
        if argv[i] in options and i + 1 < len(argv):
            options[argv[i]], i = argv[i + 1], i + 2
        else:
            print(f"usage: state-digest [--repo DIR]; unknown {argv[i]!r}", file=sys.stderr)
            return 2
    deadline = time.monotonic() + DEADLINE_SECONDS
    paths, why = _repo_paths(options["--repo"], deadline)
    if paths is None or paths["common"] is None:
        print(f"state-digest: not a git repository, or its layout cannot be read ({why or options['--repo']})",
              file=sys.stderr)
        return 1
    digest = _bound_state_digest(options["--repo"], deadline)
    if digest is None:
        print("state-digest: the program-selecting state cannot be read in full, so there is no digest; the gate "
              "will ask for every form in this repository", file=sys.stderr)
        return 1
    skeleton = {"repo": os.path.realpath(paths["common"]), "form": "git <the exact command to free>",
                "effect": "free", "state_digest": digest}
    sys.stdout.write(digest + "\n")
    sys.stdout.write(json.dumps(skeleton, indent=2, sort_keys=True) + "\n")
    return 0


TRANSPORT_USAGE = "usage: transport-digest [--repo DIR] [--remote NAME]"


def transport_digest_command(argv: list[str]) -> int:
    """`transport-digest [--repo DIR] [--remote NAME]` (default remote origin): print the transport digest of D35 and the
    entry a person copies into transports.json in the gate directory to approve that transport. The gate never writes
    that file; run this in the same environment the agent's pushes run in, since the digest binds it."""
    options, i = {"--repo": ".", "--remote": "origin"}, 0
    while i < len(argv):
        if argv[i] in options and i + 1 < len(argv):
            options[argv[i]], i = argv[i + 1], i + 2
        else:
            print(f"{TRANSPORT_USAGE}; unknown {argv[i]!r}", file=sys.stderr)
            return 2
    deadline = time.monotonic() + DEADLINE_SECONDS
    try:
        paths, why = _repo_paths(options["--repo"], deadline)
        if paths is None or paths["common"] is None:
            print(f"transport-digest: not a git repository, or its layout cannot be read ({why or options['--repo']})",
                  file=sys.stderr)
            return 1
        urls = _git(options["--repo"], "remote", "get-url", "--push", "--all", options["--remote"], deadline=deadline)
        lines = _git_lines(urls.stdout) if urls.returncode == 0 else None
        if not lines or len(lines) != 1 or not lines[0]:
            print(f"transport-digest: git names no single push URL of remote {options['--remote']!r}", file=sys.stderr)
            return 1
        document, problems = _transport_parts_or_unread(options["--repo"], options["--remote"], lines[0], deadline,
                                                        os.environ)
        digest = None if document is None else _canonical_digest(document)
    except GateError as exc:
        print(f"transport-digest: {exc}", file=sys.stderr)
        return 1
    for problem in problems:
        print(f"transport-digest: note: a hand-over does not rely on this transport: {problem}", file=sys.stderr)
    if digest is None:
        print("transport-digest: the transport configuration cannot be read whole, so there is no digest",
              file=sys.stderr)
        return 1
    entry = {"repo": os.path.realpath(paths["common"]), "remote": options["--remote"], "url": lines[0],
             "transport_digest": digest}
    sys.stdout.write(digest + "\n")
    sys.stdout.write(json.dumps(entry, indent=2, sort_keys=True) + "\n")
    return 0


def log_directory(host: str, environ: dict | None = None) -> str | None:
    """The first plugin data directory the host names that is, or can be made, a writable directory."""
    environ = os.environ if environ is None else environ
    for name in LOG_DIR_VARIABLES.get(host, ()):
        value = environ.get(name)
        if not value or not os.path.isabs(value):
            continue
        try:
            os.makedirs(value, exist_ok=True)
        except OSError:
            continue
        if os.path.isdir(value) and os.access(value, os.W_OK):
            return value
    return None


def log_entry(host: str, event: object, outcome: "Outcome | None", actions: list[str],
              environ: dict | None = None) -> dict:
    """What one call leaves in the log: no evidence content, no environment, no key. The approval mode is
    recorded on every entry, and the applied rule (origin, repo, form, effect, state_match) when a human rule
    freed the call, so the log shows each approval and a human can audit and revoke it."""
    environ = os.environ if environ is None else environ
    session = event.get("session_id") if isinstance(event, dict) else None
    tool = event.get("tool_name") if isinstance(event, dict) else None
    verdict = outcome.decision if outcome is not None else "not_gated"
    sent = ("none" if verdict in ("pass", "inactive", "warn", "handover", "not_gated")
            else ("deny" if host == "codex" else verdict))
    autonomy = getattr(outcome, "autonomy", None) if outcome is not None else None
    if autonomy is not None:
        verdict = autonomy.get("vorher", verdict)   # D85: the verdict is what decide() gave, the decision what was sent
    repos = [] if outcome is None else [
        {"path": v.repo, "head": v.head, "verdict": v.decision, "reason_id": v.reason_id, "digests": list(v.digests),
         **({"evidence": list(v.reads)} if v.reads else {})}
        for v in outcome.verdicts]
    entry = {"ts": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()), "host": host, "gate_version": GATE_VERSION,
             "session_id": session if isinstance(session, str) else None,
             "tool": tool if isinstance(tool, str) else None, "actions": actions, "decision": sent,
             "verdict": verdict, "mode": _read_mode(environ),
             "reason_ids": [r["reason_id"] for r in repos] or [verdict], "repos": repos}
    if outcome is not None and outcome.applied_rule is not None:
        entry["applied_rule"] = outcome.applied_rule
    if autonomy is not None:
        entry["autonomy"] = {key: autonomy[key] for key in ("klasse", "hinweise", "wirkung", "freigabe_offen")
                             if key in autonomy}   # D119: freigabe_offen, a release that did not let the call run
        if "quittung" in autonomy:
            entry["quittung"] = autonomy["quittung"]   # D92: what the machine check measured in place of a click
    return entry


def write_log(entry: dict, host: str) -> str | None:
    """Append the entry; never raises, never changes the answer. None when no directory was writable."""
    directory = log_directory(host)
    if directory is None:
        return None
    path = os.path.join(directory, LOG_NAME)
    try:
        if os.path.exists(path) and os.path.getsize(path) > MAX_LOG_BYTES:
            os.replace(path, path + ".1")
        # A FIFO with no reader is never waited on (R18-2 class): the open does not block, and an entry that is no
        # regular file at the opened descriptor is not written to. Mode 600: the gate's bilanz and the plugin's server
        # read the log, both under the account of the session, and no other account (CodeQL alert 150).
        fd = os.open(path, os.O_WRONLY | os.O_APPEND | os.O_CREAT | getattr(os, "O_NONBLOCK", 0)
                     | getattr(os, "O_CLOEXEC", 0), 0o600)
        try:
            if not stat.S_ISREG(os.fstat(fd).st_mode):
                return None
            os.write(fd, (json.dumps(entry, sort_keys=True) + "\n").encode("utf-8"))
        finally:
            os.close(fd)
    except OSError:
        return None
    return path


# --- the done check: the end of a session only with a receipt for the current state (DECISIONS.md, D26) ---

def _tree_object_id(oid_length: int, files: dict) -> str:
    """The git tree id of {path: (mode, blob id)}, built as git builds a tree object: entries sorted by name, a
    directory compared as its name with a trailing slash. The same construction as the package's pytest plugin."""
    nested: dict = {}
    for path, entry in files.items():
        *dirs, leaf = path.split(b"/")
        node = nested
        for d in dirs:
            node = node.setdefault(d, {})
        node[leaf] = entry

    def build(node: dict) -> str:
        rows = []
        for name, value in node.items():
            if isinstance(value, dict):
                rows.append((name + b"/", b"40000 " + name, build(value)))
            else:
                rows.append((name, value[0] + b" " + name, value[1]))
        body = b"".join(head + b"\0" + bytes.fromhex(oid) for _key, head, oid in sorted(rows))
        hasher = _BLOB_HASHES[oid_length](b"tree %d\0" % len(body))
        hasher.update(body)
        return hasher.hexdigest()
    return build(nested)


def _state_excluded(path: bytes) -> bool:
    """An untracked path that is not part of the working state: the evidence folder and bytecode caches."""
    return path.startswith(EVIDENCE_DIR.encode()) or b"__pycache__" in path.split(b"/")


def working_state(repo: str, deadline: float) -> dict:
    """{"commit", "tree", "worktree", "problem", "files"} of the repository: HEAD's commit and tree id, and the tree id of
    the working state, the files of HEAD and every other file git does not ignore, read as raw bytes and modes
    (100755 when the owner may execute a file, else 100644), outside untracked files of the top-level
    .proofbundle/ folder and of __pycache__ folders. No clean or smudge filter, line-ending rule, fsmonitor, hook
    or index takes part (review round 8, R8-1). "worktree" is None and "problem" says why where the working
    state cannot be read as files: a submodule, a path component that is a link or not a directory, a file
    that is neither regular nor a link. The rules are the package's pytest plugin's, so both name the same tree
    for the same bytes."""
    _refuse_partial_clone(repo, deadline)
    ids = []
    for rev in ("HEAD^{commit}", "HEAD^{tree}"):
        proc = _git(repo, "rev-parse", "--verify", "-q", rev, deadline=deadline)
        value = proc.stdout.decode("ascii", "replace").strip()
        if proc.returncode != 0 or len(value) not in _BLOB_HASHES:
            raise GateError("the repository has no commit at HEAD")
        ids.append(value)
    commit, tree = ids
    state = {"commit": commit, "tree": tree, "worktree": None, "problem": None, "files": None}
    listing = _git(repo, "ls-tree", "-r", "-z", "--full-tree", commit, deadline=deadline)
    if listing.returncode != 0:
        raise GateError(f"git could not list the tree of {commit[:12]}")
    head = set()
    for record in listing.stdout.split(b"\0"):
        if not record:
            continue
        meta, tab, path = record.partition(b"\t")
        fields = meta.split(b" ")
        if not tab or len(fields) != 3:
            raise GateError("git ls-tree gave a line the gate cannot read")
        if fields[1] != b"blob":
            state["problem"] = f"the tree holds a {fields[1].decode(errors='replace')} at {path.decode(errors='replace')}"
            return state
        head.add(path)
    with tempfile.TemporaryDirectory(prefix="proofbundle-state-") as scratch:
        os.mkdir(os.path.join(scratch, "hooks"))
        env = dict(_read_env(repo), GIT_INDEX_FILE=os.path.join(scratch, "no-index"))
        left = deadline - time.monotonic()
        if left <= 0:
            raise GateError("the gate ran out of time")
        try:
            proc = subprocess.run(["git", *_READ_ONLY_GIT, "-c", "core.fsmonitor=false", "-c",
                                   f"core.hooksPath={os.path.join(scratch, 'hooks')}", "-c", "core.untrackedCache=false",
                                   "-C", repo, "ls-files", "-z", "--others", "--exclude-standard"],
                                  env=env, capture_output=True, timeout=left, check=False)
        except FileNotFoundError as exc:
            raise GateError("git is not on PATH") from exc
        except subprocess.TimeoutExpired as exc:
            raise GateError("git did not answer in time") from exc
    if proc.returncode != 0:
        raise GateError("git could not list the working tree's files")
    paths = head | {p for p in proc.stdout.split(b"\0") if p and p not in head and not _state_excluded(p)}
    root = os.fsencode(repo)
    files = {}
    for path in sorted(paths):
        shown = path.decode(errors="replace")
        parts = path.split(b"/")
        if any(part in (b"", b".", b"..") for part in parts):
            state["problem"] = f"{shown} has a path component the gate cannot follow safely"
            return state
        deleted = False
        for depth in range(1, len(parts)):
            try:
                mode_bits = os.lstat(os.path.join(root, *parts[:depth])).st_mode
            except FileNotFoundError:
                deleted = True
                break
            except OSError:
                state["problem"] = f"{shown} lies below a directory the gate cannot read"
                return state
            if not stat.S_ISDIR(mode_bits):
                state["problem"] = f"{shown} lies below {b'/'.join(parts[:depth]).decode(errors='replace')}, which is " \
                                   "a link or not a directory in the working tree"
                return state
        if deleted:
            continue
        full = os.path.join(root, *parts)
        try:
            st = os.lstat(full)
            if stat.S_ISLNK(st.st_mode):
                mode, data = b"120000", os.readlink(full)
            elif stat.S_ISREG(st.st_mode):
                mode = b"100755" if st.st_mode & stat.S_IXUSR else b"100644"
                data = _read_regular(full, -1)   # checked again at the descriptor (R18-2 class)
            else:
                state["problem"] = f"{shown} is neither a regular file nor a link in the working tree"
                return state
        except FileNotFoundError:
            continue
        except OSError:
            state["problem"] = f"{shown} cannot be read in the working tree"
            return state
        hasher = _BLOB_HASHES[len(commit)](b"blob %d\0" % len(data))
        hasher.update(data)
        files[path] = (mode, hasher.hexdigest())
    state["worktree"] = _tree_object_id(len(commit), files)
    state["files"] = files
    return state


def commit_state(repo: str, commit: str, deadline: float) -> dict:
    """The state of a commit itself, in the shape of working_state: its commit and tree id, its tree as the state
    the receipts must name ("worktree"), and its files as git lists them (path: (mode, blob id)), not as the disk
    holds them. The done check at a pushed commit uses it (owner choice N2 C): the push sends that commit's tree,
    whatever the working tree holds. A submodule or another entry that is not a file leaves it unreadable as files,
    as in working_state."""
    _refuse_partial_clone(repo, deadline)
    proc = _git(repo, "rev-parse", "--verify", "-q", f"{commit}^{{tree}}", deadline=deadline)
    tree = proc.stdout.decode("ascii", "replace").strip()
    if proc.returncode != 0 or len(tree) not in _BLOB_HASHES:
        raise GateError(f"git could not name the tree of {commit[:12]}")
    state = {"commit": commit, "tree": tree, "worktree": None, "problem": None, "files": None}
    listing = _git(repo, "ls-tree", "-r", "-z", "--full-tree", commit, deadline=deadline)
    if listing.returncode != 0:
        raise GateError(f"git could not list the tree of {commit[:12]}")
    files = {}
    for record in listing.stdout.split(b"\0"):
        if not record:
            continue
        meta, tab, path = record.partition(b"\t")
        fields = meta.split(b" ")
        if not tab or len(fields) != 3:
            raise GateError("git ls-tree gave a line the gate cannot read")
        if fields[1] != b"blob":
            state["problem"] = f"the tree holds a {fields[1].decode(errors='replace')} at {path.decode(errors='replace')}"
            return state
        files[path] = (fields[0], fields[2].decode("ascii", "replace"))
    state["worktree"], state["files"] = tree, files
    return state


_THRESHOLD_ONE = re.compile(r"1(?:\.0+)?")


def done_claim_problem(claim: object) -> str | None:
    """Why a verified receipt's claim does not say that every test passed, or None. Done means a pytest pass
    rate of at least exactly 1 with passed true, at least one test and pytest's exit status 0: a lower
    threshold signs passed true for failing tests, and pytest's own receipt signs passed true for a run that
    exited 1 when the pass rate met the threshold (measured 2026-09-30, D23)."""
    if not isinstance(claim, dict) or claim.get("schema") != EVAL_CLAIM_SCHEMA:
        return "the receipt is not an eval receipt"
    if claim.get("suite") != "pytest" or claim.get("metric") != "pass_rate":
        return "the receipt is not a pytest receipt of the pass rate"
    if claim.get("comparator") != ">=" or not (isinstance(claim.get("threshold"), str)
                                               and _THRESHOLD_ONE.fullmatch(claim["threshold"])):
        return "the receipt does not require every test to pass (it needs comparator >= and threshold 1)"
    if claim.get("passed") is not True:
        return "the receipt says the tests did not pass"
    n, provenance = claim.get("n"), claim.get("provenance")
    if not (isinstance(n, int) and not isinstance(n, bool) and n >= 1):
        return "the receipt names no test that ran"
    status = provenance.get("exit_status") if isinstance(provenance, dict) else None
    if not (isinstance(status, int) and not isinstance(status, bool) and status == 0):
        return f"the receipt's pytest run did not exit 0 (exit status {status!r})"
    return None


def tested_tree(provenance: object) -> str | None:
    """The tree id the receipt's tests ran on: git_tree for a clean run, git_worktree_tree for a run on a
    working state that differed from HEAD, else None."""
    if not isinstance(provenance, dict):
        return None
    if provenance.get("git_clean") is True:
        value = provenance.get("git_tree")
    elif provenance.get("git_clean") is False:
        value = provenance.get("git_worktree_tree")
    else:
        return None
    return value if isinstance(value, str) and len(value) in _BLOB_HASHES and all(
        c in "0123456789abcdef" for c in value) else None


def _short(text: str, limit: int = 240) -> str:
    return text if len(text) <= limit else text[:limit - 3] + "..."


def _recorded_key_path(environ: dict, repo: str | None) -> str | None:
    """The key file done-init made for the repository, as its record in the gate directory names it (B30-2), or None:
    no repository, no gate directory, no protected channel in the hook's environment (D128: a session writes the record
    as it writes the owner files of D124), no record, or a record the gate does not read as one (not a regular file,
    larger than MAX_STATE_BYTES, not strict JSON of one object, no absolute path for this repository). Only the path is
    read."""
    directory = _gate_dir(environ)
    if repo is None or directory is None or not _owner_state_read(environ):   # D128
        return None
    try:
        doc = strict_json(_read_regular(os.path.join(directory, DONE_KEYS_RECORD), MAX_STATE_BYTES + 1))
    except (OSError, GateError, ValueError):
        return None
    path = doc.get(os.path.realpath(repo)) if isinstance(doc, dict) else None
    return path if isinstance(path, str) and os.path.isabs(path) and "\0" not in path else None


def _record_key_path(environ: dict, repo: str, key_path: str) -> str | None:
    """Record in the gate directory the key file done-init made for the repository (B30-2): a fresh temporary file
    that replaces the record, never through a link. None on success, else why not."""
    directory = _gate_dir(environ)
    if directory is None:
        return "no gate directory is known"
    target = os.path.join(directory, DONE_KEYS_RECORD)
    try:
        doc = strict_json(_read_regular(target, MAX_STATE_BYTES + 1)) if os.path.lexists(target) else {}
    except (OSError, GateError, ValueError):
        doc = None
    if not isinstance(doc, dict):
        return f"{DONE_KEYS_RECORD} in the gate directory is not a record the gate reads"
    doc[os.path.realpath(repo)] = key_path
    data = (json.dumps(doc, indent=1, sort_keys=True) + "\n").encode("utf-8", "surrogatepass")
    if len(data) > MAX_STATE_BYTES:
        return f"{DONE_KEYS_RECORD} would be more than {MAX_STATE_BYTES} bytes"
    temporary = os.path.join(directory, f".{DONE_KEYS_RECORD}.{secrets.token_hex(6)}.tmp")
    try:
        os.makedirs(directory, mode=0o700, exist_ok=True)
        fd = os.open(temporary, os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_NOFOLLOW", 0), 0o600)
        with os.fdopen(fd, "wb") as handle:
            handle.write(data)
        os.replace(temporary, target)
    except OSError as exc:
        try:
            os.unlink(temporary)
        except OSError:
            pass
        return f"{DONE_KEYS_RECORD} could not be written ({_os_error(exc)})"
    return None


def check_command(check: dict, environ: dict, repo: str | None = None) -> str:
    """The command that runs one check of the done section and leaves its receipt (D26, D28). A check of the
    order names its pytest arguments and clears PYTEST_ADDOPTS, so the receipt names exactly that selection. The key
    is PROOFBUNDLE_KEY where it is an absolute path, else the key file done-init made for the repository as the gate
    directory records it (B30-2, follow-up note 32: `done-init --key` may put it anywhere; read only with the protected
    channel, D128), else the default key file of the gate directory."""
    key = environ.get("PROOFBUNDLE_KEY")
    if not (key and os.path.isabs(key)):
        key = _recorded_key_path(environ, repo)
    if not key:
        directory = _gate_dir(environ)
        key = os.path.join(directory, DONE_KEY_FILE) if directory else "<your test key file>"
    selection = "" if check["args"] is None else "PYTEST_ADDOPTS= "
    args = "" if check["args"] is None else "".join(" " + shlex.quote(a) for a in check["args"])
    return (f"{selection}PROOFBUNDLE_EMIT=1 PROOFBUNDLE_THRESHOLD=1 PROOFBUNDLE_OUT={shlex.quote(check['receipt'])} "
            f"PROOFBUNDLE_KEY={shlex.quote(key)} python -m pytest{args}")


def selection_problem(check: dict, provenance: dict) -> str | None:
    """Why the receipt's run is not the run the check asks for, or None. A check of the order asks for exactly its
    pytest arguments, an empty PYTEST_ADDOPTS and no deselected test; the one-check form asks for no selection. Not
    seen here: plugins or conftest code that skip, select or rewrite tests in other ways (D28)."""
    if check["args"] is None:
        return None
    args, addopts, deselected = (provenance.get("pytest_args"), provenance.get("pytest_addopts"),
                                 provenance.get("n_deselected"))
    if not (isinstance(args, list) and all(isinstance(a, str) for a in args) and isinstance(addopts, str)
            and type(deselected) is int):
        return "the receipt does not name how pytest was asked to run (pytest_args, pytest_addopts, n_deselected)"
    if args != check["args"]:
        return "the receipt's run had other pytest arguments than the check asks for"
    if addopts.strip():
        return "the receipt's run had PYTEST_ADDOPTS set, which the check does not allow"
    if deselected != 0:
        return f"the receipt's run deselected {deselected} tests"
    return None


def _receipt_bytes(path: str) -> bytes | None:
    """The receipt file's bytes; None when there is none. A link, another file type or an oversized file is
    refused, not followed."""
    try:
        st = os.lstat(path)
    except FileNotFoundError:
        return None
    except OSError as exc:
        raise GateError(f"the receipt {path} cannot be read: {exc}") from exc
    if not stat.S_ISREG(st.st_mode):
        raise GateError(f"the receipt {path} is not a regular file")
    if st.st_size > MAX_EVIDENCE_BYTES:
        raise GateError(f"the receipt {path} is larger than {MAX_EVIDENCE_BYTES} bytes")
    try:
        return _read_regular(path, MAX_EVIDENCE_BYTES + 1)   # checked again at the descriptor (R18-2 class)
    except _NotRegular as exc:
        raise GateError(f"the receipt {path} is not a regular file") from exc


def _signed_payload(content: bytes) -> bytes | None:
    """B of a proofbundle bundle: the payload bytes its signature covers, or None where there is none to read."""
    try:
        bundle = strict_json(content)
        return base64.b64decode(bundle["payload_b64"], validate=True) if isinstance(bundle, dict) else None
    except (KeyError, TypeError, ValueError, binascii.Error):
        return None


#: How many commits that changed the declaration the gate reads back to find the commit that declared the order; past
#: it the base is NOT MEASURED (owner choice Nordstern B).
MAX_ORDER_WALK = 256


def _parents(repo: str, commit: str, deadline: float) -> tuple[list[str], list[str]] | None:
    """(shown, recorded): the parents git shows for a commit and the parents its commit object names, or None where git
    cannot read either. They differ where git cuts the history at the commit (a shallow clone, or a shallow file named
    by GIT_SHALLOW_FILE), whatever source told git so; the gate reads no shallow file itself (review round 6 of
    2026-10-10, R6-1: it read the cut points from `--git-path shallow` while git followed GIT_SHALLOW_FILE). Replace refs
    and grafts are already off for every read of the gate (_read_env), so a difference is a cut."""
    shown = _git(repo, "rev-list", "--parents", "--max-count=1", commit, deadline=deadline)
    raw = _git(repo, "cat-file", "commit", commit, deadline=deadline)
    if shown.returncode != 0 or raw.returncode != 0:
        return None
    ids = shown.stdout.decode("ascii", "replace").split()
    if not ids or ids[0] != commit:
        return None
    header = raw.stdout.split(b"\n\n", 1)[0]
    recorded = [line[len(b"parent "):].decode("ascii", "replace") for line in header.split(b"\n")
                if line.startswith(b"parent ")]
    return ids[1:], recorded


def _order_at(repo: str, commit: str, deadline: float) -> tuple | None:
    """The canonical done section at a commit, None where it declares none; a declaration that does not parse is an
    order of its own (its bytes' digest), never the same as a valid one."""
    raw = _blob(repo, commit, DECLARATION, deadline, MAX_DECLARATION_BYTES)
    if raw is None:
        return None
    try:
        done = parse_done(raw)
    except GateError:
        return ("malformed", hashlib.sha256(raw).hexdigest())
    return None if done is None else _done_canonical(done)


def order_base(repo: str, commit: str, done: dict, deadline: float) -> tuple[str | None, str]:
    """The commit that declared the order as it stands at `commit` (owner choice Nordstern B, D28): on the first-parent
    line, the newest commit that changed the declaration and whose first parent declares another order or none. A
    change to the declaration that leaves the done section as it is (an evidence item, a subject) does not move it.
    (None, why) where it cannot be determined: the history is cut before it is found (git shows a commit without the
    parents its object names: a shallow clone or a shallow file git reads, R6-1), more than MAX_ORDER_WALK commits
    changed the declaration, or git cannot list them. `rev-list`, not `log`: no signature check, no pager, no program a
    configuration names."""
    section = _done_canonical(done)
    proc = _git(repo, "rev-list", "--first-parent", f"--max-count={MAX_ORDER_WALK + 1}", commit, "--", DECLARATION,
                deadline=deadline)
    if proc.returncode != 0:
        return None, "git could not list the commits that changed the declaration"
    candidates = proc.stdout.decode("ascii", "replace").split()
    for n, candidate in enumerate(candidates):
        if n == MAX_ORDER_WALK:
            return None, f"more than {MAX_ORDER_WALK} commits changed {DECLARATION} since the order was declared"
        parents = _parents(repo, candidate, deadline)
        if parents is None:
            return None, f"git could not read the parents of {candidate[:12]}"
        shown, recorded = parents
        if shown != recorded:
            return None, (f"the history is cut at {candidate[:12]}: git shows it without the parents its commit names "
                          "(a shallow clone, or a shallow file git reads), so the gate cannot tell which commit declared "
                          "the order")
        if not recorded:
            return candidate, ""   # a root commit of a full history declared it
        if _order_at(repo, recorded[0], deadline) != section:
            return candidate, ""
    return None, f"no commit on the first-parent line of {commit[:12]} declared the order it holds"


def changed_paths(repo: str, base: str, files: dict, deadline: float) -> list[str]:
    """The paths whose mode or bytes differ between the tree of `base`, the commit that declared the order
    (order_base), and the state `files` (D28)."""
    listing = _git(repo, "ls-tree", "-r", "-z", "--full-tree", base, deadline=deadline)
    if listing.returncode != 0:
        raise GateError(f"git could not list the tree of {base[:12]}, the commit that set the order")
    before = {}
    for record in listing.stdout.split(b"\0"):
        if not record:
            continue
        meta, tab, path = record.partition(b"\t")
        fields = meta.split(b" ")
        if not tab or len(fields) != 3 or fields[1] != b"blob":
            raise GateError(f"the tree of {base[:12]}, the commit that set the order, holds an entry the gate cannot "
                            "compare as a file")
        before[path] = (fields[0], fields[2].decode("ascii", "replace"))
    changed = sorted(p for p in set(before) | set(files) if before.get(p) != files.get(p))
    return [p.decode("utf-8", "surrogateescape") for p in changed]


#: Which reason id a deny of the done check carries for its first open point.
_OPEN_REASON = {"missing": "no_receipt", "unverified": "verification_failed", "red": "not_done",
                "other_selection": "other_selection", "no_state": "not_done", "stale": "stale_receipt",
                "outside_paths": "outside_paths", "no_change": "no_change"}


def done_evaluation(directory: str, deadline: float, receipt_path: str | None = None, environ: dict | None = None,
                    receipt_dir: str | None = None, at_commit: str | None = None, reviewed: bool = False,
                    order: dict | None = None, local_order: bool = False) -> dict:
    """The done check (D26, D28) with what it found: {"verdict", "done", "repo", "commit", "state", "checks",
    "open", "policy", "base", "inside"}. Pass when every check of the done section has a receipt that verifies under
    the declared policy at HEAD, says that every test passed, was run with the check's selection, names HEAD's commit
    and tree and the tree of the working state now, and, for an order with paths, the working state changes at least
    one path the order names and none it does not allow, since the commit that declared the order; inactive (NOT
    MEASURED, no block) where no done check is declared; deny otherwise, naming the first open
    point and the command that closes it. `receipt_path` (one check) and `receipt_dir` (receipts named <id>.json)
    override the declared receipts, for the CI check, whose receipts lie outside the checkout. `at_commit` is the
    check at a pushed commit (owner choice N2 C): the declaration, the policy and the order come from that commit,
    and its tree, read from git, stands in for the working state; the receipts are still read from the working
    tree. A pushed commit without a declaration or a done check gets no done check (inactive). At a commit a receipt
    counts only for a clean run on that commit (git_clean true, review 2026-10-09 F1): a run on a working state that
    differed from it is not a run on the commit, whatever tree ids the receipt names. `reviewed` names the commit in
    the texts as the commit under review (the CI check) instead of a pushed commit. `order` is a local done order
    (D38, _local_orders): its done section, policy and base stand in for the declaration's at HEAD, and the texts name
    the repository. `local_order` says that the repository has a local order, which stands for a declaration found only
    in the work tree, so that one is not refused as uncommitted (D38)."""
    result = {"verdict": None, "done": None, "repo": None, "commit": None, "state": None, "checks": [], "open": [],
              "policy": None, "base": None, "inside": [], "local": None if order is None else order["file"]}
    try:
        return _evaluate_done(result, directory, deadline, receipt_path, environ, receipt_dir, at_commit, reviewed,
                              order, local_order)
    except Exception as exc:
        # What the check had found before it failed, for the Stop hook's count (review 2026-10-09, F6).
        try:
            exc.partial = result  # type: ignore[attr-defined]
        except AttributeError:
            pass
        raise


def _refused(result: dict, verdict: Verdict, ident: str) -> dict:
    """A check that refuses before it reaches the open checks: the verdict, and the same refusal as the one open point,
    so the Stop hook counts it toward max_blocks and writes the blocker like any other (review 2026-10-09, F6)."""
    result["verdict"] = verdict
    result["open"] = [{"id": ident, "status": verdict.reason_id, "failed": verdict.failed,
                       "command": verdict.next_step}]
    return result


def _evaluate_done(result: dict, directory: str, deadline: float, receipt_path: str | None, environ: dict | None,
                   receipt_dir: str | None, at_commit: str | None, reviewed: bool, order: dict | None = None,
                   local_order: bool = False) -> dict:
    environ = os.environ if environ is None else environ
    repo, unreadable = _work_tree(directory, deadline, "--path-format=absolute")
    if unreadable:
        raise GateError(unreadable)   # a read that failed is not "no repository": the end is not freed (R5-1)
    if repo is None:
        result["verdict"] = Verdict("inactive", "NOT MEASURED: not a git repository; no done check applies.",
                                    "no_repository")
        return result
    # The repository is known from here on: a failure after this point, the partial-clone refusal of the HEAD read
    # among them, is counted toward the repeat limit like any other refusal (review round 2 of 2026-10-09, R2-4).
    result["repo"] = repo
    head = _git(repo, "rev-parse", "--verify", "-q", "HEAD^{commit}", deadline=deadline)
    head_commit = head.stdout.decode("ascii", "replace").strip() if head.returncode == 0 else ""
    commit, where, now = head_commit, "HEAD", "the working state now"
    if at_commit is not None:
        pushed = _git(repo, "rev-parse", "--verify", "-q", f"{at_commit}^{{commit}}", deadline=deadline)
        commit = pushed.stdout.decode("ascii", "replace").strip()
        if pushed.returncode != 0 or len(commit) not in _BLOB_HASHES:
            raise GateError(f"git could not name the {'commit under review' if reviewed else 'pushed commit'} "
                            f"{at_commit[:12]}")
        where, now = ((f"the commit under review {commit[:12]}", "the tree of the commit under review") if reviewed
                      else (f"the pushed commit {commit[:12]}", "the tree the push sends"))
    result.update(repo=repo, commit=commit or None)
    if order is not None:
        return _evaluate_rows(result, repo, commit, head_commit, where, now, order["done"], order["policy"], deadline,
                              receipt_path, environ, receipt_dir, at_commit, order)
    raw = _blob(repo, commit, DECLARATION, deadline, MAX_DECLARATION_BYTES) if commit else None
    if raw is None and at_commit is not None:
        result["verdict"] = Verdict("inactive", f"NOT MEASURED: no declaration at {where} ({DECLARATION} is absent "
                                                "there); no done check applies to it.", "nothing_declared", repo=repo,
                                    head=commit)
        return result
    if raw is None:
        if _absent_in_working_tree(repo):
            result["verdict"] = Verdict("inactive", f"NOT MEASURED: no declaration ({DECLARATION} is absent at HEAD "
                                                    "and in the working tree); no done check applies.",
                                        "nothing_declared", repo=repo, head=commit or None)
            return result
        if local_order:
            # D38: the repository has a local done order, made from the declaration in the work tree or from files
            # outside it; that order is judged on its own, so the uncommitted declaration is not refused here
            result["verdict"] = Verdict("inactive", f"NOT MEASURED: {DECLARATION} is not at HEAD; the repository's local "
                                                    "done order is judged in its place (D38).",
                                        "local_order_stands", repo=repo, head=commit or None)
            return result
        return _refused(result, Verdict("deny", f"NOT MEASURED: {DECLARATION} is in the working tree but not at HEAD.",
                                        "declaration_not_committed", evidence=f"the declaration {DECLARATION}",
                                        failed="the declaration is not committed, so the done check cannot read it "
                                               "from HEAD", next_step=f"commit {DECLARATION}", repo=repo,
                                        head=commit or None), "declaration")
    done = parse_done(raw)
    if done is None:
        result["verdict"] = Verdict("inactive", f"NOT MEASURED: {DECLARATION} at {where} declares no done check.",
                                    "no_done_check", repo=repo, head=commit)
        return result
    result["done"] = done
    checks = done["checks"]
    if receipt_path is not None and len(checks) != 1:
        raise GateError(f"the done check declares {len(checks)} checks; name a folder of receipts with --receipt-dir")
    policy = _blob(repo, commit, done["policy"], deadline, MAX_DECLARATION_BYTES)
    if policy is None:
        return _refused(result, Verdict("deny", f"proofbundle gate: the done policy {done['policy']} is missing at "
                                                f"{where}.", "missing_file", evidence=f"the done policy {done['policy']}",
                                        failed=f"the policy is missing at {where}",
                                        next_step=f"commit the policy {done['policy']} that pins your test key",
                                        repo=repo, head=commit), "policy")
    require_pinned_signer(policy, f"the done policy {done['policy']}")
    return _evaluate_rows(result, repo, commit, head_commit, where, now, done, policy, deadline, receipt_path, environ,
                          receipt_dir, at_commit, None)


def _evaluate_rows(result: dict, repo: str, commit: str, head_commit: str, where: str, now: str, done: dict,
                   policy: bytes, deadline: float, receipt_path: str | None, environ, receipt_dir: str | None,
                   at_commit: str | None, order: dict | None) -> dict:
    """The checks of a done section against their receipts and the working state, from the declaration at HEAD or from
    a local done order (D38), whose policy and base it carries."""
    checks = done["checks"]
    if order is not None:
        result["done"] = done
        if receipt_path is not None and len(checks) != 1:
            raise GateError(f"the done check declares {len(checks)} checks; name a folder of receipts with "
                            "--receipt-dir")
        require_pinned_signer(policy, f"the policy of the local done order {order['file']}")
    result["policy"] = policy
    rows = []
    for check in checks:
        if receipt_path is not None:
            location = receipt_path
        elif receipt_dir is not None:
            location = os.path.join(receipt_dir, check["id"] + ".json")
        else:
            location = os.path.join(repo, *check["receipt"].split("/"))
        command = check_command(check, environ, repo)
        if at_commit is not None and commit != head_commit:  # the receipt must name the pushed commit's tree
            command = f"{_shell_command('git', 'checkout', commit[:12])} && {command}"
        row = {"id": check["id"], "receipt": check["receipt"], "location": location, "status": None, "failed": "",
               "command": command, "content": None, "payload": None}
        try:
            row["content"] = _receipt_bytes(location)
        except GateError as exc:
            row.update(status="unverified", failed=str(exc))
        if row["status"] is None and row["content"] is None:
            shown = check["receipt"] if receipt_path is None and receipt_dir is None else location
            row.update(status="missing", failed=f"no test run left a receipt at {shown}")
        rows.append(row)
    present = [row for row in rows if row["status"] is None]
    if present:
        with tempfile.TemporaryDirectory(prefix="proofbundle-done-") as scratch:
            policy_file = os.path.join(scratch, "policy.json")
            with open(policy_file, "wb") as handle:
                handle.write(policy)
            requests = []
            for n, row in enumerate(present):
                target = os.path.join(scratch, f"receipt-{n}.json")
                with open(target, "wb") as handle:
                    handle.write(row["content"])
                requests.append({"kind": "bundle", "path": target, "policy_path": policy_file})
            answers = verify_items(requests, deadline)
        for row, answer in zip(present, answers):
            exit_code = answer.get("exit_code")
            if answer["is_error"] or not (isinstance(exit_code, int) and not isinstance(exit_code, bool)
                                          and exit_code == 0):
                why = answer.get("error") or f"exit {exit_code!r}: {answer.get('meaning')}"
                row.update(status="unverified", failed=f"it does not verify under the done policy ({why})")
    state = None
    for row, check in zip(rows, checks):
        if row["status"] is not None:
            continue
        row["payload"] = _signed_payload(row["content"])
        try:
            claim = strict_json(row["payload"]) if row["payload"] is not None else None
        except ValueError:
            claim = None
        problem = done_claim_problem(claim)
        if problem is not None:
            row.update(status="red", failed=problem)
            continue
        provenance = claim["provenance"]
        problem = selection_problem(check, provenance)
        if problem is not None:
            row.update(status="other_selection", failed=problem)
            continue
        tested = tested_tree(provenance)
        if tested is None:
            row.update(status="no_state", failed="the receipt names no git state the tests ran on")
            continue
        if state is None:
            state = working_state(repo, deadline) if at_commit is None else commit_state(repo, commit, deadline)
            result["state"] = state
            if state["worktree"] is None:
                result["checks"] = rows
                return _refused(result, _state_not_measured(now, state, repo, commit), "state")
        named = (provenance.get("git_hash"), provenance.get("git_tree"))
        if named != (state["commit"], state["tree"]):
            row.update(status="stale", failed=f"the receipt names commit {str(named[0])[:12]} with tree "
                                              f"{str(named[1])[:12]}, and {where.removesuffix(' ' + commit[:12])} is "
                                              f"commit {state['commit'][:12]} with tree {state['tree'][:12]}")
            continue
        if tested != state["worktree"]:
            row.update(status="stale", failed=f"the tests ran on tree {tested[:12]}, and {now} is "
                                              f"tree {state['worktree'][:12]}")
            continue
        if at_commit is not None and provenance.get("git_clean") is not True:
            row.update(status="stale", failed=f"the receipt says git_clean false: its tests ran on a working state "
                                              f"that differed from commit {state['commit'][:12]}, and at "
                                              f"{where.removesuffix(' ' + commit[:12])} only a clean run on its own "
                                              "tree counts")
            continue
        row.update(status="green", tested=tested, tests=claim["n"])
    result["checks"] = rows
    opened = [{"id": row["id"], "status": row["status"], "failed": row["failed"], "command": row["command"],
               "receipt": row["receipt"]} for row in rows if row["status"] != "green"]
    if done["paths"] is not None:
        # Owner choice Nordstern B: an order that names paths is done only with a change in them since the commit that
        # declared it, for the state the receipts are for; and with none outside them (D28).
        if state is None:
            state = result["state"] = (working_state(repo, deadline) if at_commit is None
                                       else commit_state(repo, commit, deadline))
            if state["worktree"] is None:
                return _refused(result, _state_not_measured(now, state, repo, commit), "state")
        base, why = (order_base(repo, commit, done, deadline) if order is None
                     else _local_order_base(repo, order, deadline))
        if base is None:
            return _refused(result, Verdict(
                "deny", f"NOT MEASURED: {why}, so the gate cannot tell whether the work changed the paths the order "
                        "names.", "order_base_not_measured", evidence=f"the history of {DECLARATION}", failed=why,
                next_step="fetch the full history (git fetch --unshallow) and run the checks again, or have a person "
                          "judge the work", repo=repo, head=commit), "paths")
        result["base"] = base
        changed = changed_paths(repo, base, state["files"], deadline)
        named = ", ".join(done["paths"])
        inside = [p for p in changed if any(fnmatch.fnmatchcase(p, pattern) for pattern in done["paths"])]
        outside = [p for p in changed if p not in inside]
        result["inside"] = inside
        if not inside:
            opened.insert(0, {"id": "paths", "status": "no_change",
                              "failed": _short(f"nothing in the paths the order names ({named}) changed in {now} since "
                                               f"{base[:12]}, the commit that declared the order, so the work the "
                                               "order asks for is missing", 400),
                              "command": f"do the work the order asks for in {named}, then run the checks again"})
        if outside:
            shown = ", ".join(outside[:5]) + (f" and {len(outside) - 5} more" if len(outside) > 5 else "")
            opened.append({"id": "paths", "status": "outside_paths",
                           "failed": _short(f"the work changes paths the order does not allow since {base[:12]}: "
                                            f"{shown}", 400),
                           "command": "undo the changes outside the allowed paths, or ask the owner to change the "
                                      "order", "outside": outside})
    result["open"] = opened
    if opened:
        first = opened[0]
        others = [f"{p['id']} ({p['status'].replace('_', ' ')})" for p in opened[1:]]
        failed = f"check {first['id']} is {first['status'].replace('_', ' ')}: {first['failed']}"
        if others:
            failed += "; also open: " + ", ".join(others)
        next_step = first["command"] if first["status"] in ("outside_paths", "no_change") else f"run {first['command']}"
        if order is not None:   # D38, D49: the end may be judged from another directory; the order is named, never
            failed = f"{_order_label(order['file'])}: {failed}"   # the root it records
            next_step += " in its repository, the root done-order --list names"
        result["verdict"] = Verdict("deny", f"proofbundle gate: {failed}.", _OPEN_REASON[first["status"]],
                                    evidence=f"the receipt {first['receipt']}" if "receipt" in first
                                    else "the working state", failed=failed, next_step=next_step, repo=repo,
                                    head=commit)
        return result
    tested = rows[0]["tested"]
    names = ", ".join(row["id"] for row in rows)
    result["verdict"] = Verdict(
        "pass", f"proofbundle gate: done. {len(rows)} {'check' if len(rows) == 1 else 'checks'} ({names}): every "
                f"receipt verifies under "
                f"{done['policy'] if order is None else 'the policy of ' + _order_label(order['file'])}, says every "
                f"one of its tests passed with exit status 0, was "
                f"run with the check's selection, and names commit {commit[:12]} and tree {tested}, {now}"
                + ("" if at_commit is not None else f" ({'clean' if tested == state['tree'] else 'with uncommitted changes'})")
                + (f"; no path outside the order changed since {result['base'][:12]}, the commit that declared it, "
                   f"and {len(result['inside'])} {'path' if len(result['inside']) == 1 else 'paths'} in it did"
                   if result["base"] else "")
                + ". This proves who signed the receipts and which tree they name, not that the tests test anything.",
        "done", repo=repo, head=commit)
    return result


def _state_not_measured(now: str, state: dict, repo: str, commit: str) -> Verdict:
    return Verdict("deny", f"NOT MEASURED: {now} cannot be read as files: {state['problem']}.", "state_not_measured",
                   evidence="the working tree", failed=state["problem"],
                   next_step="remove the cause named here, then run the tests with a receipt", repo=repo, head=commit)


def done_verdict(directory: str, deadline: float, receipt_path: str | None = None,
                 environ: dict | None = None) -> Verdict:
    """The verdict of done_evaluation alone."""
    return done_evaluation(directory, deadline, receipt_path, environ)["verdict"]


def _done_line(verdict: Verdict) -> str:
    """The one line a blocked end shows: the open point and the command that closes it."""
    return (f"proofbundle done check: {verdict.failed.rstrip('.')}. Next: {verdict.next_step.rstrip('.')}. "
            "Never weaken the declaration, the policy or the key to end the session.")


# --- the done check's own files in the evidence folder (D28) -------------------------------------------------------

def _evidence_folder(repo: str, create: bool = False) -> str | None:
    """The repository's .proofbundle folder when it is a real directory (not a link), else None. With create, a folder
    that is absent (nothing at all at its path) is made first, so the done check can count its blocks in a working tree
    from which the folder was removed (review round 3 of 2026-10-09, R3-4); a file or a link there is left as it is."""
    path = os.path.join(repo, EVIDENCE_DIR.rstrip("/"))
    if create:
        try:
            os.mkdir(path, 0o755)
        except OSError:
            pass   # it exists (a directory, a file or a link), or it cannot be made: the check below decides
    try:
        return path if stat.S_ISDIR(os.lstat(path).st_mode) else None
    except OSError:
        return None


def _read_done_file(repo: str, name: str, kind: str) -> dict | None:
    """One of the done check's own files, or None where it is absent, not a regular file, too large, not strict
    JSON or of another schema. Its content is counted, never trusted for a verdict."""
    if _evidence_folder(repo) is None:
        return None
    path = os.path.join(repo, *name.split("/"))
    try:
        st = os.lstat(path)
        if not stat.S_ISREG(st.st_mode) or st.st_size > MAX_STATE_BYTES:
            return None
        doc = strict_json(_read_regular(path, MAX_STATE_BYTES + 1))   # checked again at the descriptor
    except (OSError, ValueError):
        return None
    return doc if isinstance(doc, dict) and doc.get("schema") == DONE_FILES_SCHEMA.format(kind) else None


def _done_file_problem(repo: str, name: str, kind: str) -> str | None:
    """Why one of the done check's own files is present but cannot be read back (_read_done_file), None when it is
    absent or readable (review round 4 of 2026-10-09, R4-3: a record the next count cannot read is named, not taken
    for a first block in silence)."""
    path = os.path.join(repo, *name.split("/"))
    try:
        st = os.lstat(path)
    except FileNotFoundError:
        return None
    except OSError as exc:
        return f"{name} cannot be examined ({exc.strerror or exc})"
    if _read_done_file(repo, name, kind) is not None:
        return None
    if not stat.S_ISREG(st.st_mode):
        return f"{name} is not a regular file"
    if st.st_size > MAX_STATE_BYTES:
        return f"{name} is {st.st_size} bytes, more than the {MAX_STATE_BYTES} the hook reads back"
    return f"{name} is not the hook's own record (strict JSON of its schema)"


def _write_done_file(repo: str, name: str, doc: dict) -> str | None:
    """Write one of the done check's own files through a fresh temporary file that replaces it; never through a
    link. None on success, else why not. A document whose bytes exceed MAX_STATE_BYTES is not written: the hook would
    not read it back, so the next count would start again in silence (R4-3)."""
    data = (json.dumps(doc, indent=1, sort_keys=True) + "\n").encode("utf-8", "surrogatepass")
    if len(data) > MAX_STATE_BYTES:
        return f"{name} would be {len(data)} bytes, more than the {MAX_STATE_BYTES} the hook reads back"
    folder = _evidence_folder(repo, create=True)
    if folder is None:
        return f"{EVIDENCE_DIR} is not a directory of the repository"
    target = os.path.join(repo, *name.split("/"))
    temporary = os.path.join(folder, f".{os.path.basename(name)}.{secrets.token_hex(6)}.tmp")
    try:
        # Mode 600: only the Stop hook of the session reads these files back (CodeQL alert 151).
        fd = os.open(temporary, os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_NOFOLLOW", 0), 0o600)
        with os.fdopen(fd, "wb") as handle:
            handle.write(data)
        os.replace(temporary, target)
    except OSError as exc:
        try:
            os.unlink(temporary)
        except OSError:
            pass
        return f"{name} could not be written: {exc}"
    return None


def _tally(repo: str, **increments) -> None:
    """Add to the local counters in DONE_METRICS (D28, N5): no network, nothing leaves the machine. A file that is
    not the counters' own form is started afresh."""
    metrics = _read_done_file(repo, DONE_METRICS, "metrics")
    if metrics is None or not all(type(metrics.get(k)) is int for k in METRIC_KEYS) \
            or not isinstance(metrics.get("open"), dict):
        metrics = {"schema": DONE_FILES_SCHEMA.format("metrics"), "first": _now(), "open": {},
                   **{k: 0 for k in METRIC_KEYS}}
    opened = increments.pop("open", ())
    for key, value in increments.items():
        metrics[key] += value
    for status in opened:
        metrics["open"][status] = (metrics["open"].get(status) if type(metrics["open"].get(status)) is int else 0) + 1
    metrics["last"] = _now()
    _write_done_file(repo, DONE_METRICS, metrics)


#: The longest session id a blocker names in full; a longer one is named by its sha256 alone (R4-3).
MAX_SESSION_TEXT = 256


def _session_key(event: dict | None) -> str:
    """The sha256 of the host's session id ("" when the event names none): the state file binds the session by this
    fixed-length key, so the record stays within MAX_STATE_BYTES whatever the host sends (review round 4 of
    2026-10-09, R4-3: a session id of 65536 characters made a record of 65684 bytes the next read discarded). Equal
    ids give equal keys and different ids different keys, so the count stays per session."""
    session = event.get("session_id") if isinstance(event, dict) and isinstance(event.get("session_id"), str) else ""
    return hashlib.sha256(session.encode("utf-8", "surrogatepass")).hexdigest()


def _session_text(event: dict | None) -> str | None:
    """The session id for a human reading the blocker, None when it is longer than MAX_SESSION_TEXT."""
    session = event.get("session_id") if isinstance(event, dict) and isinstance(event.get("session_id"), str) else ""
    return session if len(session) <= MAX_SESSION_TEXT else None


_STATE_FIELDS = frozenset({"schema", "session_sha256", "open", "blocks", "blocker"})
#: The form the gate wrote before R4-3, with the session id in clear (f0e25574 and earlier).
_STATE_FIELDS_CLEAR = frozenset({"schema", "session", "open", "blocks", "blocker"})
_SESSION_SHA256 = re.compile(r"[0-9a-f]{64}")


def _done_state(repo: str) -> tuple[dict | None, str | None]:
    """The count record (DONE_STATE) as (record, problem). record carries session_sha256, open, blocks and blocker
    when the file is a running count, problem is None then and where there is no file; (None, why) where a present
    file does not serve as a running count. The schema value alone does not make a record usable: every field is
    checked (review round 5 of 2026-10-09, R5-3: an older gate's record with the session in clear, and blocks "1" as a
    string, both restarted the count without a word). The form the gate wrote before R4-3, with the session id in
    clear, is taken over by the session's sha256, so an update of the plugin continues the count it finds."""
    doc = _read_done_file(repo, DONE_STATE, "state")
    if doc is None:
        return None, _done_file_problem(repo, DONE_STATE, "state")
    return _count_record(doc, DONE_STATE)


def _count_record(doc: dict, name: str) -> tuple[dict | None, str | None]:
    """The checks of _done_state on a count record read from `name`: (record, None) for a running count, (None, why)
    otherwise. The same checks hold for the count of a local done order in the gate directory (D38, O3)."""
    fields = frozenset(doc)
    if fields == _STATE_FIELDS_CLEAR and isinstance(doc["session"], str):
        session = hashlib.sha256(doc["session"].encode("utf-8", "surrogatepass")).hexdigest()
    elif fields == _STATE_FIELDS:
        session = doc["session_sha256"]
    else:
        return None, f"{name} carries the fields {', '.join(sorted(fields))}, not those of the hook's count"
    open_points = doc["open"]
    why = ("its session is not a sha256" if not (isinstance(session, str) and _SESSION_SHA256.fullmatch(session))
           else "its open points are not a list of [id, status] pairs"
           if not (isinstance(open_points, list) and all(isinstance(p, list) and len(p) == 2
                                                         and all(isinstance(x, str) for x in p) for p in open_points))
           else "its block count is not a whole number of at least 0"
           if not (type(doc["blocks"]) is int and doc["blocks"] >= 0)
           else "its blocker flag is not true or false" if type(doc["blocker"]) is not bool else None)
    if why is not None:
        return None, f"{name} is not a running count: {why}"
    return {"session_sha256": session, "open": open_points, "blocks": doc["blocks"], "blocker": doc["blocker"]}, None


def _blocker(result: dict, event: dict | None, blocks: int) -> dict:
    """The blocker file: every open point of the last verdict, in its order, with what it found and the command that
    closes it (review 2026-10-09, F5: a missing change in the order's paths was not named, and the paths outside them
    were lost when it came first); the paths the order names, the commit it was compared with, and each check."""
    state = result["state"] or {}
    # A check is "verified" only when it was judged green; one the check stopped before comparing with the state
    # (status None, e.g. a state that could not be measured) is not judged, never verified (R2-5).
    checks = [{"id": row["id"], "status": row["status"],
               "detail": row["failed"] or ("verified" if row["status"] == "green" else
                                           "not judged: the check stopped before it compared this receipt with the "
                                           "state"),
               "command": row["command"]}
              for row in result["checks"]]
    opened = [{"id": p["id"], "status": p["status"], "detail": p["failed"], "command": p["command"],
               **({"outside": p["outside"]} if "outside" in p else {})} for p in result["open"]]
    outside = next((p.get("outside", []) for p in result["open"] if p["status"] == "outside_paths"), [])
    done = result["done"] or {}
    return {"schema": DONE_FILES_SCHEMA.format("blocker"), "verdict": "NOT DONE", "written": _now(),
            "session": _session_text(event), "session_sha256": _session_key(event),
            "blocks_without_progress": blocks - 1, "head": result["commit"],
            "tree": state.get("tree"), "working_tree": state.get("worktree"),
            "clean": (state.get("worktree") == state.get("tree")) if state else None, "open": opened,
            "checks": checks, "paths": done.get("paths"), "order_base": result.get("base"), "outside_paths": outside,
            "text": "NOT DONE. The Stop hook stopped blocking after the same open points stayed open; this file names "
                    "them and the state the gate measured. It is not a receipt and proves nothing about the tests."}


def _account_block(result: dict, event: dict | None, limit: int) -> tuple[str | None, str | None, str | None]:
    """Count one blocked end (D28, N3 and N5) and decide whether to keep blocking. Returns (blocker, problem, unread):
    blocker
    None to block, else the path of the blocker file written instead: after `limit` blocks (the order's max_blocks)
    with the same open points (no progress) in the same session the hook writes the blocker and lets the session end
    without a done verdict. problem names why the count could not be recorded, None when it was: the bounded end then
    cannot take effect, and the block says so instead of depending silently on a file it could not write (review
    round 3 of 2026-10-09, R3-4). The record binds the session by its sha256 and never exceeds the bound it is read
    with; unread names a present record the hook could not read, in which case this block counted as the first and the
    record is written again (R4-3; a record of the right schema that is no running count included, R5-3), None
    otherwise."""
    repo = result["repo"]
    session = _session_key(event)
    signature = [[p["id"], p["status"]] for p in result["open"]]
    previous, unread = _done_state(repo)
    same = previous is not None and previous["session_sha256"] == session and previous["open"] == signature
    blocks = previous["blocks"] + 1 if same else 1
    statuses = [p["status"] for p in result["open"]]
    if blocks > limit:
        first = not (same and previous["blocker"] is True)
        # Every stop past the limit writes the blocker from the verdict it reached, so the file the message names
        # exists and shows the state last measured: the open points can keep their ids and statuses while the paths
        # and the tree change, and a deleted blocker is written again (review round 2 of 2026-10-09, R2-5). The
        # counter of blockers counts it once.
        problem = _write_done_file(repo, DONE_BLOCKER, _blocker(result, event, blocks))
        if problem is not None:
            _tally(repo, blocked=1, missing_checks=statuses.count("missing"), open=statuses)
            counted = _write_done_file(repo, DONE_STATE, {"schema": DONE_FILES_SCHEMA.format("state"),
                                                          "session_sha256": session, "open": signature,
                                                          "blocks": blocks, "blocker": False})
            return None, (f"the blocker could not be written ({problem})"
                          + ("" if counted is None else f", nor the block count ({counted})")), unread
        if first:
            _tally(repo, blockers=1)
        # The end stands once the blocker is written; a count the hook could not record is named in the end's message,
        # never dropped: the next stop reads the record from before this end (review round 7 of 2026-10-10, R7-5)
        counted = _write_done_file(repo, DONE_STATE, {"schema": DONE_FILES_SCHEMA.format("state"),
                                                      "session_sha256": session, "open": signature, "blocks": blocks,
                                                      "blocker": True})
        return DONE_BLOCKER, (None if counted is None else f"the end could not be recorded in the count ({counted})"), \
            unread
    _tally(repo, blocked=1, missing_checks=statuses.count("missing"), open=statuses)
    problem = _write_done_file(repo, DONE_STATE, {"schema": DONE_FILES_SCHEMA.format("state"), "session_sha256": session,
                                                  "open": signature, "blocks": blocks, "blocker": False})
    return None, (None if problem is None else f"the block count could not be recorded ({problem})"), unread


def _account_pass(result: dict, event: dict | None) -> tuple[str | None, str | None, str | None]:
    """Count a done verdict, and a completion after at least one block in the same session; the blocker of an
    earlier stop no longer stands and is removed. Returns (problem, removal, unread): problem names why the reset count
    could not be written, removal why the earlier blocker could not be removed, unread a present record the hook could
    not read (replaced only where problem is None), None where there is none. A done end names each like a refused one
    (review round 6 of 2026-10-10, R6-4: the record's problem was read here and dropped, so a record with blocks "1" was
    written over without a word, against R5-3). The three stay apart (review round 8 of 2026-10-10, R8-4: a removal that
    failed was reported as a count that could not be recorded, while the record held a valid count, and the note on the
    replaced unread record was dropped). The hand-over record of D127 goes with the blocker; removal names each file that
    stays, with what it means."""
    repo = result["repo"]
    session = _session_key(event)
    previous, unread = _done_state(repo)
    after_block = previous is not None and previous["session_sha256"] == session and previous["blocks"] >= 1
    _tally(repo, done=1, completed_after_block=1 if after_block else 0)
    problem = _write_done_file(repo, DONE_STATE, {"schema": DONE_FILES_SCHEMA.format("state"), "session_sha256": session,
                                                  "open": [], "blocks": 0, "blocker": False})
    removed = []
    for name, what, stale in ((DONE_BLOCKER, "blocker", "the blocker file is out of date"),
                              (DONE_HANDOVER, "hand-over record", "a later hand-over may count its rounds from that "
                                                                  "record (D127)")):
        path = os.path.join(repo, *name.split("/"))
        try:
            if stat.S_ISREG(os.lstat(path).st_mode):
                os.unlink(path)
        except FileNotFoundError:
            pass
        except OSError as exc:   # the earlier NOT DONE would stand beside this done end: named, not dropped (R7-5 class)
            removed.append(f"the earlier {what} {name} could not be removed ({exc}); this done end stands, and {stale}")
    return (None if problem is None else f"the count could not be reset ({problem})"), ("; ".join(removed) or None), \
        unread


def _hook_event(argv: list[str], name: str) -> tuple[str, dict]:
    host = _host(argv)
    try:
        event = strict_json(sys.stdin.read())
    except ValueError as exc:
        raise GateError(f"the hook input is not JSON ({exc})") from exc
    if not isinstance(event, dict) or event.get("hook_event_name") != name:
        raise GateError(f"the hook input is not a {name} event")
    return host, event


# --- local done orders, outside every work tree (D38) --------------------------------------------------------------

#: The folder of the gate directory that holds the local done orders (D38): one file `<key>.json` per repository and the
#: gate's record of its digest, `<key>.seen.json`. Nothing of it lies in a work tree or a commit. A hook reads the
#: folder only where its environment states the protected channel of D124 (D128, _hook_orders); `done-order --list`
#: reads it for a person whatever is set.
DONE_ORDERS_DIR = "done-orders"
DONE_ORDER_SCHEMA = "proofbundle-plugin/done-order/v0.1"
DONE_ORDER_SEEN_SCHEMA = "proofbundle-plugin/done-order-seen/v0.1"
_DONE_ORDER_KEYS = frozenset({"schema", "repo", "gitdir", "base", "created", "done", "policy"})
_DONE_ORDER_SEEN_KEYS = frozenset({"schema", "sha256", "written", "replaced"})
MAX_ORDER_BYTES = 256 * 1024
_ORDER_FILE = re.compile(r"([0-9a-f]{64})\.json")
_ORDER_SEEN_FILE = re.compile(r"([0-9a-f]{64})\.seen\.json")
_FULL_COMMIT = re.compile(r"[0-9a-f]{40}|[0-9a-f]{64}")


def _order_key(toplevel: str, gitdir: str) -> str:
    """The name of a repository's local done order: the sha256 of its work tree root and git directory, each resolved
    physically, so a link to the clone names the same order and another worktree of it names another one."""
    joined = os.path.realpath(toplevel) + "\0" + os.path.realpath(gitdir)
    return hashlib.sha256(joined.encode("utf-8", "surrogateescape")).hexdigest()


def _order_label(file: str) -> str:
    """A local done order as a reason names it (D49): by the first twelve characters of its file name, the
    sha256 the gate makes of its root and git directory, never by the root, git directory or base it records, which
    `done-order --list` names to a person."""
    return f"the local done order {os.path.basename(file)[:12]}"


def _orders_dir(environ) -> str | None:
    gate_dir = _gate_dir(environ)
    return None if gate_dir is None else os.path.join(gate_dir, DONE_ORDERS_DIR)


def _parse_local_order(raw: bytes) -> dict:
    """A local done order as done-order writes it: exactly its keys, the done section in the form of the declaration's
    (D28), the policy as base64 of its bytes, an absolute root and git directory and a full commit id as the base of
    `paths`. GateError for anything else."""
    try:
        doc = strict_json(raw)
    except (ValueError, UnicodeDecodeError) as exc:
        raise GateError(f"it is not strict JSON ({exc})") from exc
    if not isinstance(doc, dict) or set(doc) != _DONE_ORDER_KEYS or doc["schema"] != DONE_ORDER_SCHEMA:
        raise GateError(f"it is not a done order of this gate (the keys and the schema {DONE_ORDER_SCHEMA})")
    if not all(isinstance(doc[k], str) and os.path.isabs(doc[k]) for k in ("repo", "gitdir")):
        raise GateError("its repo and gitdir are not absolute paths")
    if not (isinstance(doc["base"], str) and _FULL_COMMIT.fullmatch(doc["base"])) or not isinstance(doc["created"], str):
        raise GateError("its base is not a full commit id, or its created time is not a string")
    try:
        policy = base64.b64decode(doc["policy"], validate=True) if isinstance(doc["policy"], str) else b""
    except (ValueError, binascii.Error):
        policy = b""
    if not policy:
        raise GateError("its policy is not base64 of the policy's bytes")
    return {"repo": doc["repo"], "gitdir": doc["gitdir"], "base": doc["base"], "created": doc["created"],
            "done": _done_section(doc["done"]), "policy": policy}


def _order_seen(folder: str, key: str) -> tuple[dict | None, str | None]:
    """The gate's record of an order's digest as (record, None), (None, None) where there is none, (None, why) where a
    present record is not the gate's own (D38)."""
    path = os.path.join(folder, f"{key}.seen.json")
    try:
        raw = _read_regular(path, MAX_STATE_BYTES + 1)
    except FileNotFoundError:
        return None, None
    except OSError as exc:
        return None, f"the record {path} cannot be read ({exc.strerror or exc})"
    try:
        doc = strict_json(raw) if len(raw) <= MAX_STATE_BYTES else None
    except (ValueError, UnicodeDecodeError):
        doc = None
    if not (isinstance(doc, dict) and set(doc) == _DONE_ORDER_SEEN_KEYS and doc["schema"] == DONE_ORDER_SEEN_SCHEMA
            and isinstance(doc["sha256"], str) and _HEX64.fullmatch(doc["sha256"]) and isinstance(doc["replaced"], list)):
        return None, f"the record {path} is not the gate's record of a done order"
    return doc, None


def _order_refusal(entry: dict, reason: str, failed: str, next_step: str) -> dict:
    """The result of a local done order the gate refuses before its checks (D38): a deny with the order as its one open
    point. The repository is the order's own only where git found it bound as the order names it; there the block is
    counted toward max_blocks (D28), elsewhere in the gate directory beside the order (owner choice O3 of follow-up note 13),
    both with the default limit: a changed order does not set its own."""
    verdict = Verdict("deny", f"proofbundle gate: the local done order {entry['file']} is refused: {failed}.", reason,
                      evidence=f"the local done order {entry['file']}", failed=f"the local done order {entry['file']}: "
                                                                            f"{failed}",
                      next_step=next_step, repo=entry.get("bound"))
    return {"verdict": verdict, "done": None, "repo": entry.get("bound"), "commit": None, "state": None,
            "checks": [], "open": [{"id": "local-order", "status": reason, "failed": verdict.failed,
                                    "command": next_step}],
            "policy": None, "base": None, "inside": [], "local": entry["file"], "order_key": entry["key"]}


def _local_orders(environ, deadline: float) -> list[dict]:
    """Every local done order in the gate directory (D38), each {"key", "file", "order"} where the order holds its
    digest and binding, or {"key", "file", "refusal"} with the result that blocks the end: an order that changed since
    the gate wrote it, that has no record of the gate, whose record has no order left, that cannot be read, or whose
    repository git no longer finds at its root with its git directory. A folder that cannot be listed is a refusal
    too: the end does not pass on orders the gate could not read."""
    folder = _orders_dir(environ)
    if folder is None:
        return []
    try:
        names = sorted(os.listdir(folder))
    except FileNotFoundError:
        return []
    except OSError as exc:
        entry = {"key": "", "file": folder}
        return [{**entry, "refusal": _order_refusal(entry, "order_unreadable", f"the folder cannot be listed "
                                                                               f"({exc.strerror or exc})",
                                                    f"make {folder} a folder the hook can read")}]
    keys = sorted({m.group(1) for n in names for m in (_ORDER_FILE.fullmatch(n), _ORDER_SEEN_FILE.fullmatch(n)) if m})
    entries = []
    for key in keys:
        path = os.path.join(folder, f"{key}.json")
        entry = {"key": key, "file": path}
        again = "have a person make the order again with done-order --replace, or remove it with done-order --remove"
        try:
            raw = _read_regular(path, MAX_ORDER_BYTES + 1)
        except FileNotFoundError:
            entries.append({**entry, "refusal": _order_refusal(entry, "order_removed", "the gate's record of the order "
                                                               "is there, the order is not: it was removed other than "
                                                               "by done-order --remove", again)})
            continue
        except OSError as exc:
            entries.append({**entry, "refusal": _order_refusal(entry, "order_unreadable", f"it cannot be read "
                                                               f"({exc.strerror or exc})", again)})
            continue
        if len(raw) > MAX_ORDER_BYTES:
            entries.append({**entry, "refusal": _order_refusal(entry, "order_unreadable", f"it holds more than "
                                                               f"{MAX_ORDER_BYTES} bytes", again)})
            continue
        try:
            order = _parse_local_order(raw)
        except GateError as exc:
            entries.append({**entry, "refusal": _order_refusal(entry, "order_unreadable", str(exc), again)})
            continue
        entry["done"] = order["done"]
        paths, _why = _repo_paths(order["repo"], deadline) if os.path.isdir(order["repo"]) else (None, "")
        bound = (paths is not None and paths["toplevel"] is not None and paths["gitdir"] is not None
                 and os.path.realpath(paths["toplevel"]) == order["repo"]
                 and os.path.realpath(paths["gitdir"]) == order["gitdir"]
                 and _order_key(order["repo"], order["gitdir"]) == key)
        if bound:
            entry["bound"] = order["repo"]
        digest = hashlib.sha256(raw).hexdigest()
        seen, why = _order_seen(folder, key)
        if seen is None:
            entries.append({**entry, "refusal": _order_refusal(
                entry, "order_unrecorded", why or "the gate has no record of its digest: it was not made with "
                                                  "done-order, or the record was removed", again)})
            continue
        if seen["sha256"] != digest:
            entries.append({**entry, "refusal": _order_refusal(
                entry, "order_changed", f"it changed after the gate first read it (sha256 {seen['sha256'][:12]} when "
                                        f"written, {digest[:12]} now)", again)})
            continue
        if not bound:
            entries.append({**entry, "refusal": _order_refusal(
                entry, "order_unbound", "git does not find the repository it names at the root and with the git "
                                        "directory it records (done-order --list names them)",
                "restore the repository, or have a person remove the order with done-order --remove --repo <the root "
                "done-order --list names>")})
            continue
        entries.append({**entry, "order": {**order, "file": path, "sha256": digest,
                                           "replaced": len(seen["replaced"])}})
    return entries


#: What done-order and `done-order --list` print about where the hooks read an order (D128).
HOOK_ORDERS_NOTE = ("the Stop, TaskCompleted and SessionStart hooks read local done orders only where their "
                    f"environment sets {OWNER_STATE_VARIABLE}={OWNER_STATE_PROTECTED} (D128)")


def _hook_orders(environ, deadline: float) -> list[dict]:
    """The local done orders a hook judges (D128): those of _local_orders where the hook's environment states the
    protected channel of D124, else none. A session writes done-orders/ as it writes the owner files of D124, and an
    order it writes can drop a check; without the channel the done check runs on the repository's declaration alone,
    and an order the gate would refuse blocks no end and is counted nowhere."""
    return _local_orders(environ, deadline) if _owner_state_read(environ) else []


def _local_order_base(repo: str, order: dict, deadline: float) -> tuple[str | None, str]:
    """The base of a local order's paths (D31, D38): the commit that was HEAD when the order was made, while git still
    names it as a commit of the repository."""
    proc = _git(repo, "rev-parse", "--verify", "-q", f"{order['base']}^{{commit}}", deadline=deadline)
    if proc.returncode != 0 or proc.stdout.decode("ascii", "replace").strip() != order["base"]:
        return None, "the base the local done order records is not a commit of the repository"
    return order["base"], ""


def _write_record(path: str, doc: dict) -> str | None:
    """Write a count record or blocker of a local done order through a fresh temporary file that replaces it, never
    through a link (as _write_done_file does in a repository). None on success, else why not."""
    data = (json.dumps(doc, indent=1, sort_keys=True) + "\n").encode("utf-8", "surrogatepass")
    if len(data) > MAX_STATE_BYTES:
        return f"{os.path.basename(path)} would be {len(data)} bytes, more than the {MAX_STATE_BYTES} the hook reads back"
    temporary = os.path.join(os.path.dirname(path), f".{os.path.basename(path)}.{secrets.token_hex(6)}.tmp")
    try:
        fd = os.open(temporary, os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_NOFOLLOW", 0), 0o600)
        with os.fdopen(fd, "wb") as handle:
            handle.write(data)
        os.replace(temporary, path)
    except OSError as exc:
        try:
            os.unlink(temporary)
        except OSError:
            pass
        return f"{os.path.basename(path)} could not be written: {exc}"
    return None


def _order_count(path: str) -> tuple[dict | None, str | None]:
    """The count record of a local done order in the gate directory, as _done_state reads one in a repository."""
    try:
        raw = _read_regular(path, MAX_STATE_BYTES + 1)
    except FileNotFoundError:
        return None, None
    except OSError as exc:
        return None, f"{os.path.basename(path)} cannot be read ({exc.strerror or exc})"
    try:
        doc = strict_json(raw) if len(raw) <= MAX_STATE_BYTES else None
    except (ValueError, UnicodeDecodeError):
        doc = None
    if not (isinstance(doc, dict) and doc.get("schema") == DONE_FILES_SCHEMA.format("state")):
        return None, f"{os.path.basename(path)} is not the hook's own record (strict JSON of its schema)"
    return _count_record(doc, os.path.basename(path))


def _account_order_block(result: dict, event: dict | None, limit: int) -> tuple[str | None, str | None, str | None]:
    """Count one blocked end for a refused local done order whose repository git does not find (owner choice O3 of
    follow-up note 13): in the gate directory beside the order, `<key>.state.json` and `<key>.blocker.json`, by the rule of
    _account_block. After `limit` blocks with the same open point in the same session the blocker is written and the
    session ends without a done verdict, under both hosts; the order stays, and done-order --list names it."""
    folder, key = os.path.dirname(result["local"]), result["order_key"]
    state, blocker = os.path.join(folder, f"{key}.state.json"), os.path.join(folder, f"{key}.blocker.json")
    session = _session_key(event)
    signature = [[p["id"], p["status"]] for p in result["open"]]
    previous, unread = _order_count(state)
    same = previous is not None and previous["session_sha256"] == session and previous["open"] == signature
    blocks = previous["blocks"] + 1 if same else 1
    record = {"schema": DONE_FILES_SCHEMA.format("state"), "session_sha256": session, "open": signature,
              "blocks": blocks, "blocker": False}
    if blocks > limit:
        problem = _write_record(blocker, _blocker(result, event, blocks))
        counted = _write_record(state, {**record, "blocker": problem is None})
        if problem is not None:
            return None, (f"the blocker could not be written ({problem})"
                          + ("" if counted is None else f", nor the block count ({counted})")), unread
        return blocker, (None if counted is None else f"the end could not be recorded in the count ({counted})"), unread
    problem = _write_record(state, record)
    return None, (None if problem is None else f"the block count could not be recorded ({problem})"), unread


def _failed_result(exc: Exception, verdict: Verdict, local: str | None = None) -> dict:
    """The result of a check that failed, with the failure as its one open point (_failed_check), or one that names no
    repository, so it blocks without being counted."""
    partial = _failed_check(exc, verdict)
    if partial is not None:
        return partial
    return {"verdict": verdict, "done": None, "repo": None, "commit": None, "state": None, "checks": [], "open": [],
            "policy": None, "base": None, "inside": [], "local": local}


def done_evaluations(directory: str, deadline: float, environ: dict | None = None) -> list[dict]:
    """The done check of an end (Stop, TaskCompleted; D26, D28, D38): the repository of `directory` as before, then
    each local done order in the gate directory, in the order of its key, whatever the directory. A repository with a
    local order is judged by that order, and by the declaration at HEAD where it has one; a declaration found only in
    its work tree is not refused there, the local order stands for it. Each result is done_evaluation's, with "local"
    naming the order's file. The orders are read only with the protected channel (D128, _hook_orders)."""
    environ = os.environ if environ is None else environ
    entries = _hook_orders(environ, deadline)
    keys = {e["key"] for e in entries}   # a refused order stands for the work tree's declaration too: it blocks itself
    results = []
    try:
        paths, _why = _repo_paths(directory, deadline)
        here = (_order_key(paths["toplevel"], paths["gitdir"]) if paths is not None and paths["toplevel"]
                and paths["gitdir"] else None)
        results.append(done_evaluation(directory, deadline, environ=environ, local_order=here in keys))
    except GateError as exc:
        results.append(_failed_result(exc, Verdict("deny", f"proofbundle gate: {exc}.", "gate_error",
                                                   evidence="the done check", failed=f"the check reached no verdict "
                                                                                     f"({exc})",
                                                   next_step="fix the cause named here")))
    for entry in entries:
        if "refusal" in entry:
            results.append(entry["refusal"])
            continue
        order = entry["order"]
        try:
            results.append(done_evaluation(order["repo"], deadline, environ=environ, order=order))
        except GateError as exc:
            verdict = Verdict("deny", f"proofbundle gate: {_order_label(order['file'])}: {exc}.",
                              "gate_error", evidence="the done check", failed=f"{_order_label(order['file'])}: the "
                                                                              f"check reached no verdict ({exc})",
                              next_step="fix the cause named here")
            results.append(_failed_result(exc, verdict, order["file"]))
    return results


def _event_directory(event: dict) -> str:
    cwd = event.get("cwd")
    return cwd if isinstance(cwd, str) and os.path.isabs(cwd) else os.getcwd()


# --- the claims of the last message against their evidence (D80) --------------------------------------

#: The newest bytes of the transcript the claim check reads (D80): the evidence of an end lies at its end.
MAX_TRANSCRIPT_BYTES = 16 * 1024 * 1024
#: The longest last message the claim check reads; a longer one is read up to here.
MAX_CLAIM_MESSAGE = 64 * 1024
#: The record of the claim blocks per session in the plugin data directory (D80, point 4 of follow-up note 32).
CLAIM_STATE = "claim-state.json"
CLAIM_STATE_SCHEMA = "proofbundle-plugin/claim-state/v0.1"
#: How often the same block of a claim comes on the unchanged state in a row; the next end names the claim as open.
CLAIM_MAX_BLOCKS = 2
_CLAIM_STATE_KEEP = 64
#: The receipts a verdict may name its digest in: the JSON files of the evidence folder, each read up to this bound.
MAX_CLAIM_RECEIPTS = 64
MAX_CLAIM_RECEIPT_BYTES = 1024 * 1024

#: The words that take a claim back when one of them stands among the four words before it in its clause: a negation,
#: a part, a condition, a modal or future form, an alternative. A word that frees nothing: it only says the clause
#: claims nothing, and a claim in another clause stays a claim.
_CLAIM_TAKEN_BACK = frozenset({
    "nicht", "nichts", "kein", "keine", "keinen", "keinem", "keiner", "keines", "nie", "niemals", "ohne",
    "not", "no", "never", "neither", "nor", "without", "cannot",
    "fast", "beinahe", "nahezu", "halb", "teilweise", "teils", "größtenteils", "weitgehend",
    "almost", "nearly", "partially", "partly", "mostly", "half",
    "wenn", "falls", "sobald", "sofern", "bevor", "bis", "ob", "if", "once", "when", "whenever", "before", "until",
    "unless", "whether",
    "soll", "sollte", "sollten", "sollen", "muss", "müssen", "müsste", "kann", "können", "könnte", "könnten", "wird",
    "werden", "würde", "würden", "should", "must", "can", "could", "will", "would", "may", "might", "need", "needs",
    "to", "oder", "or", "bzw", "entweder", "either"})
_CLAIM_WORDS = re.compile(r"[^\W_]+(?:['’][^\W_]+)?")
_CLAIM_DONE = re.compile(r"(?i)(?<![\w-])(fertig|erledigt|done|finished|completed)(?![\w-])(?![ ]?(?:check|checks|verdict|"
                         r"order|orders|policy|state|metrics|blocker|receipt|init|key|keys)\b)")
_CLAIM_TEST_SUBJECT = re.compile(r"(?i)(?<![\w-])(tests?|testsuite|test-suite|suite|pytest|unittests?|testl[äa]ufe?)"
                                 r"(?![\w-])")
_CLAIM_TEST_GREEN = re.compile(r"(?i)(?<![\w-])(grün|gruen|green|bestanden|bestehen|besteht|passed|pass|passes|passing|"
                               r"durchgelaufen|erfolgreich|successful|succeeded|succeed|succeeds|ok)(?![\w-])"
                               r"|(?<![\w-])l[äa]uf(?:en|t) durch(?![\w-])")
#: A done word after one of these names what was done, it claims nothing: "what was done", "welche erledigt sind".
_CLAIM_DONE_OBJECT = re.compile(r"(?i)(?<![\w-])(what|which|welche|welcher|welches)(?![\w-])")
_CLAIM_TEST_COUNT = re.compile(r"(?i)(?<![\w.-])[0-9]+ (passed|bestanden)(?![\w-])")
#: A sentence that names red tests beside green ones is a partial status, not a claim that the tests pass.
_CLAIM_TEST_RED = re.compile(r"(?i)(?<![\w.-])[1-9][0-9]* (failed|failing|errors?|error|rot|rote|roten|fehlgeschlagen)"
                             r"(?![\w-])|(?<![\w-])(bis auf|außer|ausser|except|apart from|other than)(?![\w-])")
_CLAIM_PUSHED = re.compile(r"(?i)(?<!\w)(gepusht|gepushed|pushed)(?![\w-])")
_CLAIM_MERGED = re.compile(r"(?i)(?<!\w)(gemergt|gemerged|merged|gelandet|landed)(?![\w-])")
_CLAIM_LOCAL = re.compile(r"(?i)(?<![\w-])(lokal|lokale|lokalen|locally|local)(?![\w-])")
_CLAIM_VERDICT = re.compile(r"(?<![\w/-])(WITHSTANDS|PASS|PASSED|FREIGABE|FREIGEGEBEN)(?:_[A-Z0-9]+)*(?![\w/-])")
_CLAIM_OK = re.compile(r"(?<![\w/-])OK(?![\w/-])")
#: D118: a status of its clause without a test word or a script word: green, holds, OK.
_CLAIM_GREEN = re.compile(r"(?i)(?<![\w-])(grün|gruen|green)(?![\w-])")
_CLAIM_HOLDS = re.compile(r"(?i)(?<![\w-])(hält|haelt|holds)(?![\w-])")
#: D118: a word after hält or holds in its clause that makes it another verb (anhalten, festhalten, für etwas halten,
#: hold back): the clause claims nothing.
_CLAIM_HOLDS_OTHER = re.compile(r"(?i)(?<![\w-])(an|auf|fest|zurück|zurueck|für|fuer|ab|aus|ein|inne|still|stand|"
                                r"back|up|off|on|onto|out|for)(?![\w-])")
#: D118: the words after a status word that take it back in addition to _CLAIM_TAKEN_BACK: a subjunctive or "only then".
_CLAIM_TAKEN_BACK_AFTER = frozenset({"wäre", "wären", "sei", "seien", "erst", "only"})
#: D118: a count of tests a runner names as run or passed; a checked count of any run is a whole number of its own.
_CLAIM_TEST_RAN = re.compile(r"(?i)(?<![\w.-])([0-9]+) (?:passed|bestanden)(?![\w-])|(?<![\w-])Ran ([0-9]+) tests?(?![\w-])"
                             r"|(?<![\w-])Tests?: +([0-9]+) passed(?![\w-])")
_CLAIM_WHOLE = re.compile(r"(?<![\w./:,-])([0-9]+)(?![\w./:%-]|[.,][0-9])")
#: D118: the evidence a repository declares a completion needs, read where it is committed, pushed and in the work tree.
DONE_CLAIMS_FILE = EVIDENCE_DIR + "done-claims.json"
DONE_CLAIMS_SCHEMA = "proofbundle-plugin/done-claims/v0.1"
MAX_DONE_CLAIMS_BYTES = 64 * 1024
MAX_DONE_CLAIMS_EVIDENCE = 16
_CLAIM_SCRIPT_WORD = re.compile(r"(?i)(?<![\w-])(skript|script|prüfskript|pruefskript|checkskript|crosscheck|"
                                r"kreuzprobe|probe|prüfung|pruefung|check|verify|verifier|prüfer)(?![\w-])"
                                r"|(\S+\.(?:sh|py|bash))(?![\w-])")
_CLAIM_SCRIPT_FILE_NAMED = re.compile(r"()(?<![\w.-])(\S*?[\w-]+\.(?:sh|py|bash))(?![\w-])")
_CLAIM_DIGEST = re.compile(r"(?<![0-9A-Za-z])([0-9a-f]{12,128})(?![0-9A-Za-z])")
_CLAIM_COMMIT = re.compile(r"(?<![0-9A-Za-z])([0-9a-f]{7,64})(?![0-9A-Za-z])")
_CLAIM_VERSION_CONTEXT = re.compile(r"(?i)python|interpreter|cpython|\bpy3[0-9]{1,2}\b|matri[xz]")
_CLAIM_VERSION = re.compile(r"(?i)(?<![\w.])(?:py3([0-9]{1,2})|(?:python|cpython)?\s?3\.([0-9]{1,2}))(?![\w]|\.[0-9])")
_CLAIM_QUOTED = re.compile(r"„[^“”\"\n]{0,200}[“”\"]|“[^”\n]{0,200}”|»[^«\n]{0,200}«|«[^»\n]{0,200}»|\"[^\"\n]{0,200}\"")
_CLAIM_FENCE = re.compile(r"```.*?(?:```|\Z)", re.S)
#: What a claim of each kind says, for the reason.
_CLAIM_NAMES = {"done": "the work is done", "tests": "the tests pass", "pushed": "it is pushed",
                "merged": "it is merged or landed", "verdict": "a verdict", "script": "a check script reported OK",
                "green": "a checked set is green", "holds": "it holds", "ok": "it is OK"}


def _claim_text(message: str) -> str:
    """The last message as the claim check reads it: no fenced code, no quoted line (`>`), no quotation in quotation
    marks (a claim someone else made, or a case the message names), no backticks or emphasis around words."""
    text = _CLAIM_FENCE.sub("\n", message[:MAX_CLAIM_MESSAGE])
    text = "\n".join(line for line in text.splitlines() if not line.lstrip().startswith(">"))
    text = _CLAIM_QUOTED.sub(" ", text)
    return text.replace("`", "").replace("*", "").replace("__", "")


def _claim_taken_back(clause: str, start: int) -> bool:
    """Whether a word of _CLAIM_TAKEN_BACK, or a word ending in n't, stands among the four words before the claim."""
    words = [w.lower() for w in _CLAIM_WORDS.findall(clause[:start])][-4:]
    return any(w in _CLAIM_TAKEN_BACK or w.endswith(("n't", "n’t")) for w in words)


def _claim_status(clause: str, sentence: str, red: bool, versions: list, kinds: set) -> list[tuple]:
    """D118: the status words of a clause of at most eight words that claim a checked set without a test
    word or a script word: green ("Abnahme grün"), holds ("N46 hält", not where a word after it makes another verb of
    it: "hält … an", "holds back"), OK in capitals that is not the first word of its sentence. Not in a sentence that
    names red ones, not where D80 found the tests or a check script in the clause, not where a word of
    _CLAIM_TAKEN_BACK stands among the four words before it or a word of either list among the three after it."""
    if len(_CLAIM_WORDS.findall(clause)) > 8:
        return []

    def taken_back(m: re.Match) -> bool:
        after = [w.lower() for w in _CLAIM_WORDS.findall(clause[m.end():])][:3]
        return _claim_taken_back(clause, m.start()) or any(
            w in _CLAIM_TAKEN_BACK or w in _CLAIM_TAKEN_BACK_AFTER for w in after)

    found = []
    m = _CLAIM_GREEN.search(clause)
    if m and not red and "tests" not in kinds and not taken_back(m):
        found.append(("green", m.group(0), {"versions": versions}))
    m = _CLAIM_HOLDS.search(clause)
    if m and not taken_back(m) and not _CLAIM_HOLDS_OTHER.search(clause[m.end():]):
        found.append(("holds", clause[:m.end()], {}))
    m = _CLAIM_OK.search(clause)
    if (m and "script" not in kinds and not taken_back(m)
            and _CLAIM_WORDS.findall(sentence)[:1] != ["OK"]):
        found.append(("ok", clause[:m.end()], {}))
    return found


def message_claims(message: str) -> list[dict]:
    """The claims of the closed list in the last message (D80): each {"kind", "words", "digests", "commits",
    "versions", "script"}. The message is cut into sentences (a full stop, question or exclamation mark before a
    space, a line, a semicolon, a table cell) and those into clauses (a comma, a dash, or a conjunction of the list the
    code splits at, in English and in German). A
    question claims nothing; a clause claims nothing where a word of _CLAIM_TAKEN_BACK stands among the four words
    before its claim. A claim that the work is done counts in a clause of at most eight words that does not name what
    was done; a claim that the tests pass names a test word before its green word, or a count of passed tests, in a
    sentence that names no red ones."""
    claims: list[dict] = []
    for sentence in re.split(r"(?<=[.!?])\s+|\n+|;\s*|\s\|\s?|\|", _claim_text(message)):
        sentence = sentence.strip()
        if not sentence or sentence.endswith("?"):
            continue
        digests = _CLAIM_DIGEST.findall(sentence)
        commits = _CLAIM_COMMIT.findall(sentence)
        versions = sorted({f"3.{a or b}" for a, b in _CLAIM_VERSION.findall(sentence)}) \
            if _CLAIM_VERSION_CONTEXT.search(sentence) else []
        red = _CLAIM_TEST_RED.search(sentence) is not None
        for clause in re.split(r",\s+|\s+(?:und|and|aber|but|sowie|jedoch|however|while|während|whereas)\s+"
                               r"|\s+[—–-]\s+", sentence):
            clause = clause.strip(" \t-*•")
            found = []
            m = _CLAIM_DONE.search(clause)
            if (m and len(_CLAIM_WORDS.findall(clause)) <= 8 and not _claim_taken_back(clause, m.start())
                    and not _CLAIM_DONE_OBJECT.search(clause[:m.start()])):
                found.append(("done", m.group(0), {}))
            if not red:
                count = _CLAIM_TEST_COUNT.search(clause)
                subject = _CLAIM_TEST_SUBJECT.search(clause)
                green = next((g for g in _CLAIM_TEST_GREEN.finditer(clause)
                              if subject is not None and g.start() > subject.end()
                              and len(_CLAIM_WORDS.findall(clause[subject.end():g.start()])) <= 6), None)
                hit = green or count
                if hit is not None and not _claim_taken_back(clause, hit.start()):
                    found.append(("tests", clause[(subject.start() if green else hit.start()):hit.end()],
                                  {"versions": versions}))
            for kind, pattern in (("pushed", _CLAIM_PUSHED), ("merged", _CLAIM_MERGED)):
                m = pattern.search(clause)
                if m and not _claim_taken_back(clause, m.start()) and not (kind == "merged"
                                                                          and _CLAIM_LOCAL.search(clause)):
                    found.append((kind, m.group(0), {"commits": commits}))
            m = _CLAIM_VERDICT.search(clause)
            if m and not _claim_taken_back(clause, m.start()):
                found.append(("verdict", m.group(0), {"digests": digests}))
            m = _CLAIM_OK.search(clause)
            script = _CLAIM_SCRIPT_FILE_NAMED.search(clause) or _CLAIM_SCRIPT_WORD.search(clause)
            if m and script and not _claim_taken_back(clause, m.start()):
                found.append(("script", clause[min(m.start(), script.start()):max(m.end(), script.end())],
                              {"script": os.path.basename(script.group(2)) if script.group(2) else None}))
            found += _claim_status(clause, sentence, red, versions, {k for k, _w, _e in found})
            for kind, words, extra in found:
                claims.append({"kind": kind, "words": words[:60], "digests": [], "commits": [], "versions": [],
                               "script": None, **extra})
    return claims


# The transcript of Claude Code (2.1.302, measured in follow-up note 32): one JSON object per line; a tool call is an item
# {"type": "tool_use", "id", "name", "input"} of an assistant message, its result an item {"type": "tool_result",
# "tool_use_id", "content", "is_error"} of the next user message, is_error true for an exit code other than 0 (content
# "Exit code N\n…"), and the user line carries toolUseResult with "interrupted".

def _read_tail(path: str, limit: int) -> bytes:
    """The last `limit` bytes of the regular file at path, from the first whole line on; never through a link, never
    waiting on a FIFO (R18-2 class)."""
    fd = os.open(path, os.O_RDONLY | getattr(os, "O_NONBLOCK", 0) | getattr(os, "O_CLOEXEC", 0)
                 | getattr(os, "O_NOFOLLOW", 0))
    try:
        size = os.fstat(fd).st_size
        if not stat.S_ISREG(os.fstat(fd).st_mode):
            raise _NotRegular(errno.EINVAL, "not a regular file", path)
        start = max(0, size - limit)
        os.lseek(fd, start, os.SEEK_SET)
        chunks, left = [], size - start
        while left > 0:
            chunk = os.read(fd, min(left, 1 << 20))
            if not chunk:
                break
            chunks.append(chunk)
            left -= len(chunk)
    finally:
        os.close(fd)
    data = b"".join(chunks)
    if start > 0:
        cut = data.find(b"\n")
        data = data[cut + 1:] if cut >= 0 else b""
    return data


def _result_text(content: object) -> str:
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        return "\n".join(i["text"] for i in content if isinstance(i, dict) and isinstance(i.get("text"), str))
    return ""


def read_transcript(path: object) -> tuple[list[dict] | None, str | None]:
    """The tool calls of the transcript in their order, each {"name", "input", "error", "text", "interrupted"}, error
    and text None where no result follows; or (None, why) where the transcript cannot be read."""
    if not isinstance(path, str) or not os.path.isabs(path):
        return None, "the Stop event names no transcript"
    try:
        data = _read_tail(path, MAX_TRANSCRIPT_BYTES)
    except OSError as exc:
        return None, f"the transcript cannot be read ({exc.strerror or exc})"
    calls: list[dict] = []
    by_id: dict = {}
    for line in data.splitlines():
        if b'"tool_use"' not in line and b'"tool_result"' not in line:
            continue
        try:
            entry = json.loads(line)
        except ValueError:
            continue
        message = entry.get("message") if isinstance(entry, dict) else None
        content = message.get("content") if isinstance(message, dict) else None
        if not isinstance(content, list):
            continue
        for item in content:
            if not isinstance(item, dict):
                continue
            if item.get("type") == "tool_use" and isinstance(item.get("name"), str):
                call = {"name": item["name"], "input": item.get("input") if isinstance(item.get("input"), dict)
                        else {}, "error": None, "text": None, "interrupted": False}
                calls.append(call)
                if isinstance(item.get("id"), str):
                    by_id[item["id"]] = call
            elif item.get("type") == "tool_result" and item.get("tool_use_id") in by_id:
                call = by_id[item["tool_use_id"]]
                call["error"] = item.get("is_error") is True
                call["text"] = _result_text(item.get("content"))
                result = entry.get("toolUseResult")
                call["interrupted"] = isinstance(result, dict) and result.get("interrupted") is True
                if isinstance(result, dict) and isinstance(result.get("stderr"), str) and result["stderr"]:
                    call["text"] += "\n" + result["stderr"]
    return calls, None


#: The tools of Claude Code that change files, or may: the file tools, and a subagent, whose own calls stand in a
#: transcript of their own that the claim check does not read.
_CLAIM_EDIT_TOOLS = frozenset({"Edit", "Write", "MultiEdit", "NotebookEdit", "Task", "Agent"})
#: Programs that change no file of the work tree, with the forms below that do left out (D80). Anything else changes.
_CLAIM_STILL = frozenset({
    "cd", "pwd", "echo", "printf", "cat", "head", "tail", "wc", "ls", "grep", "egrep", "fgrep", "rg", "sha256sum",
    "sha1sum", "sha512sum", "md5sum", "b2sum", "stat", "file", "which", "type", "true", "false", ":", "sleep", "date",
    "whoami", "id", "uname", "hostname", "df", "du", "tree", "diff", "cmp", "jq", "uniq", "cut", "tr", "column", "nl",
    "basename", "dirname", "realpath", "readlink", "printenv", "test", "[", "[[", "set", "export", "source", ".",
    "unset", "shopt", "ps", "pgrep", "free", "uptime", "nproc", "seq", "xxd", "od", "hexdump", "strings", "zcat",
    "less", "more", "wait", "exit", "return"})
_CLAIM_GIT_CHANGES = frozenset({
    "checkout", "switch", "restore", "reset", "merge", "rebase", "pull", "cherry-pick", "revert", "stash", "clean",
    "mv", "rm", "am", "apply", "worktree", "submodule", "clone", "init", "sparse-checkout", "lfs", "filter-branch",
    "filter-repo", "bisect", "archive", "format-patch", "bundle", "read-tree", "checkout-index"})
_CLAIM_GH_CHANGES = frozenset({("pr", "checkout"), ("repo", "clone"), ("release", "download"), ("run", "download"),
                               ("gist", "clone"), ("repo", "fork")})
_CLAIM_WRAPPERS = frozenset({"env", "timeout", "nice", "time", "command", "exec", "stdbuf", "nohup"})
_CLAIM_RUNNERS = frozenset({"pytest", "py.test", "tox", "nox", "ctest", "bats", "jest", "vitest", "phpunit", "rspec"})
_CLAIM_RUNNER_SUBCOMMANDS = {"npm": {"test", "t"}, "pnpm": {"test", "t"}, "yarn": {"test"}, "bun": {"test"},
                             "deno": {"test"}, "cargo": {"test", "nextest"}, "go": {"test"},
                             "make": {"test", "tests", "check"}, "mvn": {"test", "verify"},
                             "gradle": {"test", "check"}, "hatch": {"test"}, "dotnet": {"test"}}
_CLAIM_PYTHON = re.compile(r"(?:python|pypy)([0-9]+(?:\.[0-9]+)?)?")
_CLAIM_SCRIPT_FILE = re.compile(r"[^/]+\.(?:sh|bash|py)")
_CLAIM_TEST_SCRIPT = re.compile(r"(?i)test|suite")
_CLAIM_HEREDOC = re.compile(r"<<(-?)[ \t]*(['\"]?)([A-Za-z_][A-Za-z0-9_]*)\2")


def _claim_strip_heredocs(command: str) -> str:
    """The command without the bodies of its here-documents, which are input and never words of the shell."""
    out, i = [], 0
    while True:
        m = _CLAIM_HEREDOC.search(command, i)
        if m is None:
            out.append(command[i:])
            return "".join(out)
        out.append(command[i:m.start()])
        end_of_line = command.find("\n", m.end())
        if end_of_line < 0:
            out.append(command[m.end():])
            return "".join(out)
        out.append(command[m.end():end_of_line + 1])
        j = end_of_line + 1
        while j < len(command):
            k = command.find("\n", j)
            line = command[j:] if k < 0 else command[j:k]
            j = len(command) if k < 0 else k + 1
            if (line.lstrip("\t") if m.group(1) else line) == m.group(3):
                break
        i = j


def _claim_runs(command: str) -> tuple[list, list, list] | None:
    """The runs of words of a command, the operator after each ("" after the last) and whether an output redirection
    of each writes a file; None where the gate cannot read the command. Groups are read flat: `(a && b) | c` as
    `a && b | c`."""
    toks = _lex(_drop_comments(_claim_strip_heredocs(command)))
    if toks is None:
        return None
    runs, ops, writes, run, write = [], [], [], [], False
    for t in toks:
        if t[0] == "word":
            run.append(t[1:])
        elif t[0] == "redir":
            target = t[2]
            if t[1] in _READ_ONLY_SINKS and not (target is not None and target[0] == "/dev/null"):
                write = True
        elif t[0] == "op" and t[1] in (";", "&&", "||", "|", "&"):
            if run or write:
                runs.append(run)
                ops.append(t[1])
                writes.append(write)
            elif ops:
                ops[-1] = t[1] if ops[-1] == ";" else ops[-1]
            run, write = [], False
    if run or write:
        runs.append(run)
        ops.append("")
        writes.append(write)
    return runs, ops, writes


def _claim_program(run: list) -> tuple[str, list]:
    """The program of a run and its words after the assignments and wrappers in front (env, timeout, nice, time, …),
    the program by the last part of its path."""
    words = list(run)
    while words:
        value = words[0][0]
        if re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*=.*", value, re.S):
            words = words[1:]
            continue
        name = os.path.basename(value)
        if name not in _CLAIM_WRAPPERS:
            return name, words[1:]
        words = words[1:]
        if name == "timeout":
            while words and words[0][0].startswith("-"):
                words = words[2:] if words[0][0] in ("-s", "-k", "--signal", "--kill-after") else words[1:]
            words = words[1:]   # the duration
        elif name in ("env", "nice", "stdbuf"):
            while words and (words[0][0].startswith("-") or "=" in words[0][0]):
                words = words[2:] if words[0][0] in ("-u", "-n", "-C", "--unset", "--adjustment") else words[1:]
    return "", []


def _claim_test_run(name: str, args: list) -> tuple[bool, list[str]]:
    """Whether the run starts a test runner of the closed list (D80), and the Python versions it names."""
    words = [a[0] for a in args]
    versions = []
    python = _CLAIM_PYTHON.fullmatch(name)
    if python and python.group(1) and "." in python.group(1):
        versions.append(python.group(1))
    if name in ("uv", "poetry", "pipenv", "pdm", "rye") and words[:1] == ["run"]:
        rest = words[1:]
        while rest and rest[0].startswith("-"):
            if rest[0] in ("-p", "--python") and len(rest) > 1:
                versions.append(rest[1])
                rest = rest[2:]
                continue
            if rest[0].startswith("--python="):
                versions.append(rest[0].split("=", 1)[1])
            rest = rest[2:] if rest[0] in ("--with", "--extra", "--group", "--directory", "--project", "--package",
                                           "--env-file", "--index", "--from") else rest[1:]
        if not rest:
            return False, versions
        inner, more = _claim_test_run(os.path.basename(rest[0]), [(w, False, w) for w in rest[1:]])
        return inner, versions + more
    if name in _CLAIM_RUNNERS:
        if name == "tox":
            versions += [f"3.{m}" for m in re.findall(r"py3([0-9]{1,2})", " ".join(words))]
        return True, versions
    if name in _CLAIM_RUNNER_SUBCOMMANDS:
        rest = [w for w in words if not w.startswith("-")]
        if rest[:1] == ["run"] and name in ("npm", "pnpm", "yarn"):
            rest = rest[1:]
        return bool(rest) and rest[0] in _CLAIM_RUNNER_SUBCOMMANDS[name], versions
    if python:
        rest = list(words)
        while rest and rest[0].startswith("-") and rest[0] != "-m":
            if rest[0] == "-c":
                return False, versions
            rest = rest[2:] if rest[0] in ("-X", "-W") else rest[1:]
        if rest[:1] == ["-m"]:
            return len(rest) > 1 and rest[1] in ("pytest", "unittest", "tox", "nox"), versions
        return bool(rest) and _CLAIM_SCRIPT_FILE.fullmatch(os.path.basename(rest[0])) is not None and \
            _CLAIM_TEST_SCRIPT.search(os.path.basename(rest[0])) is not None, versions
    return _claim_script(name, args) is not None and _CLAIM_TEST_SCRIPT.search(_claim_script(name, args)) is not None, \
        versions


def _claim_script(name: str, args: list) -> str | None:
    """The file name of the script a run starts (a program word ending in .sh, .bash or .py, or bash, sh or python
    with such a file first), None for any other run."""
    if _CLAIM_SCRIPT_FILE.fullmatch(name):
        return name
    if name in ("bash", "sh", "zsh", "dash") or _CLAIM_PYTHON.fullmatch(name):
        rest = [a[0] for a in args]
        while rest and rest[0].startswith("-"):
            if rest[0] in ("-c", "-m"):
                return None
            rest = rest[2:] if rest[0] in ("-o", "-O", "-X", "-W") else rest[1:]
        if rest and _CLAIM_SCRIPT_FILE.fullmatch(os.path.basename(rest[0])):
            return os.path.basename(rest[0])
    return None


def _claim_still_run(name: str, args: list) -> bool:
    """Whether a run changes no file of the work tree (D80): a program of _CLAIM_STILL in a form that writes nothing, a
    git or gh call that leaves the work tree as it is, a test runner."""
    words = [a[0] for a in args]
    if name in ("sed",):
        return not any(w.startswith(("-i", "--in-place")) or (re.fullmatch(r"-[a-zA-Z]*i[a-zA-Z]*", w) is not None)
                       for w in words)
    if name == "sort":
        return not any(w.startswith(("-o", "--output")) for w in words)
    if name == "find":
        return not any(w in _READ_ONLY_FIND_ACTIONS for w in words)
    if name in ("awk", "gawk", "mawk"):
        return not any(">" in w or "system(" in w or "|" in w for w in words)
    if name == "tar":
        return bool(words) and (words[0] in ("t", "-t", "--list") or re.fullmatch(r"-?t[a-zA-Z]*", words[0]) is not None)
    if name == "xargs":
        rest = list(args)
        while rest and rest[0][0].startswith("-"):
            rest = rest[1:]
        return not rest or _claim_still_run(os.path.basename(rest[0][0]), rest[1:])
    if name == "git":
        rest = list(words)
        while rest and rest[0].startswith("-"):
            rest = rest[2:] if rest[0] in ("-C", "-c", "--git-dir", "--work-tree", "--namespace") else rest[1:]
        if not rest:
            return True
        if rest[0] == "worktree":
            return rest[1:2] == ["list"]
        if rest[0] == "stash":
            return rest[1:2] in (["list"], ["show"])
        if rest[0] == "apply":
            return "--check" in rest or "--stat" in rest
        return rest[0] not in _CLAIM_GIT_CHANGES
    if name == "gh":
        rest = [w for w in words if not w.startswith("-")]
        return tuple(rest[:2]) not in _CLAIM_GH_CHANGES
    if name in _CLAIM_STILL:
        return True
    return _claim_test_run(name, args)[0]


def _claim_command(command: str, depth: int = 0) -> dict:
    """What a Bash command of the transcript is for the claim check (D80): {"change": whether it may change a file of
    the work tree after its last test run (or at all, where it runs none), "test": whether it runs a test runner,
    "own": whether the exit code of the command is each runner's own (nothing after a runner but `&&`, or a pipe with
    pipefail set before it; no `||` between a runner and the list before it; not sent to the background), "versions":
    the Python versions it names, "words": its words, "scripts": the scripts it starts, "git": the words of each git
    call after its switches, "gh": the words of each gh call}. A command the gate cannot read changes and runs
    nothing."""
    out = {"change": True, "test": False, "own": False, "versions": [], "words": set(), "scripts": [], "git": [],
           "gh": [], "script_own": False, "programs": []}
    parsed = _claim_runs(command) if depth <= MAX_NESTING else None
    if parsed is None:
        return out
    runs, ops, writes = parsed
    changes, tests, pipefail = [], [], None
    for n, run in enumerate(runs):
        name, args = _claim_program(run)
        words = [a[0] for a in args]
        out["words"].update(w[0] for w in run)
        if name == "set" and "pipefail" in words and pipefail is None:
            pipefail = n
        is_test, versions = _claim_test_run(name, args)
        if is_test:
            tests.append(n)
            out["versions"] += versions
        script = _claim_script(name, args)
        if script is not None:
            out["scripts"].append(script)
        if name == "git":
            rest = list(words)
            while rest and rest[0].startswith("-"):
                rest = rest[2:] if rest[0] in ("-C", "-c", "--git-dir", "--work-tree", "--namespace") else rest[1:]
            out["git"].append(rest)
        if name == "gh":
            out["gh"].append([w for w in words if not w.startswith("-")] + [w for w in words if w == "--auto"])
        if writes[n] or not name or not _claim_still_run(name, args):
            changes.append(n)
    inner = any(_claim_command(body, depth + 1)["change"] for body in _subst_bodies(command))
    out["test"] = bool(tests)
    out["change"] = inner or (any(n > tests[-1] for n in changes) if tests else bool(changes))

    def own_exit(n: int) -> bool:
        before = ops[:n]
        last_list = max((i for i, op in enumerate(before) if op in (";", "&")), default=-1)
        return ops[-1] != "&" and "||" not in before[last_list + 1:] and all(
            op == "&&" or (op == "|" and pipefail is not None and pipefail < n) for op in ops[n:len(runs) - 1])

    out["own"] = bool(tests) and all(own_exit(n) for n in tests)
    # D118: the same rule for the script runs and for every program a declaration of done-claims.json may name
    script_runs = [n for n, run in enumerate(runs) if _claim_script(*_claim_program(run)) is not None]
    out["script_own"] = bool(script_runs) and all(own_exit(n) for n in script_runs)
    out["programs"] = [([name] + [a[0] for a in args], own_exit(n), n in tests)
                       for n, (name, args) in enumerate(_claim_program(run) for run in runs) if name]
    return out


#: The hints before a run (D81, point 3 of follow-up note 32): an id and the text the model reads as additional context.
_HINTS = {
    "pipe_without_pipefail": ("proofbundle hint (D81): the exit code of this command is the last program's of its "
                              "pipe, not the one of the test or check run in it. Set `set -o pipefail` first, or run "
                              "it without the pipe, before you read a result from its exit code."),
    "pytest_r_without_failures": ("proofbundle hint (D81): this pytest -r selection lists no failed and no erroring "
                                  "test in the short summary, so an empty list there says nothing about red tests. "
                                  "Read red cases from -rfE."),
}


def evidence_hints(command: str) -> list[str]:
    """The ids of the hints of _HINTS for a Bash command (D81): a test runner or a check script whose output goes into
    a pipe without pipefail set before it (F4 of account A), and pytest with a -r selection that names neither failed nor
    errors (f, E, a or A; F5 of account A). A hint never changes a decision; a command the gate cannot read gets none."""
    parsed = _claim_runs(command)
    if parsed is None:
        return []
    runs, ops, _writes = parsed
    hints, pipefail = [], False
    for n, run in enumerate(runs):
        name, args = _claim_program(run)
        words = [a[0] for a in args]
        if name == "set" and "pipefail" in words:
            pipefail = True
        is_test = _claim_test_run(name, args)[0]
        if (is_test or _claim_script(name, args) is not None) and ops[n] == "|" and not pipefail:
            hints.append("pipe_without_pipefail")
        if is_test and (name in ("pytest", "py.test") or "pytest" in words):
            for i, word in enumerate(words):
                spec = word[2:] if word.startswith("-r") and len(word) > 2 else (
                    words[i + 1] if word == "-r" and i + 1 < len(words) else None)
                if spec is not None and not set(spec) & set("fEaA"):
                    hints.append("pytest_r_without_failures")
    return sorted(set(hints))


def _claim_numbers(text: str) -> bool:
    """Whether output names a number of its own beside OK: a count or a measure, not a part of a path, a name or an id."""
    return re.search(r"(?<![\w./:-])[0-9]+(?:[.,][0-9]+)?(?:/[0-9]+)?%?(?![\w./:-])", text) is not None


def _claim_version_shown(command: str, text: str) -> tuple[str, str] | None:
    """(program word, version) where the command is `<program> -V` or `<program> --version` and its output names a
    Python version (`Python 3.12.1`), else None."""
    parsed = _claim_runs(command)
    if parsed is None or len(parsed[0]) != 1:
        return None
    words = [w[0] for w in parsed[0][0]]
    m = re.search(r"Python (3\.[0-9]{1,2})", text)
    return (words[0], m.group(1)) if len(words) == 2 and words[1] in ("-V", "--version") and m else None


def _claim_evidence_calls(calls: list[dict]) -> dict:
    """What the transcript shows for the claim check: the index of the last change, the passing test runs after it
    with their own exit code and their versions, the last test run after it (any outcome), the script runs, the git
    fetches and pushes that succeeded, the merges of gh or of the GitHub tools that succeeded."""
    last_change, runs, scripts, remote, merges, shown, known, programs = -1, [], [], [], [], {}, {}, []
    for n, call in enumerate(calls):
        name, inp = call["name"], call["input"]
        if name in _CLAIM_EDIT_TOOLS:
            if call["error"] is not True:
                last_change = n
            continue
        if "merge_pull_request" in name and call["error"] is False:
            merges.append(n)
            continue
        command = inp.get("command") if name == "Bash" else None
        if not isinstance(command, str):
            continue
        info = known.get(command)
        if info is None:
            info = known[command] = _claim_command(command)
        if info["change"]:
            last_change = n
        background = inp.get("run_in_background") is True
        succeeded = call["error"] is False and not call["interrupted"] and not background
        if succeeded and ("-V" in command or "--version" in command):
            version = _claim_version_shown(command, call["text"] or "")
            if version is not None:
                shown[version[0]] = version[1]
        if info["test"]:
            runs.append({"at": n, "own": info["own"], "ok": succeeded, "versions": info["versions"],
                         "text": call["text"] or "", "words": info["words"]})
        for script in info["scripts"]:
            scripts.append({"at": n, "script": script, "ok": succeeded, "text": call["text"] or "",
                            "own": info["script_own"]})
        for words, own, is_test in info["programs"]:   # D118: the runs a declaration of done-claims.json may name
            programs.append({"at": n, "words": words, "own": own, "ok": succeeded, "test": is_test,
                             "text": call["text"] or ""})
        if succeeded:
            for words in info["git"]:
                if words[:1] in (["fetch"], ["pull"], ["push"]) or words[:2] == ["remote", "update"]:
                    remote.append({"at": n, "words": words, "text": call["text"] or ""})
            for words in info["gh"]:
                if words[:2] == ["pr", "merge"] and "--auto" not in words:
                    merges.append(n)
    return {"last_change": last_change, "runs": runs, "scripts": scripts, "remote": remote, "merges": merges,
            "versions_shown": shown, "count": len(calls), "programs": programs}


def _claim_tests_open(claim: dict, seen: dict, done_passed: bool) -> tuple[str, str] | None:
    """Why a claim that the tests pass, or that the work is done, has no evidence at the current state, and the
    smallest next step; None where it has (D80). Evidence: the declared done check passed at this end (a receipt
    with the git state of the work tree), or a test run after the last change in the transcript with its own exit code
    0. Each Python version the claim names needs such a run that names it (in its command, its output, or the version
    its interpreter showed). A claim that the work is done needs no run where the transcript shows no change."""
    if done_passed and not claim["versions"]:
        return None
    after = [r for r in seen["runs"] if r["at"] > seen["last_change"]]
    good = [r for r in after if r["own"] and r["ok"]]
    if claim["kind"] == "done" and seen["last_change"] < 0:
        return None
    step = ("run the tests after the last change as a command of their own (nothing after the runner but `&&`, or "
            "`set -o pipefail` before a pipe) and read its exit code")
    if not good:
        if not after:
            return "no test run follows the last change in the transcript", step
        last = after[-1]
        if not last["ok"]:
            return "the last test run after the last change did not exit 0", ("fix what is red and run the tests "
                                                                                "again, or report them as red")
        return ("the exit code of the last test run after the last change is not its own (a pipe without pipefail, a "
                "list or || after the runner)"), step
    good = [r for r in good if _claim_count(r["text"], True) > 0]   # D118: zero checked tests are never green
    if not good:
        return ("the last passing test run after the last change names no checked count above 0",
                "run the tests so that the runner names how many passed, and quote that count")
    missing = []
    for version in claim["versions"]:
        if not any(version in run["versions"] or re.search(rf"Python {re.escape(version)}(?![0-9])", run["text"])
                   or any(seen["versions_shown"].get(w) == version for w in run["words"]) for run in good):
            missing.append(version)
    if missing:
        return (f"no passing test run after the last change names Python {', '.join(missing)}",
                f"run the tests under Python {', '.join(missing)} too, or name only the interpreters that ran")
    return None


def _claim_repo_ok(repo: str | None, seen: dict, claim: dict, deadline: float) -> tuple[str, str] | None:
    """Why a claim that something is pushed, merged or landed has no evidence, and the smallest next step; None where
    it has (D80). Pushed: a fetch, pull or push succeeded in the transcript, and after it a remote-tracking ref points
    at the reported state (the commits the sentence names, else HEAD); or a push's output names the reported commit as
    the new value of a ref. Merged or landed: a fetch, pull or push succeeded in the transcript and the default branch
    of a remote contains the reported state; or, where the sentence names no commit, a merge of gh (not --auto) or of
    the GitHub tools succeeded."""
    pushed = claim["kind"] == "pushed"
    step = ("run `git fetch`, then compare the remote branch with the reported commit (`git rev-parse @{u}`) and push "
            "it where they differ" if pushed else
            "run `git fetch`, then check that the remote default branch contains the reported commit (`git merge-base "
            "--is-ancestor <commit> origin/main`)")
    if not pushed and not claim["commits"] and seen["merges"]:
        return None
    if repo is None:
        return "the working directory is no git repository, so no remote ref can show it", step
    reported = []
    for hexa in claim["commits"] or ["HEAD"]:
        proc = _git(repo, "rev-parse", "--verify", "-q", f"{hexa}^{{commit}}", deadline=deadline)
        if proc.returncode == 0:
            reported.append(proc.stdout.decode("ascii", "replace").strip())
    if not reported:
        return "the commit the message names is not a commit of this repository", step
    if pushed:
        for push in seen["remote"]:
            if push["words"][:1] == ["push"]:
                for m in re.finditer(r"[0-9a-f]{7,64}\.\.\.?([0-9a-f]{7,64})\s", push["text"]):
                    if any(r.startswith(m.group(1)) for r in reported):
                        return None
    if not seen["remote"]:
        return "no fetch, pull or push succeeded in the transcript, so the remote refs are not known", step
    refs = _git(repo, "for-each-ref", "--format=%(objectname) %(refname)", "refs/remotes/", deadline=deadline)
    if refs.returncode != 0:
        return "git could not list the remote-tracking refs", step
    remote = {}
    for line in refs.stdout.decode("utf-8", "replace").splitlines():
        oid, _, ref = line.partition(" ")
        remote[ref] = oid
    if pushed:
        targets = [ref for ref, oid in remote.items() if oid in reported]
        others = [r for r in reported if r not in remote.values()]
        if targets and all(_git(repo, "merge-base", "--is-ancestor", r, remote[targets[0]], deadline=deadline)
                           .returncode == 0 for r in others):
            return None
        return "no remote-tracking ref points at the reported state after the last fetch", step
    defaults = set()
    for ref in remote:
        parts = ref.split("/")
        if len(parts) == 4 and parts[3] in ("main", "master"):
            defaults.add(ref)
    heads = _git(repo, "for-each-ref", "--format=%(symref)", "refs/remotes/*/HEAD", deadline=deadline)
    if heads.returncode == 0:
        defaults.update(x for x in heads.stdout.decode("utf-8", "replace").split() if x in remote)
    for ref in sorted(defaults):
        if all(_git(repo, "merge-base", "--is-ancestor", r, remote[ref], deadline=deadline).returncode == 0
               for r in reported):
            return None
    return "no default branch of a remote contains the reported state after the last fetch", step


def _claim_receipts(repo: str | None) -> list[str]:
    """The hex strings of the receipts in the evidence folder (D80): its JSON files whose name says receipt, each read
    up to MAX_CLAIM_RECEIPT_BYTES. The declaration, the policy and the gate's own files are no receipts."""
    folder = _evidence_folder(repo) if repo is not None else None
    if folder is None:
        return []
    try:
        names = sorted(n for n in os.listdir(folder) if n.endswith(".json")
                       and "receipt" in n.lower())[:MAX_CLAIM_RECEIPTS]
    except OSError:
        return []
    found = []
    for name in names:
        try:
            raw = _read_regular(os.path.join(folder, name), MAX_CLAIM_RECEIPT_BYTES)
        except OSError:
            continue
        found += re.findall(r"(?<![0-9a-f])[0-9a-f]{12,128}(?![0-9a-f])", raw.decode("utf-8", "replace"))
    return found


def _claim_count(text: str, test: bool) -> int:
    """D118: the checked count a run names, 0 where it names none: for a test run the tests its runner names as passed
    or run (`5 passed`, `Ran 4 tests`, `Tests: 5 passed`), for any other run the largest whole number of its own, not
    a part of a decimal, a duration, a path, a name or an id."""
    if test:
        return max((int(next(g for g in m.groups() if g)) for m in _CLAIM_TEST_RAN.finditer(text)), default=0)
    return max((int(m.group(1)) for m in _CLAIM_WHOLE.finditer(text)), default=0)


def _claim_after(run: dict, seen: dict) -> bool:
    """Whether a run stands after the last change: a test run after it, a script run at it or after it (the run of a
    script is itself a change, D80)."""
    return run["at"] > seen["last_change"] or (run["at"] == seen["last_change"] and not run.get("test", True))


def _claim_status_open(claim: dict, seen: dict) -> tuple[str, str] | None:
    """D118: why a status of green, holds or OK has no evidence, and the smallest next step; None where it has. The
    last test run or check-script run after the last change must exit 0 with its own exit code and name a checked
    count above 0; each Python version a green status names needs such a test run that names it (D80)."""
    after = sorted([dict(r, test=True) for r in seen["runs"]] + [dict(s, test=False) for s in seen["scripts"]],
                   key=lambda r: r["at"])
    after = [r for r in after if _claim_after(r, seen)]
    step = ("run the tests or the check after the last change as a command of its own (nothing after it but `&&`, or "
            "`set -o pipefail` before a pipe) and quote the checked count")
    if not after:
        return "no test run or check-script run follows the last change in the transcript", step
    last = after[-1]
    if not last["ok"]:
        return "the last run after the last change did not exit 0", "fix what is red and run it again, or report it as red"
    if not last["own"]:
        return ("the exit code of the last run after the last change is not its own (a pipe without pipefail, a list or "
                "|| after it)"), step
    if _claim_count(last["text"].replace("OK", " "), last["test"]) == 0:
        return "the last run after the last change names no checked count above 0", step
    if claim["versions"]:
        return _claim_tests_open(claim, seen, False)
    return None


def _done_claims_entries(raw: bytes, where: str) -> list[tuple[str, tuple]]:
    """D118: the evidence a declaration of done-claims.json names, as (id, program words); GateError where it does not
    hold its form: exactly the keys schema and evidence, the schema DONE_CLAIMS_SCHEMA, at most
    MAX_DONE_CLAIMS_EVIDENCE entries of exactly id (a name as in done.checks) and program (1 to 8 words)."""
    try:
        doc = strict_json(raw)
    except (AmbiguousJSON, UnicodeDecodeError, ValueError) as exc:
        raise GateError(f"{where} is not JSON of one meaning") from exc
    if not (isinstance(doc, dict) and set(doc) == {"schema", "evidence"} and doc["schema"] == DONE_CLAIMS_SCHEMA
            and isinstance(doc["evidence"], list) and len(doc["evidence"]) <= MAX_DONE_CLAIMS_EVIDENCE):
        raise GateError(f"{where} must be an object with exactly the keys schema ({DONE_CLAIMS_SCHEMA}) and evidence, a "
                        f"list of at most {MAX_DONE_CLAIMS_EVIDENCE} entries")
    entries = []
    for n, entry in enumerate(doc["evidence"]):
        program = entry.get("program") if isinstance(entry, dict) else None
        if not (isinstance(entry, dict) and set(entry) == {"id", "program"} and isinstance(entry["id"], str)
                and _CHECK_ID.fullmatch(entry["id"]) and isinstance(program, list) and 1 <= len(program) <= 8
                and all(isinstance(w, str) and w and len(w) <= 256 and "\0" not in w for w in program)):
            raise GateError(f"{where} evidence[{n}] must be an object with exactly the keys id and program (1 to 8 "
                            "words)")
        entries.append((entry["id"], tuple(program)))
    return entries


def done_claims(repo: str | None, deadline: float) -> list[tuple[str, tuple]]:
    """D118: the evidence a completion needs in the repository, the union of the declarations of done-claims.json at
    HEAD, at the default branch of the remote origin (origin/HEAD, else origin/main, else origin/master) and in the
    work tree, so a session drops no entry by changing only one of them; [] where none declares any. GateError where a
    declaration is there but does not read."""
    if repo is None:
        return []
    found: list[tuple[str, tuple]] = []
    head = _git(repo, "rev-parse", "--verify", "--quiet", "HEAD^{commit}", deadline=deadline)
    revs = ["HEAD"] if head.returncode == 0 and _git_value(head.stdout) else []   # a repository without a commit
    for ref in ("refs/remotes/origin/HEAD", "refs/remotes/origin/main", "refs/remotes/origin/master"):
        got = _git(repo, "rev-parse", "--verify", "--quiet", f"{ref}^{{commit}}", deadline=deadline)
        if got.returncode == 0 and _git_value(got.stdout):
            revs.append(_git_value(got.stdout))
            break
    for rev in revs:
        raw = _blob(repo, rev, DONE_CLAIMS_FILE, deadline, MAX_DONE_CLAIMS_BYTES)
        if raw is not None:
            found += _done_claims_entries(raw, f"{DONE_CLAIMS_FILE} at {'HEAD' if rev == 'HEAD' else 'origin'}")
    try:
        raw = _read_regular(os.path.join(repo, DONE_CLAIMS_FILE), MAX_DONE_CLAIMS_BYTES + 1)
    except FileNotFoundError:
        raw = None
    except OSError as exc:
        raise GateError(f"{DONE_CLAIMS_FILE} in the work tree cannot be read ({exc.strerror or exc})") from exc
    if raw is not None:
        if len(raw) > MAX_DONE_CLAIMS_BYTES:
            raise GateError(f"{DONE_CLAIMS_FILE} in the work tree is larger than {MAX_DONE_CLAIMS_BYTES} bytes")
        found += _done_claims_entries(raw, f"{DONE_CLAIMS_FILE} in the work tree")
    return list(dict.fromkeys(found))


def _claim_declared_open(seen: dict, declared: list[tuple[str, tuple]]) -> tuple[str, str] | None:
    """D118: the first evidence of done-claims.json without its run: a run after the last change whose program (by the
    last part of its path; any python for python) and words begin as declared, exits 0 with its own exit code and
    names a checked count above 0."""
    def read_over(words: list) -> list:   # a python's switches before -m or the script, as _claim_test_run reads them
        rest = list(words[1:])
        while _CLAIM_PYTHON.fullmatch(words[0]) and rest and rest[0].startswith("-") and rest[0] not in ("-m", "-c"):
            rest = rest[2:] if rest[0] in ("-X", "-W") else rest[1:]
        return rest

    for ident, program in declared:
        name = os.path.basename(program[0])
        runs = [p for p in seen["programs"] if _claim_after(p, seen) and (
            p["words"][0] == name or (_CLAIM_PYTHON.fullmatch(p["words"][0]) and _CLAIM_PYTHON.fullmatch(name)))
            and read_over(p["words"])[:len(program) - 1] == list(program[1:])]
        last = runs[-1] if runs else None
        if last is None or not (last["ok"] and last["own"]
                                and _claim_count(last["text"].replace("OK", " "), last["test"]) > 0):
            return (f"the declared evidence {ident} ({DONE_CLAIMS_FILE}) has no run after the last change with its own "
                    "exit code 0 and a checked count above 0",
                    f"run `{' '.join(program)}` after the last change as a command of its own and quote its count")
    return None


#: D118: the claims a declaration of done-claims.json applies to: a completion, not a push, a merge or a verdict.
_CLAIM_COMPLETION = frozenset({"done", "tests", "green", "holds", "ok"})


def _claim_open(claim: dict, seen: dict | None, why: str | None, repo: str | None, done_passed: bool,
                receipts: list[str] | None, deadline: float,
                declared: tuple[list, str | None] | None = None) -> tuple[str, str] | None:
    """Why one claim has no evidence at the current state, and the smallest next step; None where it has (D80). D118:
    a completion needs as well the evidence the repository declares (`declared`: its entries and why it does not
    read)."""
    kind = claim["kind"]
    if kind == "verdict":
        if not claim["digests"]:
            return ("the verdict names no digest",
                    "name the digest the verdict is for, beside a receipt in .proofbundle/ that names exactly that "
                    "digest, or drop the verdict")
        if receipts is None:
            receipts = _claim_receipts(repo)
        if all(any(r == d or r.startswith(d) for r in receipts) for d in claim["digests"]):
            return None
        return ("no receipt in .proofbundle/ names the digest of the verdict",
                "keep a receipt that names exactly that digest in .proofbundle/, or drop the verdict")
    entries, problem = declared if declared is not None else ([], None)
    if seen is None:
        if kind in ("done", "tests") and done_passed and not claim["versions"] and not entries and problem is None:
            return None
        return why or "the transcript cannot be read", "end with a status that claims nothing"
    if kind in ("done", "tests"):
        found = _claim_tests_open(claim, seen, done_passed)
    elif kind in ("green", "holds", "ok"):
        found = _claim_status_open(claim, seen)
    elif kind == "script":
        runs = [s for s in seen["scripts"] if claim["script"] is None or s["script"] == claim["script"]]
        step = "run the check script again and quote its numbers, not only OK"
        if not runs:
            return "no run of the check script is in the transcript", step
        last = runs[-1]
        if not last["ok"]:
            return "the last run of the check script did not exit 0", step
        if not _claim_numbers(last["text"].replace("OK", " ")):
            return "the output of the last run of the check script names no number beside OK", step
        if not last["own"]:   # D118
            return ("the exit code of the last run of the check script is not its own (a pipe without pipefail, a "
                    "list or || after it)"), step
        if _claim_count(last["text"].replace("OK", " "), False) == 0:   # D118
            return "the output of the last run of the check script names no checked count above 0", step
        return None
    else:
        return _claim_repo_ok(repo, seen, claim, deadline)
    if found is None and kind in _CLAIM_COMPLETION:   # D118: the evidence the repository declares
        if problem is not None:
            return (f"{DONE_CLAIMS_FILE} cannot be read ({problem})",
                    "a person fixes the declaration in a commit, or end with a status that claims nothing")
        found = _claim_declared_open(seen, entries)
    return found


def claim_check(event: dict, deadline: float, done_passed: bool = False) -> dict:
    """The claims of the last message and their evidence at the current state (D80): {"claims": [{"kind", "words",
    "open", "next"}], "open": the claims without evidence, "count": the tool calls of the transcript, "repo"}. A
    message without a claim of the closed list needs nothing; the transcript is read only for a claim that needs it."""
    message = event.get("last_assistant_message")
    claims = message_claims(message) if isinstance(message, str) else []
    out = {"claims": [], "open": [], "count": None, "repo": None}
    if not claims:
        return out
    directory = _event_directory(event)
    try:
        paths, _why = _repo_paths(directory, deadline)
        repo = paths["toplevel"] if paths is not None else None
    except GateError:
        repo = None
    out["repo"] = repo
    seen, why = None, None
    if any(c["kind"] != "verdict" for c in claims):
        calls, why = read_transcript(event.get("transcript_path"))
        if calls is not None:
            seen = _claim_evidence_calls(calls)
            out["count"] = seen["count"]
    receipts, declared = None, None
    if any(c["kind"] in _CLAIM_COMPLETION for c in claims):   # D118
        try:
            declared = (done_claims(repo, deadline), None)
        except GateError as exc:
            declared = ([], str(exc))
    for claim in claims:
        try:
            found = _claim_open(claim, seen, why, repo, done_passed, receipts, deadline, declared)
        except GateError:
            found = ("the gate could not read the repository", "end with a status that claims nothing")
        row = {"kind": claim["kind"], "words": claim["words"], "open": None if found is None else found[0],
               "next": None if found is None else found[1]}
        out["claims"].append(row)
        if found is not None and not any(o["kind"] == row["kind"] and o["open"] == row["open"] for o in out["open"]):
            out["open"].append(row)
    return out


def _claim_verdict(result: dict) -> Verdict:
    """The deny of a claim without evidence (D80): every open claim, the first one's next step."""
    failed = "; ".join(f"the last message claims {_CLAIM_NAMES[o['kind']]} ({o['words']}), but {o['open']}"
                       for o in result["open"])
    return Verdict("deny", f"proofbundle claim check: {failed}.", "claim_without_evidence",
                   evidence="the last message and the transcript", failed=failed, next_step=result["open"][0]["next"],
                   repo=result["repo"])


def _claim_line(verdict: Verdict) -> str:
    return (f"proofbundle claim check: {verdict.failed.rstrip('.')}. Next: {verdict.next_step.rstrip('.')}, or end "
            "with a status that claims nothing: partial, blocked or not checked, each with its reason.")


def _claim_fingerprint(result: dict, deadline: float) -> str:
    """The state a claim block speaks for (point 4 of follow-up note 32, "am unveränderten Stand"): the open claims and why,
    HEAD, the status of the work tree and the remote-tracking refs. A commit, a change of a file, a fetch or push that
    moves a ref, or another reason makes another state; a tool call that changes none of them does not, so an agent
    cannot keep a block alive by calling tools that change nothing."""
    head, status, remotes = None, None, None
    if result["repo"] is not None:
        proc = _git(result["repo"], "rev-parse", "--verify", "-q", "HEAD", deadline=deadline)
        head = proc.stdout.decode("ascii", "replace").strip() if proc.returncode == 0 else None
        proc = _git(result["repo"], "status", "--porcelain=v1", "-z", "--untracked-files=all", deadline=deadline)
        status = hashlib.sha256(proc.stdout).hexdigest() if proc.returncode == 0 else None
        proc = _git(result["repo"], "for-each-ref", "--format=%(objectname) %(refname)", "refs/remotes/",
                    deadline=deadline)
        remotes = hashlib.sha256(proc.stdout).hexdigest() if proc.returncode == 0 else None
    shape = [[o["kind"], o["open"]] for o in result["open"]]
    return hashlib.sha256(json.dumps([shape, head, status, remotes]).encode("utf-8")).hexdigest()


def _account_claim_block(event: dict, result: dict, host: str, deadline: float) -> tuple[int, str | None]:
    """Count one claim block (D80, point 4 of follow-up note 32) and return (blocks, problem): the blocks in a row of the
    same open claims on the same state in this session, this one included, and why the count could not be recorded.
    A Stop event with stop_hook_active false follows no block, so it counts as the first; where the count cannot be
    kept, a Stop after a block (stop_hook_active true) counts as past the limit, so the session never loops on a block
    the hook cannot count."""
    session = _session_key(event)
    after_block = event.get("stop_hook_active") is True
    fingerprint = _claim_fingerprint(result, deadline)
    directory = log_directory(host)
    if directory is None:
        return (CLAIM_MAX_BLOCKS + 1 if after_block else 1), "no plugin data directory can be written"
    path = os.path.join(directory, CLAIM_STATE)
    sessions: dict = {}
    try:
        raw = _read_regular(path, MAX_STATE_BYTES + 1)
        doc = strict_json(raw) if len(raw) <= MAX_STATE_BYTES else None
        if (isinstance(doc, dict) and doc.get("schema") == CLAIM_STATE_SCHEMA and isinstance(doc.get("sessions"), dict)):
            sessions = {k: v for k, v in doc["sessions"].items() if isinstance(v, dict)
                        and isinstance(v.get("blocks"), int) and not isinstance(v.get("blocks"), bool)
                        and isinstance(v.get("fingerprint"), str)}
    except (OSError, ValueError, UnicodeDecodeError):
        sessions = {}
    previous = sessions.pop(session, None)
    same = after_block and previous is not None and previous["fingerprint"] == fingerprint
    blocks = previous["blocks"] + 1 if same else 1
    sessions[session] = {"fingerprint": fingerprint, "blocks": blocks}
    while len(sessions) > _CLAIM_STATE_KEEP:
        sessions.pop(next(iter(sessions)))
    problem = _write_record(path, {"schema": CLAIM_STATE_SCHEMA, "sessions": sessions})
    if problem is not None and after_block and not same:
        return CLAIM_MAX_BLOCKS + 1, problem
    return blocks, problem


def stop_command(argv: list[str]) -> int:
    """The Stop hook (D26, D28), the same for Claude Code and Codex. Prints a block whose reason is the one line for
    the model and whose message is the short line for the user (D53); nothing for a pass without a finding, a message
    for a pass with one (a count the hook could not write or read, a blocker file out of date) and for an end without a
    done verdict; nothing where no done check is declared; exits 0. It never sets continue: a block asks the host to go on
    working (Codex inserts the reason as a new turn), it never stops the host. Any failure inside the check blocks:
    the session does not end on a check that reached no verdict. After max_blocks blocks without progress it writes
    DONE_BLOCKER and stops blocking (N3). Claude Code overrides a Stop hook after eight continuations without a tool
    call in between (documented; nine blocks measured with Claude Code 2.1.294), which is why the hard boundary is
    the CI check (README). Beside the repository of the cwd it judges every repository with a local done order (D38,
    done_evaluations)."""
    deadline = time.monotonic() + DEADLINE_SECONDS
    host, event = "claude", None
    try:
        host, event = _hook_event(argv, "Stop")
        results = done_evaluations(_event_directory(event), deadline)
    except GateError as exc:
        verdict = Verdict("deny", f"proofbundle gate: {exc}.", "gate_error", evidence="the done check",
                          failed=f"the check reached no verdict ({exc})", next_step="fix the cause named here")
        results = [_failed_result(exc, verdict)]
    except Exception as exc:  # noqa: BLE001 - any failure inside the check blocks, it never lets the end through
        verdict = Verdict("deny", f"proofbundle gate: internal error {type(exc).__name__}: {exc}.", "internal_error",
                          evidence="the done check", failed=f"internal error {type(exc).__name__}: {exc}",
                          next_step="report this error")
        results = [_failed_result(exc, verdict)]
    # D38: every repository with a local done order is judged beside the one of the cwd. Each counts its own blocks: the
    # first repository that still blocks gives the answer; one past its limit writes its blocker and the next one is
    # looked at; the end without a done verdict comes only when every refused repository has written its blocker.
    shown, ended, passed = None, [], []
    for result in results:
        if result["verdict"].decision != "pass" or result["done"] is None:
            continue
        try:
            counting, removal, unread = _account_pass(result, event)
        except Exception as exc:  # noqa: BLE001 - counting never changes the answer, but a failed count is named (R3-4)
            counting, removal, unread = f"counting failed ({type(exc).__name__}: {exc})", None, None
        passed.append((result, counting, removal, unread))
    for result in results:
        verdict = result["verdict"]
        if verdict.decision != "deny":
            continue
        # Every refusal counts toward the limit, a check that refused early or failed included (review 2026-10-09, F6);
        # where no order could be read, the default limit applies.
        limit = result["done"]["max_blocks"] if result["done"] is not None else DEFAULT_MAX_BLOCKS
        blocker, counting, unread = None, None, None
        try:
            if result["repo"] and result["open"]:
                blocker, counting, unread = _account_block(result, event, limit)
            elif result.get("order_key") and result["open"]:   # O3: no repository, the gate directory counts
                blocker, counting, unread = _account_order_block(result, event, limit)
        except Exception as exc:  # noqa: BLE001 - counting never changes the answer, but a failed count is named (R3-4)
            blocker, counting = None, f"counting failed ({type(exc).__name__}: {exc})"
        if blocker is None:
            shown = (verdict, limit, counting, unread)
            break
        ended.append((result, verdict, limit, blocker, counting))
    decisive = (shown[0] if shown is not None else ended[0][1] if ended else passed[0][0]["verdict"] if passed
                else results[0]["verdict"])
    # D80: where the done check lets the end through, the claims of the last message need their own evidence; under
    # Claude Code, whose transcript form is measured. A block of the done check or its end goes first.
    claims, claim_block, claim_end = None, None, None
    if (shown is None and not ended and host == "claude" and isinstance(event, dict)
            and all(r["verdict"].decision in ("inactive", "pass", "deny") for r in results)):
        here_passed = bool(results) and results[0]["verdict"].decision == "pass" and results[0]["done"] is not None
        try:
            claims = claim_check(event, deadline, here_passed)
        except Exception as exc:  # noqa: BLE001 - a failure of the claim check holds only a message that claims
            try:
                found = message_claims(event.get("last_assistant_message") or "")
            except Exception:  # noqa: BLE001
                found = [{"kind": "done", "words": ""}]
            claims = {"claims": [], "count": None, "repo": None,
                      "open": [{"kind": c["kind"], "words": c["words"], "next": "end with a status that claims nothing",
                                "open": f"the claim check reached no verdict ({type(exc).__name__})"}
                               for c in found[:1]]}
        if claims["open"]:
            verdict = _claim_verdict(claims)
            try:
                blocks, counting = _account_claim_block(event, claims, host, deadline)
            except Exception as exc:  # noqa: BLE001 - a count that failed ends the session after a block (point 4)
                blocks = CLAIM_MAX_BLOCKS + 1 if event.get("stop_hook_active") is True else 1
                counting = f"counting failed ({type(exc).__name__})"
            if blocks > CLAIM_MAX_BLOCKS:
                claim_end = verdict
            else:
                claim_block = (verdict, counting)
            decisive = verdict
    try:
        entry = log_entry(host, event, Outcome(decisive.decision, decisive.text(), [decisive]),
                          ["Stop"] + (["claims"] if claims and claims["claims"] else [])
                          + (["claims-ended"] if claim_end is not None else []))
        if claims and claims["claims"]:
            entry["claims"] = [{"kind": c["kind"], "evidence": c["open"] is None} for c in claims["claims"]]
        write_log(entry, host)
    except Exception:  # noqa: BLE001 - the log never changes the answer
        pass
    language = _read_language(os.environ)
    if claim_block is not None:
        verdict, counting = claim_block
        line = _claim_line(verdict)
        if counting is not None:
            line += (f" The hook could not count this block ({counting}), so the next stop after a block ends the "
                     "session with the claim open.")
        sys.stdout.write(json.dumps({"decision": "block", "reason": line,
                                     "systemMessage": _stop_short(verdict, language)}) + "\n")
        return 0
    claim_note = None if claim_end is None else (
        f"proofbundle claim check: OPEN. The same claim stayed without evidence through {CLAIM_MAX_BLOCKS} blocks on "
        f"the unchanged state, so the hook stops blocking and the session ends with the claim open, not confirmed. "
        f"Open: {claim_end.failed.rstrip('.')}.")
    if shown is not None:
        verdict, limit, counting, unread = shown
        line = _done_line(verdict)
        if counting is not None:
            line += (f" The hook could not count this block: {counting}, so the end after {limit} blocks without "
                     f"progress cannot take effect; make {EVIDENCE_DIR} a directory of the repository that the hook "
                     "can write.")
        elif unread is not None:
            line += (f" The hook counted this block as the first: the earlier count could not be read ({unread}); "
                     f"its own record is written again, so the end after {limit} blocks without progress counts from "
                     "here.")
        sys.stdout.write(json.dumps({"decision": "block", "reason": line,
                                     "systemMessage": _stop_short(verdict, language)}) + "\n")
    elif ended:
        result, verdict, limit, blocker, counting = ended[0]
        message = (f"proofbundle done check: NOT DONE. The same open points stayed open through {limit} "
                   f"blocks, so the hook stops blocking and the session ends without a done verdict. The open points "
                   f"and the state the gate measured are in {blocker}. Open: {verdict.failed.rstrip('.')}.")
        if counting is not None:   # an unread record never reaches here: it makes this block the first (R4-3)
            message += (f" The hook could not record this end in its count: {counting}; the next stop reads the record "
                        "from before it.")
        for other, other_verdict, _limit, other_blocker, _counting in ended[1:]:
            shown = _order_label(other["local"]) if other.get("local") else other["repo"]
            message += (f" Also ended without a done verdict: {shown}, open points in "
                        f"{other_blocker}: "
                        f"{other_verdict.failed.rstrip('.')}.")
        sys.stdout.write(json.dumps({"systemMessage": message}) + "\n")
    elif passed and any(c is not None or r is not None or u is not None for _res, c, r, u in passed):
        # D53: a passed end is silent; a failure of the hook's own files is a finding and stays visible, each named for
        # what it is, and only one that happened (R8-4)
        messages = []
        for result, counting, removal, unread in passed:
            message = result["verdict"].detail
            if counting is not None:
                message += f" The hook could not record this end in its count: {counting}."
            if unread is not None:
                message += (f" The earlier count could not be read ({unread}); "
                            + ("the hook wrote its own record in its place." if counting is None
                               else "it stays in place, since the hook could not write its own record."))
            if removal is not None:   # each removal names what stays and what it means (D127: the hand-over record)
                message += f" {removal[0].upper()}{removal[1:]}."
            if result.get("local"):
                message += f" (Local done order {result['local']}, D38.)"
            messages.append(message)
        sys.stdout.write(json.dumps({"systemMessage": " ".join(([claim_note] if claim_note else []) + messages)})
                         + "\n")
    elif passed:
        if claim_note is not None:   # D53: a passed end without a finding is silent; the log holds it
            sys.stdout.write(json.dumps({"systemMessage": claim_note}) + "\n")
    elif any(r["verdict"].decision not in ("inactive", "pass", "deny") for r in results):
        line = _done_line(decisive)
        sys.stdout.write(json.dumps({"decision": "block", "reason": line,
                                     "systemMessage": _stop_short(decisive, language)}) + "\n")
    elif claim_note is not None:
        sys.stdout.write(json.dumps({"systemMessage": claim_note}) + "\n")
    return 0


def _stop_short(verdict: Verdict, language: str) -> str:
    """The short line a blocked end shows the user (D53); the model gets the one line of _done_line as the reason."""
    return short_line(verdict.decision, Outcome(verdict.decision, verdict.text(), [verdict]), None, language,
                      form="stop")


def _failed_check(exc: Exception, verdict: Verdict) -> dict | None:
    """The result the check had reached when it failed (done_evaluation attaches it), with the failure as its one open
    point, so a check that fails the same way at every stop is counted like any other refusal; None when the failure
    came before the repository was known."""
    partial = getattr(exc, "partial", None)
    if not isinstance(partial, dict) or not partial.get("repo"):
        return None
    partial["verdict"] = verdict
    partial["open"] = [{"id": "done-check", "status": verdict.reason_id, "failed": verdict.failed,
                        "command": verdict.next_step}]
    return partial


def task_completed_command(argv: list[str]) -> int:
    """The TaskCompleted hook of Claude Code (D28): the same check as the Stop hook. Prints the one line on stdout
    when the task must stay open, nothing when it may be marked completed, and exits 0 either way; the hook command
    in hooks.json turns a printed line into exit 2 with the line on stderr, and any other exit into exit 2 with its
    own line. Python itself exits 2 when it cannot open the gate (measured), so exit 2 cannot be the gate's own
    signal. Any failure inside the check keeps the task open. Codex has no such event. Like the Stop hook it judges
    every repository with a local done order too (D38)."""
    deadline = time.monotonic() + DEADLINE_SECONDS
    try:
        _host_name, event = _hook_event(argv, "TaskCompleted")
        results = done_evaluations(_event_directory(event), deadline)
    except GateError as exc:
        results = [_failed_result(exc, Verdict("deny", f"proofbundle gate: {exc}.", "gate_error",
                                               evidence="the done check", failed=f"the check reached no verdict ({exc})",
                                               next_step="fix the cause named here"))]
    except Exception as exc:  # noqa: BLE001 - any failure inside the check keeps the task open
        results = [_failed_result(exc, Verdict("deny", f"proofbundle gate: internal error {type(exc).__name__}: {exc}.",
                                               "internal_error", evidence="the done check",
                                               failed=f"internal error {type(exc).__name__}: {exc}",
                                               next_step="report this error"))]
    # D38: the task stays open while any repository the end judges, a local done order's included, refuses it
    result = next((r for r in results if r["verdict"].decision == "deny"), None)
    if result is None:
        return 0
    try:
        if result["done"] is not None:
            _tally(result["repo"], task_blocked=1)
    except Exception:  # noqa: BLE001 - counting never changes the answer
        pass
    sys.stdout.write(_done_line(result["verdict"]) + "\n")
    return 0


# --- the hand-over of an open blocker at the next session start (D127) ---------------------------------------------

#: The rounds one open set is handed on; at the next start without progress the hook writes the owner card instead.
HANDOVER_ROUNDS = 2
_HANDOVER_FIELDS = frozenset({"schema", "rounds", "open", "head", "carded", "written"})
#: The folder of the gate directory the house collects owner cards from (D25's location: user-wide, outside every
#: repository), and the card's form.
OWNER_CARDS_DIR = "owner-cards"
OWNER_CARD_SCHEMA = "proofbundle-plugin/owner-card/v0.1"
#: The gate's status names an open point of the hand-over may show (T2): those of a check and of the paths
#: (_OPEN_REASON), and those of a refusal before the checks (_refused, _order_refusal). A check's command is run; the
#: others name their next step.
_HANDOVER_CHECK_STATUSES = frozenset({"missing", "unverified", "red", "other_selection", "no_state", "stale"})
_HANDOVER_STATUSES = frozenset(_OPEN_REASON) | frozenset({
    "declaration_not_committed", "missing_file", "state_not_measured", "order_base_not_measured", "order_changed",
    "order_unrecorded", "order_removed", "order_unreadable", "order_unbound"})
_HANDOVER_BOUNDARY = ("The task counts as done only when the Stop hook's done check passes; this hand-over asks for "
                      "nothing else.")
OWNER_CARD_TEXT = ("The done check of this repository stayed NOT DONE with the same open points through two hand-overs "
                   "without progress (D127); the hook hands these open points on no further, and a changed open set "
                   "starts the hand-over again. Guard does not count a task as done before the required checks pass; "
                   "it does not make the agent work until they pass. This card is a notice to the owner, not a "
                   "receipt, and proves nothing about the tests.")


def _blocked_repos(directory: str, deadline: float, environ) -> list[str]:
    """The repositories that hold a blocker of the Stop hook (DONE_BLOCKER, a regular file), each once: the one of
    directory and each one a local done order binds (D38), where the hook reads the orders (D128, _hook_orders). Only
    the file's presence is read, never its text (T1)."""
    repo, unreadable = _work_tree(directory, deadline, "--path-format=absolute")
    if unreadable:
        raise GateError(unreadable)
    candidates = [] if repo is None else [str(repo)]
    for entry in _hook_orders(environ, deadline):
        bound = entry["order"]["repo"] if "order" in entry else entry.get("bound")
        if bound:
            candidates.append(bound)
    found, seen = [], set()
    for candidate in candidates:
        if os.path.realpath(candidate) in seen:
            continue
        seen.add(os.path.realpath(candidate))
        try:
            if stat.S_ISREG(os.lstat(os.path.join(candidate, *DONE_BLOCKER.split("/"))).st_mode):
                found.append(candidate)
        except OSError:
            pass
    return found


def _unbound_blockers(environ, deadline: float) -> list[str]:
    """The blockers of local done orders whose repository git does not find (owner choice O3, _account_order_block):
    `<key>.blocker.json` beside the order in the gate directory, a regular file, where the hook reads the orders (D128).
    Only the file's presence is read, never its text (T1). There is no repository to hand anything on to; the start
    names them (owner answer A on card OA-694b3f17d4)."""
    found = []
    for entry in _hook_orders(environ, deadline):
        if not entry.get("key"):
            continue
        blocker = os.path.join(os.path.dirname(entry["file"]), f"{entry['key']}.blocker.json")
        try:
            if stat.S_ISREG(os.lstat(blocker).st_mode):
                found.append(blocker)
        except OSError:
            pass
    return found


def _handover_record(repo: str) -> tuple[dict | None, str | None]:
    """The hand-over record (DONE_HANDOVER) as (record, problem): (None, None) where there is none, (None, why) where a
    present file is not the hook's record. Its content is counted, never shown: the hand-over is built from the fresh
    verdict alone."""
    doc = _read_done_file(repo, DONE_HANDOVER, "handover")
    if doc is None:
        return None, _done_file_problem(repo, DONE_HANDOVER, "handover")
    pairs = doc.get("open")
    if not (frozenset(doc) == _HANDOVER_FIELDS and type(doc["rounds"]) is int and doc["rounds"] >= 1
            and type(doc["carded"]) is bool and isinstance(pairs, list)
            and all(isinstance(p, list) and len(p) == 2 and all(isinstance(x, str) for x in p) for p in pairs)):
        return None, f"{DONE_HANDOVER} is not the hook's hand-over record (its fields or their types differ)"
    return doc, None


def _shown_repo(repo: str) -> str:
    """The repository as the hand-over names it: its path, in JSON quotes where it holds a character that is not
    printable (a line break would end the line it stands in)."""
    return repo if repo.isprintable() else json.dumps(repo)


def _handover_text(repo: str, rounds: int, points: list[dict]) -> str:
    """The hand-over the model gets (D127), built from the fresh verdict alone: the repository, the round, each open
    point by its id and status with the command the gate built for it, and the boundary. An id outside the order's
    grammar, a status that is not the gate's, and the command beside them, are not shown (T2)."""
    lines = [f"proofbundle done check, round {rounds} of the hand-over (D127), repository {_shown_repo(repo)}: the Stop "
             "hook let a session end there without a done verdict, and the done check, run again at this start, is "
             "still NOT DONE. Open:"]
    for point in points:
        ident, status, command = point.get("id"), point.get("status"), point.get("command")
        if (isinstance(ident, str) and _CHECK_ID.fullmatch(ident) and isinstance(status, str)
                and status in _HANDOVER_STATUSES and isinstance(command, str) and command):
            lines.append(f"- {ident} ({status}): {'run ' if status in _HANDOVER_CHECK_STATUSES else ''}{command}")
        else:
            lines.append("- an open point the gate does not show")
    lines.append(_HANDOVER_BOUNDARY)
    return "\n".join(lines)


def _owner_card_path(environ, repo: str, pairs: list) -> str | None:
    """Where the owner card of a stalled hand-over lies: <gate directory>/owner-cards/, named by the sha256 of the
    repository and the open set, so the same stalled state has one card. None without a gate directory."""
    directory = _gate_dir(environ)
    if directory is None:
        return None
    named = json.dumps([os.path.realpath(repo), sorted(pairs)]).encode("utf-8")
    return os.path.join(directory, OWNER_CARDS_DIR, f"done-handover-{hashlib.sha256(named).hexdigest()}.json")


def _write_owner_card(path: str, doc: dict) -> str | None:
    """Write the owner card once, never through a link: a regular file of the same name stands and is not written
    again. None where the card stands now, else why not."""
    folder = os.path.dirname(path)
    try:
        os.makedirs(folder, 0o700, exist_ok=True)
    except OSError as exc:
        return f"the folder {folder} cannot be made ({exc})"
    try:
        fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_NOFOLLOW", 0), 0o600)
    except FileExistsError:
        try:
            return None if stat.S_ISREG(os.lstat(path).st_mode) else f"{path} is there and is not a regular file"
        except OSError as exc:
            return f"{path} cannot be examined ({exc})"
    except OSError as exc:
        return f"{path} cannot be made ({exc})"
    try:
        with os.fdopen(fd, "wb") as handle:
            handle.write((json.dumps(doc, indent=1, sort_keys=True) + "\n").encode("utf-8", "surrogatepass"))
    except OSError as exc:
        try:
            os.unlink(path)
        except OSError:
            pass
        return f"{path} could not be written ({exc})"
    return None


def _hand_over(directory: str, deadline: float, environ) -> tuple[list[str], list[str]]:
    """The hand-over of every open blocker (D127) as (the contexts for the model, the messages for the user). Without a
    blocker, nothing. With one, the done check runs again as at Stop (done_evaluations) and only its fresh open points
    count: a pass or no done check hands nothing on and leaves the files; NOT DONE updates the hand-over record and hands
    the open points on for HANDOVER_ROUNDS rounds of the same open set, after which one owner card replaces the
    hand-over of that set. A check that reached no verdict, or ran past the deadline, hands nothing on. The blocker of
    an order whose repository git does not find (O3) is named to the user and hands nothing on."""
    unbound = [f"proofbundle done check: a session ended NOT DONE on a local done order whose repository git does not "
               f"find, and its blocker {_shown_repo(path)} stands; there is no repository to hand anything on to, "
               "done-order --list names the order, and a person removes it with done-order --remove (D127, O3)."
               for path in _unbound_blockers(environ, deadline)]
    blocked = _blocked_repos(directory, deadline, environ)
    if not blocked:
        return [], unbound
    results = done_evaluations(directory, deadline, environ)
    repos = {os.path.realpath(repo): repo for repo in blocked}
    failed = [r["verdict"].failed or r["verdict"].reason_id for r in results
              if r["verdict"].reason_id in ("gate_error", "internal_error")
              and (r["repo"] is None or os.path.realpath(r["repo"]) in repos)]
    if failed or time.monotonic() > deadline:
        why = "; ".join(failed) if failed else f"it ran past the {DEADLINE_SECONDS:g} seconds the Stop hook has"
        return [], unbound + [f"proofbundle done check: the hand-over could not run the done check again "
                              f"({_short(why, 400)}), so no open point was handed on; the blocker stands (D127)."]
    contexts, notes = [], list(unbound)
    for key, repo in repos.items():
        group = [r for r in results if r["repo"] and os.path.realpath(r["repo"]) == key]
        points = [p for r in group if r["verdict"].decision == "deny" for p in r["open"]]
        if not points:
            continue   # a pass or no done check: nothing to hand on; the next Stop counts a pass (_account_pass)
        pairs = []
        for point in points:
            if [point["id"], point["status"]] not in pairs:
                pairs.append([point["id"], point["status"]])
        head = next((r["commit"] for r in group if r["commit"]), None)
        shown = _shown_repo(repo)
        record, unread = _handover_record(repo)
        if unread is not None:
            notes.append(f"proofbundle done check: the earlier hand-over record of {shown} could not be read "
                         f"({unread}); this start counts as round 1 (D127).")
        # No progress is the same open set; any other set, a strict subset (progress) included, starts at round 1
        same = record is not None and {tuple(p) for p in record["open"]} == {tuple(p) for p in pairs}
        rounds = record["rounds"] + 1 if same else 1
        carded = bool(same and record["carded"])
        if rounds <= HANDOVER_ROUNDS:
            contexts.append(_handover_text(repo, rounds, points))
            notes.append(f"proofbundle done check: the open points of {shown} are handed on to this session, round "
                         f"{rounds} of the hand-over (D127).")
        else:
            card = _owner_card_path(environ, repo, pairs)
            if carded:
                notes.append(f"proofbundle done check: {shown} is still NOT DONE with the open points of the owner card "
                             f"{card or 'in the gate directory'}; the hook hands them on no further (D127).")
            else:
                problem = ("there is no gate directory (PROOFBUNDLE_GATE_DIR is not an absolute path and there is no "
                           "home)") if card is None else _write_owner_card(card, {
                    "schema": OWNER_CARD_SCHEMA, "kind": "done-handover-stalled", "repo": repo, "head": head,
                    "open": pairs, "rounds": rounds, "blocker": os.path.join(repo, *DONE_BLOCKER.split("/")),
                    "written": _now(), "text": OWNER_CARD_TEXT})
                carded = problem is None
                notes.append(f"proofbundle done check: {shown} stayed NOT DONE with the same open points through "
                             f"{HANDOVER_ROUNDS} hand-overs without progress; "
                             + (f"the owner card {card} names them" if problem is None
                                else f"the owner card could not be written ({problem})")
                             + ", and the hook hands them on no further (D127).")
        written = _write_done_file(repo, DONE_HANDOVER, {"schema": DONE_FILES_SCHEMA.format("handover"),
                                                         "rounds": rounds, "open": pairs, "head": head,
                                                         "carded": carded, "written": _now()})
        if written is not None:
            notes.append(f"proofbundle done check: the hand-over record of {shown} could not be written ({written}), "
                         "so this round is not counted (D127).")
    return contexts, notes


def session_start_command(argv: list[str]) -> int:
    """The SessionStart hook of Claude Code (D127), for every source (startup, resume, clear, compact): where the Stop
    hook ended a session NOT DONE and left its blocker, the next start hands the open points of a fresh done check on
    as additional context, never the blocker's text. Prints that context and a short message for the user, a message
    alone for an owner card or a failure, and nothing where there is no blocker or the check passes; exits 0 always: a
    failure never blocks the start, it is named. Guard does not count a task as done before the required checks pass;
    the hand-over does not make the agent work until they pass. Codex does not register it (NOT MEASURED there)."""
    deadline = time.monotonic() + DEADLINE_SECONDS
    try:
        _host_name, event = _hook_event(argv, "SessionStart")
        contexts, notes = _hand_over(_event_directory(event), deadline, os.environ)
    except Exception as exc:  # noqa: BLE001 - a failure never blocks the start, and it is named, never silent (T5)
        contexts, notes = [], [f"proofbundle done check: the hand-over failed ({type(exc).__name__}: "
                               f"{_short(str(exc), 400)}), so no open point was handed on; the done check at Stop is "
                               "unchanged (D127)."]
    answer: dict = {}
    if notes:
        answer["systemMessage"] = " ".join(notes)
    if contexts:
        answer["hookSpecificOutput"] = {"hookEventName": "SessionStart", "additionalContext": "\n\n".join(contexts)}
    if answer:
        try:
            sys.stdout.write(json.dumps(answer) + "\n")
        except Exception:  # noqa: BLE001 - where even the message fails, the start goes on without a word
            pass
    return 0


DONE_ORDER_USAGE = ("usage: done-order --repo DIR [--declaration FILE] [--policy FILE] [--replace] | "
                    "done-order --remove (--repo DIR | --key KEY) | done-order --list")


def _write_order_file(folder: str, name: str, data: bytes) -> None:
    """Write a file of the orders folder through a fresh temporary file that replaces it, never through a link."""
    temporary = os.path.join(folder, f".{name}.{secrets.token_hex(6)}.tmp")
    fd = os.open(temporary, os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_NOFOLLOW", 0), 0o600)
    try:
        with os.fdopen(fd, "wb") as handle:
            handle.write(data)
        os.replace(temporary, os.path.join(folder, name))
    except BaseException:
        try:
            os.unlink(temporary)
        except OSError:
            pass
        raise


def _ignored(root: str, path: str, deadline: float) -> bool:
    """Whether git ignores `path` in the work tree at `root`. check-ignore refuses the literal pathspecs of the gate's
    read environment, so this call alone runs without them; `path` is a relative path of a done section, checked by
    _relative, with no pathspec magic."""
    _refuse_partial_clone(root, deadline)
    left = deadline - time.monotonic()
    if left <= 0:
        raise GateError("the gate ran out of time")
    environment = {k: v for k, v in _read_env(root).items() if k != "GIT_LITERAL_PATHSPECS"}
    proc = subprocess.run(["git", *_READ_ONLY_GIT, "-C", root, "check-ignore", "-q", "--", path], capture_output=True,
                          timeout=left, check=False, env=environment)
    if proc.returncode not in (0, 1):
        raise GateError(f"git check-ignore failed for {path}: "
                        f"{proc.stderr.decode('utf-8', 'replace').strip() or proc.returncode}")
    return proc.returncode == 0


def _ignore_receipts(root: str, done: dict, deadline: float) -> list[str]:
    """Add to the repository's info/exclude every receipt and every file of the done check's own that git does not yet
    ignore, so none of them reaches a commit (D38). Returns the lines added."""
    wanted = [check["receipt"] for check in done["checks"]] + list(DONE_OWN_FILES)
    missing = [path for path in wanted if not _ignored(root, path, deadline)]
    if not missing:
        return []
    where = _git(root, "rev-parse", "--path-format=absolute", "--git-path", "info/exclude", deadline=deadline)
    lines = _git_lines(where.stdout) if where.returncode == 0 else None
    if not lines or len(lines) != 1 or not os.path.isabs(lines[0]):
        raise GateError("git does not name the repository's info/exclude file")
    added = [f"/{path}" for path in missing]
    os.makedirs(os.path.dirname(lines[0]), exist_ok=True)
    with open(lines[0], "a", encoding="utf-8") as handle:
        handle.write("# proofbundle done order (D38): receipts and the done check's own files stay out of commits\n")
        handle.write("".join(line + "\n" for line in added))
    still = [path for path in missing if not _ignored(root, path, deadline)]
    if still:
        raise GateError(f"git still does not ignore {', '.join(still)} (a tracked file is never ignored); the order "
                        "is not written")
    return added


def done_order(repo_dir: str, declaration: str | None, policy_file: str | None, replace: bool, deadline: float,
               environ: dict | None = None) -> str:
    """Make the local done order of a repository (D38): its done section from a declaration (by default the one in the
    work tree, account A's variant E), the policy's bytes, the commit at HEAD as the base of `paths`, the work tree root and
    the git directory, written to the gate directory with the gate's record of its digest. An order that exists is
    replaced only with `replace`, and the record keeps the digest it replaces. The receipts are added to info/exclude
    where git does not yet ignore them. It writes whatever its own environment sets, and says that the hooks read the
    order only with the protected channel (D128): the setting is the hook's, and a person's shell need not carry it."""
    environ = os.environ if environ is None else environ
    folder = _orders_dir(environ)
    if folder is None:
        raise GateError("no gate directory is known (an absolute PROOFBUNDLE_GATE_DIR, XDG_CONFIG_HOME or HOME)")
    paths, why = _repo_paths(repo_dir, deadline)
    if paths is None or paths["toplevel"] is None or paths["gitdir"] is None:
        raise GateError(f"{repo_dir} is not in a git work tree ({why or 'git names none'})")
    root, gitdir = os.path.realpath(paths["toplevel"]), os.path.realpath(paths["gitdir"])
    source = declaration or os.path.join(root, *DECLARATION.split("/"))
    raw = _read_regular(source, MAX_DECLARATION_BYTES + 1, follow=True)
    if len(raw) > MAX_DECLARATION_BYTES:
        raise GateError(f"{source} holds more than {MAX_DECLARATION_BYTES} bytes")
    done = parse_done(raw)
    if done is None:
        raise GateError(f"{source} declares no done check")
    section = strict_json(raw)["done"]
    policy_path = policy_file or os.path.join(root, *done["policy"].split("/"))
    policy = _read_regular(policy_path, MAX_DECLARATION_BYTES + 1, follow=True)
    if len(policy) > MAX_DECLARATION_BYTES:
        raise GateError(f"{policy_path} holds more than {MAX_DECLARATION_BYTES} bytes")
    require_pinned_signer(policy, f"the done policy {policy_path}")
    head = _git(root, "rev-parse", "--verify", "-q", "HEAD^{commit}", deadline=deadline)
    base = head.stdout.decode("ascii", "replace").strip()
    if head.returncode != 0 or not _FULL_COMMIT.fullmatch(base):
        raise GateError("the repository has no commit at HEAD, the base the order's paths are compared with")
    key = _order_key(root, gitdir)
    data = (json.dumps({"schema": DONE_ORDER_SCHEMA, "repo": root, "gitdir": gitdir, "base": base, "created": _now(),
                        "done": section, "policy": base64.b64encode(policy).decode("ascii")},
                       indent=1, sort_keys=True) + "\n").encode("utf-8", "surrogatepass")
    if len(data) > MAX_ORDER_BYTES:
        raise GateError(f"the order would hold more than {MAX_ORDER_BYTES} bytes")
    _parse_local_order(data)   # the gate reads back what it writes
    os.makedirs(folder, mode=0o700, exist_ok=True)
    order_path = os.path.join(folder, f"{key}.json")
    seen, _why = _order_seen(folder, key)
    try:
        previous = hashlib.sha256(_read_regular(order_path, MAX_ORDER_BYTES + 1)).hexdigest()
    except FileNotFoundError:
        previous = None
    except OSError:
        previous = "unreadable"
    if (previous is not None or os.path.lexists(os.path.join(folder, f"{key}.seen.json"))) and not replace:
        raise GateError(f"a local done order for {root} exists ({order_path}); --replace writes a new one, and the "
                        "gate keeps the digest it replaces")
    replaced = list(seen["replaced"]) if seen is not None else []
    if previous is not None or seen is not None:
        replaced.append({"sha256": previous or "absent", "recorded": seen["sha256"] if seen else "none", "at": _now()})
    added = _ignore_receipts(root, done, deadline)
    _write_order_file(folder, f"{key}.json", data)
    _write_order_file(folder, f"{key}.seen.json", (json.dumps(
        {"schema": DONE_ORDER_SEEN_SCHEMA, "sha256": hashlib.sha256(data).hexdigest(), "written": _now(),
         "replaced": replaced}, indent=1, sort_keys=True) + "\n").encode("utf-8"))
    names = ", ".join(check["id"] for check in done["checks"])
    lines = [f"wrote the local done order {order_path} for {root} (checks {names}; sha256 "
             f"{hashlib.sha256(data).hexdigest()}; base {base[:12]})"]
    if replaced:
        lines.append(f"it replaces an earlier order; the gate records {len(replaced)} replacement(s)")
    if added:
        lines.append(f"added to the repository's info/exclude: {' '.join(added)}")
    lines.append(HOOK_ORDERS_NOTE)
    return "\n".join(lines)


def done_order_remove(repo_dir: str | None, key: str | None, deadline: float, environ: dict | None = None) -> str:
    """Remove the local done order of a repository, and the gate's record of it (D38). By repository: every order that
    names its root, whether or not the repository is still there. By key: the order and record of that key."""
    environ = os.environ if environ is None else environ
    folder = _orders_dir(environ)
    if folder is None:
        raise GateError("no gate directory is known (an absolute PROOFBUNDLE_GATE_DIR, XDG_CONFIG_HOME or HOME)")
    keys = set()
    if key is not None:
        if not _HEX64.fullmatch(key):
            raise GateError("--key must be the 64 hexadecimal digits of an order's name")
        keys.add(key)
    else:
        root = os.path.realpath(repo_dir)
        paths, _why = _repo_paths(repo_dir, deadline) if os.path.isdir(repo_dir) else (None, "")
        if paths is not None and paths["toplevel"] is not None and paths["gitdir"] is not None:
            root = os.path.realpath(paths["toplevel"])
            keys.add(_order_key(root, paths["gitdir"]))
        try:
            names = os.listdir(folder)
        except FileNotFoundError:
            names = []
        for name in names:
            match = _ORDER_FILE.fullmatch(name)
            if not match:
                continue
            try:
                doc = strict_json(_read_regular(os.path.join(folder, name), MAX_ORDER_BYTES + 1))
            except (OSError, ValueError, UnicodeDecodeError):
                continue
            if isinstance(doc, dict) and doc.get("repo") == root:
                keys.add(match.group(1))
    removed = []
    for k in sorted(keys):
        for name in (f"{k}.json", f"{k}.seen.json", f"{k}.state.json", f"{k}.blocker.json"):
            try:
                os.unlink(os.path.join(folder, name))
                removed.append(name)
            except FileNotFoundError:
                pass
    if not removed:
        raise GateError("no local done order matches")
    return f"removed from {folder}: {', '.join(removed)}"


def done_order_list(deadline: float, environ: dict | None = None) -> str:
    """Every local done order and what the gate finds for it now (D38), for a person whatever the environment sets;
    a last line says where the hooks read the orders (D128)."""
    environ = os.environ if environ is None else environ
    rows = []
    for entry in _local_orders(environ, deadline):
        if "order" in entry:
            order = entry["order"]
            rows.append(f"{entry['key']}\t{order['repo']}\tchecks {', '.join(c['id'] for c in order['done']['checks'])}"
                        f"\tbase {order['base'][:12]}\tcreated {order['created']}\treplaced {order['replaced']}\tok")
        else:
            refusal = entry["refusal"]["verdict"]
            rows.append(f"{entry['key']}\t{entry['file']}\t{refusal.reason_id}: {refusal.failed}")
    return "\n".join([*rows, HOOK_ORDERS_NOTE]) if rows else "no local done order"


def done_order_command(argv: list[str]) -> int:
    options = {"--repo": None, "--declaration": None, "--policy": None, "--key": None}
    flags, i = {"--replace": False, "--remove": False, "--list": False}, 0
    while i < len(argv):
        if argv[i] in flags and not flags[argv[i]]:
            flags[argv[i]], i = True, i + 1
        elif argv[i] in options and i + 1 < len(argv) and options[argv[i]] is None:
            options[argv[i]], i = argv[i + 1], i + 2
        else:
            print(f"{DONE_ORDER_USAGE}; unexpected {argv[i]!r}", file=sys.stderr)
            return 2
    deadline = time.monotonic() + DEADLINE_SECONDS
    making = options["--declaration"] or options["--policy"] or flags["--replace"]
    if flags["--list"] and not (flags["--remove"] or making or options["--repo"] or options["--key"]):
        action = lambda: done_order_list(deadline)   # noqa: E731
    elif flags["--remove"] and not making and (options["--repo"] is None) != (options["--key"] is None):
        action = lambda: done_order_remove(options["--repo"], options["--key"], deadline)   # noqa: E731
    elif options["--repo"] and not (flags["--remove"] or flags["--list"] or options["--key"]):
        action = lambda: done_order(options["--repo"], options["--declaration"], options["--policy"],   # noqa: E731
                                    flags["--replace"], deadline)
    else:
        print(DONE_ORDER_USAGE, file=sys.stderr)
        return 2
    try:
        print(action())
    except (GateError, OSError, ValueError) as exc:
        print(f"proofbundle done-order: {exc}", file=sys.stderr)
        return 1
    return 0


#: The file name of this gate, by which a shell command names it: directly as a program or as the script of an
#: interpreter (D38).
GATE_SCRIPT = "proofbundle_gate.py"
#: The done-order switches that only add a duty: a new order (--repo, with its sources) or the list (owner choice O2 of
#: follow-up note 13). Every other form replaces or removes an order, or is one the gate cannot read whole.
_DONE_ORDER_NEW = ("--repo", "--declaration", "--policy")
#: Programs that run a command with words they build from their input: xargs and GNU parallel append the words they read,
#: or put them where a replacement string stands (`-I %`), so the gate cannot read the switches done-order gets (owner
#: choice F1 of follow-up note 17). find's -exec and -execdir are not among them: the words after them are fixed, and `{}` and
#: the closing `;` are words the gate already answers as a change (measured at d6e248a8).
_ARGUMENT_BUILDERS = frozenset({"xargs", "parallel"})


def _unreadable_word(word: tuple) -> bool:
    """Whether the shell may build or rewrite the word before the program sees it: a substitution, an expansion, a glob
    or another character _shell_rewrites names."""
    value, has_subst, raw = word
    return bool(has_subst) or _expansion_present(raw) or _shell_rewrites(raw)


def _done_order_kind(args: list[tuple]) -> str:
    """"free" for `done-order --list` and for a new order (--repo with at most --declaration and --policy, each once,
    every word literal), "change" for every other form: --replace, --remove, an unknown switch, a word the shell builds
    or rewrites (owner choice O2 of follow-up note 13: what the gate cannot read is answered as a replacement)."""
    if any(_unreadable_word(a) for a in args):
        return "change"
    values = [a[0] for a in args]
    if values == ["--list"]:
        return "free"
    seen, i = set(), 0
    while i < len(values):
        if values[i] in _DONE_ORDER_NEW and values[i] not in seen and i + 1 < len(values):
            seen.add(values[i])
            i += 2
            continue
        return "change"
    return "free" if "--repo" in seen else "change"


def _done_order_run(run: list[tuple], depth: int) -> list[str]:
    """The done-order calls of one run of words (D38, O2): the gate's script named by its file name, directly or as the
    script of an interpreter or wrapper, followed by `done-order`; a script word the shell builds, followed by
    `done-order`; and a subcommand word the shell builds after the script, which may be done-order. A shell's `-c`
    string and the string of eval, source and `.` are read in turn, as gated_calls reads them. Behind xargs or parallel
    (_ARGUMENT_BUILDERS) the script with done-order or with no subcommand word, and done-order itself, are a change in
    every form: the program appends words from its input or puts them in place (F1 of follow-up note 17)."""
    found = []
    built = False
    for k, word in enumerate(run):
        base = os.path.basename(word[0])
        rest = [w[0] for w in run[k + 1:]]
        built = built or base in _ARGUMENT_BUILDERS
        if base in _SHELL_DASH_C and depth < MAX_NESTING:
            command = _shell_c_arg(rest)
            if command is not None:
                found.extend(_done_order_calls(command, depth + 1))
        elif base in _STRING_EXECUTORS and depth < MAX_NESTING:
            found.extend(kind for arg in rest if not arg.startswith("-") for kind in _done_order_calls(arg, depth + 1))
        if base == GATE_SCRIPT and built and (k + 1 >= len(run) or run[k + 1][0] == "done-order"):
            found.append("change")   # xargs or parallel give it words the gate does not see (F1)
        elif base == GATE_SCRIPT and k + 1 < len(run):
            subcommand = run[k + 1]
            if _unreadable_word(subcommand):
                found.append("change")
            elif subcommand[0] == "done-order":
                found.append(_done_order_kind(run[k + 2:]))
        elif word[0] == "done-order" and (built or any(_unreadable_word(w) for w in run[:k])):
            found.append("change")   # the program before it may be the gate, built by the shell or from the input
    return found


def _done_order_calls(command: str, depth: int = 0) -> list[str]:
    """Each call of the gate's done-order in a shell command, as "free" or "change" (D38, owner choice O2 of follow-up note
    13), in every form gated_calls reads a program in: the whole command, each run of a chain, a pipeline or a list, the
    words of a redirection, each command substitution, and a shell's `-c` string or the string of eval, source and `.`.
    A command the gate cannot parse that names done-order counts as a change."""
    text = _drop_comments(command)
    toks = _lex(text)
    if toks is None or depth > MAX_NESTING:
        return ["change"] if "done-order" in text or GATE_SCRIPT in text else []
    found, run = [], []
    for t in [*toks, ("op", ";")]:
        if t[0] == "word":
            run.append(t[1:])
        elif t[0] == "redir":
            if t[2] is not None:
                run.append(t[2])
        else:
            if run:
                found.extend(_done_order_run(run, depth))
            run = []
    if depth < MAX_NESTING:
        for body in _subst_bodies(text):
            found.extend(_done_order_calls(body, depth + 1))
    return found


#: The forms of a command that only reads (D66), a closed set: find without an action that deletes, runs a
#: program or writes a file; xargs that runs grep; grep; read and echo; the shell words of a while loop around them;
#: a pipe or a list between them; an output redirection only to /dev/null or onto another descriptor. Every program
#: word is a literal bare name. Nothing else reads as such a command, whatever it does. Under Claude Code, addendum 1
#: to follow-up note 31 (D77) adds the read programs of _READ_PROGRAMS and the shell's test command `[`, xargs that runs
#: head, ls or wc, the words of an if around them, and `&&` and `||` between them: whichever run the shell starts, each
#: only reads.
_READ_ONLY_FIND_ACTIONS = frozenset({"-delete", "-exec", "-execdir", "-ok", "-okdir", "-fprint", "-fprint0", "-fprintf",
                                     "-fls"})
_READ_ONLY_XARGS_SWITCHES = frozenset({"-0", "--null", "-r", "--no-run-if-empty"})
_READ_ONLY_KEYWORDS = frozenset({"while", "do", "done"})
_READ_D77_KEYWORDS = frozenset({"if", "then", "elif", "else", "fi"})
_READ_D77_LISTS = frozenset({"&&", "||"})
_READ_ONLY_SINKS = frozenset({">", "1>", "2>", ">>", "1>>", "2>>", "&>", "&>>"})
_READ_ONLY_DUPLICATES = frozenset({">&", "1>&", "2>&"})


#: The closed grammar of a read program (D77): the short switches without a value, with one (attached or the next word)
#: and with an optional one (attached only); the long switches without a value, with one (`--name=value` or the next
#: word) and with an optional one (`--name=value` only); and whether an obsolete `-NUM` counts.
_ReadProgramGrammar = collections.namedtuple("_ReadProgramGrammar", ("flags", "values", "optional", "long_flags",
                                                                     "long_values", "long_optional", "number"),
                                             defaults=(frozenset(), frozenset(), frozenset(), frozenset(), frozenset(),
                                                       False))


#: The read programs of owner choice O26-1 (D77) with their closed grammars, GNU coreutils
#: 9.4 as measured under strace -f in bash -c (truth_readprog_e1.py of the delivery, 336 runs under four sources): each
#: started only itself, opened no file for writing but /dev/null, made no socket but a lookup of a user name over the
#: local socket of nscd (ls -l), wrote no file and started no git or gh first on PATH. Left out on purpose: tail -f, -F,
#: --follow, --retry, --pid, -s and an obsolete `+N` or `-Nf` (each follows a file and never ends); date -s, --set, -f,
#: --file and an operand that is no format (a time to set); every option of ls, head and wc not named. sort came with
#: owner choice O31E1-1 A (D83), with the options measured there (-b -c -f -n -r -s -u -V -z, -k and -t) and
#: one named exception: from a pipe of 0.8 MB on it writes temporary files of its own in TMPDIR, opened with O_EXCL and
#: mode 0600 and removed by sort itself (truth_sort_temp_e1.sh); -o, -T, -S, -m, every long option and every option not
#: measured stay out. cd stays with D33.
_READ_TAIL = _ReadProgramGrammar(frozenset("qvz"), frozenset("nc"),
                                 long_flags=frozenset({"--quiet", "--silent", "--verbose", "--zero-terminated"}),
                                 long_values=frozenset({"--lines", "--bytes"}), number=True)
_READ_PROGRAMS = {
    "head": _READ_TAIL,
    "tail": _READ_TAIL,
    "wc": _ReadProgramGrammar(frozenset("cmlwL"), long_flags=frozenset({"--bytes", "--chars", "--lines", "--words",
                                                                        "--max-line-length"})),
    "ls": _ReadProgramGrammar(frozenset("aAbBcCdfFgGhHiklLmnNopqQrRsStuUvxX1"), frozenset("wTI"),
                              long_flags=frozenset({"--all", "--almost-all", "--escape", "--ignore-backups",
                                                    "--directory", "--file-type", "--full-time",
                                                    "--group-directories-first", "--no-group", "--human-readable",
                                                    "--si", "--dereference-command-line", "--dereference", "--inode",
                                                    "--kibibytes", "--literal", "--numeric-uid-gid",
                                                    "--hide-control-chars", "--show-control-chars", "--quote-name",
                                                    "--reverse", "--recursive", "--size", "--author"}),
                              long_values=frozenset({"--width", "--tabsize", "--ignore", "--hide", "--sort", "--time",
                                                     "--time-style", "--format", "--indicator-style",
                                                     "--quoting-style", "--block-size"}),
                              long_optional=frozenset({"--color", "--classify"})),
    "date": _ReadProgramGrammar(frozenset("uR"), frozenset("dr"), frozenset("I"),
                                long_flags=frozenset({"--utc", "--universal", "--rfc-email"}),
                                long_values=frozenset({"--date", "--reference", "--rfc-3339"}),
                                long_optional=frozenset({"--iso-8601"})),
    "sleep": _ReadProgramGrammar(frozenset()),
    "sort": _ReadProgramGrammar(frozenset("bcfnrsuVz"), frozenset("kt")),
}
#: The read programs xargs may start (D77): those none of whose options writes, follows a file or sets a time, as the
#: words xargs reads from its input become their arguments too.
_READ_XARGS_PROGRAMS = frozenset({"head", "ls", "wc"})
#: The versions of GNU coreutils whose read programs D77 measured. A read program of another version, or one that is
#: not GNU coreutils, leaves the command as it was before D77 (NOT MEASURED).
_READ_PROGRAM_VERSIONS = frozenset({"9.4"})
_READ_SLEEP_DURATION = re.compile(r"(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)[smhd]?")


def _read_program_args(name: str, args: list[tuple]) -> bool:
    """Whether the words after the read program name are on its closed grammar (_READ_PROGRAMS, D77): every word
    literal (a word the shell builds or rewrites may be any option), every switch named, a value after a switch that
    takes one; after `--` only operands. An operand of sleep is a duration; date takes at most one, a format that starts
    with `+`; no operand of tail starts with `+` (an obsolete `+N` or `+Nf`); head, ls and wc take any file."""
    grammar = _READ_PROGRAMS[name]
    if any(_unreadable_word(a) for a in args):
        return False
    words, operands, i, options = [a[0] for a in args], [], 0, True
    while i < len(words):
        word = words[i]
        i += 1
        if not options or word == "-" or not word.startswith("-"):
            operands.append(word)
        elif word == "--":
            options = False
        elif word.startswith("--"):
            long, equals, _value = word.partition("=")
            if long in grammar.long_values:
                if not equals:
                    if i == len(words):
                        return False
                    i += 1
            elif long not in grammar.long_optional and (long not in grammar.long_flags or equals):
                return False
        elif not (grammar.number and re.fullmatch(r"-[0-9]+", word)):
            for k, letter in enumerate(word[1:], start=2):
                if letter in grammar.values:
                    if k == len(word):
                        if i == len(words):
                            return False
                        i += 1
                    break
                if letter in grammar.optional:
                    break
                if letter not in grammar.flags:
                    return False
    if name == "sleep":
        return bool(operands) and all(_READ_SLEEP_DURATION.fullmatch(w) for w in operands)
    if name == "date":
        return len(operands) <= 1 and all(w.startswith("+") for w in operands)
    return name != "tail" or not any(w.startswith("+") for w in operands)


def _read_only_run(run: list[tuple], used: set | None = None) -> bool:
    """Whether one run of words is one of the read forms of _read_only_form. With used None only the closed set of D66;
    with a set also those of D77, and a read program of D77 the run starts is added to it, for the check of its version
    (_read_programs_measured)."""
    keywords = _READ_ONLY_KEYWORDS if used is None else _READ_ONLY_KEYWORDS | _READ_D77_KEYWORDS
    words = list(run)
    while words and not _unreadable_word(words[0]) and words[0][0] in keywords:
        words = words[1:]
    if not words:
        return True
    program, args = words[0], words[1:]
    if program[2] == "[" and used is not None:
        # the shell's test command (D60, D77): a builtin of bash, whose every operator only tests; its last word `]`;
        # `-v` only before a plain name, as bash expands the index of a name as an expression (D82); a function of the
        # session may carry its name (B36-2)
        used.add(("[", "builtin"))
        return bool(args) and args[-1][2] == "]" and not _test_names_an_expression([a[0] for a in args[:-1]])
    if program[2] == "test" and used is not None:
        # the same builtin written as test (owner choice O31E1-5, D84; measured as `[`, truth_test_n34.py)
        used.add(("test", "builtin"))
        return not _test_names_an_expression([a[0] for a in args])
    if _unreadable_word(program):
        return False
    if used is not None and program[2] == "command" and args and not _unreadable_word(args[0]) and \
            args[0][0] in _READ_PROGRAMS and args[0][2] == args[0][0]:
        # B36-2: `command <name>` starts the program past an alias and a function of the session (measured)
        used.add((args[0][0], "command"))
        return _read_program_args(args[0][0], args[1:])
    if used is not None and program[2] == program[0] and os.path.isabs(program[0]) and \
            os.path.basename(program[0]) in _READ_PROGRAMS:
        # B36-2: a read program named by its absolute path, with the version check on that path
        used.add((os.path.basename(program[0]), program[0]))
        return _read_program_args(os.path.basename(program[0]), args)
    if program[0] == "read":
        return _read_names_plain(args)
    if program[0] == "find":
        return not any(_unreadable_word(a) or a[0] in _READ_ONLY_FIND_ACTIONS for a in args)
    if program[0] == "xargs":
        i = 0
        while i < len(args) and not _unreadable_word(args[i]) and args[i][0] in _READ_ONLY_XARGS_SWITCHES:
            i += 1
        if i == len(args) or _unreadable_word(args[i]):
            return False
        if args[i][0] in _READ_XARGS_PROGRAMS and used is not None:
            used.add((args[i][0], "exec"))   # xargs starts it by its path, past the session's shell (B36-2, measured)
            return _read_program_args(args[i][0], args[i + 1:])
        return args[i][0] == "grep"
    if program[0] in _READ_PROGRAMS and used is not None:
        used.add((program[0], "word"))
        return _read_program_args(program[0], args)
    return program[0] in ("grep", "read", "echo")


#: A name as bash reads it in an assignment: no index, no expression (D82).
_PLAIN_NAME = re.compile(r"[A-Za-z_][A-Za-z0-9_]*")
#: The options of the read builtin of bash 5.2 (`help read`), those with a value and those without (D82).
_READ_VALUE_OPTIONS = frozenset("adinNptu")
_READ_FLAG_OPTIONS = frozenset("ers")


def _test_names_an_expression(words: list[str]) -> bool:
    """Whether a test (`[` or `test`) gives `-v` a word that is no plain name: bash expands the index of `a[…]` as an
    expression, and a substitution in it runs, single quotes or not (C31-1, measured with bash 5.2.21; D82). `-R` and
    the arithmetic comparisons read an integer and run nothing (measured)."""
    return any(word == "-v" and (k + 1 == len(words) or not _PLAIN_NAME.fullmatch(words[k + 1]))
               for k, word in enumerate(words))


def _read_names_plain(args: list[tuple]) -> bool:
    """Whether every word the read builtin takes as a name is a plain name written as such (C31-2, D82): the operands
    after its options and the value of -a. bash assigns to `a[…]` and expands its index as an expression, and a
    substitution in it runs, single quotes or not (measured with bash 5.2.21); the other options read a number, a
    delimiter or a text and run nothing (measured). An option the builtin does not know, and a name the shell builds
    or rewrites, make the run no read form."""
    words, i = list(args), 0
    while i < len(words) and words[i][0].startswith("-") and words[i][0] != "-":
        if _unreadable_word(words[i]):
            return False
        word = words[i][0]
        i += 1
        if word == "--":
            break
        for k, letter in enumerate(word[1:], start=2):
            if letter in _READ_FLAG_OPTIONS:
                continue
            if letter not in _READ_VALUE_OPTIONS:
                return False
            value = word[k:] if k < len(word) else (words[i][0] if i < len(words) else None)
            if value is None:
                return False
            if k == len(word):
                if letter == "a" and (_unreadable_word(words[i]) or not _PLAIN_NAME.fullmatch(value)):
                    return False
                i += 1
            elif letter == "a" and not _PLAIN_NAME.fullmatch(value):
                return False
            break
    return all(not _unreadable_word(w) and _PLAIN_NAME.fullmatch(w[0]) for w in words[i:])


def _read_only_form(command: str, depth: int = 0, used: set | None = None) -> bool:
    """Whether every program of a shell command only reads (D66): each run is a read form of the closed set above, each
    output redirection goes to /dev/null or onto another descriptor, and each command substitution is such a command
    in turn. Such a command runs no done-order and writes no file; a command the gate cannot read whole is none. With
    used a set, the forms of D77 count too, and each read program of D77 the command starts is added to it
    (_read_only_command checks its version)."""
    lists = {"|", ";"} if used is None else {"|", ";"} | _READ_D77_LISTS
    text = _drop_comments(command)
    toks = _lex(text)
    if toks is None or depth > MAX_NESTING or "<(" in text or ">(" in text:
        return False
    run = []
    for t in [*toks, ("op", ";")]:
        if t[0] == "word":
            run.append(t[1:])
        elif t[0] == "redir":
            op, target = t[1], t[2]
            if target is None or _unreadable_word(target):
                return False
            if not ((op in _READ_ONLY_SINKS and target[0] == "/dev/null")
                    or (op in _READ_ONLY_DUPLICATES and target[0] in ("1", "2"))):
                return False
        elif t[0] == "op" and t[1] in lists:
            if not _read_only_run(run, used):
                return False
            run = []
        else:
            return False
    return all(_read_only_form(body, depth + 1, used) for body in _subst_bodies(text))


def _read_programs_measured(used: set, environ: dict, deadline: float) -> bool:
    """Whether each read program of D77 the command starts runs as the program the gate measured. B36-2:
    the word is not the program. A bare name, `[` and `test` count only where the session is measured
    (_session_definitions) and defines none of them as an alias, a function or a hashed path; `command <name>` only
    where a measured session neither defines `command` nor hashes the name; an absolute path only where a measured
    session does not define that path as a name; a program xargs starts by its path counts whatever the session holds
    (measured with bash 5.2.21, truth_alias_n36.sh). Then each program but the builtins is GNU coreutils of a measured
    version (_READ_PROGRAM_VERSIONS): every PATH entry an absolute path that does not depend on the process (as for gh,
    _gh_version_problem), where the program is found on PATH, and `<program> --version` names it. Measured with
    coreutils 9.4: `--version` starts nothing and writes nothing. This shows a version, not an origin (D27): a program
    that prints the line is not caught."""
    names = {name for name, form in used if form in ("word", "builtin")}
    names |= {form for _name, form in used if os.path.isabs(form)}
    names |= {"command"} | {name for name, form in used if form == "command"}
    defined = _session_definitions(names, environ)
    for name, form in used:
        if form in ("word", "builtin"):
            if defined is None or defined.get(name):
                return False
        elif form == "command":
            if defined is not None and (defined.get("command") or "hash" in defined.get(name, ())):
                return False
        elif form != "exec" and defined is not None and defined.get(form):
            return False
    searched = [(name, form) for name, form in sorted(used) if form in ("word", "command", "exec")]
    entries = environ.get("PATH", "").split(os.pathsep)
    if searched and any(not os.path.isabs(entry) or _process_dependent(entry) for entry in entries):
        return False
    for name, form in sorted(used):
        if form == "builtin":
            continue
        if os.path.isabs(form):
            program = form if not _process_dependent(form) and os.path.isfile(form) else None
        else:
            program = shutil.which(name, path=environ.get("PATH", ""))
        left = deadline - time.monotonic()
        if program is None:
            return False
        if left <= 0:
            raise GateError("the gate ran out of time")
        try:
            out = subprocess.run([program, "--version"], capture_output=True, stdin=subprocess.DEVNULL, cwd="/",
                                 env={"PATH": environ.get("PATH", ""), "LC_ALL": "C"}, timeout=min(left, 5.0),
                                 check=False)
        except (subprocess.TimeoutExpired, OSError):
            return False
        first = out.stdout.decode("utf-8", "replace").splitlines()[:1]
        m = re.fullmatch(rf"{re.escape(name)} \(GNU coreutils\) ([0-9.]+)", first[0]) if first else None
        if out.returncode != 0 or m is None or m.group(1) not in _READ_PROGRAM_VERSIONS:
            return False
    return True


#: B36-2: the snapshots of the session's shell that Claude Code keeps under its configuration folder and
#: sources before each Bash command (measured with Claude Code 2.1.302 in this container: shell-snapshots/
#: snapshot-bash-<time>-<id>.sh with aliases, functions written as `eval $'name () …'`, shell options and PATH), and how
#: much of them the gate reads.
SHELL_SNAPSHOTS = "shell-snapshots"
MAX_SNAPSHOTS = 64
MAX_SNAPSHOT_BYTES = 1024 * 1024
#: The shells whose start for a command the gate models: bash, sh and dash read no file of the person for `-c` but the
#: one BASH_ENV or ENV names; zsh also reads the zshenv files (zsh(1)); the global ones are read as snapshots are.
_SESSION_SHELLS = frozenset({"bash", "sh", "dash", "zsh"})
_ZSH_GLOBAL_ENV = ("/etc/zshenv", "/etc/zsh/zshenv")
_DEFINE_LEAD = r"(?:^|(?<=[\s;&|({'\"`$]))"
_DEFINE_END = r"(?=[\s;&|)]|$)"


def _definition_kinds(text: str, name: str) -> set:
    """The kinds of definition of `name` the shell text holds, read by pattern, never run: alias (alias, zsh's aliases
    and galiases), function (`name ()`, `function name`, zsh's functions and autoload), hash (`hash … name`, BASH_CMDS)
    and builtin (`enable … name`, zsh's builtins, zmodload). A pattern may find a name that the text only mentions,
    which counts as defined: the reading errs toward the answer of today."""
    n = re.escape(name)
    kinds = set()
    if re.search(rf"\balias\b[^\n]*?(?:\s|['\"]){n}=", text, re.M) or \
            re.search(rf"\b(?:g?aliases)\[['\"]?{n}['\"]?\]", text):
        kinds.add("alias")
    if re.search(rf"{_DEFINE_LEAD}(?:function\s+)?{n}\s*\(\s*\)", text, re.M) or \
            re.search(rf"\bfunction\s+{n}(?=[\s{{(]|$)", text, re.M) or \
            re.search(rf"\bfunctions\[['\"]?{n}['\"]?\]", text) or \
            re.search(rf"\bautoload\b[^\n;&|]*\s{n}{_DEFINE_END}", text, re.M):
        kinds.add("function")
    if re.search(rf"\bhash\b[^\n;&|]*\s{n}{_DEFINE_END}", text, re.M) or \
            re.search(rf"\bBASH_CMDS\[['\"]?{n}", text):
        kinds.add("hash")
    if re.search(rf"\benable\b[^\n;&|]*\s{n}{_DEFINE_END}", text, re.M) or \
            re.search(rf"\bbuiltins\[['\"]?{n}", text) or re.search(r"\bzmodload\b", text):
        kinds.add("builtin")
    return kinds


def _session_definitions(names: set, environ: dict) -> dict | None:
    """{name: kinds} of the names the session's shell defines (_definition_kinds), or None where the gate cannot
    measure the session (B36-2). Measured without running the shell: the snapshots Claude Code keeps
    (SHELL_SNAPSHOTS under CLAUDE_CONFIG_DIR, else ~/.claude), every file of that folder, read for the definition of a
    name and nothing else; under zsh also the global zshenv files; and the names of exported functions in the hook's
    environment (BASH_FUNC_<name>%%), whose values the gate does not read. Not measured: a shell other than bash, sh,
    dash and zsh; BASH_ENV or ENV set (a file the shell sources); a .zshenv of the person under zsh (the gate does not
    read a person's own shell files, which may hold a credential); a snapshot folder that is no directory, more than
    MAX_SNAPSHOTS files in it, one that is no regular file or is larger than MAX_SNAPSHOT_BYTES, and any error reading
    them. No snapshot folder under bash, sh or dash is measured as nothing defined: the shell reads no file then."""
    shell = os.path.basename(environ.get("SHELL") or "bash")
    if shell not in _SESSION_SHELLS or environ.get("BASH_ENV") or environ.get("ENV"):
        return None
    home = environ.get("HOME")
    config = environ.get("CLAUDE_CONFIG_DIR")
    if config and os.path.isabs(config):
        base = config
    elif home and os.path.isabs(home):
        base = os.path.join(home, ".claude")
    else:
        return None
    texts: list = []
    try:
        if shell == "zsh":
            own = environ.get("ZDOTDIR") or home
            if not own or not os.path.isabs(own) or os.path.lexists(os.path.join(own, ".zshenv")):
                return None
            for path in _ZSH_GLOBAL_ENV:
                if os.path.lexists(path):
                    texts.append(_read_regular(path, MAX_SNAPSHOT_BYTES + 1, follow=True))
        folder = os.path.join(base, SHELL_SNAPSHOTS)
        if os.path.lexists(folder):
            if os.path.islink(folder) or not os.path.isdir(folder):
                return None
            entries = sorted(os.listdir(folder))
            if len(entries) > MAX_SNAPSHOTS:
                return None
            texts += [_read_regular(os.path.join(folder, entry), MAX_SNAPSHOT_BYTES + 1) for entry in entries]
    except OSError:
        return None
    if any(len(text) > MAX_SNAPSHOT_BYTES for text in texts):
        return None
    decoded = [text.decode("utf-8", "surrogateescape") for text in texts]
    defined = {name: set().union(*[_definition_kinds(text, name) for text in decoded]) for name in names}
    for key in environ:
        if key.startswith("BASH_FUNC_") and (key.endswith("%%") or key.endswith("()")):
            exported = key[len("BASH_FUNC_"):-2]
            if exported in defined:
                defined[exported].add("function")
    return defined


def _read_only_command(command: str, host: str, environ: dict, deadline: float) -> bool:
    """Whether the command is wholly of the closed read forms: under Codex those of D66 (_read_only_form), under Claude
    Code also those of D77, where every read program of D77 it starts is of a measured version
    (_read_programs_measured). Under Codex every ask is a deny, so D77 would free a command Codex denies today."""
    if host == "codex":
        return _read_only_form(command)
    used: set = set()
    return _read_only_form(command, used=used) and (not used or _read_programs_measured(used, environ, deadline))


def _done_order_verdict(command: str, host: str = "codex", environ: dict | None = None,
                        deadline: float | None = None) -> Verdict | None:
    """The answer to a shell command that replaces or removes a local done order, or calls done-order in a form the gate
    cannot read whole (owner choice O2 of follow-up note 13): ask under Claude Code, deny under Codex. A new order and the
    list are free; None where the command makes no such call. A command whose every program only reads
    (_read_only_form, D66) calls no done-order, whatever words it names: the script's name as a pattern of grep or an
    argument of echo is read, not run; under Claude Code so is a command of the read programs of D77
    (_read_only_command)."""
    environ = os.environ if environ is None else environ
    deadline = time.monotonic() + DEADLINE_SECONDS if deadline is None else deadline
    if _read_only_command(command, host, environ, deadline) or \
            "change" not in _done_order_calls(_d117_view(command, host, environ)[0]):   # D117
        return None
    return Verdict("ask", "NOT MEASURED: the command replaces or removes a local done order, or calls done-order in a "
                          "form the gate cannot read whole. A done order is a duty a person set (D38); a new order and "
                          "the list are free, a replacement or a removal is a person's decision.",
                   "done_order_change", evidence="the local done orders in the gate directory",
                   failed="the command may replace or remove a local done order (done-order --replace or --remove, or "
                          "a form of done-order the gate cannot read whole)",
                   next_step="have a person run done-order --replace or --remove outside the agent")


def _with_done_order(outcome: Outcome | None, command: str, host: str = "codex", environ: dict | None = None,
                     deadline: float | None = None) -> Outcome | None:
    """The answer of decide() with a done-order change added (D38, O2): it asks beside any answer short of a deny, and is
    named beside a deny. Codex turns the ask into a deny (answer)."""
    verdict = _done_order_verdict(command, host, environ, deadline)
    if verdict is None:
        return outcome
    if outcome is None or outcome.decision not in ("deny", "ask"):
        return Outcome("ask", verdict.text(), ([] if outcome is None else list(outcome.verdicts)) + [verdict])
    return Outcome(outcome.decision, f"{outcome.text} {verdict.text()}", list(outcome.verdicts) + [verdict])


#: D114 (owner answer O46-1): the owner's script that writes pin-state.json in the gate directory,
#: beside the gate. Only a person pins or renews a clone, outside the agent, never a session.
PIN_SCRIPT = "pin_state_schleuse.py"


def _pin_script_verdict(command: str, host: str = "codex", environ: dict | None = None,
                        deadline: float | None = None) -> Verdict | None:
    """D114 (O46-1): a deny for a command that names the owner's pin script and is not a command that only
    reads (D66, D77): the script writes the gate directory where it takes the folder from the environment, a path the
    command does not name, so the write guard of D25 does not see it. The name is looked for in the text and in the
    net's normal form (quotes and ANSI-C quotes resolved), in any letter case. None otherwise. A name the shell builds
    from parts, or a script run under another name, is not seen (D8, the class of a write in another language)."""
    stem = PIN_SCRIPT[:-len(".py")]
    if stem not in command.lower() and stem not in _net_normal_form(command):
        return None
    environ = os.environ if environ is None else environ
    deadline = time.monotonic() + DEADLINE_SECONDS if deadline is None else deadline
    if _read_only_command(command, host, environ, deadline) or _pin_script_read(command):
        return None
    return Verdict("deny", f"proofbundle gate: the command runs or names the owner's pin script {PIN_SCRIPT}, which "
                           "writes pin-state.json in the gate directory; only a person pins or renews a clone, outside "
                           "the agent (O46-1; DECISIONS.md D114, D25).", "write_to_gate_dir",
                   evidence="the pin state in the gate directory",
                   failed="a session would pin its own clone through the owner's script",
                   next_step="the owner runs the script through the lock, outside the agent")


def _pin_script_read(command: str) -> bool:
    """D114: whether class c reads the command as data steps only (_SH_DATA with the limits of _sh_kind,
    and cd): such a command reads the pin script or names it, and runs no program that could run it. A command class c
    does not model is no such command."""
    try:
        steps: list = []
        _sh_walk(_sh_parse(command), None, steps)
    except (_ShUnmodeled, RecursionError):
        return False
    return bool(steps) and all(s.kind in ("data", "cd") for s in steps)


def _with_pin_script(outcome: Outcome | None, command: str, host: str = "codex", environ: dict | None = None,
                     deadline: float | None = None) -> Outcome | None:
    """The answer of decide() with the deny of the pin script (D114) before every other answer."""
    verdict = _pin_script_verdict(command, host, environ, deadline)
    if verdict is None:
        return outcome
    known = [] if outcome is None else list(outcome.verdicts)
    text = verdict.text() if outcome is None or not outcome.text else f"{verdict.text()} {outcome.text}"
    return Outcome("deny", text, [verdict] + known)


DONE_CHECK_USAGE = "usage: done-check --repo DIR [--receipt FILE | --receipt-dir DIR] [--at-commit REV]"


def done_check_command(argv: list[str]) -> int:
    """The done check in CI (D26, Teil 3): exit 0 only for a pass; every NOT MEASURED, every deny and a repository
    that declares no done check exit 1; a wrong call exits 2. `--at-commit REV` checks that commit as the commit under
    review: its declaration, policy and order, its tree in place of the working state, and only a clean run on it
    (review 2026-10-09 F1). The CI job names the commit it checked out, from the event, never HEAD, which the test
    command can move."""
    options, i = {"--repo": None, "--receipt": None, "--receipt-dir": None, "--at-commit": None}, 0
    while i < len(argv):
        if argv[i] in options and i + 1 < len(argv) and options[argv[i]] is None:
            options[argv[i]], i = argv[i + 1], i + 2
        else:
            print(f"{DONE_CHECK_USAGE}; unexpected {argv[i]!r}", file=sys.stderr)
            return 2
    if not options["--repo"] or options["--receipt"] == "" or options["--receipt-dir"] == "" or \
            options["--at-commit"] == "" or (options["--receipt"] is not None and options["--receipt-dir"] is not None):
        print(DONE_CHECK_USAGE, file=sys.stderr)
        return 2
    deadline = time.monotonic() + DEADLINE_SECONDS
    try:
        verdict = done_evaluation(options["--repo"], deadline, options["--receipt"],
                                  receipt_dir=options["--receipt-dir"], at_commit=options["--at-commit"],
                                  reviewed=options["--at-commit"] is not None)["verdict"]
    except GateError as exc:
        verdict = Verdict("deny", f"proofbundle gate: {exc}.", "gate_error", evidence="the done check",
                          failed=str(exc), next_step="fix the cause named here")
    code = 0 if verdict.decision == "pass" else 1
    report = {"exit_code": code, "verdict": verdict.decision, "reason_id": verdict.reason_id, "repo": verdict.repo,
              "head": verdict.head, "message": verdict.text(), "gate_version": GATE_VERSION}
    sys.stdout.write(json.dumps(report, indent=1) + "\n")
    print(("proofbundle done check passed: " if code == 0 else "proofbundle done check FAILED: ") + verdict.text(),
          file=sys.stderr)
    return code


# --- the done check as an in-toto Statement (D29) ------------------------------------------------------------------

INTOTO_STATEMENT_TYPE = "https://in-toto.io/Statement/v1"
INTOTO_PAYLOAD_TYPE = "application/vnd.in-toto+json"
VSA_PREDICATE_TYPE = "https://slsa.dev/verification_summary/v1"
#: The verifier of the Verification Summary, a URI that names the plugin's done check; a consumer accepts only the
#: (signer, verifier) pairs it trusts (SLSA VSA v1.2, verifier).
VSA_VERIFIER_ID = "https://github.com/b7n0de/proofbundle/tree/main/plugins/proofbundle#done-check"
PINNED_PROOFBUNDLE = "6.3.0"
_RESOURCE_URI = re.compile(r"[a-z][a-z0-9+.-]*:[!-~]+")
_SIGN_TOOL = """# /// script
# requires-python = ">=3.10"
# dependencies = ["proofbundle==6.3.0"]
# ///
import hashlib, json, sys
from proofbundle.dsse import sign_envelope
from proofbundle.emit import load_signer
signer = load_signer(sys.argv[1])
with open(sys.argv[2], "rb") as handle:
    body = handle.read()
keyid = hashlib.sha256(signer.public_key().public_bytes_raw()).hexdigest()
print(json.dumps(sign_envelope(body, signer, payload_type="application/vnd.in-toto+json", keyid=keyid)))
"""


def verification_summary(result: dict, resource_uri: str, time_verified: str) -> dict:
    """The in-toto Statement v1 with the SLSA Verification Summary v1 predicate for a passing done check on a clean
    state, built as draft-gruszka-evaluation-receipt-mappings Section 4.3 cites a receipt: the subject is HEAD by
    gitCommit and gitTree, each receipt the check verified is an inputAttestation named by SHA-256 over its signed
    payload bytes B, in the order of the declared checks, and verificationResult is the done check's result, not a
    receipt's own passed. An inputAttestation carries the digest alone: the VSA v1 binding of in-toto-attestation
    0.9.3 reads only uri and digest there and refuses any other field (measured 2026-10-08), and a receipt has no
    URI to fetch it from."""
    done, state = result["done"], result["state"]
    policy = result["policy"]
    blob = _BLOB_HASHES[len(result["commit"])](b"blob %d\0" % len(policy) + policy).hexdigest()
    inputs = [{"digest": {"sha256": hashlib.sha256(row["payload"]).hexdigest()}} for row in result["checks"]]
    return {
        "_type": INTOTO_STATEMENT_TYPE,
        "subject": [{"name": resource_uri, "digest": {"gitCommit": state["commit"], "gitTree": state["tree"]}}],
        "predicateType": VSA_PREDICATE_TYPE,
        "predicate": {
            "verifier": {"id": VSA_VERIFIER_ID, "version": {"proofbundle-plugin": GATE_VERSION,
                                                            "proofbundle": PINNED_PROOFBUNDLE}},
            "timeVerified": time_verified,
            "resourceUri": resource_uri,
            "policy": {"uri": f"{resource_uri}@{state['commit']}#{done['policy']}",
                       "digest": {"sha256": hashlib.sha256(policy).hexdigest(), "gitBlob": blob}},
            "inputAttestations": inputs,
            "verificationResult": "PASSED",
            "verifiedLevels": ["SLSA_SOURCE_LEVEL_UNEVALUATED"],
            "slsaVersion": "1.2",
        },
    }


def _resource_uri(value: str) -> str:
    if not _RESOURCE_URI.fullmatch(value) or len(value) > 2048:
        raise GateError("--resource-uri must be an absolute URI without spaces, for example "
                        "git+https://github.com/<owner>/<repo>")
    if "//" in value:
        authority = value.split("//", 1)[1].split("/", 1)[0]
        if "@" in authority:
            raise GateError("--resource-uri must not carry user information (a name or token before @)")
    return value


def done_statement(directory: str, key: str, out: str, resource_uri: str, deadline: float,
                   receipt_dir: str | None = None) -> str:
    """Write the done check's Verification Summary as a DSSE envelope (D29): only for a pass on a clean state, signed
    with the key file through the pinned package. Refuses an output that is a link or not a regular file."""
    resource_uri = _resource_uri(resource_uri)
    if not os.path.isabs(key):
        raise GateError("--key must be an absolute path to a key file outside the repository")
    result = done_evaluation(directory, deadline, receipt_dir=receipt_dir)
    verdict = result["verdict"]
    if verdict.decision != "pass":
        raise GateError(f"the done check does not pass, so there is no statement: {verdict.text()}")
    if result["state"]["worktree"] != result["state"]["tree"]:
        raise GateError("the working state differs from HEAD; the statement names a commit and its tree, so commit "
                        "the work and run the checks again")
    body = json.dumps(verification_summary(result, resource_uri, _now()), sort_keys=True,
                      separators=(",", ":")).encode("utf-8")
    try:
        st = os.lstat(out)
        if not stat.S_ISREG(st.st_mode):
            raise GateError(f"{out} exists and is not a regular file")
    except FileNotFoundError:
        pass
    uv = shutil.which("uv")
    if uv is None:
        raise GateError("uv is not on PATH, so the statement cannot be signed with the package")
    with tempfile.TemporaryDirectory(prefix="proofbundle-statement-") as scratch:
        tool, payload = os.path.join(scratch, "sign_tool.py"), os.path.join(scratch, "statement.json")
        with open(tool, "w", encoding="utf-8") as handle:
            handle.write(_SIGN_TOOL)
        with open(payload, "wb") as handle:
            handle.write(body)
        left = deadline - time.monotonic()
        proc = subprocess.run([uv, "run", "--quiet", "--no-config", "--script", tool, key, payload], cwd=scratch,
                              env=_isolated_env(), capture_output=True, text=True, timeout=max(left, 1), check=False)
    try:
        envelope = strict_json(proc.stdout) if proc.returncode == 0 else None
        ok = (isinstance(envelope, dict) and envelope.get("payloadType") == INTOTO_PAYLOAD_TYPE
              and base64.b64decode(envelope.get("payload", ""), validate=True) == body
              and isinstance(envelope.get("signatures"), list) and len(envelope["signatures"]) == 1)
    except (ValueError, binascii.Error, TypeError):
        ok = False
    if not ok:
        raise GateError(f"the package could not sign the statement with {key}: {proc.stderr.strip()[:300]}")
    with open(out, "w", encoding="utf-8") as handle:
        handle.write(json.dumps(envelope, indent=1) + "\n")
    return (f"proofbundle done statement written to {out}: an in-toto Statement v1 with the SLSA Verification Summary "
            f"v1 predicate, subject {resource_uri} at commit {result['commit'][:12]}, {len(result['checks'])} "
            "receipts cited by the SHA-256 of their signed payload, signed with the key in DSSE. It states what the "
            "done check verified, not that the tests test anything.")


DONE_STATEMENT_USAGE = ("usage: done-statement --repo DIR --key FILE --out FILE --resource-uri URI "
                        "[--receipt-dir DIR]")


def done_statement_command(argv: list[str]) -> int:
    options, i = {"--repo": None, "--key": None, "--out": None, "--resource-uri": None, "--receipt-dir": None}, 0
    while i < len(argv):
        if argv[i] in options and i + 1 < len(argv) and options[argv[i]] is None:
            options[argv[i]], i = argv[i + 1], i + 2
        else:
            print(f"{DONE_STATEMENT_USAGE}; unexpected {argv[i]!r}", file=sys.stderr)
            return 2
    if not all(options[k] for k in ("--repo", "--key", "--out", "--resource-uri")) or options["--receipt-dir"] == "":
        print(DONE_STATEMENT_USAGE, file=sys.stderr)
        return 2
    try:
        print(done_statement(options["--repo"], options["--key"], options["--out"], options["--resource-uri"],
                             time.monotonic() + DEADLINE_SECONDS, options["--receipt-dir"]))
    except (GateError, OSError) as exc:
        print(f"proofbundle done-statement: {exc}", file=sys.stderr)
        return 1
    return 0


_KEY_TOOL = """# /// script
# requires-python = ">=3.10"
# dependencies = ["proofbundle==6.3.0"]
# ///
import base64, os, sys
from proofbundle.emit import generate_signer, load_signer, save_signer
path = sys.argv[1]
if not os.path.exists(path):
    save_signer(generate_signer(), path)
print(base64.b64encode(load_signer(path).public_key().public_bytes_raw()).decode("ascii"))
"""
DONE_INIT_USAGE = "usage: done-init --repo DIR [--key FILE]"


def done_init(directory: str, key_path: str | None, deadline: float, environ: dict | None = None) -> str:
    """Set up the done check in a repository (D26): a test key with the package's own key path (a 32-byte seed
    file, PROOFBUNDLE_KEY), a policy that pins it, the done section of the declaration and an ignore rule for the
    receipt, all staged. Writes nothing it has not named; refuses a repository that already declares a done
    check. The key is a local test key, never a release key."""
    environ = os.environ if environ is None else environ
    repo, unreadable = _work_tree(directory, deadline, "--path-format=absolute")
    if repo is None:
        raise GateError(unreadable or f"{directory} is not a git repository")
    if key_path is None:
        gate_dir = _gate_dir(environ)
        if gate_dir is None:
            raise GateError("no gate directory is known; name the key file with --key")
        os.makedirs(gate_dir, mode=0o700, exist_ok=True)
        key_path = os.path.join(gate_dir, DONE_KEY_FILE)
    if not os.path.isabs(key_path):
        raise GateError("--key must be an absolute path outside the repository")
    declaration = os.path.join(repo, *DECLARATION.split("/"))
    if os.path.lexists(declaration):
        try:
            raw = _read_regular(declaration, MAX_DECLARATION_BYTES + 1, follow=True)   # R18-2 class
        except _NotRegular as exc:
            raise GateError(f"{DECLARATION} is not a regular file") from exc
        parse_declaration(raw)
        doc = strict_json(raw)
        if "done" in doc:
            raise GateError(f"{DECLARATION} already declares a done check; change it in a reviewed commit")
    else:
        doc = {"schema": DECLARATION_SCHEMA, "evidence": []}
    doc["done"] = {"receipt": DONE_RECEIPT, "policy": DONE_POLICY}
    uv = shutil.which("uv")
    if uv is None:
        raise GateError("uv is not on PATH, so the key cannot be made with the package")
    with tempfile.TemporaryDirectory(prefix="proofbundle-key-") as scratch:
        tool = os.path.join(scratch, "key_tool.py")
        with open(tool, "w", encoding="utf-8") as handle:
            handle.write(_KEY_TOOL)
        left = deadline - time.monotonic()
        proc = subprocess.run([uv, "run", "--quiet", "--no-config", "--script", tool, key_path], cwd=scratch,
                              env=_isolated_env(), capture_output=True, text=True, timeout=max(left, 1), check=False)
    public = proc.stdout.strip()
    try:
        ok = proc.returncode == 0 and len(base64.b64decode(public, validate=True)) == 32
    except (binascii.Error, ValueError):
        ok = False
    if not ok:
        raise GateError(f"the package could not make or read the key {key_path}: {proc.stderr.strip()[:300]}")
    policy = {"schema": "proofbundle/trust-policy/v0.1", "policy_id": "local/done-check",
              "allowed_issuers": [{"public_key_b64": public}], "signature": {"require_expected_signer": True}}
    policy_file = os.path.join(repo, *DONE_POLICY.split("/"))
    if os.path.lexists(policy_file):
        raise GateError(f"{DONE_POLICY} exists already; remove it or set the done check up by hand")
    # Read before anything is written, and never waited on (the class of R18-2: a FIFO as .gitignore had blocked
    # done-init after it had written the policy and the declaration).
    ignore = os.path.join(repo, ".proofbundle", ".gitignore")
    try:
        existing = (_read_regular(ignore, -1, follow=True).decode("utf-8").splitlines()
                    if os.path.lexists(ignore) else [])
    except _NotRegular as exc:
        raise GateError(".proofbundle/.gitignore is not a regular file") from exc
    os.makedirs(os.path.dirname(declaration), exist_ok=True)
    with open(policy_file, "w", encoding="utf-8") as handle:
        handle.write(json.dumps(policy, indent=2) + "\n")
    with open(declaration, "w", encoding="utf-8") as handle:
        handle.write(json.dumps(doc, indent=2) + "\n")
    missing =[name.split("/", 1)[1] for name in (DONE_RECEIPT, *DONE_OWN_FILES) if name.split("/", 1)[1] not in existing]
    missing += [] if "receipts/" in existing else ["receipts/"]
    if missing:
        with open(ignore, "a", encoding="utf-8") as handle:
            handle.write("".join(line + "\n" for line in missing))
    staged = _git(repo, "add", "--", DECLARATION, DONE_POLICY, ".proofbundle/.gitignore", deadline=deadline)
    if staged.returncode != 0:
        raise GateError("git could not stage the done check")
    # B30-2: the block of the Stop hook names this key file, wherever --key put it; D128: the record is written whatever
    # this command's environment sets, and a hook reads it only with the protected channel
    unrecorded = _record_key_path(environ, repo, key_path)
    recorded = "" if unrecorded is None else (f" The gate directory does not record the key file ({unrecorded}), so a "
                                              "block names the default key file; set PROOFBUNDLE_KEY to this one.")
    if unrecorded is None and key_path != os.path.join(_gate_dir(environ) or "", DONE_KEY_FILE):
        recorded = (" The block of the Stop hook names this key file only where the hook's environment sets "
                    f"{OWNER_STATE_VARIABLE}={OWNER_STATE_PROTECTED} (D128); elsewhere it names the default key file, "
                    "so set PROOFBUNDLE_KEY to this one there.")
    return (f"proofbundle done check set up in {repo}: test key {key_path} (a local test key, never a release key), "
            f"{DONE_POLICY} pins it, {DECLARATION} declares the done check, .proofbundle/.gitignore keeps the receipt "
            f"and the done check's own files out of the tree. Staged. Next: git commit -m \"declare the done check\"; then the tests run with a "
            f"receipt: {check_command(_done_section(doc['done'])['checks'][0], dict(environ, PROOFBUNDLE_KEY=key_path))}"
            f"{recorded}")


def done_init_command(argv: list[str]) -> int:
    options, i = {"--repo": None, "--key": None}, 0
    while i < len(argv):
        if argv[i] in options and i + 1 < len(argv) and options[argv[i]] is None:
            options[argv[i]], i = argv[i + 1], i + 2
        else:
            print(f"{DONE_INIT_USAGE}; unexpected {argv[i]!r}", file=sys.stderr)
            return 2
    if not options["--repo"]:
        print(DONE_INIT_USAGE, file=sys.stderr)
        return 2
    try:
        print(done_init(options["--repo"], options["--key"], time.monotonic() + DEADLINE_SECONDS))
    except (GateError, OSError) as exc:
        print(f"proofbundle done-init: {exc}", file=sys.stderr)
        return 1
    return 0


CI_USAGE = "usage: ci-check --repo DIR --require-declaration true|false"


def ci_check(repo: str, require_declaration: bool, deadline: float | None = None) -> tuple[int, dict]:
    """The CI mode (DECISIONS.md, D22): the gate's own evaluation of HEAD, stricter than at a push.

    Exit 0 only when every declared item verified and is bound to the tree of the commit, or when nothing
    is declared and the workflow says the repository need not declare (`not_required`, which is a waiver,
    not a verified result). CI fails every required check that is NOT MEASURED; with require-declaration
    false and no declaration it returns not_required, not verified. Every deny and a missing declaration
    where one is required exit 1. Whether a declaration is required comes from the workflow, not from the
    declaration, so deleting the declaration cannot switch the check off. The push range of D20 is not read:
    in CI the reviewed state of the evidence rules is CODEOWNERS' part.
    """
    deadline = time.monotonic() + DEADLINE_SECONDS if deadline is None else deadline
    try:
        verdict = evaluate_repository(repo, deadline, check_range=False)
    except GateError as exc:
        verdict = Verdict("deny", f"proofbundle gate: {exc}. The check fails because the gate reached no verdict.",
                          "gate_error", evidence=f"the declaration {DECLARATION} and the evidence it names",
                          failed=str(exc), next_step="fix the cause named here", repo=repo)
    if verdict.decision == "pass":
        code, outcome = 0, "verified"
    elif verdict.decision == "inactive" and not require_declaration:
        code, outcome = 0, "not_required"
    elif verdict.decision == "inactive":
        code, outcome = 1, "declaration_required"
        found = ("declares only a done check, no evidence," if verdict.reason_id == "done_only" else "is absent")
        verdict = Verdict("deny", f"proofbundle gate: the workflow requires a declaration, and {DECLARATION} {found} "
                                  f"at HEAD {verdict.head[:12]}.", "declaration_required", evidence=f"the declaration {DECLARATION}",
                          failed="the repository must declare evidence, and it declares none",
                          next_step="restore the declaration and its evidence, or change the workflow input in a "
                                    "reviewed change", repo=verdict.repo, head=verdict.head)
    else:
        code, outcome = 1, "not_measured" if verdict.detail.startswith("NOT MEASURED") else "failed"
    report = {"outcome": outcome, "exit_code": code, "require_declaration": require_declaration,
              "repo": verdict.repo, "head": verdict.head, "verdict": verdict.decision, "reason_id": verdict.reason_id,
              "digests": list(verdict.digests), "message": verdict.text(), "gate_version": GATE_VERSION}
    return code, report


def ci_check_command(argv: list[str]) -> int:
    options, i = {"--repo": None, "--require-declaration": None}, 0
    while i < len(argv):
        if argv[i] in options and i + 1 < len(argv):
            options[argv[i]], i = argv[i + 1], i + 2
        else:
            print(f"{CI_USAGE}; unknown {argv[i]!r}", file=sys.stderr)
            return 2
    if None in options.values() or options["--require-declaration"] not in ("true", "false"):
        print(CI_USAGE, file=sys.stderr)
        return 2
    code, report = ci_check(options["--repo"], options["--require-declaration"] == "true")
    sys.stdout.write(json.dumps(report, indent=1) + "\n")
    print(("proofbundle evidence check passed: " if code == 0 else "proofbundle evidence check FAILED: ")
          + report["message"], file=sys.stderr)
    return code


# --- a test run as evidence (DECISIONS.md, D23) ------------------------------------------------------

RUN_SCHEMA = "proofbundle-plugin/test-run/v1"
RUN_KEYS = frozenset({"schema", "commit", "tree_before", "tree_after", "command", "program", "exit_code", "counts",
                      "report_sha256", "started_at", "finished_at", "platform", "gate_version"})
COUNT_KEYS = frozenset({"tests", "passed", "failed", "errors", "skipped"})
RUN_TIMEOUT_SECONDS = 600.0
MAX_REPORT_BYTES = 16 * 1024 * 1024
RUN_USAGE = "usage: run-evidence --repo DIR --out FILE [--timeout SECONDS] [--junit-out FILE] -- COMMAND..."


def _count(value) -> bool:
    return type(value) is int and value >= 0


def run_record_problem(run, digest) -> str | None:
    """What a run record shows that is not a green run on the tree digest, or None for a green one.

    Green: the record has the keys of RUN_SCHEMA, ran on the digest before and after, exited 0, and its
    counts add up with no failure, no error and at least one passed test. The gate asks this of every
    signed run record, whoever made it, so a signed record of a red run never binds.
    """
    if not isinstance(run, dict) or set(run) != RUN_KEYS or run["schema"] != RUN_SCHEMA:
        return f"the signed run record is not a {RUN_SCHEMA} record"
    if not isinstance(digest, str) or run["tree_before"] != digest or run["tree_after"] != digest:
        return "the signed run record ran on another tree than its subject names"
    if type(run["exit_code"]) is not int or run["exit_code"] != 0:
        return f"the signed run record shows exit code {run['exit_code']!r}"
    counts = run["counts"]
    if not isinstance(counts, dict) or set(counts) != COUNT_KEYS or not all(_count(v) for v in counts.values()):
        return "the signed run record has no readable counts"
    if (counts["failed"] or counts["errors"] or counts["passed"] < 1
            or counts["tests"] != counts["passed"] + counts["failed"] + counts["errors"] + counts["skipped"]):
        return (f"the signed run record shows {counts['passed']} passed, {counts['failed']} failed and "
                f"{counts['errors']} errors of {counts['tests']} tests")
    command = run["command"]
    if not isinstance(command, list) or not command or not all(isinstance(part, str) for part in command):
        return "the signed run record names no command"
    return None


def signed_run_problem(kind: str, content: bytes) -> str | None:
    """For a bundle whose signed payload carries a run record: what the record shows that is not a green
    run on the tree its subject names. None for every other evidence."""
    if kind != "bundle":
        return None
    try:
        document = strict_json(content)
        statement = strict_json(base64.b64decode(document["payload_b64"], validate=True))
    except AmbiguousJSON as exc:
        return f"the evidence {exc}, so its run record is ambiguous"
    except (KeyError, TypeError, ValueError, UnicodeDecodeError, binascii.Error):
        return None
    if not isinstance(statement, dict) or "run" not in statement:
        return None
    subject = statement.get("subject")
    return run_record_problem(statement["run"], subject.get("digest") if isinstance(subject, dict) else None)


def signed_run_counts(kind: str, content: bytes):
    """The counts of a bundle's signed run record, or None when its payload carries none. Meaningful only
    once the item has verified and run_record_problem returned None, so the counts describe a green run."""
    if kind != "bundle":
        return None
    try:
        document = strict_json(content)
        statement = strict_json(base64.b64decode(document["payload_b64"], validate=True))
    except (KeyError, TypeError, ValueError, UnicodeDecodeError, binascii.Error):   # AmbiguousJSON included
        return None
    if not isinstance(statement, dict) or not isinstance(statement.get("run"), dict):
        return None
    counts = statement["run"].get("counts")
    return counts if isinstance(counts, dict) and {"passed", "tests"} <= set(counts) else None


#: git's object id of a blob: the hash of `blob <size>` NUL and the bytes; SHA-1 for 40 hexadecimal digits, SHA-256
#: for 64 (the repository's object format, gitrepository-layout(5) extensions.objectFormat).
_BLOB_HASHES = {40: hashlib.sha1, 64: hashlib.sha256}


def _directory_problem(root: bytes, prefix: bytes) -> str | None:
    """None when root/prefix is a real directory (lstat, so a symbolic link is not followed), else why not."""
    shown = prefix.decode(errors="replace")
    try:
        st = os.lstat(os.path.join(root, prefix))
    except OSError:
        return f"{shown}, which is absent or cannot be read in the working tree"
    if stat.S_ISLNK(st.st_mode):
        return f"{shown}, which is a symbolic link in the working tree and a directory in the commit"
    if not stat.S_ISDIR(st.st_mode):
        return f"{shown}, which is not a directory in the working tree"
    return None


def _working_tree_problem(repo: str, commit: str, deadline: float) -> str | None:
    """None when the working tree holds exactly the files of the commit's tree, outside the top-level
    .proofbundle/ folder the tree digest leaves out, else the first difference (review round 8, R8-1).

    The comparison is of the bytes a test run reads and of the path types it sees, not of what `git add`
    would stage: every committed file must be a regular file (mode 100644, or 100755 with the owner's execute
    bit) or a symbolic link (120000) whose own bytes, or link text, hash to the committed blob id, and no
    other file that git does not ignore may exist. No configured clean or smudge filter, line-ending or
    encoding rule, fsmonitor or hook runs, because none is asked, and no checkout transformation is modelled:
    a working file whose bytes differ from its committed blob is refused before the run, including differences
    caused by checkout transformations, never staged into agreement with HEAD (review round 9, R9-7). The one git call
    that lists the other files reads the ignore rules only, with an index that does not exist (so nothing
    is refreshed or written), core.fsmonitor off and an empty hook directory. Measured by the reviewer: a
    clean filter that wrote the committed value back while staging let a run on another working file be
    recorded as a run on HEAD.

    Every intermediate component of a committed path must be a real directory in the working tree, checked
    with lstat before and after the run whatever the ignore rules say; a symbolic link, any other type, a
    component that cannot be read and an empty, `.` or `..` component are refused (review round 9, R9-1:
    a working directory replaced by a link to an outside directory with the same leaf bytes, ignored by a
    committed `.gitignore`, gave a green run for a tree on which the same test fails)."""
    # A second lock: run_evidence's tree_digest refuses first, and the ls-tree below goes through _git (R8-3).
    _refuse_partial_clone(repo, deadline)
    listing = _git(repo, "ls-tree", "-r", "-z", "--full-tree", commit, deadline=deadline)
    if listing.returncode != 0:
        raise GateError(f"git could not list the tree of {commit[:12]}")
    committed = {}
    for record in listing.stdout.split(b"\0"):
        if not record:
            continue
        meta, tab, path = record.partition(b"\t")
        fields = meta.split(b" ")
        if not tab or len(fields) != 3:
            raise GateError("git ls-tree gave a line the gate cannot read")
        mode, kind, oid = fields
        if path.startswith(EVIDENCE_DIR.encode()):
            continue
        if kind != b"blob" or mode not in TREE_MODES or len(oid) not in _BLOB_HASHES:
            raise GateError(f"the tree holds a {kind.decode(errors='replace')} at {path.decode(errors='replace')} "
                            "that the gate cannot compare with the working tree")
        committed[path] = (mode, oid.decode("ascii"))
    root = os.fsencode(repo)
    directories: dict[bytes, str | None] = {}
    for path, (mode, oid) in sorted(committed.items()):
        shown = path.decode(errors="replace")
        parts = path.split(b"/")
        if any(part in (b"", b".", b"..") for part in parts):
            return f"{shown} has a path component the gate cannot check safely"
        for depth in range(1, len(parts)):
            prefix = b"/".join(parts[:depth])
            if prefix not in directories:
                directories[prefix] = _directory_problem(root, prefix)
            if directories[prefix] is not None:
                return f"{shown} lies below {directories[prefix]}"
        full = os.path.join(root, path)
        try:
            st = os.lstat(full)
        except OSError:
            return f"{shown} is committed but absent from the working tree"
        if mode == b"120000":
            if not stat.S_ISLNK(st.st_mode):
                return f"{shown} is a symbolic link in the commit but not in the working tree"
            data = os.readlink(full)
        else:
            if not stat.S_ISREG(st.st_mode):
                return f"{shown} is a file in the commit but not a regular file in the working tree"
            if bool(st.st_mode & stat.S_IXUSR) != (mode == b"100755"):
                return f"{shown} has another execute bit in the working tree than in the commit"
            data = _read_regular(full, -1)   # checked again at the descriptor (R18-2 class)
        hasher = _BLOB_HASHES[len(oid)](b"blob %d\0" % len(data))
        hasher.update(data)
        if hasher.hexdigest() != oid:
            return (f"{shown} in the working tree differs from the committed bytes (a local change, or a "
                    "checkout filter, line-ending or encoding rule the gate does not model)")
    with tempfile.TemporaryDirectory(prefix="proofbundle-untracked-") as scratch:
        os.mkdir(os.path.join(scratch, "hooks"))
        env = dict(_read_env(repo), GIT_INDEX_FILE=os.path.join(scratch, "no-index"))
        left = deadline - time.monotonic()
        if left <= 0:
            raise GateError("the gate ran out of time")
        try:
            proc = subprocess.run(["git", *_READ_ONLY_GIT, "-c", "core.fsmonitor=false", "-c",
                                   f"core.hooksPath={os.path.join(scratch, 'hooks')}", "-c", "core.untrackedCache=false",
                                   "-C", repo, "ls-files", "-z", "--others", "--exclude-standard"],
                                  env=env, capture_output=True, timeout=left, check=False)
        except FileNotFoundError as exc:
            raise GateError("git is not on PATH") from exc
        except subprocess.TimeoutExpired as exc:
            raise GateError("git did not answer in time") from exc
    if proc.returncode != 0:
        raise GateError("git could not list the working tree's files")
    for path in proc.stdout.split(b"\0"):
        if path and not path.startswith(EVIDENCE_DIR.encode()) and path not in committed:
            return f"{path.decode(errors='replace')} is in the working tree but not in the commit"
    return None


_PYTHON_NAME = re.compile(r"python(?:3(?:\.\d+)*)?")


def _pytest_command(command: list[str]) -> bool:
    """Whether the command is a supported pytest form: an executable named pytest or py.test, or a Python
    interpreter with `-m pytest`. The run-evidence binding, stated verbatim (review F6, F7, N7, Befund 2):
    "The command must have a supported pytest form, and the report must carry this invocation's random suite
    name. This rejects unsupported command forms and an unchanged report from another invocation; it does
    not authenticate the executable or the reported test activity."
    """
    name = os.path.basename(command[0])
    if name in ("pytest", "py.test"):
        return True
    return _PYTHON_NAME.fullmatch(name) is not None and command[1:3] == ["-m", "pytest"]


class StaleReport(GateError):
    """The JUnit report does not carry the name this run set, so it is not the report this call wrote."""


def _junit_counts(path: str, suite_name: str) -> tuple[dict, str]:
    """Counts from the JUnit XML report the run wrote, and the report's sha256. Every testsuite must carry
    the name this call set, so a report left from another invocation is rejected (review F7, N7)."""
    import xml.etree.ElementTree as ElementTree  # only this subcommand reads XML

    try:
        data = _read_regular(path, MAX_REPORT_BYTES + 1, follow=True)   # R18-2 class: a FIFO is never waited on
    except OSError as exc:
        raise GateError("the command wrote no JUnit XML report") from exc
    if len(data) > MAX_REPORT_BYTES:
        raise GateError(f"the report is larger than {MAX_REPORT_BYTES} bytes")
    if b"<!DOCTYPE" in data or b"<!ENTITY" in data:
        raise GateError("the report declares a DOCTYPE or an entity")
    try:
        root = ElementTree.fromstring(data)
    except ElementTree.ParseError as exc:
        raise GateError(f"the report is not XML ({exc})") from exc
    suites = [root] if root.tag == "testsuite" else root.findall("testsuite") if root.tag == "testsuites" else []
    if not suites:
        raise GateError("the report has no testsuite")
    if any(suite.get("name") != suite_name for suite in suites):
        raise StaleReport("the report was not written by this run (a testsuite does not carry the name this "
                          "call set); a replayed or stale report does not count")
    totals = dict.fromkeys(("tests", "failures", "errors", "skipped"), 0)
    for suite in suites:
        for name in totals:
            value = suite.get(name, "0")
            if not re.fullmatch(r"[0-9]{1,15}", value):
                raise GateError(f"the report's {name} is not a count")
            totals[name] += int(value)
    counts = {"tests": totals["tests"], "failed": totals["failures"], "errors": totals["errors"],
              "skipped": totals["skipped"]}
    counts["passed"] = counts["tests"] - counts["failed"] - counts["errors"] - counts["skipped"]
    if counts["passed"] < 0:
        raise GateError("the report's counts do not add up")
    return counts, hashlib.sha256(data).hexdigest()


def _file_sha256(path: str) -> str:
    """The sha256 of the regular file at `path`, a link followed; _NotRegular for any other entry (R18-2 class)."""
    return hashlib.sha256(_read_regular(path, -1, follow=True)).hexdigest()


def _now() -> str:
    return time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())


def run_evidence(directory: str, out: str, command: list[str],
                 timeout: float = RUN_TIMEOUT_SECONDS, junit_out: str | None = None) -> tuple[int, dict]:
    """Run a pytest command on the clean working tree of HEAD and, for a green run that left the tree as it
    was, write the statement a bundle signs: the subject and the run record (DECISIONS.md, D23).

    There is no evidence when the working tree differs from HEAD before the run, when the run moves HEAD or
    changes the working tree, when it times out or writes no readable report, or when it is not green. The
    record holds no environment value. Nothing is signed here.

    When junit_out is given, the exact JUnit report the record's report_sha256 is taken over is copied there,
    so a reader can hold the raw report beside the signed record and confirm the hash (review round 5,
    Befund 5; the report is otherwise discarded with the scratch directory).
    """
    report = {"outcome": "no_evidence", "reason_id": None, "message": "", "statement": None, "run": None,
              "gate_version": GATE_VERSION}

    def refuse(reason_id: str, message: str, run: dict | None = None) -> tuple[int, dict]:
        report.update(reason_id=reason_id, run=run,
                      message=f"NO EVIDENCE: {message}. Nothing was written, and nothing may be signed as this run.")
        return 1, report

    try:
        deadline = time.monotonic() + DEADLINE_SECONDS
        repo, unreadable = _work_tree(directory, deadline)
        if repo is None:
            return refuse("not_a_work_tree", unreadable or f"{directory} is not inside a git work tree")
        head = _git(repo, "rev-parse", "--verify", "--quiet", "HEAD^{commit}", deadline=deadline)
        if head.returncode != 0:
            return refuse("no_commit", f"{repo} has no commit at HEAD")
        commit = head.stdout.decode().strip()
        # The command is judged before the tree is read, so a call that cannot run is refused before any
        # comparison (review round 8, R8-1: the old staging ran fsmonitor and hooks before this refusal).
        program = shutil.which(command[0])
        if program is None:
            return refuse("no_program", f"{command[0]!r} is not an executable file on PATH")
        if not _pytest_command(command):
            return refuse("not_pytest", f"{command[0]!r} is not a pytest command; run-evidence runs only pytest "
                                        "(an executable named pytest, or a Python interpreter with -m pytest)")
        program = os.path.abspath(program)
        digest = tree_digest(repo, commit, deadline)
        problem = _working_tree_problem(repo, commit, deadline)
        if problem is not None:
            return refuse("tree_not_clean", f"the working tree of {repo} differs from HEAD {commit[:12]}: "
                                            f"{problem}; commit or remove the changes, then run again (files git "
                                            "ignores are not compared)")
        with tempfile.TemporaryDirectory(prefix="proofbundle-run-") as scratch:
            junit = os.path.join(scratch, "report.xml")
            suite_name = "proofbundle-run-" + secrets.token_hex(16)
            argv = [program, *command[1:], "-p", "no:cacheprovider", f"--junitxml={junit}",
                    "-o", f"junit_suite_name={suite_name}"]
            started = _now()
            # The check process starts in the work tree, and a relative GIT_DIR or GIT_WORK_TREE of the host would name
            # another repository or tree from there than the one compared above: it gets the values git resolved in the
            # call's directory (_pins), and none of the other settings of the gate's own reads (review round 8 of
            # 2026-10-10, R8-1; measured with git 2.43.0 and 2.51.1: GIT_WORK_TREE=repo given in P made the test read
            # P/repo/repo while the statement named P/repo).
            check_env = dict(os.environ, **(getattr(repo, "pins", None) or {}), PYTHONDONTWRITEBYTECODE="1")
            try:
                proc = subprocess.Popen(argv, cwd=repo, env=check_env,
                                        stdin=subprocess.DEVNULL, stdout=2, stderr=2, start_new_session=True)
            except OSError as exc:
                return refuse("not_started", f"the command could not start ({exc})")
            try:
                exit_code = proc.wait(timeout=timeout)
            except subprocess.TimeoutExpired:
                try:
                    os.killpg(proc.pid, signal.SIGKILL)
                except ProcessLookupError:
                    pass
                proc.wait()
                return refuse("timeout", f"the command did not finish within {timeout:g} s")
            finished = _now()
            deadline = time.monotonic() + DEADLINE_SECONDS
            after = _git(repo, "rev-parse", "--verify", "--quiet", "HEAD^{commit}", deadline=deadline)
            if after.returncode != 0 or after.stdout.decode().strip() != commit:
                return refuse("head_moved", f"the run moved HEAD away from {commit[:12]}")
            problem = _working_tree_problem(repo, commit, deadline)
            if problem is not None:
                return refuse("tree_changed", f"the run changed the working tree of {repo} ({problem}), so it did "
                                              "not run on the tree it would name")
            tree_after = digest   # the working tree still holds exactly the commit's files
            try:
                counts, report_sha256 = _junit_counts(junit, suite_name)
            except StaleReport as exc:
                return refuse("stale_report", str(exc))
            except GateError as exc:
                return refuse("no_report", str(exc))
            if junit_out is not None:
                try:
                    shutil.copyfile(junit, junit_out)  # the exact bytes report_sha256 is taken over (Befund 5)
                except OSError as exc:
                    return refuse("junit_not_written", f"the JUnit report could not be copied to {junit_out} ({exc})")
        import platform  # only this subcommand names the platform

        run = {"schema": RUN_SCHEMA, "commit": commit, "tree_before": digest, "tree_after": tree_after,
               "command": argv, "program": {"path": program, "sha256": _file_sha256(program)},
               "exit_code": exit_code, "counts": counts, "report_sha256": report_sha256, "started_at": started,
               "finished_at": finished, "gate_version": GATE_VERSION,
               "platform": {"system": platform.system(), "release": platform.release(), "machine": platform.machine()}}
        problem = run_record_problem(run, digest)
        if problem is not None:
            return refuse("run_failed", problem.replace("the signed run record", "the run"), run)
        statement = json.dumps({"subject": {"algorithm": TREE_ALGORITHM, "digest": digest}, "run": run},
                               indent=1, sort_keys=True) + "\n"
        try:
            with open(out, "x", encoding="utf-8") as handle:
                handle.write(statement)
        except OSError as exc:
            return refuse("not_written", f"the statement could not be written to {out} ({exc})", run)
    except GateError as exc:
        return refuse("gate_error", str(exc))
    report.update(outcome="evidence", reason_id="green_run", run=run, statement=os.path.abspath(out),
                  message=f"proofbundle run: {counts['passed']} of {counts['tests']} tests passed, exit 0, on "
                          f"{TREE_ALGORITHM} {digest} at HEAD {commit[:12]}, and the run left the tree as it "
                          f"was. The statement is unsigned; sign it only if you mean to vouch for this run. "
                          "It records what the run reported, not that the tests test anything.")
    return 0, report


def run_evidence_command(argv: list[str]) -> int:
    if "--" not in argv:
        print(RUN_USAGE, file=sys.stderr)
        return 2
    split = argv.index("--")
    options, command, i = {"--repo": None, "--out": None, "--timeout": None, "--junit-out": None}, argv[split + 1:], 0
    head = argv[:split]
    while i < len(head):
        if head[i] in options and i + 1 < len(head):
            options[head[i]], i = head[i + 1], i + 2
        else:
            print(f"{RUN_USAGE}; unknown {head[i]!r}", file=sys.stderr)
            return 2
    timeout = RUN_TIMEOUT_SECONDS
    if options["--timeout"] is not None:
        if not re.fullmatch(r"[0-9]{1,5}", options["--timeout"]) or int(options["--timeout"]) == 0:
            print(f"{RUN_USAGE}; the timeout is a whole number of seconds from 1 to 99999", file=sys.stderr)
            return 2
        timeout = float(options["--timeout"])
    if options["--repo"] is None or options["--out"] is None or not command:
        print(RUN_USAGE, file=sys.stderr)
        return 2
    code, report = run_evidence(options["--repo"], options["--out"], command, timeout, options["--junit-out"])
    sys.stdout.write(json.dumps(report, indent=1) + "\n")
    print(report["message"], file=sys.stderr)
    return code


def _host(argv: list[str]) -> str:
    argv = [a for a in argv if a != AUTONOMOUS_FLAG]   # D85: the flag of the autonomous answer, read by main()
    if not argv:
        return "claude"
    if len(argv) == 2 and argv[0] == "--host" and argv[1] in HOSTS:
        return argv[1]
    raise GateError(f"unknown arguments {argv!r}; the gate takes --host claude or --host codex, and "
                    f"{AUTONOMOUS_FLAG}")


# --- the pilot of Z405: a signed decision receipt for each GitHub write the gate decides (DECISIONS.md D55) -------
#
# The pilot contract and github-write/1 profile define the intended decision receipts. This implementation attempts
# receipts for recognized GitHub writes; an issuance failure can leave no receipt. Ordinary receipt attempts are
# observational and must not change the gate's permission decision, exit code, log line or answer bytes. D119 owner
# releases are different: where the configured pilot recognizes the write, release_settle requires a signed ALLOW
# before the release is used. A receipt that cannot be issued is journaled where possible; journal failure must not
# prevent the ordinary hook answer from returning.

PILOT_FILE = "pilot.json"
MAX_PILOT_BYTES = 16 * 1024
MAX_CLOSING_RULES_BYTES = 64 * 1024
PILOT_PROFILE = "github-write/1"
PILOT_ENGINE, PILOT_REVISION = "proofbundle-pilot/github-write", "1"
DECISION_RECEIPT_TYPE = "https://b7n0de.com/proofbundle/predicates/decision-receipt/v0.1"
# INTOTO_STATEMENT_TYPE and INTOTO_PAYLOAD_TYPE are those of the done check's statement (D29), bound once above
PILOT_SURFACES = ("github.conversationComment", "github.reviewThreadReply", "github.pullRequestBody", "git.push",
                  "github.merge")
#: How long the gate waits for the signer of the operator before it gives up on one receipt. Since D58 the signer is a
#: service that decides the call again with its own copy of the gate before it signs; its whole path stays within this.
PILOT_SIGNER_SECONDS = 10.0
#: The request the gate hands the signer service (D58): the hook event as the host gave it, the host and the working
#: directory at Level 1, the remote, the URL, git's ref lines and the line at Level 2, and the proposed statement.
PILOT_SIGN_REQUEST = "proofbundle/pilot-sign-request/v1"
#: The exit status by which the signer service refuses, with one reason name on stdout (D58).
PILOT_SIGNER_REFUSES = 3
#: The decisions of the gate at Level 1 and the verdicts of decision-receipt/v0.1 they are recorded as. pass approves;
#: deny refuses; ask hands the call to a person, whose answer the gate does not see. inactive, handover and warn get no
#: receipt: there the gate leaves the write to another check (D5, D35, D12), and Level 2 decides a push it hands over.
_PILOT_VERDICTS = {"pass": "ALLOW", "deny": "DENY", "ask": "ESCALATE"}
_PILOT_KEYS = frozenset({"profile", "gate_id", "observer_id", "agent_id", "principal_id", "validity_seconds",
                         "receipts", "signer", "public_key", "closing_rules"})
_PILOT_ID = re.compile(r"[A-Za-z0-9][A-Za-z0-9:._@/-]{0,63}\Z", re.ASCII)
_PILOT_HEX_KEY = re.compile(r"[0-9a-f]{64}\Z", re.ASCII)
_PILOT_REASON = re.compile(r"[a-z0-9_]{1,64}\Z", re.ASCII)
_PILOT_OID = re.compile(r"(?:[0-9a-f]{40}|[0-9a-f]{64})\Z", re.ASCII)
_GH_OWNER = r"[A-Za-z0-9][A-Za-z0-9-]{0,38}"
_GH_REPO = r"[A-Za-z0-9._-]{1,100}?"
_GH_SLUG = re.compile(rf"({_GH_OWNER})/({_GH_REPO})\Z", re.ASCII)
#: The number of a pull request as the pilot reads it (no leading zero, at most ten digits). Its own name (N405-a): the
#: read forms of class b keep _GH_NUMBER, bound once; a second binding of that name rebound it for every reader at call
#: time, while _GH_READ_ARGS kept the first.
_PILOT_GH_NUMBER = re.compile(r"[1-9][0-9]{0,9}\Z", re.ASCII)
_GH_PULL_URL = re.compile(rf"https://github\.com/({_GH_OWNER})/({_GH_REPO})/pull/([1-9][0-9]{{0,9}})\Z", re.ASCII)
_GH_REPLIES = re.compile(rf"/?repos/({_GH_OWNER})/({_GH_REPO})/pulls/([1-9][0-9]{{0,9}})/comments/[1-9][0-9]{{0,19}}"
                         r"/replies\Z", re.ASCII)
#: The push URLs the pilot reads a GitHub repository from: https, scp-like ssh and ssh URLs to github.com, with nothing
#: else in them. A URL that carries a user, a password, a port or a query is not one of them, so the receipt names no
#: target there and never a part of such a URL (the rule of D49).
_GH_PUSH_URLS = (re.compile(rf"https://github\.com/({_GH_OWNER})/({_GH_REPO})(?:\.git)?/?\Z", re.ASCII),
                 re.compile(rf"git@github\.com:({_GH_OWNER})/({_GH_REPO})(?:\.git)?/?\Z", re.ASCII),
                 re.compile(rf"ssh://git@github\.com/({_GH_OWNER})/({_GH_REPO})(?:\.git)?/?\Z", re.ASCII))
_PILOT_BRANCH = re.compile(r"[A-Za-z0-9._/-]{1,200}\Z", re.ASCII)
#: The plain gh forms the pilot reads a write from: the surface, the options that take a value and the slot each fills,
#: the options without a value. Every other option, a second use of one, `--` and a spelling such as `-bTEXT` leave the
#: form unread: the gate still decides it, and no receipt is written, so an effect of it counts under M5.
_PILOT_GH_FORMS = {
    ("pr", "comment"): ("github.conversationComment", {"--body": "body", "-b": "body", "--repo": "repo", "-R": "repo"},
                        {}),
    ("pr", "edit"): ("github.pullRequestBody", {"--body": "body", "-b": "body", "--repo": "repo", "-R": "repo"}, {}),
    ("pr", "merge"): ("github.merge", {"--repo": "repo", "-R": "repo"},
                      {"--merge": "method", "-m": "method", "--squash": "method", "-s": "method", "--rebase": "method",
                       "-r": "method"}),
    ("pr", "create"): ("github.pullRequestBody", {"--title": "title", "-t": "title", "--body": "body", "-b": "body",
                                                  "--head": "head", "-H": "head", "--base": "base", "-B": "base",
                                                  "--repo": "repo", "-R": "repo"}, {}),
}


def _pilot_config(environ: dict) -> dict | None:
    """The pilot configuration a person wrote into pilot.json of the gate directory (D55), or None: no directory, no
    file, or a file that is not exactly the pilot's form. Read like `mode`, and decide_write denies every write to
    that directory, so the model does not write it. Its values select the receipts' folder, the signer, the key and
    the names of the pilot's roles; none of them is a secret, and only the names enter a receipt."""
    directory = _gate_dir(environ)
    if directory is None:
        return None
    try:
        raw = _read_regular(os.path.join(directory, PILOT_FILE), MAX_PILOT_BYTES + 1, follow=True)
        data = strict_json(raw) if len(raw) <= MAX_PILOT_BYTES else None
    except (OSError, ValueError):
        return None
    if not isinstance(data, dict) or set(data) != _PILOT_KEYS or data["profile"] != PILOT_PROFILE:
        return None
    if not all(isinstance(data[k], str) and _PILOT_ID.fullmatch(data[k])
               for k in ("gate_id", "observer_id", "agent_id", "principal_id")):
        return None
    seconds = data["validity_seconds"]
    if type(seconds) is not int or not 1 <= seconds <= 86400:
        return None
    if not (isinstance(data["public_key"], str) and _PILOT_HEX_KEY.fullmatch(data["public_key"])):
        return None
    signer, paths = data["signer"], [data["receipts"]] + ([data["closing_rules"]] if data["closing_rules"] else [])
    if not (isinstance(signer, list) and 1 <= len(signer) <= 32 and all(isinstance(w, str) and w for w in signer)):
        return None
    if data["closing_rules"] is not None and not isinstance(data["closing_rules"], str):
        return None
    for text in [signer[0]] + paths:
        if not (isinstance(text, str) and os.path.isabs(text) and len(text) <= 4096):
            return None
    if any(ord(c) < 32 for text in signer + paths for c in text):
        return None
    return data


def _pilot_instant(nanoseconds: int) -> str:
    """An RFC 3339 instant in UTC with six fraction digits, the most the decision's verifier reads (pilot profile)."""
    whole, rest = divmod(nanoseconds, 1_000_000_000)
    return time.strftime("%Y-%m-%dT%H:%M:%S", time.gmtime(whole)) + f".{rest // 1000:06d}Z"


def _pilot_canonical(value: object) -> bytes:
    """The RFC 8785 form of a receipt the gate builds. It holds objects, lists, strings and one boolean, and every
    string is ASCII, so sorted keys without spaces are that form; a non-ASCII byte refuses the receipt (ValueError)
    rather than risk a second reading of it."""
    raw = json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=False, allow_nan=False).encode("utf-8")
    if not raw.isascii():
        raise ValueError("a receipt holds a byte outside ASCII")
    return raw


def _pilot_keyid(public: bytes) -> str:
    """OpenSSH's SHA256 fingerprint of the Ed25519 public key, as the profile writes it into every envelope."""
    def string(data: bytes) -> bytes:
        return len(data).to_bytes(4, "big") + data
    digest = hashlib.sha256(string(b"ssh-ed25519") + string(public)).digest()
    return "SHA256:" + base64.b64encode(digest).decode("ascii").rstrip("=")


def _pilot_policy_digest(environ: dict) -> str:
    """The sha256 the receipt names as the gate's policy: over the gate's own file, the mode and the rules a person
    wrote (an absent file counts as empty). Recorded, not interpreted (pilot profile). The gate's own file is read as
    _sha256_or_none reads, without blocking and only as a regular file (D123): a FIFO in its place is an OSError at
    once, and the receipt is not issued."""
    parts = {}
    own = os.path.realpath(__file__)
    parts["gate"] = _sha256_or_none(own)
    if parts["gate"] is None:
        raise OSError(errno.EINVAL, "the gate's own file is no regular file it can read", own)
    directory = _gate_dir(environ)
    for name, limit in (("mode", MAX_MODE_BYTES + 1), ("rules.json", MAX_RULES_BYTES + 1)):
        try:
            raw = _read_regular(os.path.join(directory, name), limit, follow=True) if directory else b""
        except OSError:
            raw = b""
        parts[name] = hashlib.sha256(raw).hexdigest()
    return hashlib.sha256(_pilot_canonical(parts)).hexdigest()


def _pilot_options(args: list[str], valued: dict, flags: dict) -> tuple[dict, list] | None:
    """The options and positional words of a plain gh form, or None for a word the pilot does not read."""
    found, positional, i = {}, [], 0
    while i < len(args):
        word = args[i]
        name, eq, value = word.partition("=") if word.startswith("--") else (word, "", "")
        if eq and name in valued and valued[name] not in found:
            found[valued[name]], i = value, i + 1
        elif not eq and word in valued and valued[word] not in found and i + 1 < len(args):
            found[valued[word]], i = args[i + 1], i + 2
        elif not eq and word in flags and flags[word] not in found:
            found[flags[word]], i = word, i + 1
        elif word.startswith("-"):
            return None
        else:
            positional.append(word)
            i += 1
    return found, positional


def _pilot_pull_target(positional: list, found: dict) -> str | None:
    """https://github.com/<owner>/<repo>/pull/<n> for a pull request named by its URL, or by its number and --repo."""
    if len(positional) != 1:
        return None
    match = _GH_PULL_URL.fullmatch(positional[0])
    if match and "repo" not in found:
        owner, repo, number = match.groups()
    else:
        slug = _GH_SLUG.fullmatch(found.get("repo", ""))
        if not (slug and _PILOT_GH_NUMBER.fullmatch(positional[0])):
            return None
        (owner, repo), number = slug.groups(), positional[0]
    return None if repo in (".", "..") else f"https://github.com/{owner}/{repo}/pull/{number}"


def _pilot_compare_target(owner: str, repo: str, base: object, head: object) -> str | None:
    """https://github.com/<owner>/<repo>/compare/<base>...<head> for a pull request that does not exist yet."""
    if repo in (".", "..") or not all(isinstance(b, str) and _PILOT_BRANCH.fullmatch(b) and ".." not in b
                                      for b in (base, head)):
        return None
    return f"https://github.com/{owner}/{repo}/compare/{base}...{head}"


def _pilot_bytes(text: object) -> bytes | None:
    try:
        return text.encode("utf-8") if isinstance(text, str) else None
    except UnicodeEncodeError:
        return None


def _pilot_shell_action(command: str) -> dict | None:
    """The one GitHub write a plain shell command makes, as the pilot reads it (D55): its surface, its target and the
    bytes it writes, the last two None where the form does not name them. None for a command that is not one simple
    command of literal words, or not a write the pilot reads. `git push` at Level 1 has neither target nor bytes: the
    gate does not resolve what a push sends there (D3), and Level 2 writes the receipt that names them."""
    toks = _lex(_drop_comments(command))
    if toks is None or not toks or any(t[0] != "word" or t[2] for t in toks) or _expansion_present(command):
        return None
    words = [t[1] for t in toks]
    if words[:2] == ["git", "push"]:
        return {"surface": "git.push", "target": None, "bytes": None, "media": "text/plain"}
    if words[:1] != ["gh"] or len(words) < 3:
        return None
    if words[1] == "api":
        parsed = _pilot_options(words[3:], {"-f": "field", "--raw-field": "field", "-X": "method",
                                            "--method": "method"}, {})
        path = _GH_REPLIES.fullmatch(words[2])
        if parsed is None or parsed[1] or path is None or parsed[0].get("method", "POST") != "POST":
            return None
        name, eq, body = parsed[0].get("field", "").partition("=")
        owner, repo, number = path.groups()
        if name != "body" or not eq or repo in (".", ".."):
            return None
        return {"surface": "github.reviewThreadReply", "target": f"https://github.com/{owner}/{repo}/pull/{number}",
                "bytes": _pilot_bytes(body), "media": "text/markdown"}
    form = _PILOT_GH_FORMS.get((words[1], words[2]))
    parsed = _pilot_options(words[3:], form[1], form[2]) if form else None
    if parsed is None:
        return None
    surface, (found, positional) = form[0], parsed
    if (words[1], words[2]) == ("pr", "create"):
        slug = _GH_SLUG.fullmatch(found.get("repo", ""))
        if positional or slug is None or not {"title", "body", "head", "base"} <= set(found):
            return None
        target = _pilot_compare_target(*slug.groups(), found["base"], found["head"])
        return {"surface": surface, "target": target, "bytes": _pilot_bytes(found["body"]), "media": "text/markdown"}
    target = _pilot_pull_target(positional, found)
    if surface == "github.merge":
        # A merge writes no text of the agent: its approved bytes are the empty string (D55).
        return {"surface": surface, "target": target, "bytes": b"", "media": "text/plain"}
    if "body" not in found:
        return None
    return {"surface": surface, "target": target, "bytes": _pilot_bytes(found["body"]), "media": "text/markdown"}


def _pilot_mcp_action(tool: str, tool_input: object) -> dict | None:
    """The GitHub write a gated MCP tool makes, read from its own arguments (D55), or None."""
    name = tool.rsplit("__", 1)[-1]
    if not isinstance(tool_input, dict):
        return None
    owner, repo = tool_input.get("owner"), tool_input.get("repo")
    slug = _GH_SLUG.fullmatch(f"{owner}/{repo}") if isinstance(owner, str) and isinstance(repo, str) else None
    if slug is None or repo in (".", ".."):
        return None
    if name == "create_pull_request":
        target = _pilot_compare_target(owner, repo, tool_input.get("base"), tool_input.get("head"))
        return {"surface": "github.pullRequestBody", "target": target, "bytes": _pilot_bytes(tool_input.get("body")),
                "media": "text/markdown"}
    if name == "merge_pull_request":
        number = tool_input.get("pullNumber", tool_input.get("pull_number"))
        number = str(number) if type(number) is int else number
        target = (f"https://github.com/{owner}/{repo}/pull/{number}"
                  if isinstance(number, str) and _PILOT_GH_NUMBER.fullmatch(number) else None)
        return {"surface": "github.merge", "target": target, "bytes": b"", "media": "text/plain"}
    if name in ("push_files", "create_or_update_file"):
        branch = tool_input.get("branch")
        target = (f"https://github.com/{owner}/{repo}#refs/heads/{branch}"
                  if isinstance(branch, str) and _PILOT_BRANCH.fullmatch(branch) and ".." not in branch else None)
        return {"surface": "git.push", "target": target, "bytes": None, "media": "text/plain"}
    return None


def _pilot_push_actions(url: str | None, lines: list[tuple]) -> list[tuple[dict, str]]:
    """One git.push action per ref line of Level 2 (D55): the target is the repository the push URL names on GitHub
    and the ref it writes, the bytes are the commit it sends, `<sha>` and a line feed. A URL that is no plain GitHub URL
    leaves the target unnamed, and a deletion the bytes."""
    slug = None
    for pattern in _GH_PUSH_URLS:
        match = pattern.fullmatch(url) if isinstance(url, str) else None
        if match and match.group(2) not in (".", ".."):
            slug = match.groups()
    actions = []
    for local_ref, local_sha, remote_ref, remote_sha in lines:
        ref_ok = (remote_ref.startswith(_TRACKABLE) and _PILOT_BRANCH.fullmatch(remote_ref) and ".." not in remote_ref
                  and not remote_ref.endswith(("/", ".lock")))
        target = f"https://github.com/{slug[0]}/{slug[1]}#{remote_ref}" if slug and ref_ok else None
        sent = (local_sha + "\n").encode("ascii") if _PILOT_OID.fullmatch(local_sha) and local_sha not in _ZERO_OIDS \
            else None
        key = hashlib.sha256(" ".join((local_ref, local_sha, remote_ref, remote_sha)).encode("utf-8",
                                                                                            "surrogatepass")).hexdigest()
        actions.append(({"surface": "git.push", "target": target, "bytes": sent, "media": "text/plain"}, key))
    return actions


def _pilot_journal(folder: str, entry: dict) -> None:
    """One line of the receipt folder's journal: what was issued, or why a receipt was not, by a fixed name. The journal
    is opened without blocking and without following a link, and the line is written only where the opened descriptor
    is a regular file (D123, the class of R18-2): a FIFO with or without a reader, a device, a folder or a link there
    is never waited on and gets no line. Such a journal raises an OSError, as one that cannot be opened does; the
    callers drop it, so an ordinary answer returns as it is (under D119 the release stays unused, release_settle)."""
    entry = {"at": _pilot_instant(time.time_ns()), **entry}
    os.makedirs(folder, exist_ok=True)
    path = os.path.join(folder, "journal.jsonl")
    # 0o644 like the pilot's decision files, since the records are copied for the reconciliation under another account
    # (tests/test_plugin_files_name_their_readers.py); under a umask of 0, 0o666 made the journal writable by everyone
    # (CodeQL on pull request 460).
    fd = os.open(path, os.O_WRONLY | os.O_APPEND | os.O_CREAT | getattr(os, "O_NONBLOCK", 0)
                 | getattr(os, "O_NOFOLLOW", 0) | getattr(os, "O_CLOEXEC", 0), 0o644)
    try:
        if not stat.S_ISREG(os.fstat(fd).st_mode):
            raise _NotRegular(errno.EINVAL, "not a regular file", path)
        handle = os.fdopen(fd, "ab")
    except BaseException:
        os.close(fd)
        raise
    with handle:
        handle.write((json.dumps(entry, sort_keys=True) + "\n").encode("ascii"))


def _pilot_sign(config: dict, body: bytes, context: dict) -> bytes:
    """The Ed25519 signature the operator's signer makes over the DSSE PAE of `body`, the canonical statement. The
    gate holds no key (D55). Since D58 the signer is a service of the operator that decides the call again: it reads
    the request (PILOT_SIGN_REQUEST: `context`, the call as the hook saw it, and the statement in base64) on stdin and
    writes the 64-byte signature in base64 on stdout, or exits PILOT_SIGNER_REFUSES with one reason name."""
    request = {"schema": PILOT_SIGN_REQUEST, **context, "statement": base64.b64encode(body).decode("ascii")}
    try:
        proc = subprocess.run(config["signer"], input=json.dumps(request, sort_keys=True).encode("utf-8"),
                              capture_output=True, timeout=PILOT_SIGNER_SECONDS, env={"PATH": os.defpath, "LANG": "C"},
                              check=False)
    except subprocess.TimeoutExpired as exc:
        raise GateError("signer_timeout") from exc   # killed after PILOT_SIGNER_SECONDS: no receipt (N405-b)
    refused = proc.stdout.decode("ascii", "replace").strip()
    if proc.returncode == PILOT_SIGNER_REFUSES and re.fullmatch(r"[a-z_]{1,48}", refused):
        raise GateError(f"signer_refused_{refused}")
    if proc.returncode != 0 or len(proc.stdout) > 256:
        raise GateError("signer_failed")
    try:
        signature = base64.b64decode(proc.stdout.strip(), validate=True)
    except (binascii.Error, ValueError) as exc:
        raise GateError("signer_answer") from exc
    if len(signature) != 64:
        raise GateError("signer_answer")
    return signature


def _pilot_action_id(config: dict, action: dict, key: str) -> str:
    """The action id of a decision (D55): a digest of the surface, the target, the bytes and the agent, so a retried
    action keeps its id; where the gate resolves no target or no bytes, of the surface, the key of the call and the
    agent."""
    digest = hashlib.sha256(action["bytes"]).hexdigest() if action["bytes"] is not None else None
    named = [action["surface"], action["target"], digest, config["agent_id"]] if action["target"] and digest else \
        [action["surface"], "unresolved", key, config["agent_id"]]
    return "a-" + hashlib.sha256("\0".join(named).encode("ascii")).hexdigest()[:32]


def _pilot_statement(config: dict, environ: dict, action: dict, verdict: str, reasons: list[str], decision_id: str,
                     decided_ns: int) -> dict:
    """The in-toto Statement of one decision receipt of github-write/1 (D55), as the gate proposes it and as the signer
    service builds it again from its own decision before it signs (D58): everything but the decision's id and instant
    follows from the pilot's configuration, the action, the verdict and the reasons."""
    digest = hashlib.sha256(action["bytes"]).hexdigest() if action["bytes"] is not None else None
    surface, target = action["surface"], action["target"]
    closing = None
    if config["closing_rules"] is not None:
        try:
            raw = _read_regular(config["closing_rules"], MAX_CLOSING_RULES_BYTES + 1, follow=True)
        except OSError as exc:
            raise GateError("closing_rules_unread") from exc
        if len(raw) > MAX_CLOSING_RULES_BYTES:
            raise GateError("closing_rules_unread")
        closing = hashlib.sha256(raw).hexdigest()
    proposed = {"actionType": surface, "method": "write",
                "target": {"name": target, "uri": target} if target else {"name": "not resolved by the gate"}}
    if digest is not None:
        proposed["parametersDigest"] = {"sha256": digest}
    else:
        proposed["parametersRef"] = {"uri": "urn:proofbundle:pilot:not-resolved"}
    snapshot = ([{"name": "approved bytes" if verdict == "ALLOW" else "proposed bytes",
                  "digest": {"sha256": digest}, "mediaType": action["media"]}] if digest else []) + \
        ([{"name": "closing rules", "digest": {"sha256": closing}, "mediaType": "application/json"}]
         if closing else [])
    not_checked = [{"field": "content", "reason": "the gate does not judge whether the text is true",
                    "impact": "an approved text can be wrong"}]
    if target is None or digest is None:
        not_checked.append({"field": "proposedAction", "reason": "the gate does not resolve the target or the "
                            "bytes of this form", "impact": "an effect cannot be matched to this decision by them"})
    predicate = {
        "schemaVersion": "0.1.0", "decisionId": decision_id, "decisionType": "preActionAuthorization",
        "decidedAt": _pilot_instant(decided_ns), "decisionMaker": {"id": config["gate_id"]},
        "agent": {"id": config["agent_id"]}, "principal": {"id": config["principal_id"]},
        "proposedAction": proposed, "inputSnapshot": snapshot,
        "policyBoundary": {"policyEngine": PILOT_ENGINE, "policyId": "outbound-gate-rules",
                           "decisionPath": f"outbound-gate/{verdict.lower()}-write",
                           "policyDigest": {"sha256": _pilot_policy_digest(environ)},
                           "bundleRevision": PILOT_REVISION},
        "evidenceRefs": [], "decision": {"verdict": verdict, "reasonCodes": reasons or ["no_reason_named"]},
        "notChecked": not_checked,
        "decisionChangeConditions": [{"conditionType": "ruleChange",
                                      "description": "a changed gate, mode or rule of the gate"}],
        "privacy": {"rawInputsIncluded": False},
        "validity": {"audience": [config["observer_id"]], "nonce": decision_id,
                     "expiresAt": _pilot_instant(decided_ns + config["validity_seconds"] * 1_000_000_000)},
    }
    return {"_type": INTOTO_STATEMENT_TYPE,
            "subject": [{"name": f"decision:{decision_id}",
                         "digest": {"sha256": hashlib.sha256(_pilot_canonical(predicate)).hexdigest()}}],
            "predicateType": DECISION_RECEIPT_TYPE, "predicate": predicate}


def _pilot_issue(config: dict, environ: dict, action: dict, key: str, verdict: str, reasons: list[str],
                 context: dict | None = None) -> None:
    """Write one decision receipt of github-write/1 into <receipts>/decisions (D55), signed by the operator's signer.
    decisionId is `<action id>#<attempt>` (_pilot_action_id); the attempt is the first number no receipt of that id
    holds yet. context goes to the signer service with the statement (D58)."""
    folder, decided_ns = config["receipts"], time.time_ns()
    action_id = _pilot_action_id(config, action, key)
    if config["closing_rules"] is not None:
        _pilot_statement(config, environ, action, verdict, reasons, "a-0#0", decided_ns)   # an unread file: no slot
    decisions = os.path.join(folder, "decisions")
    os.makedirs(decisions, exist_ok=True)
    for attempt in range(1, 100_000):
        path = os.path.join(decisions, f"{action_id}-{attempt}.json")
        try:
            # Mode 644 on purpose: the observer and the reconciliation read the decisions from the records under
            # accounts of their own (D56; CodeQL alert 152, kept).
            fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_NOFOLLOW", 0), 0o644)
            break
        except FileExistsError:
            continue
    else:
        raise GateError("attempts_exhausted")
    try:
        decision_id = f"{action_id}#{attempt}"
        body = _pilot_canonical(_pilot_statement(config, environ, action, verdict, reasons, decision_id, decided_ns))
        signature = _pilot_sign(config, body, context or {})
        envelope = {"payload": base64.b64encode(body).decode("ascii"), "payloadType": INTOTO_PAYLOAD_TYPE,
                    "signatures": [{"keyid": _pilot_keyid(bytes.fromhex(config["public_key"])),
                                    "sig": base64.b64encode(signature).decode("ascii")}]}
        with os.fdopen(fd, "w", encoding="ascii") as handle:
            fd = None
            handle.write(json.dumps(envelope, sort_keys=True) + "\n")
    except BaseException:
        if fd is not None:
            os.close(fd)
        os.unlink(path)
        raise
    _pilot_journal(folder, {"issued": True, "decisionId": decision_id, "verdict": verdict,
                            "file": os.path.join("decisions", os.path.basename(path))})


def _pilot_reasons(reasons: list) -> list[str]:
    """The reason ids a receipt names: the gate's own ids of the decision, each once, in order (D55)."""
    return sorted({r for r in reasons if isinstance(r, str) and _PILOT_REASON.fullmatch(r)})


def _pilot_issue_all(config: dict | None, environ: dict, actions: list[tuple[dict, str]], verdict: str | None,
                     reasons: list[str], context: dict | None = None) -> None:
    """Issue a receipt for each action; a failure is a journal line with its fixed name and never an answer (D55).
    context is the call as the signer service needs it to decide again (D58); at Level 2 each receipt names its line."""
    if config is None or verdict is None:
        return
    reasons = _pilot_reasons(reasons)
    for index, (action, key) in enumerate(actions):
        try:
            _pilot_issue(config, environ, action, key, verdict, reasons,
                         {**(context or {}), **({"line": index} if (context or {}).get("level") == 2 else {})})
        except Exception as exc:  # noqa: BLE001 - a receipt never changes the answer (D55)
            why = str(exc) if isinstance(exc, GateError) and _PILOT_REASON.fullmatch(str(exc)) else \
                f"internal_{type(exc).__name__}"
            try:
                _pilot_journal(config["receipts"], {"issued": False, "why": why})
            except Exception:  # noqa: BLE001 - nor does a journal it cannot write
                pass


def _pilot_tool_verdict(outcome: "Outcome", host: str) -> str | None:
    """The verdict a Level 1 receipt records for an outcome (D55): what the host enforces. Codex has no dialog, and the
    gate answers an ask there as a refusal (answer, D4), so the receipt says DENY. None where no receipt is written."""
    decision = "deny" if host == "codex" and outcome.decision == "ask" else outcome.decision
    return _PILOT_VERDICTS.get(decision)


def _pilot_tool_action(event: object) -> tuple[dict | None, str]:
    """The GitHub write a hook event makes as the pilot reads it, and the key of the call (D55): (None, "") for an event
    that is no such write, a file tool's included."""
    if not isinstance(event, dict):
        return None, ""
    tool = event.get("tool_name")
    if isinstance(tool, str) and tool.startswith("mcp__"):
        key = hashlib.sha256(json.dumps(event.get("tool_input"), sort_keys=True, ensure_ascii=True,
                                        default=str).encode("ascii")).hexdigest()
        return _pilot_mcp_action(tool, event.get("tool_input")), key
    if isinstance(tool, str) and tool in FILE_WRITE_TOOLS:
        return None, ""
    command, _cwd = _command_from_event(event)
    return _pilot_shell_action(command), hashlib.sha256(command.encode("utf-8", "surrogatepass")).hexdigest()


def pilot_after_tool(event: object, outcome: "Outcome", environ: dict, host: str = "claude",
                     event_text: str | None = None) -> None:
    """Level 1 (D55): after the gate's verdict on a tool call, a receipt for the GitHub write the call makes, when the
    pilot is on and the pilot reads the form (_pilot_tool_action, _pilot_tool_verdict). The signer service gets the
    event as the host gave it, event_text, to decide again (D58)."""
    verdict = _pilot_tool_verdict(outcome, host)
    config = _pilot_config(environ) if verdict is not None else None
    if config is None or not isinstance(event, dict):
        return
    action, key = _pilot_tool_action(event)
    if action is not None:
        text = event_text if isinstance(event_text, str) else json.dumps(event)
        _pilot_issue_all(config, environ, [(action, key)], verdict, [v.reason_id for v in outcome.verdicts],
                         {"level": 1, "host": host, "event": text})


def pilot_after_push(url: str | None, lines: list[tuple], decision: str, reasons: list[str], environ: dict,
                     remote: str | None = None, cwd: str | None = None) -> None:
    """Level 2 (D55): after the pre-push verdict, a receipt per ref line. pass approves the push and every other
    verdict but inactive denies it, as the hook's exit code does; inactive gets no receipt. The signer service gets the
    remote, the URL, git's ref lines and the repository to decide the push again (D58)."""
    if decision == "inactive":
        return
    _pilot_issue_all(_pilot_config(environ), environ, _pilot_push_actions(url, lines),
                     "ALLOW" if decision == "pass" else "DENY", reasons,
                     {"level": 2, "cwd": cwd or os.getcwd(), "remote": remote, "url": url,
                      "lines": [list(line) for line in lines]})


def pre_push_command(argv: list[str]) -> int:
    """PROTOTYPE git pre-push hook entry (DECISIONS.md, D24; installed only by install-pre-push, D24B). git runs a
    pre-push hook as `hook <remote-name> <remote-url>` with one `<local_ref> <local_sha> <remote_ref>
    <remote_sha>` line per ref on stdin, in the repository being pushed. This reaches a verdict from those
    lines alone and denies the push (exit 1) when the evidence does not verify, whatever shell form launched
    the push. The two positional arguments, the remote's name and the push URL (measured with git 2.34.1: a pushurl
    and an insteadOf rewrite applied), are compared with a hand-over of Level 1 where there is one (D35)."""
    deadline = time.monotonic() + DEADLINE_SECONDS
    lines = []
    for raw in sys.stdin.read().splitlines():
        parts = raw.split()
        if not parts:
            continue  # a blank line carries no ref
        if len(parts) != 4:
            # R5-5: a non-empty line that is not git's four-field form is a controlled rejection, never an
            # empty ref list the gate would read as 'nothing to push' and let pass.
            sys.stderr.write("proofbundle pre-push (prototype): a ref line on stdin did not have the four "
                             "fields git writes (<local_ref> <local_sha> <remote_ref> <remote_sha>). "
                             "The push is denied.\n")
            return 1
        lines.append(tuple(parts))
    url = argv[1] if len(argv) > 1 else None
    try:
        verdict = pre_push_verdict(os.getcwd(), lines, deadline, argv[0] if argv else None, url)
    except GateError as exc:
        try:
            pilot_after_push(url, lines, "deny", ["pre_push_gate_error"], os.environ, argv[0] if argv else None)
        except Exception:  # noqa: BLE001 - a receipt never changes the answer (D55)
            pass
        sys.stderr.write(f"proofbundle pre-push (prototype): {exc}. The push is denied.\n")
        return 1
    try:
        pilot_after_push(url, lines, verdict.decision, [verdict.reason_id], os.environ, argv[0] if argv else None)
    except Exception:  # noqa: BLE001 - a receipt never changes the answer (D55)
        pass
    sys.stderr.write(verdict.text() + "\n")
    # Point 1 (review round 5): exit 0 only for pass and a measured inactive; ask, unknown states, measurement
    # errors and any exception all block (exit 1). A rule change stays blocked; there is no release switch in
    # an environment the model can write or run (D24).
    return 0 if verdict.decision in ("pass", "inactive") else 1


# --- install-pre-push: Level 2 into the repository where the user asks for it (owner choice K5-D C, D24B) -----------

INSTALL_USAGE = "usage: install-pre-push [--repo DIR]"
#: The line that marks a pre-push hook this command wrote; a hook without it is someone else's and is never replaced.
PRE_PUSH_MARK = "# proofbundle-pre-push-wrapper 1"
#: Environment names that move the repository away from the one the command is called in. A core.hooksPath given in
#: the environment (GIT_CONFIG_COUNT, GIT_CONFIG_PARAMETERS) shows up in the `command` scope and is refused there.
_INSTALL_MOVED_BY = ("GIT_DIR", "GIT_WORK_TREE", "GIT_COMMON_DIR")
#: Run by the wrapper at each push with the recorded plugin root: the gate of that root, or, when the root is a
#: version folder of an installed plugin (`…/proofbundle/<version>`), the gate of the newest version folder beside
#: it, so a plugin update needs no new install. Prints nothing when it finds none. No single quote may appear here.
_PRE_PUSH_RESOLVER = """import os, re, sys
root = sys.argv[1]
version = re.compile(r"[0-9]+([.][0-9]+)*")
def gate(folder):
    path = os.path.join(folder, "hooks", "proofbundle_gate.py")
    return path if os.path.isfile(path) and not os.path.islink(path) else None
family, name = os.path.split(root)
found = None
if version.fullmatch(name) and os.path.basename(family) == "proofbundle":
    best = None
    for entry in (os.listdir(family) if os.path.isdir(family) else []):
        if version.fullmatch(entry) and gate(os.path.join(family, entry)):
            key = tuple(int(part) for part in entry.split("."))
            best = max(best, (key, entry)) if best else (key, entry)
    found = gate(os.path.join(family, best[1])) if best else None
else:
    found = gate(root)
print(found or "")
"""


def _sh_quote(text: str) -> str:
    return "'" + text.replace("'", "'\\''") + "'"


def pre_push_wrapper(plugin_root: str) -> str:
    """The fixed pre-push hook install-pre-push writes: it records the plugin root it was installed from, finds the
    gate at each push (_PRE_PUSH_RESOLVER) and runs it as `pre-push` with git's arguments and ref lines. When it finds
    no gate it denies the push (exit 1); so does a failed python3."""
    assert "'" not in _PRE_PUSH_RESOLVER
    return (f"#!/bin/sh\n{PRE_PUSH_MARK} (install-pre-push, DECISIONS.md D24B)\n"
            "# Written on request by proofbundle_gate.py install-pre-push, which alone replaces it. It finds the\n"
            "# plugin's gate at each push and denies the push (exit 1) when it finds none.\n"
            f"root={_sh_quote(plugin_root)}\n"
            f"gate=$(python3 -I -c '{_PRE_PUSH_RESOLVER}' \"$root\") || gate=\"\"\n"
            'if [ -z "$gate" ]; then\n'
            '  echo "proofbundle pre-push: no proofbundle plugin gate found at $root or in a newer version beside'
            ' it, so the push is denied. Run install-pre-push again from the installed plugin, or remove $0." >&2\n'
            "  exit 1\n"
            "fi\n"
            'exec python3 -I "$gate" pre-push "$@"\n')


def _inside(path: str, folders: list[str]) -> bool:
    real = os.path.realpath(path)
    return any(os.path.commonpath([real, os.path.realpath(f)]) == os.path.realpath(f) for f in folders if f)


def install_pre_push(directory: str, deadline: float, environ: dict | None = None,
                     plugin_root: str | None = None) -> str:
    """Write the pre-push wrapper into the hook folder git uses for the repository at directory (owner choice K5-D C,
    D24B), and nowhere else: the repository's own `.git/hooks`, or a `core.hooksPath` set in its local or worktree
    configuration that points inside the repository. Sets no configuration, local or global. Refuses a hook folder
    set in any other scope, one outside the repository, an environment that moves the repository, and an existing
    pre-push hook it did not write, which it names and leaves as it is. Runs only when the user calls it."""
    environ = os.environ if environ is None else environ
    moved = [name for name in _INSTALL_MOVED_BY if environ.get(name)]
    if moved:
        raise GateError(f"{', '.join(moved)} is set, which moves the repository away from {directory}; run "
                        "install-pre-push without it")
    plugin_root = plugin_root or os.path.dirname(os.path.dirname(os.path.realpath(__file__)))
    if any(ord(c) < 32 for c in plugin_root):
        raise GateError("the plugin folder's path holds a control character, so no hook can name it safely")
    paths, why = _repo_paths(directory, deadline)
    if paths is None:
        raise GateError(f"git cannot tell the hook folder of {directory}: {why}")
    if paths["toplevel"] is None:
        raise GateError(f"{directory} is not the working tree of a git repository")
    entries, why = _config_entries(paths["toplevel"], deadline)
    if entries is None:
        raise GateError(f"git cannot read the configuration of {paths['toplevel']}: {why}")
    for scope, origin, key, _value in entries:
        if key == "core.hookspath" and scope not in ("local", "worktree"):
            raise GateError(f"core.hooksPath is set in the {scope} configuration ({origin}), so a hook there would act "
                            "beyond this repository; install-pre-push writes only into this repository's own hook "
                            "folder and never changes that setting")
    folder = paths["hooks"]
    if not _inside(folder, [paths["toplevel"], paths["common"]]):
        raise GateError(f"the local core.hooksPath of this repository points outside it ({folder}); install-pre-push "
                        "writes only inside the repository")
    hook = os.path.join(folder, "pre-push")
    if os.path.lexists(hook):
        ours = False
        if os.path.isfile(hook) and not os.path.islink(hook):
            try:
                lines = _read_regular(hook, 4096).splitlines()   # checked again at the descriptor (R18-2 class)
            except _NotRegular:
                lines = []
            ours = len(lines) > 1 and lines[1].startswith(PRE_PUSH_MARK.encode())
        if not ours:
            raise GateError(f"a pre-push hook that install-pre-push did not write exists at {hook}; it is left as it "
                            "is. Merge the proofbundle call into it by hand, or move it away and run "
                            "install-pre-push again")
    os.makedirs(folder, exist_ok=True)
    fd, temp = tempfile.mkstemp(prefix=".pre-push.", dir=folder)
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as handle:
            handle.write(pre_push_wrapper(plugin_root))
        # Mode 755 on purpose: git runs the hook at a push, and the pin check (_hooks_now) reads its bytes also under
        # the account of the pilot's signer service (D58; CodeQL alert 153, kept).
        os.chmod(temp, 0o755)
        updated = os.path.lexists(hook)
        os.replace(temp, hook)
    except BaseException:
        if os.path.lexists(temp):
            os.unlink(temp)
        raise
    return (f"proofbundle install-pre-push: {'replaced the' if updated else 'wrote a'} pre-push hook at {hook}. At "
            f"each push it runs the gate of the plugin at {plugin_root}, or of the newest version installed beside "
            "it, and a push it cannot check is denied. Nothing else was changed: no configuration, local or global. "
            "`git push --no-verify` skips it; the boundary is the required CI check (D22).")


def install_pre_push_command(argv: list[str]) -> int:
    options, i = {"--repo": None}, 0
    while i < len(argv):
        if argv[i] in options and i + 1 < len(argv) and options[argv[i]] is None:
            options[argv[i]], i = argv[i + 1], i + 2
        else:
            print(f"{INSTALL_USAGE}; unexpected {argv[i]!r}", file=sys.stderr)
            return 2
    try:
        print(install_pre_push(options["--repo"] or os.getcwd(), time.monotonic() + DEADLINE_SECONDS))
    except (GateError, OSError) as exc:
        print(f"proofbundle install-pre-push: {exc}", file=sys.stderr)
        return 1
    return 0


def main(argv: list[str] | None = None) -> int:
    argv = sys.argv[1:] if argv is None else argv
    if argv[:1] == ["tree-digest"]:
        return tree_digest_command(argv[1:])
    if argv[:1] == ["state-digest"]:
        return state_digest_command(argv[1:])
    if argv[:1] == ["transport-digest"]:
        return transport_digest_command(argv[1:])
    if argv[:1] == ["ci-check"]:
        return ci_check_command(argv[1:])
    if argv[:1] == ["run-evidence"]:
        return run_evidence_command(argv[1:])
    if argv[:1] == ["pre-push"]:
        return pre_push_command(argv[1:])
    if argv[:1] == ["install-pre-push"]:
        return install_pre_push_command(argv[1:])
    if argv[:1] == ["stop"]:
        return stop_command(argv[1:])
    if argv[:1] == ["done-check"]:
        return done_check_command(argv[1:])
    if argv[:1] == ["done-init"]:
        return done_init_command(argv[1:])
    if argv[:1] == ["done-order"]:
        return done_order_command(argv[1:])
    if argv[:1] == ["task-completed"]:
        return task_completed_command(argv[1:])
    if argv[:1] == ["session-start"]:
        return session_start_command(argv[1:])
    if argv[:1] == ["bilanz"]:
        return bilanz_command(argv[1:])
    if argv[:1] == ["done-statement"]:
        return done_statement_command(argv[1:])
    if argv[:1] == ["hook-state"]:
        return hook_state_command(argv[1:])
    if argv[:1] == ["pin-state"]:
        return pin_state_command(argv[1:])
    deadline = time.monotonic() + DEADLINE_SECONDS
    host, event, actions, event_text = "claude", None, [], None
    try:
        host = _host(argv)
    except Exception as exc:  # noqa: BLE001 - any failure inside the gate denies, it never allows
        verdict = _failure_outcome(exc)
    else:
        event_text = sys.stdin.read()
        event, verdict, actions = tool_outcome(event_text, host, deadline, autonomous=AUTONOMOUS_FLAG in argv)
    receipted = False
    held = getattr(verdict, "release", None)
    if held is not None and not held["genutzt"]:
        try:   # D119: the owner's release is used once, where the call runs, after the signer service's ALLOW
            verdict, receipted = release_settle(event, verdict, os.environ, host, event_text)
        except Exception:  # noqa: BLE001 - a release whose use is not written lets nothing run
            verdict = held["ohne"]
    # D81: under Claude Code a Bash command that reads its evidence wrongly gets a hint as additional context, the one
    # output of a PreToolUse hook measured to reach the model without a question; it never changes the decision, and a
    # call that is denied gets none.
    hints = []
    if host == "claude" and isinstance(event, dict) and event.get("tool_name") == "Bash" and (
            verdict is None or verdict.decision != "deny"):
        try:
            hints = evidence_hints(_command_from_event(event)[0])
        except Exception:  # noqa: BLE001 - a hint never changes the answer
            hints = []
    if host in HOSTS:
        try:
            entry = log_entry(host, event, verdict, actions)
            completed = (_autonomy_track(host, event, verdict)   # D88: the detour this call completes, if any
                         if AUTONOMOUS_FLAG in argv else None)
            if completed is not None:
                entry["umweg"] = completed
            asked = _asks_keep(event, verdict) if AUTONOMOUS_FLAG in argv and host == "claude" else None   # D94
            if asked is not None:
                entry["frage"] = asked
            if hints:
                entry["hints"] = hints
            write_log(entry, host)
        except Exception:  # noqa: BLE001 - the log never changes the answer
            pass
    printed = None
    if verdict is not None:
        try:
            if not receipted:   # D119: the receipt of a released call was asked for before its use
                pilot_after_tool(event, verdict, os.environ, host, event_text)
        except Exception:  # noqa: BLE001 - a receipt never changes the answer (D55)
            pass
        try:
            if verdict.decision != "pass" or any(v.reason_id in ("approved_by_rule", *HINT_REASONS)
                                                 for v in verdict.verdicts) or \
                    (verdict.autonomy or {}).get("klasse") in ("go", "maschine", "freigabe"):
                printed = pre_tool_answer(verdict, host, event, _step_of_event(event))
        except Exception:  # noqa: BLE001 - the short line never changes the decision: the long reason stands in
            printed = answer(verdict.decision, verdict.text, host=host)
    if hints:
        printed = dict(printed or {})
        specific = dict(printed.get("hookSpecificOutput") or {"hookEventName": "PreToolUse"})
        specific["additionalContext"] = " ".join(([specific["additionalContext"]] if specific.get("additionalContext")
                                                  else []) + [_HINTS[h] for h in hints])
        printed["hookSpecificOutput"] = specific
    if printed is not None:
        sys.stdout.write(json.dumps(printed) + "\n")
    return 0

def _failure_outcome(exc: BaseException) -> "Outcome":
    """The deny of a call the gate reached no verdict on: a GateError names what it could not read, any other failure
    is an internal error. Any failure inside the gate denies, it never allows."""
    if isinstance(exc, GateError):
        failure = Verdict("deny", f"proofbundle gate: {exc}. The call is denied because the gate reached no verdict.",
                          "hook_input", evidence="none, the gate could not read the call", failed=str(exc),
                          next_step="check the plugin's hook command and the host version")
    else:
        failure = Verdict("deny", f"proofbundle gate: internal error {type(exc).__name__}: {exc}. "
                                  "The call is denied because the gate reached no verdict.", "internal_error",
                          evidence="none, the gate failed before a verdict", failed=f"{type(exc).__name__}: {exc}",
                          next_step="report this error; the gate denies until it is fixed",
                          digests=getattr(exc, "digests", ()), head=getattr(exc, "head", None),
                          reads=getattr(exc, "reads", ()))   # R12-2: what an exception carries stays in the log
    return Outcome("deny", failure.text(), [failure])


def tool_outcome(event_text: str, host: str, deadline: float,
                 autonomous: bool = False) -> tuple[object, "Outcome | None", list[str]]:
    """The decision of the PreToolUse hook on one event as the host gave it: (the event read, the outcome, the gated
    actions the log names), without an answer, a log line or a receipt. main decides with it, and so does the signer
    service of the pilot on its own copy of the gate before it signs (D58). autonomous is the hook's --autonomous
    (D85): an ask under Claude Code gets the autonomous answer; the service decides with it only where its operator set
    it (D119). Neither writes the use of an owner's release: the outcome holds it, and the hook writes it only where
    the call runs (release_settle, D119)."""
    event, actions = None, []
    try:
        try:
            event = strict_json(event_text)
        except AmbiguousJSON as exc:
            raise GateError(f"the hook input {exc}, so the gate cannot tell which call it describes") from exc
        except ValueError as exc:
            raise GateError("the hook input is not JSON") from exc
        tool = event.get("tool_name") if isinstance(event, dict) else None
        command = None
        if isinstance(tool, str) and tool.startswith("mcp__"):
            cwd = event.get("cwd")
            cwd = cwd if isinstance(cwd, str) and cwd else os.getcwd()
            actions = [f"MCP {tool}"] if mcp_gated(tool) else []
            verdict = decide_mcp(tool, cwd, deadline, host=host)
        elif isinstance(tool, str) and tool in FILE_WRITE_TOOLS:
            cwd = event.get("cwd")
            cwd = cwd if isinstance(cwd, str) and cwd else os.getcwd()
            verdict = decide_write(tool, event.get("tool_input"), cwd, deadline, host=host)
            actions = [f"file {tool}"] if verdict is not None else []
        elif isinstance(tool, str) and tool in READ_TOOLS:
            cwd = event.get("cwd")
            cwd = cwd if isinstance(cwd, str) and cwd else os.getcwd()
            verdict = decide_read(tool, event.get("tool_input"), cwd, deadline, host=host)   # D102
            actions = [f"read {tool}"] if verdict is not None else []
        else:
            tool = "Bash"
            command, cwd = _command_from_event(event)
            actions = sorted({name for name, _, _ in gated_calls(_program_values(command))})
            verdict = decide(command, cwd, deadline, host=host)
        if autonomous and host == "claude" and verdict is not None and verdict.decision == "ask":
            try:   # D85: the autonomous answer; a failure in it keeps the ask, which lets nothing run
                verdict = autonomous_outcome(verdict, command, cwd, deadline, host, tool=tool, take=False)
            except Exception:  # noqa: BLE001 - the ask of decide() stands
                pass
    except Exception as exc:  # noqa: BLE001 - any failure inside the gate denies, it never allows
        verdict = _failure_outcome(exc)
    return event, verdict, actions


def _step_of_event(event: object) -> str | None:
    """The name of the call a hook event describes, as the short line names it (D53): the first git or gh step of a
    shell command, `MCP <tool>` for an MCP tool, the tool's name for a file tool."""
    if not isinstance(event, dict):
        return None
    tool = event.get("tool_name")
    if isinstance(tool, str) and tool.startswith("mcp__"):
        return f"MCP {tool.rsplit('__', 1)[-1]}"
    if isinstance(tool, str) and (tool in FILE_WRITE_TOOLS or tool in READ_TOOLS):
        return tool
    try:
        command, cwd = _command_from_event(event)
    except GateError:
        return None
    return _short_step_name(command, cwd)


if __name__ == "__main__":
    sys.exit(main())
